Object.assign(window.OTPU_CODE,{"tests/test_llama.py": "\"\"\"The Llama-likes on openTPU (llama.py, on Qwen3's code): SmolLM3 (no q/k norms, layers without\nRoPE) and Phi-3 / Phi-4-mini (fused qkv / gate_up projections, partial RoPE, LongRoPE) against\nHugging Face transformers. Tiny random models, saved as checkpoints and read back through\nload_spec / load_weights, always run.\"\"\"\nimport dataclasses\n\nimport numpy as np\nimport pytest\n\nfrom opentpu import language as ol\nfrom opentpu import quant as Q\nfrom opentpu.compiler import Affine, Tensor\nfrom opentpu.isasim import Machine, board_config\nfrom opentpu.kernels.gather import gather_row, onehot, table\nfrom opentpu.llm import load_spec\nfrom opentpu.llm.qwen3 import Engine, emulated_logits, gathered_rows, load_weights, reference_logits\n\ntorch = pytest.importorskip(\"torch\")\ntransformers = pytest.importorskip(\"transformers\")\n\nNOPE = [1, 1, 1, 0, 1, 1, 1, 0]                 # SmolLM3's no_rope_layers: 0 = no RoPE\n\n\ndef _cos(a, b):\n    return (a * b).sum(-1) / np.linalg.norm(a, axis=-1) / np.linalg.norm(b, axis=-1)\n\n\ndef _smollm3():\n    return transformers.SmolLM3ForCausalLM(transformers.SmolLM3Config(\n        hidden_size=256, num_hidden_layers=len(NOPE), num_attention_heads=8,\n        num_key_value_heads=2, head_dim=128, intermediate_size=512, vocab_size=1000,\n        rms_norm_eps=1e-6, rope_parameters={\"rope_type\": \"default\", \"rope_theta\": 5e6},\n        no_rope_layers=NOPE, tie_word_embeddings=True, max_position_embeddings=4096,\n        bos_token_id=1, eos_token_id=2, pad_token_id=0))\n\n\ndef _phi3():\n    \"\"\"Phi-4-mini's attention in small: query groups of 3, RoPE on 96 of 128 dimensions,\n    LongRoPE with short factors that are not all 1 (Phi-4-mini's are) and an attention factor\n    of sqrt(1 + ln 4 / ln 4096).\"\"\"\n    short = [1.0 + 0.05 * i for i in range(48)]\n    return transformers.Phi3ForCausalLM(transformers.Phi3Config(\n        hidden_size=768, num_hidden_layers=2, num_attention_heads=6, num_key_value_heads=2,\n        intermediate_size=512, vocab_size=1000, rms_norm_eps=1e-5, rope_theta=1e4,\n        partial_rotary_factor=0.75, max_position_embeddings=16384,\n        original_max_position_embeddings=4096,\n        rope_scaling={\"type\": \"longrope\", \"short_factor\": short,\n                      \"long_factor\": [4 * f for f in short]},\n        tie_word_embeddings=True, bos_token_id=1, eos_token_id=2, pad_token_id=0))\n\n\n@pytest.fixture(scope=\"module\", params=[\"smollm3\", \"phi3\"])\ndef tiny(request, tmp_path_factory):\n    torch.manual_seed(0)\n    m = {\"smollm3\": _smollm3, \"phi3\": _phi3}[request.param]().float().eval()\n    with torch.no_grad():\n        for n, p in m.named_parameters():\n            if \"norm\" in n:\n                p.copy_(1 + 0.1 * torch.randn_like(p))\n    path = tmp_path_factory.mktemp(request.param)\n    m.save_pretrained(path)                     # the loaders read it back (Phi-3: fused)\n    return request.param, m, load_spec(path), load_weights(path)\n\n\n@pytest.mark.parametrize(\"K\", [256, 768])\ndef test_embedding_rows_are_the_gathers(K):\n    \"\"\"qwen3.gathered_rows (the host's reference of an int8 embedding) is what the device's\n    gather (kernels.gather.gather_row) reads from an int8 table (quant.quantize_mxu's element\n    rows and their gather scales, as an image keeps the embedding), bit for bit (rows with a\n    zero block), within half a step of the row's scale.\"\"\"\n    rng = np.random.default_rng(K)\n    W = rng.normal(0, 0.05, (40, K)).astype(np.float32)\n    W[7, :128] = 0\n    cfg = board_config(DRAM_BYTES=1 << 22)\n    D, M = cfg.D, cfg.MCOLS\n    oh = onehot(D, M, \"int8\")\n    q, s = Q.quantize_mxu(W, \"int8\", D)\n    g = np.ascontiguousarray(Q.gather_scales(s, \"int8\", K, D)).view(np.uint8).reshape(-1)\n    OH, TAB, GS, OUT = 0, 1 << 18, 1 << 20, 1 << 21\n    img = np.zeros(cfg.DRAM_BYTES, np.uint8)\n    img[OH:OH + oh.nbytes] = oh.view(np.uint8).reshape(-1)\n    img[TAB:TAB + q.size] = q.reshape(-1)\n    img[GS:GS + g.size] = g\n    tab, rows = table(TAB, GS, 40, K, \"int8\", D), (0, 7, 39)\n\n    @ol.jit\n    def k(ohd, out):\n        op = ol.quantize(ol.load(ohd))\n        for i, r in enumerate(rows):\n            ol.store(out[i:i + 1, :], gather_row(op, tab, r, \"int8\").reshape(1, K))\n\n    prog = k.trace(cfg, 0, {\"ohd\": Tensor(Affine(OH), oh.shape, (oh.shape[1], 1)),\n                            \"out\": Tensor(Affine(OUT), (len(rows), K), (K, 1))}).finish()\n    dram = Machine(cfg, [prog], [img]).run().slices[0].dram\n    got = dram[OUT:OUT + 4 * len(rows) * K].view(np.float32).reshape(len(rows), K)\n    for i, r in enumerate(rows):\n        want = gathered_rows(W[r:r + 1], D)[0]\n        assert np.array_equal(got[i].view(np.uint32), want.view(np.uint32)), r\n        assert np.abs(got[i] - W[r]).max() <= np.abs(W[r]).max() / 254 * 1.0001\n\n\ndef test_specs(tiny):\n    name, _, spec, W = tiny\n    assert not spec.qk_norm and spec.embed == \"int8\"\n    if name == \"smollm3\":\n        assert spec.nope == (3, 7) and spec.rope_dim == 128 and not spec.rope_div\n    else:\n        assert spec.nope == () and spec.rope_dim == 96 and spec.ctx == 4096\n        assert spec.rope_div[1] == 1.05 and abs(spec.rope_scale - (1 + 1 / 6) ** 0.5) < 1e-12\n        # the fused projections, split by rows\n        qkv = W[\"model.layers.0.self_attn.qkv_proj.weight\"]\n        assert np.array_equal(W[\"model.layers.0.self_attn.k_proj.weight\"], qkv[768:1024])\n        gu = W[\"model.layers.1.mlp.gate_up_proj.weight\"]\n        assert np.array_equal(W[\"model.layers.1.mlp.up_proj.weight\"], gu[512:])\n\n\ndef test_phi3_sliding_window_bounds_the_cache(tmp_path):\n    \"\"\"Phi-3's sliding window (Hugging Face masks the keys at or before q - window; this code\n    has none): the KV capacity stays within it (Spec.ctx: Phi-3-medium-4k's 2047), or within\n    LongRoPE's range where that is smaller (Phi-4-mini: 4096 of a 262144 window); a larger\n    capacity is refused.\"\"\"\n    import json\n    short = [1.0] * 48\n\n    def spec(window, **kw):\n        c = transformers.Phi3Config(\n            hidden_size=768, num_hidden_layers=2, num_attention_heads=6, num_key_value_heads=2,\n            intermediate_size=512, vocab_size=1000, partial_rotary_factor=0.75,\n            sliding_window=window, **kw)\n        (tmp_path / \"config.json\").write_text(json.dumps(c.to_dict()))\n        return load_spec(tmp_path)\n    s = spec(2047)\n    assert s.ctx == 2047 and spec(None).ctx == 0\n    long = dict(max_position_embeddings=131072, original_max_position_embeddings=4096,\n                rope_scaling={\"type\": \"longrope\", \"short_factor\": short, \"long_factor\": short})\n    assert spec(262144, **long).ctx == 4096 and spec(2047, **long).ctx == 2047\n    s.image(board_config(DRAM_BYTES=1 << 26), 1920)\n    with pytest.raises(ValueError, match=\"range\"):\n        s.image(board_config(DRAM_BYTES=1 << 26), 2048)\n\n\n@pytest.mark.parametrize(\"config\", [\"design\", \"board\"])\ndef test_tiny_matches_hf(tiny, config):\n    _, m, spec, W = tiny\n    toks = [int(t) for t in np.random.default_rng(0).integers(0, 1000, 140)]  # > one KV block\n    with torch.no_grad():\n        hf = m(torch.tensor([toks])).logits[0].numpy()\n    assert np.abs(reference_logits(spec, W, toks) - hf).max() < 1e-4\n    cfg = board_config(DRAM_BYTES=1 << 26) if config == \"board\" else None\n    eng = Engine(spec, W, cap=256, cfg=cfg)\n    dev = np.array([eng.step(t) for t in toks])\n    assert _cos(dev, hf).min() > 0.998\n    emu = emulated_logits(spec, W, toks[:12])\n    assert _cos(dev[:12], emu).min() > 0.9995\n\n\ndef test_tiny_fp4_follows_emulation(tiny):\n    _, _, spec, W = tiny\n    toks = [int(t) for t in np.random.default_rng(0).integers(0, 1000, 12)]\n    eng = Engine(spec, W, cap=256, wformat=\"fp4\", head_format=\"int8\")\n    dev = np.array([eng.step(t) for t in toks])\n    emu = emulated_logits(spec, W, toks, wformat=\"fp4\", head_format=\"int8\")\n    assert _cos(dev, emu).min() > 0.9995\n\n\ndef test_tiny_resident_decode_is_bit_exact(tiny):\n    \"\"\"Resident decode (run-time position and token) gives the per-position programs' logits\n    bit for bit, across the bucket boundary 256, after a chunked prefill; one hardware loop\n    runs every layer, with and without RoPE, and the token's int8 embedding row is gathered\n    from the tied int8 LM head (the per-position programs gather it too).\"\"\"\n    _, _, spec, W = tiny\n    toks = [int(t) for t in np.random.default_rng(1).integers(0, 1000, 262)]\n    cfg = board_config(DRAM_BYTES=1 << 26)\n    a = Engine(spec, W, cap=512, cfg=cfg, resident=True)\n    b = Engine(spec, W, cap=512, cfg=cfg)\n    assert a.resident\n    for t in toks[:3]:\n        assert np.array_equal(a.step(t).view(np.uint32), b.step(t).view(np.uint32))\n    assert np.array_equal(a.prefill(toks[3:252]), b.prefill(toks[3:252]))\n    for t in toks[252:]:\n        assert np.array_equal(a.step(t).view(np.uint32), b.step(t).view(np.uint32))\n    assert sorted(a._decodes) == [1, 2]\n\n\ndef test_tiny_resident_own_int8_table(tiny):\n    \"\"\"A 4-bit LM head cannot serve the gather: the image holds its own int8 embedding\n    table, with the same values.\"\"\"\n    _, _, spec, W = tiny\n    toks = [int(t) for t in np.random.default_rng(3).integers(0, 1000, 6)]\n    cfg = board_config(DRAM_BYTES=1 << 26)\n    a = Engine(spec, W, cap=256, cfg=cfg, resident=True, wformat=\"fp4\", head_format=\"fp4\")\n    b = Engine(spec, W, cap=256, cfg=cfg, wformat=\"fp4\", head_format=\"fp4\")\n    assert a.resident and a.image.lookup[\"own\"]\n    for t in toks:\n        assert np.array_equal(a.step(t).view(np.uint32), b.step(t).view(np.uint32))\n\n\n@pytest.mark.parametrize(\"first,chunk\", [(0, 5), (3, 8)])\ndef test_tiny_chunked_prefill_is_bit_exact(tiny, first, chunk):\n    _, _, spec, W = tiny\n    toks = [int(t) for t in np.random.default_rng(2).integers(0, 1000, 21)]\n    a, b = Engine(spec, W, cap=128), Engine(spec, W, cap=128)\n    for t in toks[:first]:\n        a.step(t)\n        b.step(t)\n    la = a.prefill(toks[first:], chunk=chunk)\n    lb = None\n    for t in toks[first:]:\n        lb = b.step(t)\n    assert np.array_equal(la.view(np.uint32), lb.view(np.uint32))\n    lo, hi = a.image.layer0, a.image.nbytes          # the layer blocks: weights and KV cache\n    ma, mb = a.backend.machine.slices, b.backend.machine.slices\n    assert all(np.array_equal(x.dram[lo:hi], y.dram[lo:hi]) for x, y in zip(ma, mb))\n\n\ndef test_tiny_formats_per_kind(tiny, monkeypatch):\n    \"\"\"Weight formats per kind (Spec.formats, opentpu/llm/formats.py) over a 4-bit image: each\n    kind's projections in their format, one layer layout; the device follows the emulation of\n    the same formats, closer than the all-fp4 emulation; resident decode and a chunked prefill\n    give token-by-token decoding's logits bit for bit. A range that splits a kind across the\n    layers is refused (one layout).\"\"\"\n    monkeypatch.delenv(\"OTPU_FORMATS\", raising=False)\n    _, _, spec, W = tiny\n    mix = dataclasses.replace(spec, formats=\"attn=int8,gateup=fp4,down=int4,head=int8\")\n    cfg = board_config(DRAM_BYTES=1 << 26)\n    a = Engine(mix, W, cap=256, cfg=cfg, wformat=\"fp4\")\n    assert a.image.mf == dict(wq=\"int8\", wk=\"int8\", wv=\"int8\", wo=\"int8\", wg=\"fp4\", wu=\"fp4\",\n                              wd=\"int4\") and a.image.head_format == \"int8\"\n    assert mix.image(cfg, 256).nbytes < spec.image(cfg, 256).nbytes\n    toks = [int(t) for t in np.random.default_rng(4).integers(0, 1000, 12)]\n    dev = np.array([a.step(t) for t in toks])\n    emu = emulated_logits(mix, W, toks, wformat=\"fp4\")\n    e4 = emulated_logits(spec, W, toks, wformat=\"fp4\", head_format=\"int8\")\n    assert _cos(dev, emu).min() > 0.9995\n    assert np.abs(dev - emu).mean() < 0.7 * np.abs(dev - e4).mean()\n    r = Engine(mix, W, cap=256, cfg=cfg, wformat=\"fp4\", resident=True)\n    b = Engine(mix, W, cap=256, cfg=cfg, wformat=\"fp4\")\n    assert r.resident\n    for t, want in zip(toks[:4], dev):\n        assert np.array_equal(r.step(t).view(np.uint32), want.view(np.uint32))\n    assert np.array_equal(b.prefill(toks, chunk=4).view(np.uint32), dev[-1].view(np.uint32))\n\n\ndef test_tiny_formats_by_layer_range(tiny, monkeypatch):\n    \"\"\"Weight formats per layer range (formats.py's kind@a-b): a layer block layout per\n    combination, the layers in runs of one layout (a hardware loop each, its blocks with their\n    own stride): the device follows the emulation of the same formats; resident decode and a\n    chunked prefill give token-by-token decoding's logits bit for bit; the KV caches of every\n    layer end equal.\"\"\"\n    monkeypatch.delenv(\"OTPU_FORMATS\", raising=False)\n    _, _, spec, W = tiny\n    L = spec.layers\n    h = L // 2                      # attention fp4 in the first half, the MLP in the second,\n    fm = f\"attn@0-{h - 1}=fp4,mlp@{h}-{L - 1}=fp4\"              # one down int4 (SmolLM3)\n    if L >= 8:\n        fm += f\",down@{h + 1}=int4\"\n    mix = dataclasses.replace(spec, formats=fm)\n    cfg = board_config(DRAM_BYTES=1 << 26)\n    a = Engine(mix, W, cap=256, cfg=cfg)\n    img = a.image\n    assert img.lf[0] == (\"fp4\", \"int8\", \"int8\") and img.lf[-1] == (\"int8\", \"fp4\", \"fp4\")\n    assert len(img.runs) == (2 if L < 8 else 4) and len(set(img.bsize.values())) > 1\n    assert [img._off(i).const for i in range(L)] == sorted(img._off(i).const for i in range(L))\n    assert mix.image(cfg, 256).nbytes < spec.image(cfg, 256).nbytes\n    toks = [int(t) for t in np.random.default_rng(5).integers(0, 1000, 12)]\n    dev = np.array([a.step(t) for t in toks])\n    emu, e8 = emulated_logits(mix, W, toks), emulated_logits(spec, W, toks)\n    assert _cos(dev, emu).min() > 0.9995\n    assert np.abs(dev - emu).mean() < 0.7 * np.abs(dev - e8).mean()\n    r = Engine(mix, W, cap=256, cfg=cfg, resident=True)\n    b = Engine(mix, W, cap=256, cfg=cfg)\n    assert r.resident\n    for t, want in zip(toks[:4], dev):\n        assert np.array_equal(r.step(t).view(np.uint32), want.view(np.uint32))\n    assert np.array_equal(b.prefill(toks, chunk=4).view(np.uint32), dev[-1].view(np.uint32))\n    lo, hi = img.layer0, img.head[0]                # every layer block: weights and KV cache\n    assert np.array_equal(a.backend.machine.slices[0].dram[lo:hi],\n                          b.backend.machine.slices[0].dram[lo:hi])\n    # the named choice: wformat \"mix\" is int8 with Spec.mix, the same image\n    named = dataclasses.replace(spec, mix=fm).image(cfg, 256, wformat=\"mix\")\n    assert named.lf == img.lf and named.nbytes == mix.image(cfg, 256).nbytes\n    with pytest.raises(ValueError, match=\"no recommended mix\"):\n        spec.image(cfg, 256, wformat=\"mix\")\n\n\ndef test_nope_is_one_loop_body(tiny):\n    \"\"\"The rope gate keeps one layer body for every layer: the program does not grow with\n    the number of layers without RoPE.\"\"\"\n    name, _, spec, _ = tiny\n    if name != \"smollm3\":\n        pytest.skip(\"no layers without RoPE\")\n    cfg = board_config(DRAM_BYTES=1 << 26)\n    n = [len(dataclasses.replace(spec, nope=nope).image(cfg, 256).compile_step(9)[0])\n         for nope in ((3,), (1, 3, 5, 7))]\n    assert n[0] == n[1]\n\n\n@pytest.mark.parametrize(\"resident\", [False, True], ids=[\"per-position\", \"resident\"])\ndef test_tiny_token_on_board_rtl(have_verilator, tiny, resident):\n    \"\"\"A token after a 39-token prefill on the Verilator RTL through the board's memory path\n    (AXI adapter, boot loader) equals the ISA simulator bit for bit, logits and the whole DRAM\n    image, with the per-position programs and resident: SmolLM3's layers with and without RoPE,\n    Phi-4-mini's fused projections, partial RoPE and LongRoPE (fp4 layers, int8 LM head).\"\"\"\n    from opentpu import rtlsim\n    from opentpu.llm.rtl_backend import RtlBackend\n    name, _, spec, W = tiny\n    toks = [int(t) for t in np.random.default_rng(5).integers(0, 1000, 40)]\n    eng = Engine(spec, W, cap=256, cfg=board_config(DRAM_BYTES=1 << 26), wformat=\"fp4\",\n                 head_format=\"int8\", resident=resident)\n    assert eng.resident == resident\n    eng.prefill(toks[:-1])\n    n, isa = eng.image.nbytes, eng.backend\n    rtl = RtlBackend(eng.cfg, [s.dram[:n] for s in isa.machine.slices],\n                     uarch=rtlsim.BOARD_UARCH, axi=True, boot=True)\n    want = eng.step(toks[-1])\n    eng.backend, eng.pos = rtl, eng.pos - 1\n    got = eng.step(toks[-1])\n    assert np.array_equal(want.view(np.uint32), got.view(np.uint32)), name\n    assert np.array_equal(isa.machine.slices[0].dram[:n], rtl.drams[0][:n]), name\n", "tests/test_loadcal.py": "\"\"\"opentpu.host.loadcal: the DDR3 read taps centred under the core's load. The window and its\ncentre, when it is wanted, the scan against ddrcal's PHY model, and the load on the ISA simulator.\"\"\"\nfrom pathlib import Path\n\nimport numpy as np\n\nfrom opentpu import Config\nfrom opentpu.host import ddrcal as C\nfrom opentpu.host import loadcal as L\nfrom opentpu.isasim import Machine\n\nDATA = Path(__file__).parent / \"data\" / \"litedram\"\n\n\ndef test_a_window_s_centre_is_the_left_middle_of_an_even_run():\n    assert L.window([1, 0, 0, 0, 0, 0, 1]) == (1, 5, 3)\n    assert L.window([1, 1, 0, 0, 0, 0, 1, 0]) == (2, 4, 3)      # 2..5: 3, not 4\n    assert L.window([5, 5, 5]) == (0, 0, None)\n\n\ndef test_wanted_when_the_core_clock_is_not_the_controllers():\n    assert L.wanted(150000, 133.333333e6, env=\"\")\n    assert L.wanted(100000, 133.333333e6, env=\"\")\n    assert not L.wanted(133333, 133.333333e6, env=\"\")              # E3: the same clock\n    assert not L.wanted(None, 133.333333e6, env=\"\")                 # no CORE_KHZ: as before\n    assert L.wanted(133333, 133.333333e6, env=\"1\")\n    assert not L.wanted(150000, 133.333333e6, env=\"0\")\n\n\ndef test_the_scan_finds_each_lane_s_window_and_takes_its_centre():\n    fake = C.FakeCsr(DATA)\n    C.calibrate_channel(fake, DATA, stride=4, log=lambda *_: None)\n    cal = list(fake.rd)\n    err = L.scan([fake], base=0, beats=1 << 10, hz=133.333e6, reps=1)\n    lanes = L.choose(err[0], cal)\n    for m, x in enumerate(lanes):\n        assert (x[\"start\"], x[\"taps\"]) == (fake.LO[m], min(fake.HI[m], 31) - fake.LO[m] + 1)\n        assert x[\"tap\"] == fake.LO[m] + (min(fake.HI[m], 31) - fake.LO[m]) // 2\n        assert not x[\"narrow\"]\n    L.set_taps(fake, [x[\"tap\"] for x in lanes])\n    assert fake.rd == [x[\"tap\"] for x in lanes]\n    assert all(fake.good(m) for m in range(fake.nm))\n\n\ndef test_a_lane_narrower_than_the_minimum_keeps_its_calibrated_tap():\n    err = [[0 if t in (9, 10) else 5, 0 if 4 <= t <= 12 else 5] for t in range(32)]\n    a, b = L.choose(err, [11, 7])\n    assert (a[\"taps\"], a[\"tap\"], a[\"narrow\"]) == (2, 11, True)\n    assert (b[\"taps\"], b[\"tap\"], b[\"narrow\"]) == (9, 8, False)\n\n\ndef test_a_lane_takes_the_widest_eye_under_load_over_its_bitslips():\n    \"\"\"Lane 0's calibrated eye narrows under load (taps 20-22) while the same data reads at the\n    next bitslip a bit time earlier on the IDELAY (taps 8-14): the scan at the bitslips either\n    side finds it, the lane moves there and reads right; lane 1's other eye is no wider (the\n    lower tap of equals: it moves too); every other lane keeps its bitslip and centre.\"\"\"\n    fake = C.FakeCsr(DATA)\n    fake.RB[0], fake.LO[0], fake.HI[0] = 3, 18, 24\n    fake.RB[1], fake.LO[1], fake.HI[1] = 4, 16, 21\n    res = C.calibrate_channel(fake, DATA, stride=4, log=lambda *_: None)\n    cs = ([[x[\"bitslip\"] for x in res[\"read\"]]], [res[\"bit_offsets\"]])\n    cal = [x[\"tap\"] for x in res[\"read\"]]\n    assert cs[0][0][:2] == [3, 4]\n    fake.LO[0], fake.HI[0] = 20, 22                     # the load closes the calibrated eye\n    fake.EYES[0] = [(4, 8, 14)]\n    fake.EYES[1] = [(3, 4, 9)]                          # as wide as lane 1's own (16-21)\n    errs, ok = L.scan_slips([fake], cs, L.SLIPS, base=0, beats=1 << 10, hz=133.333e6, reps=1)\n    lanes = L.choose_slips(errs[0], cal, ok[0])\n    assert (lanes[0][\"slip\"], lanes[0][\"taps\"], lanes[0][\"tap\"]) == (1, 7, 11)\n    assert (lanes[1][\"slip\"], lanes[1][\"taps\"], lanes[1][\"tap\"]) == (-1, 6, 6)\n    for m in range(2, fake.nm):\n        assert lanes[m][\"slip\"] == 0\n        assert lanes[m][\"tap\"] == fake.LO[m] + (min(fake.HI[m], 31) - fake.LO[m]) // 2\n    L.set_slips(fake, [s + x[\"slip\"] for s, x in zip(cs[0][0], lanes)], cs[1][0])\n    L.set_taps(fake, [x[\"tap\"] for x in lanes])\n    assert all(fake.good(m) for m in range(fake.nm))\n\n\ndef test_a_lane_at_the_bitslip_range_s_end_does_not_wrap():\n    assert L.slips_ok(0, [0] * 8, 1) and not L.slips_ok(0, [0] * 8, -1)\n    assert not L.slips_ok(7, [0] * 8, 1) and L.slips_ok(7, [0] * 8, -1)\n    assert not L.slips_ok(5, [0, 2, 0, 0, 0, 0, 0, 0], 1)        # its bit 1 would be at 8\n    assert L.slips_ok(5, [0, -2, 0, 0, 0, 0, 0, 0], 1)\n\n\ndef test_a_narrow_lane_keeps_its_calibrated_tap_and_bitslip():\n    narrow = [[0 if t in (9, 10) else 5] for t in range(32)]\n    wide = [[0 if 3 <= t <= 8 else 5] for t in range(32)]\n    can = {0: [True], 1: [True], -1: [True]}\n    lanes = L.choose_slips({0: narrow, 1: narrow, -1: narrow}, [11], can)\n    assert (lanes[0][\"slip\"], lanes[0][\"tap\"], lanes[0][\"narrow\"]) == (0, 11, True)\n    lanes = L.choose_slips({0: narrow, 1: wide, -1: narrow}, [11], {**can, 1: [False]})\n    assert (lanes[0][\"slip\"], lanes[0][\"narrow\"]) == (0, True)            # it could not move by 1\n    lanes = L.choose_slips({0: narrow, 1: wide, -1: narrow}, [11], can)\n    assert (lanes[0][\"slip\"], lanes[0][\"tap\"], lanes[0][\"narrow\"]) == (1, 5, False)\n\n\ndef test_slips_off_scans_the_calibrated_bitslips_only():\n    assert L.slips_wanted(env=\"\") and L.slips_wanted(env=\"1\") and not L.slips_wanted(env=\"0\")\n\n\ndef test_the_load_runs_on_the_isa_simulator():\n    \"\"\"A few iterations of the load (the m8 card's TMEM): the DMA's tiles are the source tile (it\n    stores them and reloads the one before), and every row of the MMs' results is written.\"\"\"\n    cfg = Config(S=1, DRAM_BYTES=1 << 25, TMEM_WORDS=131072)\n    img, a, prog = L.build(cfg, n_mm=2, n_dma=4, n_iter=3)\n    dram = np.concatenate([img, np.zeros(cfg.DRAM_BYTES - len(img), np.uint8)])\n    m = Machine(cfg, [prog], [dram]).run()\n    got = np.asarray(m.slices[0].dram)\n    src = img[a[\"src\"]:a[\"src\"] + L.TILE]\n    for k in range(4):\n        assert np.array_equal(got[a[\"dma\"] + k * L.TILE:a[\"dma\"] + (k + 1) * L.TILE], src)\n    out = got[a[\"out\"]:a[\"out\"] + 4 * 2 * L.ROWS * L.R].view(np.float32).reshape(2 * L.ROWS, L.R)\n    assert np.isfinite(out).all() and (np.abs(out).sum(1) > 0).all()\n", "tests/test_minicpmv.py": "\"\"\"MiniCPM-V 4.7 on openTPU (docs/minicpmv.md). Its language model is Qwen3.5-MoE: a tiny random\ncheckpoint laid out as MiniCPM-V's (model_type minicpmv4_7, the language model under\nmodel.language_model.*, an LM head of its own, the vision tower and projector beside it) loads\nas qwen35's Spec and weights, without the vision tensors; a vocabulary that is not a multiple\nof D (MiniCPM-V's 248,144 = 1938 x 128 + 80) gives the logits of the head padded with zero rows,\nbit for bit.\"\"\"\nimport json\nfrom dataclasses import replace\n\nimport numpy as np\nimport pytest\n\nfrom opentpu.llm import load_spec\nfrom opentpu.llm.moe import MoESpec\nfrom opentpu.llm.qwen3 import Engine, LazyWeights, device_config, load_weights\nfrom opentpu.llm.qwen35 import Spec\n\ntorch = pytest.importorskip(\"torch\")\ntransformers = pytest.importorskip(\"transformers\")\nsafetensors = pytest.importorskip(\"safetensors.torch\")\n\nKINDS = (\"linear\", \"linear\", \"attn\", \"linear\", \"linear\", \"attn\")\nE, K, F = 8, 2, 256\nV = 1000 + 80                   # 8 x 128 + 56: the head's last D block is partial\n\n\ndef _text_config(vocab):\n    return transformers.Qwen3_5MoeTextConfig(\n        hidden_size=256, num_hidden_layers=len(KINDS), num_attention_heads=8,\n        num_key_value_heads=2, head_dim=256, vocab_size=vocab,\n        layer_types=[\"full_attention\" if k == \"attn\" else \"linear_attention\" for k in KINDS],\n        linear_num_key_heads=4, linear_num_value_heads=8, linear_key_head_dim=128,\n        linear_value_head_dim=128, linear_conv_kernel_dim=4, tie_word_embeddings=False,\n        max_position_embeddings=4096, rms_norm_eps=1e-6, num_experts=E,\n        num_experts_per_tok=K, moe_intermediate_size=F, shared_expert_intermediate_size=F,\n        rope_parameters={\"rope_type\": \"default\", \"rope_theta\": 1e7, \"partial_rotary_factor\": 0.25,\n                         \"mrope_interleaved\": True, \"mrope_section\": [11, 11, 10]})\n\n\n@pytest.fixture(scope=\"module\")\ndef tiny(tmp_path_factory):\n    \"\"\"A tiny Qwen3.5-MoE (untied, V-token vocabulary) saved as MiniCPM-V's checkpoint is laid\n    out: (the model, its directory).\"\"\"\n    torch.manual_seed(0)\n    hc = _text_config(V)\n    m = transformers.Qwen3_5MoeForCausalLM(hc).float().eval()\n    with torch.no_grad():\n        for n, p in m.named_parameters():\n            if \"norm\" in n:     # zero-centered norms, but the DeltaNet output norm is plain\n                p.copy_((1.0 if n.endswith(\"linear_attn.norm.weight\") else 0.0)\n                        + 0.1 * torch.randn_like(p))\n            elif \"experts\" in n or \"gate\" in n:\n                p.copy_(0.05 * torch.randn_like(p))\n    d = tmp_path_factory.mktemp(\"minicpmv\")\n    sd = {(k if k == \"lm_head.weight\" else k.replace(\"model.\", \"model.language_model.\", 1)):\n          v.contiguous() for k, v in m.state_dict().items()}\n    sd[\"model.vision_tower.encoder.layers.0.mlp.fc1.weight\"] = torch.randn(64, 32)\n    sd[\"model.merger.mlp.0.linear_1.weight\"] = torch.randn(32, 32)\n    safetensors.save_file(sd, str(d / \"model.safetensors\"))\n    tc = hc.to_dict()\n    tc[\"model_type\"] = \"qwen3_5_moe_text\"\n    (d / \"config.json\").write_text(json.dumps({\n        \"architectures\": [\"MiniCPMV4_7ForConditionalGeneration\"], \"model_type\": \"minicpmv4_7\",\n        \"tie_word_embeddings\": False, \"text_config\": tc, \"insert_layer_id\": 0,\n        \"downsample_mode\": \"16x\", \"mrope_mode\": \"canvas\",\n        \"vision_config\": {\"hidden_size\": 128, \"intermediate_size\": 256, \"num_hidden_layers\": 2,\n                          \"num_attention_heads\": 2, \"image_size\": 56, \"patch_size\": 14,\n                          \"model_type\": \"minicpmv4_7_vision\"},\n        \"image_token_id\": 248056, \"image_start_id\": 248078, \"image_end_id\": 248079,\n        \"slice_start_id\": 248088, \"slice_end_id\": 248089, \"newline_id\": 198}))\n    return m, d\n\n\ndef test_a_minicpmv_checkpoint_is_a_qwen35_moe(tiny):\n    \"\"\"load_spec takes model_type minicpmv4_7 to qwen35's Spec from its text_config: the MoE,\n    an LM head of its own, the int8 embedding a MoE gathers, 1-D RoPE (mRoPE's text case).\"\"\"\n    m, d = tiny\n    s = load_spec(d)\n    assert isinstance(s, Spec) and s.moe == MoESpec(E=E, k=K, ffn=F, rule=\"softmax\", shared=F)\n    assert (s.vocab, s.tied, s.embed, s.rope_dim, s.lin_nk) == (V, False, \"int8\", 64, 4)\n    assert s.kinds == tuple(\"attn\" if k == \"attn\" else \"linear\" for k in KINDS)\n\n\ndef test_a_null_eos_id_is_the_default(tiny, tmp_path):\n    \"\"\"A config whose eos_token_id is null (the tiny checkpoints': HF's default) gives the\n    language model's end tokens, no None among them (otpu-serve's stops refused one).\"\"\"\n    m, d = tiny\n    top = json.loads((d / \"config.json\").read_text())\n    top[\"text_config\"][\"eos_token_id\"] = None\n    (tmp_path / \"config.json\").write_text(json.dumps(top))\n    assert load_spec(tmp_path).eos == (248046, 248044)\n    top[\"text_config\"][\"eos_token_id\"] = [248046, None]\n    (tmp_path / \"config.json\").write_text(json.dumps(top))\n    assert load_spec(tmp_path).eos == (248046,)\n\n\n@pytest.mark.parametrize(\"lazy\", [False, True])\ndef test_the_weights_are_the_language_models_alone(tiny, lazy):\n    \"\"\"The loaders give the language model under a text-only checkpoint's names, and none of\n    the vision tower's or projector's tensors (docs/minicpmv.md 4.1).\"\"\"\n    m, d = tiny\n    W = LazyWeights(d) if lazy else load_weights(d)\n    assert set(W) == set(m.state_dict())\n    for k in (\"model.embed_tokens.weight\", \"lm_head.weight\", \"model.layers.0.mlp.gate.weight\"):\n        assert np.array_equal(W[k], m.state_dict()[k].numpy())\n\n\ndef _engine(spec, W):\n    cfg = device_config(spec, 256, S=1)\n    return Engine(spec, W, cap=256, cfg=cfg)\n\n\ndef test_a_partial_head_block_is_the_padded_heads_logits(tiny):\n    \"\"\"The device's logits for a vocabulary of V = 8 x 128 + 56 rows are bit for bit those of\n    the same head padded with zero rows to 9 x 128 (the padding's logits 0): the LM head's\n    partial last D block, MiniCPM-V's 248,144 = 1938 x 128 + 80, needs no padding of its own.\n    Its last real id is checked on its own too. (The language model alone: vision None.)\"\"\"\n    m, d = tiny\n    spec = replace(load_spec(d), vision=None)\n    W = dict(load_weights(d).items())\n    Vp = -(-V // 128) * 128\n    Wp = dict(W)\n    for k in (\"lm_head.weight\", \"model.embed_tokens.weight\"):\n        Wp[k] = np.concatenate([W[k], np.zeros((Vp - V, spec.hidden), np.float32)])\n    toks = [int(t) for t in np.random.default_rng(4).integers(0, V, 6)]\n    a, b = _engine(spec, W), _engine(replace(spec, vocab=Vp), Wp)\n    for t in toks:\n        la, lb = a.step(t), b.step(t)\n        assert la.shape == (V,) and lb.shape == (Vp,)\n        assert np.array_equal(la.view(np.uint32), lb[:V].view(np.uint32))\n        assert la[V - 1].view(np.uint32) == lb[V - 1].view(np.uint32)\n        assert not np.any(lb[V:])\n\n\n# =============================================================================== vision (HF 5.18)\ndef _hf_tiny():\n    \"\"\"A tiny random MiniCPM-V 4.7 of HF's own classes (transformers >= 5.18), fp32.\"\"\"\n    if not hasattr(transformers, \"MiniCPMV4_7ForConditionalGeneration\"):\n        pytest.skip(\"transformers without minicpmv4_7 (>= 5.18)\")\n    import sys\n    from pathlib import Path\n    sys.path.insert(0, str(Path(__file__).resolve().parents[1] / \"tools\"))\n    import minicpmv_hf\n    import tempfile\n    d = minicpmv_hf.tiny_checkpoint(Path(tempfile.mkdtemp()))\n    m = transformers.MiniCPMV4_7ForConditionalGeneration.from_pretrained(\n        d, dtype=torch.float32).eval()\n    return m, d\n\n\n@pytest.fixture(scope=\"module\")\ndef hf_tiny():\n    return _hf_tiny()\n\n\n@pytest.mark.parametrize(\"size\", [(8, 12), (16, 8), (4, 4)])\ndef test_vision_reference_matches_hf(hf_tiny, size):\n    \"\"\"The numpy tower, window merger and projector (minicpmv.vision_reference) give HF's\n    get_image_features rows for a crop of h x w patches (fp32).\"\"\"\n    from opentpu.llm import minicpmv as MV\n    m, d = hf_tiny\n    vs = MV.VisionSpec.from_hf(d)\n    W = MV.load_vision(d)\n    h, w = size\n    rng = np.random.default_rng(h * 100 + w)\n    P = rng.uniform(-1, 1, (h * w, 3 * vs.patch ** 2)).astype(np.float32)\n    # HF's packing: [1, 3, patch, N * patch], patch l's block at columns l p .. l p + p\n    pv = torch.from_numpy(P.reshape(h * w, 3, vs.patch, vs.patch).transpose(1, 2, 0, 3)\n                          .reshape(1, 3, vs.patch, h * w * vs.patch))\n    with torch.no_grad():\n        hf = m.model.get_image_features(pv, torch.tensor([[h, w]])).pooler_output[0].numpy()\n    ours = MV.vision_reference(vs, W, P, (h, w))\n    assert ours.shape == hf.shape == (h * w // 16, 256)\n    assert np.abs(ours - hf).max() < 2e-5 * max(1.0, np.abs(hf).max())\n\n\ndef test_canvas_positions_match_hf(hf_tiny):\n    \"\"\"minicpmv.rope_index gives HF's get_rope_index: text, one image without slices, one with\n    a 2 x 3 grid of slices, the image-id prefix and the newline after it, text between.\"\"\"\n    from opentpu.llm import minicpmv as MV\n    m, d = hf_tiny\n    vs = MV.VisionSpec.from_hf(d)\n    P = vs.image_token\n\n    def image(th, tw, grid=None, sh=0, sw=0, idt=(7, 8, 9)):\n        ids = list(idt) + [vs.image_start] + [P] * (th * tw // 16) + [vs.image_end]\n        sizes = [(th, tw)]\n        if grid:\n            rows = []\n            for r in range(grid[0]):\n                rows.append(([vs.slice_start] + [P] * (sh * sw // 16) + [vs.slice_end])\n                            * grid[1])\n                sizes += [(sh, sw)] * grid[1]\n            ids += sum((r + ([vs.newline] if i + 1 < grid[0] else []) for i, r in\n                        enumerate(rows)), [])\n        return ids, sizes\n    cases = []\n    a, sa = image(8, 12)\n    b, sb = image(16, 8, (2, 3), 8, 12)\n    cases.append(([1, 2, 3] + a + [vs.newline, 5, 6] + b + [vs.newline, 9, 10, 11], sa + sb))\n    cases.append(([4] * 5 + b + [12, 13], sb))\n    cases.append(([1, 2, 3, 4, 5], []))\n    for ids, sizes in cases:\n        mm = [1 if t == P else 0 for t in ids]\n        kw = {}\n        if sizes:\n            kw = dict(mm_token_type_ids=torch.tensor([mm]), target_sizes=torch.tensor(sizes))\n        else:\n            kw = dict(mm_token_type_ids=torch.tensor([mm]), target_sizes=torch.zeros(0, 2,\n                                                                                 dtype=torch.long))\n        hp, hd = m.model.get_rope_index(torch.tensor([ids]), **kw)\n        pos, delta = MV.rope_index(ids, sizes, vs)\n        assert np.array_equal(pos, hp[:, 0].numpy()), (ids, pos, hp[:, 0])\n        assert delta == int(hd[0, 0])\n\n\n# =============================================================================== vision on the card\ndef _tiny_vision_weights(vs, rng):\n    \"\"\"Random weights of a tiny vision tower, window merger and projector (load_vision's\n    names).\"\"\"\n    from opentpu.llm import minicpmv as MV\n    C, F, W = vs.hidden, vs.ffn, {}\n\n    def lin(n, o, i):\n        W[n + \".weight\"] = (rng.standard_normal((o, i)) / np.sqrt(i)).astype(np.float32)\n        W[n + \".bias\"] = (0.1 * rng.standard_normal(o)).astype(np.float32)\n\n    def ln(n, k):\n        W[n + \".weight\"] = (1 + 0.1 * rng.standard_normal(k)).astype(np.float32)\n        W[n + \".bias\"] = (0.1 * rng.standard_normal(k)).astype(np.float32)\n\n    def attn(p):\n        for n in (\"q_proj\", \"k_proj\", \"v_proj\", \"out_proj\"):\n            lin(p + \"self_attn.\" + n, C, C)\n        ln(p + \"layer_norm1\", C)\n    for i in range(vs.layers):\n        p = f\"{MV.TOWER}encoder.layers.{i}.\"\n        attn(p)\n        ln(p + \"layer_norm2\", C)\n        lin(p + \"mlp.fc1\", F, C)\n        lin(p + \"mlp.fc2\", C, F)\n    p = MV.TOWER + \"vit_merger.\"\n    attn(p)\n    ln(p + \"pre_norm\", 4 * C)\n    lin(p + \"linear_1\", 4 * F, 4 * C)\n    lin(p + \"linear_2\", C, 4 * F)\n    ln(MV.TOWER + \"post_layernorm\", C)\n    p = MV.MERGER + \"mlp.0.\"\n    ln(p + \"pre_norm\", 4 * C)\n    lin(p + \"linear_1\", 4 * C, 4 * C)\n    lin(p + \"linear_2\", vs.out, 4 * C)\n    k = vs.patch\n    W[MV.TOWER + \"embeddings.patch_embedding.weight\"] = \\\n        (rng.standard_normal((C, 3, k, k)) / 24).astype(np.float32)\n    W[MV.TOWER + \"embeddings.patch_embedding.bias\"] = (0.1 * rng.standard_normal(C)).astype(\n        np.float32)\n    W[MV.TOWER + \"embeddings.position_embedding.weight\"] = \\\n        (0.5 * rng.standard_normal((vs.side ** 2, C))).astype(np.float32)\n    return W\n\n\n@pytest.fixture(scope=\"module\")\ndef tiny_tower():\n    \"\"\"A tiny tower (C 256, 4 heads of 64: padded to D on the card, an MLP of 300: padded to\n    its chunks; 3 layers, the window merger after layer 1) on the ISA simulator.\"\"\"\n    from opentpu.isasim import board_config\n    from opentpu.llm import minicpmv as MV\n    from opentpu.llm.qwen3 import IsaBackend, _Bump\n    vs = MV.VisionSpec(hidden=256, heads=4, ffn=300, layers=3, side=5, insert=1, out=256)\n    W = _tiny_vision_weights(vs, np.random.default_rng(0))\n    cfg = board_config(DRAM_BYTES=1 << 26)\n    vi = MV.VisionImage(vs, cfg, _Bump(), nmax=256, out_rows=64)\n    img = np.zeros(cfg.DRAM_BYTES, np.uint8)\n\n    def put(addr, a):\n        v = np.ascontiguousarray(a).view(np.uint8).reshape(-1)\n        img[addr:addr + v.size] = v\n    vi.build(W, put)\n    return vs, W, vi, IsaBackend(cfg, [img])\n\n\n@pytest.mark.parametrize(\"size\", [(4, 4), (8, 12), (16, 12), (12, 20)])\ndef test_the_tower_on_the_card_is_the_reference(tiny_tower, size):\n    \"\"\"A crop of h x w patches through the card's tower, window merger and projector\n    (VisionImage.encode: its programs on the ISA simulator, int8 weights and operands) gives\n    vision_reference's rows (fp32) to within int8's error: every row's cosine >= 0.999. Sizes\n    of one window block (4 x 4), of less and more than one D-token stretch of the window\n    attention (96, 192, 240 patches).\"\"\"\n    from opentpu.kernels.lib import gelu_tanh\n    from opentpu.llm import minicpmv as MV\n    vs, W, vi, be = tiny_tower\n    h, w = size\n    P = np.random.default_rng(h * 100 + w).uniform(-1, 1, (h * w, 3 * vs.patch ** 2)).astype(\n        np.float32)\n    got = vi.encode(be, P, size, proj_gelu=gelu_tanh)\n    ref = MV.vision_reference(vs, W, P, size, gelu=MV._gelu_tanh)\n    assert got.shape == ref.shape == (h * w // 16, vs.out)\n    cos = (got * ref).sum(-1) / np.linalg.norm(got, axis=-1) / np.linalg.norm(ref, axis=-1)\n    assert cos.min() >= 0.999, cos.min()\n    assert np.abs(got - ref).max() < 0.05 * np.abs(ref).max()\n\n\n@pytest.mark.parametrize(\"size\", [(8, 12), (16, 12)])\ndef test_the_odd_stride_residual_gives_the_same_rows(tiny_tower, size, monkeypatch):\n    \"\"\"vit_out_mlp's residual at an odd row stride (its default: W_down's drain at the array's\n    rate) and at its DRAM stride (one LD, the layout before) give the tower's rows bit for bit:\n    the same arithmetic in another TMEM layout.\"\"\"\n    from opentpu import isa as I\n    from opentpu.kernels import vit as VK\n    from opentpu.kernels.lib import gelu_tanh\n    vs, W, vi, be = tiny_tower\n    h, w = size\n    P = np.random.default_rng(7).uniform(-1, 1, (h * w, 3 * vs.patch ** 2)).astype(np.float32)\n    lds = lambda: sum(i.op == I.LD for i in vi.programs(h * w)[0][\"out\"][0])\n    n_odd = lds()\n    odd = vi.encode(be, P, size, proj_gelu=gelu_tanh)\n    real = VK.vit_out_mlp\n\n    class Dense:\n        def trace(self, cfg, sid, bound):\n            return real.trace(cfg, sid, {**bound, \"odd\": False})\n    monkeypatch.setattr(VK, \"vit_out_mlp\", Dense())\n    assert lds() < n_odd\n    dense = vi.encode(be, P, size, proj_gelu=gelu_tanh)\n    assert np.array_equal(odd.view(np.uint32), dense.view(np.uint32))\n\n\n@pytest.mark.parametrize(\"fmt\", [\"int8\", \"attn=fp4,mlp=fp4,wm=fp4,proj=fp4\"])\ndef test_the_piece_table_is_the_static_layout(fmt):\n    \"\"\"The pieced weights' table (kernels/pieces.py): the tower's rows with every piece address\n    read from the table, the pieces resident, and with the pieces staged at scattered\n    slot-like addresses (shuffled, as an expert server's victims fall), are the rows of the\n    same pieces at static addresses, bit for bit: only the address source changes. Pieces of\n    at most 300 KB (160 KB at fp4): the window merger's 512-row W1 chunks span two pieces (one\n    MM a piece, each writing its columns), several W2 column parts share a piece.\"\"\"\n    from opentpu.isasim import board_config\n    from opentpu.kernels.lib import gelu_tanh\n    from opentpu.llm import minicpmv as MV\n    from opentpu.llm.qwen3 import IsaBackend, _Bump\n    vs = MV.VisionSpec(hidden=256, heads=4, ffn=300, layers=3, side=5, insert=1, out=256)\n    rng = np.random.default_rng(8)\n    W = _tiny_vision_weights(vs, rng)\n    cfg = board_config(DRAM_BYTES=1 << 27)\n    size = (8, 12)\n    P = rng.uniform(-1, 1, (96, 3 * vs.patch ** 2)).astype(np.float32)\n    outs = []\n    for mode in (\"static\", \"table\", \"staged\"):\n        vi = MV.VisionImage(vs, cfg, _Bump(), nmax=256, out_rows=64, fmt=fmt,\n                            max_piece=300_000 if fmt == \"int8\" else 160_000,\n                            resident=mode != \"staged\",\n                            table=mode != \"static\")\n        img = np.zeros(cfg.DRAM_BYTES, np.uint8)\n\n        def put(addr, a):\n            v = np.ascontiguousarray(a).view(np.uint8).reshape(-1)\n            img[addr:addr + v.size] = v\n        vi.build(W, put)\n        if mode == \"staged\":\n            pcs = vi.piece_bytes(W)\n            pitch = -(-max(len(p) for p in pcs) // 4096) * 4096\n            base = -(-vi.end // 4096) * 4096\n            at = base + rng.permutation(len(pcs)) * pitch\n            for a, p in zip(at, pcs):\n                put(int(a), p)\n            put(vi.table, at.astype(np.uint32))\n            vi.set_bound(base, base + (len(pcs) - 1) * pitch)\n        outs.append(vi.encode(IsaBackend(cfg, [img]), P, size, proj_gelu=gelu_tanh))\n    wm = vi.mmats[\"wm\"]\n    assert len(wm[\"w1\"].groups) > vi.FW // vi.WCHUNK\n    assert any(b - a > 1 for a, b in wm[\"w2\"].groups + vi.lmats[\"w2\"].groups)\n    for got in outs[1:]:\n        assert np.array_equal(got.view(np.uint32), outs[0].view(np.uint32))\n\n\n@pytest.mark.parametrize(\"pool\", [False, True])\ndef test_staged_vision_is_the_resident_towers(tiny, pool, tmp_path):\n    \"\"\"Staged vision weights (Spec.vision_staged, docs/minicpmv.md 4.2): the pieces the\n    programs read are the pool's entries past the experts, placed in expert slots by the\n    expert server for an encode (its victims the least used experts, every slot warm here),\n    their table written, the slots released after it. Two images' crops give the resident\n    tower's rows bit for bit; the server's slots are each layer's again, and a prompt's\n    prefill (the evicted experts missing) and two decode steps give the resident engine's\n    logits bit for bit. pool: the entries in a pool file (the split format, each packed on\n    its first use, as on the card host) instead of host RAM.\"\"\"\n    from types import SimpleNamespace\n    from opentpu.llm import minicpmv as MV\n    m, d = tiny\n    spec = replace(load_spec(d), vision_patches=128, vision_rows=64)\n    assert spec.vision_staged                   # (the default)\n    W = dict(load_weights(d).items())\n    W.update(_tiny_vision_weights(spec.vision, np.random.default_rng(7)))\n    cfg = device_config(spec, 256, rows=1, lookup=True, S=1, experts=E)\n    kw = dict(cap=256, cfg=cfg, rows=1, resident=True, experts=E, layer_major=2)\n    a = Engine(replace(spec, vision_staged=False), W, **kw)\n    b = Engine(spec, W, **(dict(kw, pool_file=tmp_path / \"pool.bin\") if pool else kw))\n    with pytest.raises(ValueError, match=\"staged vision: .* pieces\"):   # (2 k slots a layer)\n        spec.image(device_config(spec, 256, rows=1, lookup=True, S=1, experts=2 * K), 256, 1, 1,\n                   experts=2 * K).check_room()\n    va, vb = a.image.vision, b.image.vision\n    assert va.resident and not vb.resident and vb.max_piece <= b.image.offload.slot_bytes\n    assert b.image.pool_extra[0] == vb.npieces and a.image.pool_extra is None\n    rng = np.random.default_rng(9)\n    ims = [SimpleNamespace(patches=[rng.uniform(-1, 1, (h * w, 3 * 14 * 14)).astype(\n        np.float32)], sizes=[(h, w)], tokens=h * w // 16) for h, w in ((8, 8), (4, 12))]\n    rows = []\n    for e in (a, b):\n        n = MV.Vision(e).encode(ims)\n        rows.append(e.backend.read(0, e.image.vision.work[\"vis\"], 4 * n * spec.vision.out))\n    assert n == 7 and np.array_equal(rows[0], rows[1])\n    srv = b.server\n    if pool:                            # (the pieces the programs read packed, in the file)\n        pf = srv.pool_file\n        G = srv.L.layers * srv.L.E\n        assert pf.split and len(pf.packed) == G + vb.npieces\n        assert all(pf.packed[G + i] for i in vb.used())\n    assert srv.placed == {} and srv.place_victims > 0\n    assert srv.place_bytes >= sum(vb.piece_sizes()[i] for i in vb.used())\n    assert all(len(srv.lru[j]) + len(srv.free[j]) == E for j in range(srv.L.layers))\n    toks = [int(t) for t in rng.integers(0, V - 40, 21)]\n    la, lb = a.prefill_layers(toks), b.prefill_layers(toks)\n    assert np.array_equal(la.view(np.uint32), lb.view(np.uint32))\n    t = int(np.argmax(la))\n    for _ in range(2):\n        ga, gb = a.step(t), b.step(t)\n        assert np.array_equal(ga.view(np.uint32), gb.view(np.uint32))\n        t = int(np.argmax(ga))\n\n\ndef test_streamed_engine_opens_staged_vision_past_its_probe(tiny):\n    \"\"\"streamed.engine's own path with staged vision (the default): its probe image (the\n    layout alone, k slots a layer: no room past k for the pieces) builds, fit_experts sizes the\n    engine's slots, the engine's image has the room (Image.check_room) and a Vision opens on\n    it; an engine of k slots a layer is refused when it opens. Session mcpv3's first run\n    (2026-10-13) died at the probe: the room was checked in every image's constructor.\"\"\"\n    from opentpu.host import streamed as ST\n    from opentpu.isasim import board_config\n    from opentpu.llm import minicpmv as MV\n    m, d = tiny\n    spec = load_spec(d)\n    assert spec.vision_staged\n    W = dict(load_weights(d).items())\n    W.update(_tiny_vision_weights(spec.vision, np.random.default_rng(7)))\n    cfg = board_config(DRAM_BYTES=1 << 26)\n    kw = dict(wformat=\"int8\", head_format=None)  # (int8 slots: the tiny tower's units fit)\n    pr = ST.probe(spec, cfg, 256, lookup=True, **kw)\n    assert not pr.vision.resident and {n for _, n in pr.offload.slots} == {K}\n    with pytest.raises(ValueError, match=\"staged vision: .* pieces, 0 expert slots past k\"):\n        pr.check_room()\n    eng = ST.engine(d, cfg, \"isa\", 256, None, W=W, vision_warm=False, **kw)\n    assert not eng.image.vision.resident and min(n for _, n in eng.image.offload.slots) > K\n    MV.Vision(eng)\n    with pytest.raises(ValueError, match=\"staged vision: .* pieces\"):\n        ST.engine(d, cfg, \"isa\", 256, None, experts=K, W=W, vision_warm=False, **kw)\n\n\ndef test_the_real_staged_layout_has_room_at_the_cards_slots(tmp_path):\n    \"\"\"MiniCPM-V 4.7's own layout (its config: Qwen3.5-35B-A3B's language model, SigLIP2's\n    tower; the family's formats, chat's 2,048-token cache) on the card's 4 GiB, as\n    streamed.engine opens it: the probe image builds at k slots a layer, the slots that fit\n    (fit_experts: 36 a layer, mcpv2's) give the engine's image the room for every staged piece,\n    and at k slots a layer they do not fit. Layouts only, no weights.\"\"\"\n    from opentpu.host import streamed as ST\n    from opentpu.isasim import board_config\n    tc = transformers.Qwen3_5MoeTextConfig(\n        hidden_size=2048, num_hidden_layers=40, num_attention_heads=16, num_key_value_heads=2,\n        head_dim=256, vocab_size=248144, full_attention_interval=4, attn_output_gate=True,\n        linear_num_key_heads=16, linear_num_value_heads=32, linear_key_head_dim=128,\n        linear_value_head_dim=128, linear_conv_kernel_dim=4, tie_word_embeddings=False,\n        max_position_embeddings=262144, rms_norm_eps=1e-6, num_experts=256,\n        num_experts_per_tok=8, moe_intermediate_size=512, shared_expert_intermediate_size=512,\n        rope_parameters={\"rope_type\": \"default\", \"rope_theta\": 1e7, \"partial_rotary_factor\": 0.25,\n                         \"mrope_interleaved\": True, \"mrope_section\": [11, 11, 10]}).to_dict()\n    tc[\"model_type\"] = \"qwen3_5_moe_text\"\n    (tmp_path / \"config.json\").write_text(json.dumps({\n        \"architectures\": [\"MiniCPMV4_7ForConditionalGeneration\"], \"model_type\": \"minicpmv4_7\",\n        \"tie_word_embeddings\": False, \"text_config\": tc, \"insert_layer_id\": 6,\n        \"downsample_mode\": \"16x\", \"mrope_mode\": \"canvas\",\n        \"vision_config\": {\"hidden_size\": 1152, \"intermediate_size\": 4304,\n                          \"num_hidden_layers\": 27, \"num_attention_heads\": 16, \"image_size\": 980,\n                          \"patch_size\": 14, \"model_type\": \"minicpmv4_7_vision\"},\n        \"image_token_id\": 248056, \"image_start_id\": 248078, \"image_end_id\": 248079,\n        \"slice_start_id\": 248088, \"slice_end_id\": 248089, \"newline_id\": 198}))\n    spec = load_spec(tmp_path)\n    assert spec.vision_staged and spec.moe.k == 8 and spec.vision.layers == 27\n    wformat, head, formats = ST.defaults(spec)\n    spec = replace(spec, formats=formats)\n    cfg = board_config(DRAM_BYTES=1 << 32, MCOLS=4, ACT_ROWS=16, PAIR=True, DSTEP=True,\n                       STREAM=True)\n    kw = dict(wformat=wformat, head_format=head, lookup=True)\n    pr = ST.probe(spec, cfg, 2048, **kw)\n    n = ST.fit_experts(spec, cfg, 2048, pr)\n    assert n == 36\n    with pytest.raises(ValueError, match=\"staged vision: .* pieces, 0 expert slots past k\"):\n        pr.check_room()\n    spec.image(cfg, 2048, 1, 1, experts=n, **kw).check_room()\n\n\ndef test_a_pool_takes_the_vision_entries_past_its_experts(tmp_path):\n    \"\"\"open_pool's extra entries (staged vision's pieces, pool_key's \"vision\"): an experts-only\n    pool grows by them, its experts kept and they not packed; a run without them opens it as\n    its experts'; the same vision key keeps them; another one replaces them (not packed).\"\"\"\n    from opentpu.host.offload import Layout\n    from opentpu.llm import moe as MO\n    lay = Layout.build(4096, 4, 2, (2, 2), 4096)\n    key = {\"key\": 2, \"numerics\": 1, \"quant\": \"q\", \"format\": \"fp4\", \"D\": 128,\n           \"layout\": {\"layers\": 2}, \"checkpoint\": None}\n    p = tmp_path / \"pool.bin\"\n    n = 8\n\n    def opened(k, extra=0):\n        pf = MO.open_pool(lay, p, key=k, extra=extra)\n        if pf.warm_t is not None:\n            pf.warm_t.join()\n        return pf\n    pf = opened(key)\n    pf.arr[:] = np.arange(n, dtype=np.uint8)[:, None] + 1\n    pf.packed[:] = 1\n    pf.arr.flush()\n    pf.packed.flush()\n    vk = {\"entries\": 3, \"format\": \"int8\", \"pieces\": \"a\"}\n    pf = opened({**key, \"vision\": vk}, 3)\n    assert p.stat().st_size == 11 * 4096 and list(pf.packed) == [1] * n + [0] * 3\n    assert all(pf.arr[g][0] == g + 1 for g in range(n)) and not pf.arr[n:].any()\n    pf.arr[n:] = 77\n    pf.packed[n:] = 1\n    pf.arr.flush()\n    pf.packed.flush()\n    pf = opened(key)                    # a run without vision: its experts\n    assert pf.arr.shape[0] == n and p.stat().st_size == 11 * 4096\n    assert json.loads((tmp_path / \"pool.bin.key\").read_text())[\"vision\"] == vk\n    pf = opened({**key, \"vision\": vk}, 3)\n    assert list(pf.packed) == [1] * 11 and pf.arr[9][0] == 77\n    vk2 = {\"entries\": 2, \"format\": \"attn=fp4\", \"pieces\": \"b\"}\n    pf = opened({**key, \"vision\": vk2}, 2)\n    assert p.stat().st_size == 10 * 4096 and list(pf.packed) == [1] * n + [0] * 2\n    assert not pf.arr[n:].any() and pf.arr[3][0] == 4\n    with pytest.raises(ValueError):     # another experts' key is refused as before\n        opened({**key, \"format\": \"int8\", \"vision\": vk2}, 2)\n\n\ndef test_pack_pool_keys_the_experts_alone(tiny, tmp_path, monkeypatch):\n    \"\"\"pack_pool.py on MiniCPM-V (whose image stages its vision by default: pool_key's \"vision\"\n    and pool_extra): init writes the experts' key alone, as the file holds the experts alone;\n    the first staged open appends the vision entries (open_pool's extra) and keeps the experts\n    packed since. With the vision key on an experts-only file, pool_entries would count the\n    entries in it, and open_pool would take the file for a new pool and truncate it.\"\"\"\n    import importlib.util\n    import sys\n    from pathlib import Path\n    from opentpu.isasim import board_config\n    from opentpu.llm import moe as MO\n    _, d = tiny\n    pool = tmp_path / \"pool.bin\"\n    tool = Path(__file__).resolve().parents[1] / \"tools\" / \"offload\" / \"pack_pool.py\"\n    PP = importlib.util.module_from_spec(importlib.util.spec_from_file_location(\"pp\", tool))\n    PP.__spec__.loader.exec_module(PP)\n    # (pack_pool's image, the tiny tower's patches cut so that its pieces fit the slots)\n    spec = replace(load_spec(d), vision_patches=128, vision_rows=64)\n    img = spec.image(replace(board_config(), DRAM_BYTES=1 << 40), 1024, 1, 1, \"int8\", \"int8\",\n                     lookup=True, experts=spec.moe.k)\n    monkeypatch.setattr(PP, \"image\", lambda model, wformat, mtp=False: img)\n    monkeypatch.setattr(sys, \"argv\", [\"pack_pool.py\", str(d), str(pool), \"init\"])\n    PP.main()\n    lay, (extra, vk) = img.offload, img.pool_extra\n    n = lay.layers * lay.E\n    key = json.loads((tmp_path / \"pool.bin.key\").read_text())\n    assert \"vision\" not in key and MO.pool_entries(pool, n) == n\n    assert key == {k: v for k, v in MO.pool_key(img, str(d)).items() if k != \"vision\"}\n    pf = MO.open_pool(lay, pool, key=key)              # a pack worker's expert\n    pf.warm_t.join()\n    pf.arr[3] = 9\n    pf.packed[3] = 1\n    pf.arr.flush()\n    pf.packed.flush()\n    del pf\n    pf = MO.open_pool(lay, pool, key=MO.pool_key(img, str(d)), extra=extra)\n    pf.warm_t.join()\n    assert pool.stat().st_size == (n + extra) * lay.slot_bytes\n    assert pf.packed[3] == 1 and (pf.arr[3] == 9).all() and not pf.packed[n:].any()\n    assert json.loads((tmp_path / \"pool.bin.key\").read_text())[\"vision\"] == vk\n\n\ndef test_the_card_order_puts_each_window_in_consecutive_rows():\n    \"\"\"card_order: each 4 x 4 block of the grid row-major, its 2 x 2 windows row-major, their\n    4 patches row-major. Windows are consecutive rows (windows()' rows, in their order), and\n    so are the blocks (the projector's output rows: the h/4 x w/4 grid row-major).\"\"\"\n    from opentpu.llm import minicpmv as MV\n    for h, w in ((4, 4), (8, 12), (12, 8), (16, 20)):\n        o = MV.card_order(h, w)\n        assert sorted(o) == list(range(h * w))\n        assert {tuple(r) for r in o.reshape(-1, 4)} == {tuple(r) for r in MV.windows(h, w)}\n        blocks = o.reshape(-1, 16)\n        assert np.array_equal(np.sort(blocks, 1), np.sort(MV.windows(h, w, 4), 1))\n        for b in blocks:            # a block's windows row-major: (0, 0), (0, 1), (1, 0), (1, 1)\n            r, c = b // w, b % w\n            assert list(zip(r[::4] // 2 % 2, c[::4] // 2 % 2)) == [(0, 0), (0, 1), (1, 0), (1, 1)]\n\n\ndef test_the_real_towers_programs_fit_the_card():\n    \"\"\"MiniCPM-V 4.7's tower (C 1152, 16 heads of 72, 27 layers) compiles for the card's\n    configuration (TMEM, ACT RAM) at crops of 1024, 1056 and 2048 patches, each program within\n    IMEM.\"\"\"\n    from opentpu.isasim import board_config\n    from opentpu.llm import minicpmv as MV\n    from opentpu.llm.qwen3 import _Bump\n    cfg = board_config()\n    vi = MV.VisionImage(MV.VisionSpec(), cfg, _Bump(), nmax=2048, out_rows=2048)\n    for N in (1024, 1056, 2048):\n        progs, runs = vi.programs(N)\n        assert len(runs) == 1 + 3 * 7 + 4 + 3 * 20 + 1\n        for name, (p, _) in progs.items():\n            assert len(p) <= cfg.IMEM_WORDS // 8, (N, name, len(p))\n\n\ndef test_the_towers_mms_drain_at_the_arrays_rate():\n    \"\"\"Every MM of the real tower's programs drains at its array's rate (compiler.slow_drains:\n    where the array takes fewer cycles a column than its rows, their results are in distinct\n    TMEM banks). W_down's ACC into the residual (vit_out_mlp: KB 2, 8 cycles a column for 16\n    rows) needs the odd-stride tile it is loaded into: at its DRAM stride (C = 1152, a multiple\n    of the banks) W_down's MMs ran at 40% of their pops (docs/minicpmv.md 6). vit_embed's (KB 5)\n    keeps the dense stride and its one LD.\"\"\"\n    from conftest import assert_drains_keep_up\n    from opentpu.isasim import board_config\n    from opentpu.llm import minicpmv as MV\n    from opentpu.llm.qwen3 import _Bump\n    cfg = board_config()\n    vi = MV.VisionImage(MV.VisionSpec(), cfg, _Bump(), nmax=256, out_rows=16)\n    P, _ = vi.programs(256)\n    assert assert_drains_keep_up([p for p, _ in P.values()], cfg) > 50\n\n\n@pytest.mark.parametrize(\"staged\", [False, True])\ndef test_the_towers_wait_entries_are_the_exact_passes(staged):\n    \"\"\"The real tower's programs at 256 patches, resident and staged (the pieces' addresses\n    from the table, RLD-bounded): waits' memoized pass (wait_counts' default) gives the exact\n    pass's entries.\"\"\"\n    from opentpu import waits as WC\n    from opentpu.isasim import board_config\n    from opentpu.llm import minicpmv as MV\n    from opentpu.llm.qwen3 import _Bump\n    cfg = board_config()\n    vi = MV.VisionImage(MV.VisionSpec(), cfg, _Bump(), nmax=256, out_rows=16, resident=not staged)\n    if staged:\n        vi.set_bound(1 << 28, 1 << 30)\n    P, _ = vi.programs(256)\n    for name, (p, ra) in P.items():\n        a = WC.wait_counts(p, cfg.D, cfg.S, run_args=ra, memo=False)\n        assert np.array_equal(a, WC.wait_counts(p, cfg.D, cfg.S, run_args=ra)), name\n\n\ndef test_the_warm_counts_are_the_processors():\n    \"\"\"vision_warm.counts: every crop's patch count the processor gives (minicpmv.crops: the\n    thumbnail and the slices) of images of odd sizes at 1 and 9 slices is among them, each a\n    multiple of 16 (two 2 x 2 merges), 1,008 and 1,024 among the four most frequent.\"\"\"\n    from opentpu.host import vision_warm as VW\n    from opentpu.llm import minicpmv as MV\n    vs = MV.VisionSpec()\n    ns = VW.counts(vs, step=100)\n    assert all(n % 16 == 0 for n in ns) and {1008, 1024} <= set(ns[:4])\n    for H, W in ((300, 500), (1080, 1920), (3000, 400), (777, 777), (250, 3900)):\n        for ms in (1, 9):\n            cs, _ = MV.crops(torch.zeros((3, H, W), dtype=torch.uint8), vs, ms)\n            for c in cs:\n                assert (c.shape[-2] // vs.patch) * (c.shape[-1] // vs.patch) in ns, (H, W, ms)\n\n\ndef test_warm_entries_are_found_by_the_first_start(tiny, tmp_path, monkeypatch):\n    \"\"\"vision_warm.warm: the tower's programs at a patch count traced and their wait entries\n    computed into the program cache's disk, where a first start's (BoardBackend._entries:\n    waits.entries of the assembled words alone) finds every one, none computed; a second warm\n    finds its marker and computes nothing; with an entry gone it computes them again. start()\n    leaves a backend that takes no entries (the ISA simulator's) alone.\"\"\"\n    from types import SimpleNamespace\n    from opentpu import isa as I\n    from opentpu import waits as WC\n    from opentpu.compiler import Words\n    from opentpu.host import vision_warm as VW\n    monkeypatch.setenv(\"OTPU_PROG_CACHE\", str(tmp_path))\n    m, d = tiny\n    spec = replace(load_spec(d), vision_patches=128, vision_rows=64)\n    cfg = device_config(spec, 256, rows=1, lookup=True, S=1, experts=E)\n    image = spec.image(cfg, 256, 1, 1, experts=E)\n    layout = (\"test\", spec, cfg)\n    assert VW.warm(image, layout, 64)\n    WC._mem.clear()\n    c0, d0 = WC.stats[\"computed\"], WC.stats[\"disk\"]\n    P, _ = image.vision.programs(64)\n    for p, ra in P.values():\n        WC.entries(Words.of(I.assemble(p), ra), cfg.D, cfg.S)\n    assert WC.stats[\"computed\"] == c0 and WC.stats[\"disk\"] == d0 + len(P)\n    assert not VW.warm(image, layout, 64)\n    next(tmp_path.glob(\"*/*.npz\")).unlink()\n    assert VW.warm(image, layout, 64)\n    assert VW.start(SimpleNamespace(image=image, backend=SimpleNamespace())) is None\n    # the process (spawned: the engine's arguments pickled, opentpu imported anew); the\n    # processor's counts exceed this work area's 128 patches, so it builds the image and ends\n    p = VW.start(SimpleNamespace(image=image, backend=SimpleNamespace(waitc=True), spec=spec,\n                                 cfg=cfg, cap=256, batch=1, rows=1, _image_kw={\"experts\": E},\n                                 layout=layout))\n    p.join(120)\n    assert p.exitcode == 0\n\n\ndef test_the_card_tower_is_hfs(hf_tiny):\n    \"\"\"HF's tiny MiniCPM-V (its own weights, load_vision's reading of them) on the card's\n    tower (int8, ISA simulator): HF's get_image_features rows to within int8's error, two\n    crops of a 12 x 16 and a 16 x 8 grid.\"\"\"\n    import sys\n    from pathlib import Path\n    sys.path.insert(0, str(Path(__file__).resolve().parents[1] / \"tools\"))\n    import minicpmv_hf\n    from opentpu.llm import minicpmv as MV\n    m, d = hf_tiny\n    vs = MV.VisionSpec.from_hf(d)\n    vi, be = minicpmv_hf.card_tower(vs, MV.load_vision(d))\n    for h, w in ((12, 16), (16, 8)):\n        P = np.random.default_rng(h + w).uniform(-1, 1, (h * w, 3 * vs.patch ** 2)).astype(\n            np.float32)\n        pv = torch.from_numpy(P.reshape(h * w, 3, vs.patch, vs.patch).transpose(1, 2, 0, 3)\n                              .reshape(1, 3, vs.patch, h * w * vs.patch))\n        with torch.no_grad():\n            hf = m.model.get_image_features(pv, torch.tensor([[h, w]])).pooler_output[0].numpy()\n        got = vi.encode(be, P, (h, w))\n        cos = (got * hf).sum(-1) / np.linalg.norm(got, axis=-1) / np.linalg.norm(hf, axis=-1)\n        assert cos.min() >= 0.999, cos.min()\n\n\n# =============================================================================== image rows\n@pytest.mark.parametrize(\"em\", [False, True])\ndef test_image_rows_are_layer_zeros_input(tiny, em, monkeypatch):\n    \"\"\"A prompt's image rows (Engine.prefill_layers' vis: each its row of the image's projector\n    output, minicpmv.Image's vis) enter layer 0 as those rows: a copy run into the chunk's\n    residual rows (em: expert-major's records) and an embedded layer run. Image rows whose\n    values an int8 embedding row holds exactly (each D block q 2^-7 with a 127 in it) give\n    the logits, bit for bit, of the same prompt with text ids whose (host-gathered) embedding\n    rows are those values; then three decode steps too. 20 image rows from vis row 5, after 9\n    text rows, in chunks of 24 rows (the image crosses a chunk), runs of 2 rows.\"\"\"\n    from opentpu.llm import qwen35 as Q35\n    monkeypatch.setattr(Q35, \"PREFILL_CHUNK\", 24)\n    m, d = tiny\n    spec = replace(load_spec(d), vision_patches=128, vision_rows=64,\n                   vision_staged=False)         # (2 k slots a layer: too few to stage)\n    rng = np.random.default_rng(3)\n    W = dict(load_weights(d).items())\n    W.update(_tiny_vision_weights(spec.vision, rng))\n    n, at, v0 = 20, 9, 5\n    q = rng.integers(-127, 128, (n, spec.hidden))\n    q[:, ::128] = 127\n    rows = (q * 2.0 ** -7).astype(np.float32)\n    fake = list(range(V - 5 - n, V - 5))       # ids whose embedding rows are the image rows\n    W[\"model.embed_tokens.weight\"] = W[\"model.embed_tokens.weight\"].copy()\n    W[\"model.embed_tokens.weight\"][fake] = rows\n    toks = [int(t) for t in rng.integers(0, V - 40, 31)]\n    cfg = device_config(spec, 256, rows=1, lookup=True, S=1, experts=2 * K)\n    kw = dict(cap=256, cfg=cfg, rows=1, resident=True, experts=2 * K, layer_major=2)\n    if em:\n        kw[\"expert_major\"] = True\n    a, b = Engine(spec, W, **kw), Engine(spec, W, **kw)\n    assert a.image.vision is not None and a.expert_major == em\n    a.backend.write(0, a.image.vision.work[\"vis\"] + 4 * v0 * spec.hidden, rows)\n    vis = [-1] * at + list(range(v0, v0 + n)) + [-1] * (len(toks) - at)\n    la = a.prefill_layers(toks[:at] + [0] * n + toks[at:], vis=vis)\n    lb = b.prefill_layers(toks[:at] + fake + toks[at:])\n    assert (\"v\", 2) in a._layer_runs and not any(k[0] == \"v\" for k in b._layer_runs)\n    assert np.array_equal(la.view(np.uint32), lb.view(np.uint32))\n    t = int(np.argmax(la))\n    for _ in range(3):\n        ga, gb = a.step(t), b.step(t)\n        assert np.array_equal(ga.view(np.uint32), gb.view(np.uint32))\n        t = int(np.argmax(ga))\n\n\n\ndef test_mtp_image_rows_decode_as_plain(tiny, monkeypatch):\n    \"\"\"MiniCPM-V with the MTP drafter (its base Qwen3.5's mtp.* transplanted, docs/offload.md\n    15.6): a prompt's image rows through MTPDecoder.prefill's vis (the layer-by-layer prompt's\n    copy runs; the MTP layer's input of an image token is its placeholder's embedding row), then\n    the MTP loop on the device: the tokens are plain greedy decode's of the same prompt with\n    text ids whose embedding rows are the image rows (test_image_rows_are_layer_zeros_input's),\n    whatever the drafts. 20 image rows after 9 text rows, chunks of 24 rows.\"\"\"\n    from opentpu.llm import qwen35 as Q35\n    from opentpu.llm.mtp import MTPDecoder, MTPStats, mtp_engine\n    from test_mtp_moe import _moe_mtp_weights\n    monkeypatch.setattr(Q35, \"PREFILL_CHUNK\", 24)\n    m, d = tiny\n    spec = replace(load_spec(d), vision_patches=128, vision_rows=64,\n                   vision_staged=False)         # (2 k slots a layer: too few to stage)\n    rng = np.random.default_rng(3)\n    W = dict(load_weights(d).items())\n    W.update(_tiny_vision_weights(spec.vision, rng))\n    n, at, v0, N = 20, 9, 5, 10\n    q = rng.integers(-127, 128, (n, spec.hidden))\n    q[:, ::128] = 127\n    rows = (q * 2.0 ** -7).astype(np.float32)\n    fake = list(range(V - 5 - n, V - 5))       # ids whose embedding rows are the image rows\n    W[\"model.embed_tokens.weight\"] = W[\"model.embed_tokens.weight\"].copy()\n    W[\"model.embed_tokens.weight\"][fake] = rows\n    W = _moe_mtp_weights(W, spec)\n    toks = [int(t) for t in rng.integers(0, V - 40, 31)]\n    cfg = device_config(spec, 256, rows=1, lookup=True, S=1, experts=2 * K)\n    want = Engine(spec, W, cap=256, cfg=cfg, rows=1, resident=True,\n                  experts=2 * K).generate(toks[:at] + fake + toks[at:], max_new=N)\n    cfg = device_config(replace(spec, mtp=True), 256, rows=2, lookup=True, S=1, experts=6)\n    eng = mtp_engine(spec, W, cap=256, cfg=cfg, rows=2, experts=6, layer_major=2)\n    dec = MTPDecoder(eng)\n    assert dec.by_layers and eng.image.vision is not None\n    eng.backend.write(0, eng.image.vision.work[\"vis\"] + 4 * v0 * spec.hidden, rows)\n    vis = [-1] * at + list(range(v0, v0 + n)) + [-1] * (len(toks) - at)\n    st = MTPStats()\n    a0, d0 = dec.prefill(toks[:at] + [0] * n + toks[at:], st, vis=vis)\n    assert (\"v\", 2) in eng._layer_runs and any(k[0] == \"m\" for k in eng._layer_runs)\n    assert dec.loop_card(a0, d0, N, stop=[], st=st).tokens == want\n\n\ndef test_image_rows_run_in_expert_major_tiles(tiny, monkeypatch):\n    \"\"\"MiniCPM-V's image (Qwen3.5's Image, subclassed) takes the tiled expert-major layer runs\n    (tiled.layer_family by its base class; docs/tiled_prefill.md 14): a prompt with 20 image\n    rows from vis among 31 text rows, expert-major, its layer runs in tiles of 8 rows (layer 0's\n    image rows from vis untiled, 2 a run) against today's runs of 2 rows: the logits and three\n    decode steps, bit for bit.\"\"\"\n    from opentpu.llm import qwen35 as Q35\n    from opentpu.llm import tiled as TL\n    monkeypatch.setattr(Q35, \"PREFILL_CHUNK\", 24)\n    monkeypatch.setenv(\"OTPU_TILE\", \"1\")\n    m, d = tiny\n    spec = replace(load_spec(d), vision_patches=128, vision_rows=64, vision_staged=False)\n    rng = np.random.default_rng(4)\n    W = dict(load_weights(d).items())\n    W.update(_tiny_vision_weights(spec.vision, rng))\n    n, at, v0 = 20, 9, 5\n    rows = (0.5 * rng.standard_normal((n, spec.hidden))).astype(np.float32)\n    toks = [int(t) for t in rng.integers(0, V - 40, 31)]\n    cfg = device_config(spec, 256, rows=1, lookup=True, S=1, experts=2 * K)\n    kw = dict(cap=256, cfg=cfg, rows=1, resident=True, experts=2 * K, layer_major=2,\n              expert_major=True)\n    a = Engine(spec, W, tile_runs=True, tile_rows=8, **kw)\n    b = Engine(spec, W, tile_runs=False, **kw)\n    assert TL.layer_family(a.image) == \"qwen35\" and a.layer_tile and not b.layer_tile\n    for e in (a, b):\n        e.backend.write(0, e.image.vision.work[\"vis\"] + 4 * v0 * spec.hidden, rows)\n    vis = [-1] * at + list(range(v0, v0 + n)) + [-1] * (len(toks) - at)\n    prompt = toks[:at] + [0] * n + toks[at:]\n    la, lb = a.prefill_layers(prompt, vis=vis), b.prefill_layers(prompt, vis=vis)\n    tiles = [k for k in a._layer_runs if isinstance(k, tuple) and k[-1] == \"tile\"]\n    assert max(k[2] for k in tiles) == 8 and (\"v\", 2) in a._layer_runs\n    assert np.array_equal(la.view(np.uint32), lb.view(np.uint32))\n    t = int(np.argmax(la))\n    for _ in range(3):\n        ga, gb = a.step(t), b.step(t)\n        assert np.array_equal(ga.view(np.uint32), gb.view(np.uint32))\n        t = int(np.argmax(ga))\n\ndef test_mrope_rows_gather_the_table():\n    \"\"\"mrope_rows: frequency i of a row is the table's entry at the position of section i % 3\n    (t, h, w): the rows of a text position are the table's rows bit for bit, an image row's\n    entries each the table's at its own section's position.\"\"\"\n    from opentpu.llm import minicpmv as MV\n    rng = np.random.default_rng(0)\n    cos, sin = rng.standard_normal((2, 50, 32)).astype(np.float32)\n    pos = np.array([[3, 3, 7], [3, 4, 9], [3, 5, 11]])\n    c, s_ = MV.mrope_rows((cos, sin), pos)\n    assert np.array_equal(c[0], cos[3]) and np.array_equal(s_[0], sin[3])\n    for j in (1, 2):\n        for i in range(32):\n            assert c[j, i] == cos[pos[i % 3, j], i] and s_[j, i] == sin[pos[i % 3, j], i]\n    with pytest.raises(ValueError):\n        MV.mrope_rows((cos, sin), np.array([[50], [0], [0]]))\n\n\ndef test_an_image_cache_hit_keeps_the_position_table(tiny, tmp_path, monkeypatch):\n    \"\"\"The vision side's host table (the patch position embedding, which host_rows gathers)\n    is an entry of an attribute of the image's own (vis_tables): an image cache hit, which\n    skips the build, puts it back (opentpu/imgcache.py keeps what a build leaves on the image\n    and its dict attributes' entries, not on the objects under them).\"\"\"\n    from opentpu import imgcache as IC\n    monkeypatch.setenv(\"OTPU_IMG_CACHE\", str(tmp_path / \"img\"))\n    monkeypatch.setenv(\"OTPU_IMG_CACHE_FREE_GB\", \"0\")\n    m, d = tiny\n    ck = tmp_path / \"ck\"\n    ck.mkdir()\n    (ck / \"config.json\").write_text((d / \"config.json\").read_text())\n    spec = replace(load_spec(ck), vision_patches=128, vision_rows=64,\n                   vision_staged=False)         # (2 k slots a layer: too few to stage)\n    vw = _tiny_vision_weights(spec.vision, np.random.default_rng(4))\n    sd = safetensors.load_file(str(d / \"model.safetensors\"))\n    sd.update({k: torch.from_numpy(v) for k, v in vw.items()})\n    safetensors.save_file(sd, str(ck / \"model.safetensors\"))\n    cfg = device_config(spec, 256, rows=1, lookup=True, S=1, experts=2 * K)\n    P = np.random.default_rng(5).standard_normal((64, 3 * 14 * 14)).astype(np.float32)\n    got = []\n    for want in (\"miss\", \"hit\"):\n        e = Engine(spec, LazyWeights(ck), cap=256, cfg=cfg, rows=1, resident=True,\n                   experts=2 * K, layer_major=2)\n        assert IC.last[0] == want\n        got.append(e.image.vision.host_rows(P, (8, 8)))\n    pos = vw[\"model.vision_tower.embeddings.position_embedding.weight\"]\n    assert np.array_equal(e.image.vis_tables[\"pos\"], pos)\n    for a, b in zip(*got):\n        assert np.array_equal(a, b)\n\n\ndef test_the_card_rope_rows_are_hfs_mrope(tiny):\n    \"\"\"Vision.positions writes the device's RoPE table so that slot s holds HF's interleaved\n    M-RoPE cos / sin (Qwen3_5MoeTextRotaryEmbedding) at the sequence's canvas positions\n    (rope_index; s >= T: s + delta, the decode's), and pristine puts the 1-D rows back: a\n    thumbnail and a 1 x 2 grid of slices of different (h, w), between text.\"\"\"\n    from transformers.models.qwen3_5_moe import modeling_qwen3_5_moe as HM\n    from opentpu.llm import minicpmv as MV\n    m, d = tiny\n    spec = replace(load_spec(d), vision_patches=128, vision_rows=64,\n                   vision_staged=False)         # (2 k slots a layer: too few to stage)\n    vs = spec.vision\n    W = dict(load_weights(d).items())\n    W.update(_tiny_vision_weights(vs, np.random.default_rng(6)))\n    cap = 256\n    cfg = device_config(spec, cap, rows=1, lookup=True, S=1, experts=2 * K)\n    eng = Engine(spec, W, cap=cap, cfg=cfg, rows=1, resident=True, experts=2 * K, layer_major=2)\n    v = MV.Vision(eng)\n    sizes = [(8, 12), (12, 8), (12, 8)]\n    P_ = vs.image_token\n    ids = [5, 6, 7, vs.image_start] + [P_] * 6 + [vs.image_end] + [vs.slice_start] + \\\n        [P_] * 6 + [vs.slice_end] + [vs.slice_start] + [P_] * 6 + [vs.slice_end] + [9, 10, 11]\n    delta = v.positions(ids, sizes)\n    pos, _ = MV.rope_index(ids, sizes, vs)\n    T = len(ids)\n    rot = HM.Qwen3_5MoeTextRotaryEmbedding(m.config)\n    lk = eng.image.lookup\n    half = lk[\"half\"]\n\n    def table():\n        return [eng.backend.read(0, lk[n], 4 * half * cap).view(np.float32).reshape(cap, half)\n                for n in (\"cos_t\", \"sin_t\")]\n\n    def hf(p):\n        c, s_ = rot(torch.zeros(1), torch.from_numpy(p)[:, None, :])\n        return c[0, :, :half].numpy(), s_[0, :, :half].numpy()\n    want = hf(np.concatenate([pos, np.tile(np.arange(T, cap) + delta, (3, 1))], 1))\n    assert delta != 0 and not np.array_equal(pos[1], pos[2])\n    for got, w in zip(table(), want):\n        assert np.abs(got - w).max() < 1e-4\n    v.pristine()\n    for got, w in zip(table(), hf(np.tile(np.arange(cap), (3, 1)))):\n        assert np.abs(got - w).max() < 1e-4\n\n\n# =============================================================================== otpu-serve\nclass _Tok:\n    \"\"\"One character per token id.\"\"\"\n\n    def decode(self, ids, skip_special_tokens=False):\n        return \"\".join(chr(0x100 + int(i)) for i in ids)\n\n\ndef test_serve_keys_contexts_by_their_images(tiny):\n    \"\"\"otpu-serve's worker with images (scheduler.Request.images; prompts keyed by\n    minicpmv.keyed): two requests with different images after the same text, in turns, give\n    the tokens of their own runs on a fresh engine (the tower, the image rows, each context's\n    RoPE rows written at its switch); one that continues the first's conversation feeds only\n    what is new; one with a third image after the same text reuses no context past the text\n    (with the image tokens' one id it would take a saved one whole); a text-only one after\n    them runs on the table's own rows.\"\"\"\n    import hashlib\n\n    from opentpu.llm import minicpmv as MV\n    from opentpu.serve import scheduler as SC\n    m, d = tiny\n    sp = load_spec(d)\n    vs = replace(sp.vision, image_token=1000, image_start=1001, image_end=1002,\n                 slice_start=1003, slice_end=1004)\n    spec = replace(sp, vision=vs, vision_patches=128, vision_rows=64,\n                   vision_staged=False)         # (2 k slots a layer: too few to stage)\n    rng = np.random.default_rng(7)\n    W = dict(load_weights(d).items())\n    W.update(_tiny_vision_weights(vs, rng))\n    cfg = device_config(spec, 256, rows=1, lookup=True, S=1, experts=2 * K)\n\n    def engine():\n        return Engine(spec, W, cap=256, cfg=cfg, rows=1, resident=True, experts=2 * K,\n                      layer_major=2)\n\n    def image(seed):\n        P = np.random.default_rng(seed).uniform(-1, 1, (96, 3 * 14 * 14)).astype(np.float32)\n        return MV.ImageInput([P], [(8, 12)], None, \"\", hashlib.sha256(P.tobytes()).hexdigest())\n\n    head = [int(t) for t in rng.integers(0, 900, 7)]\n    tail = [int(t) for t in rng.integers(0, 900, 5)]\n\n    def prompt(im, more=()):\n        ids = head + ([vs.image_start] + [vs.image_token] * im.tokens + [vs.image_end]\n                      if im is not None else []) + tail + list(more)\n        return ids, ([] if im is None else [im])\n\n    def ref(ids, ims, n):\n        \"\"\"Greedy tokens of a fresh engine, as the worker feeds them (the device's loop: the\n        prompt's last token through the decode).\"\"\"\n        e = engine()\n        vis = MV.Vision(e).prompt(ids, ims) if ims else None\n        card = getattr(e, \"can_generate\", False)\n        a = len(ids) - 1 if card else len(ids)\n        lg = e.prefill_layers(ids[:a], logits=not card,\n                              **({} if vis is None else {\"vis\": vis[:a]}))\n        if card:\n            lg = e.step(ids[-1])\n        out = []\n        while True:\n            t = int(np.argmax(lg))\n            out.append(t)\n            if len(out) == n:\n                return out\n            lg = e.step(t)\n\n    def request(ids, ims, n=6):\n        key = MV.keyed(ids, ims, vs.image_token) if ims else ids\n        return SC.Request(key, max_new=n, stop_ids=frozenset({-1}), images=ims)\n\n    X, Y, Z = image(1), image(2), image(3)\n    w = SC.Worker(engine(), _Tok(), quantum=2, max_running=4).start()\n    try:\n        pa, pb = prompt(X), prompt(Y)\n        ra, rb = w.submit(request(*pa)), w.submit(request(*pb))\n        for r in (ra, rb):\n            r.wait(timeout=900)\n            assert r.error is None and r.finish == \"length\", r.error\n        assert ra.swaps + rb.swaps >= 2\n        assert ra.out == ref(*pa, 6) and rb.out == ref(*pb, 6) and ra.out != rb.out\n        pc = prompt(X, ra.out + [7, 8, 9])\n        rc = w.submit(request(*pc)).wait(timeout=900)\n        assert rc.error is None and rc.cached >= len(pa[0])\n        assert rc.out == ref(*pc, 6)\n        pz = prompt(Z)\n        rz = w.submit(request(*pz)).wait(timeout=900)\n        assert rz.error is None and rz.cached <= len(head) + 1\n        assert rz.out == ref(*pz, 6)\n        pt = prompt(None)\n        rt = w.submit(request(*pt)).wait(timeout=900)\n        assert rt.error is None and rt.out == ref(*pt, 6)\n        with pytest.raises(ValueError):    # (keys without their images)\n            w.submit(SC.Request(request(*pa).prompt, max_new=2))\n    finally:\n        w.stop(persist=False)\n\n\nclass _VTok:\n    \"\"\"A character tokenizer with MiniCPM-V's markers as single ids (1000 + i), and a template\n    that renders an image part as <|image_pad|>.\"\"\"\n    chat_template = \"minicpmv-like\"\n    SPECIAL = (\"<|image_pad|>\", \"<image>\", \"</image>\", \"<slice>\", \"</slice>\", \"<image_id>\",\n               \"</image_id>\")\n\n    def __call__(self, text):\n        import re\n        out = []\n        for piece in re.split(\"(\" + \"|\".join(re.escape(s) for s in self.SPECIAL) + \")\", text):\n            if piece in self.SPECIAL:\n                out.append(1000 + self.SPECIAL.index(piece))\n            else:\n                out += [ord(c) % 900 for c in piece]\n        return {\"input_ids\": out}\n\n    def apply_chat_template(self, msgs, add_generation_prompt, enable_thinking, tokenize):\n        def text(c):\n            return c if isinstance(c, str) else \"\".join(\n                \"<|image_pad|>\" if p[\"type\"] == \"image\" else p[\"text\"] for p in c)\n        out = \"\".join(f\"\\x01{m['role']}\\n{text(m['content'])}\\x02\\n\" for m in msgs)\n        if add_generation_prompt:\n            out += \"\\x01assistant\\n\"\n        return out if not tokenize else self(out)[\"input_ids\"]\n\n    def decode(self, ids, skip_special_tokens=True):\n        return \"\".join(chr(0x100 + int(i)) for i in ids)\n\n\nclass _Worker:\n    \"\"\"What Server takes of a scheduler.Worker; submit records the requests.\"\"\"\n\n    def __init__(self, cap=4096):\n        import threading\n        from types import SimpleNamespace\n        self.tok_lock, self.stateful = threading.Lock(), False\n        self.eng = SimpleNamespace(cap=cap)\n        self.got = []\n\n    def busy(self):\n        return 0\n\n    def submit(self, r):\n        self.got.append(r)\n        return r\n\n\ndef _png(w, h, seed):\n    import base64\n    import io\n    from PIL import Image as PI\n    a = np.random.default_rng(seed).integers(0, 256, (h, w, 3), dtype=np.uint8)\n    buf = io.BytesIO()\n    PI.fromarray(a).save(buf, format=\"PNG\")\n    return \"data:image/png;base64,\" + base64.b64encode(buf.getvalue()).decode()\n\n\ndef test_serve_takes_image_url_parts():\n    \"\"\"otpu-serve's chat with image_url parts (api.Server on MiniCPM-V's spec): each image\n    prepared at the request's max_slices, its placeholder in place of its <|image_pad|>, the\n    prompt's key its token ids with each image's tokens their content keys; the same image\n    gives the same keys, another image others; refused: an image for a model without a vision\n    side, an http(s) URL without --image-fetch, a max_slices out of range, a bad data URL.\"\"\"\n    import base64\n    from types import SimpleNamespace\n\n    from opentpu.llm import minicpmv as MV\n    from opentpu.serve import api as API\n    pytest.importorskip(\"PIL\")              # (the images' PNGs, and their decode without torchvision)\n    vs = MV.VisionSpec(image_token=1000, image_start=1001, image_end=1002, slice_start=1003,\n                       slice_end=1004)\n    spec = SimpleNamespace(vision=vs, vision_rows=2048, eos=[999])\n    tok, w = _VTok(), _Worker()\n    srv = API.Server(w, tok, spec, \"mcpv\", dict(temperature=0.0, top_k=20, top_p=1.0,\n                                                 repetition_penalty=1.0))\n    a, b = _png(1000, 700, 1), _png(1000, 700, 2)\n\n    def chat(*urls, text=\"What is this?\", **kw):\n        content = [{\"type\": \"image_url\", \"image_url\": {\"url\": u}} for u in urls] + \\\n            [{\"type\": \"text\", \"text\": text}]\n        w.got.clear()\n        srv.chat({\"messages\": [{\"role\": \"user\", \"content\": content}], **kw})\n        return w.got[0]\n\n    r = chat(a, max_slices=4)\n    ims = [MV.prepare(base64.b64decode(a.split(\",\", 1)[1]), vs, 4, image_id=0)]\n    assert len(r.images) == 1 and r.images[0].sizes == ims[0].sizes and len(ims[0].sizes) > 1\n    ids = tok(MV.expand(tok.apply_chat_template(\n        [{\"role\": \"user\", \"content\": [{\"type\": \"image\"}, {\"type\": \"text\",\n                                                          \"text\": \"What is this?\"}]}],\n        True, False, False), ims))[\"input_ids\"]\n    assert MV.unkeyed(r.prompt, vs.image_token) == ids\n    assert r.prompt == MV.keyed(ids, ims, vs.image_token)\n    assert sum(t < 0 for t in r.prompt) == ims[0].tokens\n    assert chat(a, max_slices=4).prompt == r.prompt             # the same image: the same key\n    r2 = chat(b, max_slices=4)\n    first = next(i for i, t in enumerate(r.prompt) if t < 0)\n    assert r2.prompt[:first] == r.prompt[:first] and r2.prompt[first] != r.prompt[first]\n    r3 = chat(a, b, max_slices=1)                                 # two images, numbered\n    assert [len(im.sizes) for im in r3.images] == [1, 1]\n    assert MV.unkeyed(r3.prompt, vs.image_token).count(1005) == 2   # (<image_id> twice)\n    for bad in ({\"url\": \"http://example.com/x.png\"}, {\"url\": \"/etc/passwd\"},\n                {\"url\": \"data:image/png,abc\"}):\n        with pytest.raises(API.APIError):\n            srv.chat({\"messages\": [{\"role\": \"user\", \"content\": [\n                {\"type\": \"image_url\", \"image_url\": bad}]}]})\n    with pytest.raises(API.APIError):\n        chat(a, max_slices=0)\n    text = API.Server(w, tok, SimpleNamespace(vision=None, eos=[999]), \"t\", srv.defaults)\n    with pytest.raises(API.APIError):\n        w.got.clear()\n        text.chat({\"messages\": [{\"role\": \"user\", \"content\": [\n            {\"type\": \"image_url\", \"image_url\": {\"url\": a}}]}]})\n", "tests/test_models_on_board_rtl.py": "\"\"\"The three real checkpoints in the board's 4-bit configuration (4-bit layers, int8 LM head,\ncolumn reuse) on the board's MCOLS=2 and on MCOLS=4: a token on the Verilator RTL, through the\nboard's memory path (AXI adapter, boot loader), equals the ISA simulator bit for bit. Slow\n(several minutes per case): run with --runslow.\"\"\"\nfrom pathlib import Path\n\nimport numpy as np\nimport pytest\n\nfrom opentpu import rtlsim\nfrom opentpu.isasim import board_config\nfrom opentpu.llm import load_spec\nfrom opentpu.llm.qwen3 import Engine, load_weights\n\nMODELS = Path(__file__).resolve().parent.parent / \"models\"\nCASES = [(\"Qwen3-0.6B\", [151644, 872, 198, 3838, 374, 279, 6722, 315, 9625, 30], False, False),\n         (\"LFM2.5-230M\", [1, 6, 6423, 708, 3493, 856, 779, 5706, 803, 4481], False, False),\n         (\"LFM2.5-230M\", [1, 6, 6423, 708, 3493, 856, 779, 5706, 803, 4481], False, True),\n         (\"Qwen3.5-0.8B\", [760, 6511, 314, 9338, 369], False, False),\n         (\"Qwen3.5-0.8B\", [760, 6511, 314, 9338, 369], True, False)]\n\n\n@pytest.mark.slow\n@pytest.mark.parametrize(\"mcols\", [2, 4])\n@pytest.mark.parametrize(\"model,prompt,dstep,resident\", CASES,\n                         ids=[\"qwen3\", \"lfm2\", \"lfm2-resident\", \"qwen35\", \"qwen35-dstep\"])\ndef test_token_on_board_rtl_is_bit_exact(have_verilator, model, prompt, dstep, resident, mcols):\n    \"\"\"Feed part of a prompt on the ISA simulator, then run the next token on the RTL and on the\n    ISA simulator from the same DRAM state: logits and the whole DRAM image (weights, caches,\n    recurrent state) must agree bit for bit (the Qwen3.5 DeltaNet with and without DSTEP; LFM2\n    also with the resident decode program).\"\"\"\n    from opentpu.llm.rtl_backend import RtlBackend\n    path = MODELS / model\n    if not path.exists():\n        pytest.skip(f\"models/{model} not downloaded\")\n    spec = load_spec(path)\n    cfg = board_config(DRAM_BYTES=1 << 30, MCOLS=mcols, PAIR=True, DSTEP=dstep)\n    eng = Engine(spec, load_weights(path), cap=256, cfg=cfg, wformat=\"fp4\", head_format=\"int8\",\n                 resident=resident)\n    assert eng.resident == resident\n    for t in prompt[:-1]:\n        eng.step(t)\n    n = eng.image.nbytes\n    rtl = RtlBackend(eng.cfg, [s.dram[:n] for s in eng.backend.machine.slices],\n                     uarch=rtlsim.BOARD_UARCH, axi=True, boot=True)\n    isa = eng.backend\n    want = eng.step(prompt[-1])\n    eng.backend, eng.pos = rtl, eng.pos - 1\n    got = eng.step(prompt[-1])\n    assert np.array_equal(want.view(np.uint32), got.view(np.uint32))\n    for s in range(eng.cfg.S):\n        assert np.array_equal(isa.machine.slices[s].dram[:n], rtl.drams[s][:n])\n", "tests/test_moe_fold.py": "\"\"\"opentpu/llm/moe.py's Gemma 4 folds (docs/offload.md section 11.2): the router's scales into\nits weights, so that it reads the residual's unit RMSNorm (moe_ffn's), and the per-expert scale\ninto W_down; the experts read that norm times pre_feedforward_layernorm_2's gain (moe_ffn's\ng_exp), as against transformers' Gemma4TextRouter and Gemma4TextExperts.\"\"\"\nimport numpy as np\nimport pytest\n\nfrom opentpu.llm import moe as MO\n\ntorch = pytest.importorskip(\"torch\")\ng4 = pytest.importorskip(\"transformers.models.gemma4.modeling_gemma4\")\ntransformers = pytest.importorskip(\"transformers\")\n\n\ndef _gelu_tanh(x):\n    return 0.5 * x * (1 + np.tanh(np.sqrt(2 / np.pi) * (x + 0.044715 * x ** 3)))\n\n\ndef test_gemma_folds_match_hf():\n    \"\"\"Gemma 4's MoE block from the folded weights (moe.gemma_router, moe.gemma_expert; a\n    width of 176, not a whole number of chunks), the experts on the norm times g2, and the\n    softmax rule picks the same experts and gives transformers' output in fp32.\"\"\"\n    torch.manual_seed(0)\n    H, E, k, F = 256, 8, 2, 176\n    cfg = transformers.Gemma4TextConfig(hidden_size=H, num_experts=E, top_k_experts=k,\n                                        moe_intermediate_size=F, enable_moe_block=True,\n                                        hidden_activation=\"gelu_pytorch_tanh\",\n                                        rms_norm_eps=1e-6)\n    router, experts = g4.Gemma4TextRouter(cfg), g4.Gemma4TextExperts(cfg)\n    norm2 = g4.Gemma4RMSNorm(H, eps=1e-6)\n    with torch.no_grad():\n        for p in (*router.parameters(), *experts.parameters()):\n            p.copy_(0.1 * torch.randn_like(p))\n        router.scale.copy_(1 + 0.3 * torch.randn(H))\n        router.per_expert_scale.copy_(1 + 0.3 * torch.randn(E))\n        norm2.weight.copy_(1 + 0.3 * torch.randn(H))\n        r = torch.randn(12, H)\n        _, w, idx = router(r)\n        hf = experts(norm2(r), idx, w).numpy()\n    p = \"model.layers.3.\"\n    W = {p + \"router.proj.weight\": router.proj.weight, p + \"router.scale\": router.scale,\n         p + \"router.per_expert_scale\": router.per_expert_scale,\n         p + \"experts.gate_up_proj\": experts.gate_up_proj,\n         p + \"experts.down_proj\": experts.down_proj,\n         p + \"pre_feedforward_layernorm_2.weight\": norm2.weight}\n    W = {n: v.detach().numpy() for n, v in W.items()}\n    mo = MO.MoESpec(E=E, k=k, ffn=F, rule=\"softmax\", act=\"gelu_tanh\")\n    x = r.numpy()\n    xu = x / np.sqrt(np.mean(x * x, axis=-1, keepdims=True) + 1e-6)\n    xe = xu * W[p + \"pre_feedforward_layernorm_2.weight\"]\n    lg = xu @ MO.gemma_router(W, p).T\n    out = np.zeros_like(x)\n    for t in range(len(x)):\n        ids, wt = MO.route(lg[t], None, mo)\n        assert list(ids) == idx[t].tolist()\n        for e, we in zip(ids, wt):\n            wg, wu, wd = MO.gemma_expert(W, p, e)\n            out[t] += np.float32(we) * ((_gelu_tanh(xe[t] @ wg.T) * (xe[t] @ wu.T)) @ wd.T)\n    assert np.allclose(out, hf, rtol=1e-4, atol=1e-5), np.abs(out - hf).max()\n    fmt = MO.ExpertFormat(H, F, 128, \"fp4\")\n    assert (fmt.F0, fmt.F) == (176, 256) and fmt.pack(*MO.gemma_expert(W, p, 0)).size == \\\n        fmt.nbytes\n", "tests/test_mtp.py": "\"\"\"Speculative decoding with Qwen3.5's MTP drafter (opentpu/llm/mtp.py, docs/mtp.md 9) on the ISA\nsimulator: greedy tokens equal plain greedy decode's bit for bit whatever the drafts (the MTP's,\nall right, all wrong, mixed), the committed DeltaNet states and windows equal plain decode's, and\nthe MTP program follows its numpy reference. A tiny random Qwen3.5 with random mtp.* weights;\nint8 weights, and fp4 with PAIR at the board's MCOLS 4 (the 2-row verify's MMs pair as the\ndecode steps' do, qwen35_rows).\"\"\"\nimport dataclasses\n\nimport numpy as np\nimport pytest\n\nfrom opentpu import isa as I\nfrom opentpu.compiler import Affine\nfrom opentpu.isasim import board_config\nfrom opentpu.llm import generate as G\nfrom opentpu.llm.mtp import MTPDecoder, MTPStats, mtp_engine\nfrom opentpu.llm.qwen3 import Engine\nfrom opentpu.llm.qwen35 import mtp_reference, qwen35_step, reference_logits\n\nfrom test_qwen35 import _tiny_model\n\npytest.importorskip(\"torch\")\n\nCFG = board_config(DRAM_BYTES=1 << 25, DSTEP=True, STREAM=True, PAIR=True)\n\n\ndef _mtp_weights(W, spec, seed=1):\n    \"\"\"Random mtp.* tensors for a tiny model (zero-centred norms, as the checkpoint's).\"\"\"\n    r = np.random.default_rng(seed)\n    H, d, F = spec.hidden, spec.head_dim, spec.ffn\n\n    def lin(o, i):\n        return (r.uniform(-1, 1, (o, i)) / np.sqrt(i)).astype(np.float32)\n\n    def norm(n):\n        return (0.1 * r.standard_normal(n)).astype(np.float32)\n    a = \"mtp.layers.0.self_attn.\"\n    m = {\"mtp.pre_fc_norm_embedding.weight\": norm(H), \"mtp.pre_fc_norm_hidden.weight\": norm(H),\n         \"mtp.fc.weight\": lin(H, 2 * H), \"mtp.norm.weight\": norm(H),\n         \"mtp.layers.0.input_layernorm.weight\": norm(H),\n         \"mtp.layers.0.post_attention_layernorm.weight\": norm(H),\n         a + \"q_proj.weight\": lin(2 * spec.n_q * d, H), a + \"k_proj.weight\": lin(spec.n_kv * d, H),\n         a + \"v_proj.weight\": lin(spec.n_kv * d, H), a + \"o_proj.weight\": lin(H, spec.n_q * d),\n         a + \"q_norm.weight\": norm(d), a + \"k_norm.weight\": norm(d),\n         \"mtp.layers.0.mlp.gate_proj.weight\": lin(F, H),\n         \"mtp.layers.0.mlp.up_proj.weight\": lin(F, H),\n         \"mtp.layers.0.mlp.down_proj.weight\": lin(H, F)}\n    return {**W, **m}\n\n\nFP4 = dict(wformat=\"fp4\", head_format=\"int8\")\n\n\n@pytest.fixture(scope=\"module\", params=[(8, False, False), (4, False, False), (8, True, False),\n                                        (8, False, True)],\n                ids=[\"kh8\", \"kh4-shared\", \"kh8-grouped\", \"kh8-fp4\"])\ndef tiny_mtp(request):\n    \"\"\"(weights, spec, formats).\"\"\"\n    nk, grouped, fp4 = request.param\n    _, W, spec = _tiny_model(nk)\n    return _mtp_weights(W, spec), dataclasses.replace(spec, pair_loop=grouped), FP4 if fp4 else {}\n\n\ndef _layers(eng):\n    return eng.backend.machine.slices[0].dram\n\n\ndef _states(eng, spec, slot):\n    \"\"\"Every DeltaNet layer's states and windows in `slot` (bytes).\"\"\"\n    img, dram = eng.image, _layers(eng)\n    m = img.descriptors(0, slot)\n    out = []\n    for li, k in enumerate(spec.kinds):\n        if k != \"linear\":\n            continue\n        dn = m.layer(li).dn\n        for q in range(img.nl // 2):\n            for t in [dn.state(q, 0), dn.state(q, 1), dn.window(q)]:\n                n, b = 4 * int(np.prod(t.shape)), Affine.of(t.base).static()\n                out.append(dram[b:b + n].copy())\n    return out\n\n\n@pytest.mark.parametrize(\"drafter\", [\"mtp\", \"right\", \"wrong\", \"mixed\"])\ndef test_mtp_greedy_is_plain_greedy(tiny_mtp, drafter):\n    \"\"\"Tokens equal plain greedy decode's for any drafts: the MTP's (random weights: mostly\n    rejected), all right (every iteration accepts and flips the state slot), all wrong, and\n    right but every third; then the committed states and windows equal plain decode's word\n    for word, and a decode step from the committed slot gives plain decode's next logits.\n    The prompt's 13 tokens prefill in runs of 8, 4 and 1 rows (the MTP layer over 4 + 4).\"\"\"\n    W, spec, kw = tiny_mtp\n    prompt = [int(t) for t in np.random.default_rng(4).integers(0, 1000, 13)]\n    N = 20\n    ref = Engine(spec, W, cap=256, cfg=CFG, resident=True, **kw)\n    want = ref.generate(prompt, max_new=N)\n    P = len(prompt)\n\n    def right(q, out):\n        return want[q - P] if q - P < len(want) else 0\n    drafts = {\"mtp\": None, \"right\": right,\n              \"wrong\": lambda q, out: (right(q, out) + 1) % 1000,\n              \"mixed\": lambda q, out: right(q, out) if q % 3 else (right(q, out) + 7) % 1000}\n    eng = mtp_engine(spec, W, cap=256, cfg=CFG, **kw)\n    dec = MTPDecoder(eng)\n    st = dec.generate(prompt, max_new=N, drafts=drafts[drafter])\n    assert st.tokens == want\n    if drafter == \"right\":\n        assert all(st.accepted[:-1]) and st.iterations <= N // 2 + 1\n    if drafter == \"wrong\":\n        assert not any(st.accepted)\n    # the same context as plain greedy decode feeds it: the prompt, then the tokens but the\n    # last one by one (decode steps)\n    ref = Engine(spec, W, cap=256, cfg=CFG, resident=True, **kw)\n    ref.prefill(prompt)\n    # the prompt in plain prefill's runs (their MMs pair as plain prefill's do)\n    assert [r for k, r, _ in st.runs if k == \"prefill\"] == [x.get(\"rows\", 1) for x in ref.stats]\n    for t in want[:-1]:\n        ref.step(t)\n    assert eng.pos == ref.pos == P + N - 1\n    assert all(np.array_equal(a, b) for a, b in\n               zip(_states(eng, spec, dec.slot), _states(ref, spec, 0)))\n    t, pos = want[-1], eng.pos\n    lg = []\n    for e, slot in ((eng, dec.slot), (ref, 0)):\n        prog = qwen35_step.trace(e.cfg, 0, {\"m\": e.image.descriptors(0, slot), \"pos\": pos,\n                                            \"block\": e.block, \"tok\": t}).finish()\n        e.backend.run([prog])\n        io = e.image.io\n        lg.append(e.backend.read(0, io[\"logits\"], 4 * spec.vocab).view(np.uint32))\n    assert np.array_equal(lg[0], lg[1])\n\n\ndef test_mtp_program_follows_its_reference():\n    \"\"\"The MTP program over a 4-row prompt chunk (its hidden rows from the rows kernel's\n    `hidden`): the draft head's logits against mtp_reference on the fp32 model's hidden rows,\n    and its draft ids against their argmax.\"\"\"\n    _, W, spec = _tiny_model(8)\n    W = _mtp_weights(W, spec)\n    R = 4\n    toks = [int(t) for t in np.random.default_rng(6).integers(0, 1000, R + 1)]\n    eng = mtp_engine(spec, W, cap=256, cfg=CFG)\n    img = eng.image\n    eng.backend.run(img.compile_rows([(0, j) for j in range(R)], [], tokens=toks[:R],\n                                     hidden=True))\n    hid = eng.backend.read(0, img.io[\"hid\"], 4 * R * spec.hidden).view(np.float32)\n    _, href = reference_logits(spec, W, toks[:R], hidden=True)\n    hid = hid.reshape(R, spec.hidden)\n    cos = (hid * href).sum(1) / np.linalg.norm(hid, axis=1) / np.linalg.norm(href, axis=1)\n    assert cos.min() > 0.999, cos\n    eng.backend.run(img.compile_mtp(0, R, toks[1:R + 1], keep=True))\n    got = eng.backend.read(0, img.io[\"logits\"], 4 * R * spec.vocab).view(np.float32)\n    got = got.reshape(R, spec.vocab)[:, :img.nd]\n    want = mtp_reference(spec, W, href, toks[1:R + 1])\n    cos = (got * want).sum(1) / np.linalg.norm(got, axis=1) / np.linalg.norm(want, axis=1)\n    assert cos.min() > 0.99, cos\n    ids = eng.backend.read(0, img.io[\"draft\"], 4 * R).view(np.float32).astype(int)\n    assert list(ids) == list(np.argmax(got, axis=1))\n    assert np.mean(ids == np.argmax(want, axis=1)) >= 0.75\n\n\ndef test_mtp_verify_and_draft_on_rtl(have_verilator):\n    \"\"\"A forked verify run (row 1's DeltaNet steps a STREAM into the other state slot, dst !=\n    src) and an MTP run on the RTL's board memory path: DRAM equals the ISA simulator's.\"\"\"\n    from opentpu import rtlsim\n    from opentpu.isasim import Machine\n    _, W, spec = _tiny_model(8)\n    W = _mtp_weights(W, spec)\n    toks = [int(t) for t in np.random.default_rng(7).integers(0, 1000, 8)]\n    eng = mtp_engine(spec, W, cap=256, cfg=CFG)\n    dec = MTPDecoder(eng)\n    a0, d = dec.prefill(toks[:6], MTPStats())\n    img, n = eng.image, eng.image.nbytes\n    verify = img.compile_rows([(0, 6), (0, 7)], [0, 1], tokens=[a0, d], fork=True, hidden=True)\n    assert any(i.op == I.STREAM and i.w[1] != i.w[2] for i in verify[0])\n    for progs in (verify, img.compile_mtp(6, 2, [a0, d])):\n        dram = eng.backend.machine.slices[0].dram[:n].copy()\n        m = Machine(CFG, progs, [dram.copy()]).run()\n        drams, _, _ = rtlsim.run(CFG, progs, [dram.copy()], uarch=rtlsim.BOARD_UARCH, axi=True,\n                                 boot=True)\n        assert np.array_equal(drams[0][:n], m.slices[0].dram[:n])\n        eng.backend.machine.slices[0].dram[:n] = m.slices[0].dram[:n]\n\n\ndef test_mtp_needs_paired_verify():\n    \"\"\"With PAIR and 4-bit weights at MCOLS 2 a 2-row run's MMs do not pair as the decode\n    steps' do (qwen35_rows): the decoder refuses rather than give other tokens.\"\"\"\n    _, W, spec = _tiny_model(8)\n    cfg = board_config(DRAM_BYTES=1 << 25, DSTEP=True, STREAM=True, PAIR=True, MCOLS=2)\n    eng = mtp_engine(spec, _mtp_weights(W, spec), cap=256, cfg=cfg, **FP4)\n    with pytest.raises(ValueError, match=\"MCOLS >= 4\"):\n        MTPDecoder(eng)\n\n\ndef _plain(spec, W, prompt, N, kw, cfg=CFG):\n    \"\"\"Plain greedy decode's tokens (resident decode, the host loop).\"\"\"\n    return Engine(spec, W, cap=512, cfg=cfg, resident=True, **kw).generate(prompt, max_new=N)\n\n\n@pytest.mark.parametrize(\"P, drafter, fmt, N, stop\", [\n    (250, \"right\", \"int8\", 16, False),     # V at 254 accepts: the wrap; the last token alone\n    (251, \"right\", \"int8\", 15, False),     # 253 -> 255: E, then D1 and the next bucket's V\n    (249, \"mixed\", \"int8\", 15, False),     # E at the other parity\n    (250, \"wrong\", \"int8\", 12, False),\n    (249, \"right\", \"fp4\", 15, False),\n    (250, \"mtp\", \"emb8\", 15, False),       # int8 embedding: 10 run-time values in D\n    (252, \"right\", \"int8\", 15, True),      # a stop id: the second of an accepted pair\n    (30, \"right\", \"kh16\", 6, False)])      # 16 DeltaNet heads: V's arguments move\ndef test_mtp_loop_on_the_device_is_plain_greedy(P, drafter, fmt, N, stop):\n    \"\"\"The MTP loop on the device (docs/mtp.md 10: V, E, D, D1 chained through the buckets'\n    programs, ISA simulator) gives plain greedy decode's tokens across the end of the first\n    attention bucket, whatever the drafts (the device's MTP, or the host's table: all right,\n    every third wrong, all wrong), and leaves the context as plain decode does: the committed\n    DeltaNet states and windows equal, word for word, those of the prompt and the tokens but\n    the last fed one by one. kh16: the 0.8B's and 2B's 16 DeltaNet heads, whose addresses\n    take an argument register of the verify's, so its last arguments move into the released\n    registers of the row tokens', each at its own release (Builder._move_arg).\"\"\"\n    # (the stop case: tokens that vary, init 0.2; at 0.02 the MX numerics' tokens are one\n    # token repeated)\n    _, W, spec = _tiny_model(16, 16) if fmt == \"kh16\" else _tiny_model(8, init=0.2 if stop\n                                                                         else 0.02)\n    cfg = board_config(DRAM_BYTES=1 << 26, DSTEP=True, STREAM=True, PAIR=True) \\\n        if fmt == \"kh16\" else CFG\n    if fmt == \"emb8\":\n        spec = dataclasses.replace(spec, embed=\"int8\")\n    W = _mtp_weights(W, spec)\n    kw = FP4 if fmt == \"fp4\" else {}\n    prompt = [int(t) for t in np.random.default_rng(P).integers(0, 1000, P)]\n    want = _plain(spec, W, prompt, N, kw, cfg)\n    ids = None\n    if stop:                                # the second of an accepted pair stops it: the first\n        k = next(k for k in range(2, len(want), 2) if want[k] not in want[:k])  # new to them\n        ids = [want[k]]\n        want = want[:k + 1]\n    right = np.zeros(514, np.float32)\n    right[P:P + len(want)] = want\n    drafts = {\"right\": right, \"wrong\": (right + 1) % 1000, \"mtp\": None,\n              \"mixed\": np.where(np.arange(514) % 3, right, (right + 7) % 1000)}[drafter]\n    eng = mtp_engine(spec, W, cap=512, cfg=cfg, **kw)\n    dec = MTPDecoder(eng)\n    st = dec.generate_card(prompt, max_new=N, stop=ids, drafts=drafts)\n    assert st.tokens == want\n    if drafter == \"right\" and not stop:\n        assert sum(st.accepted) >= len(want) // 2 - 2\n    if drafter == \"wrong\":\n        assert not any(st.accepted)\n    ref = Engine(spec, W, cap=512, cfg=cfg, resident=True, **kw)\n    ref.prefill(prompt)\n    for t in want[:-1]:\n        ref.step(t)\n    assert eng.pos == ref.pos == P + len(want) - 1\n    assert all(np.array_equal(a, b) for a, b in\n               zip(_states(eng, spec, dec.slot), _states(ref, spec, 0)))\n\n\n# (the tiny model's initializer range, the sampling): at 0.02 the tied head mostly gives back\n# the input token, so the penalty of row 1's draft decides picks; at 0.2 the tokens vary\nSAMPLINGS = {\"pen\": (0.02, (0.8, 5, 0.9, 1.5)), \"greedy-pen\": (0.02, (0.0, 0, 1.0, 3.0)),\n             \"free\": (0.2, (1.5, 20, 1.0, 1.0)), \"varied-pen\": (0.2, (0.8, 5, 0.9, 1.1))}\n\n\ndef _plain_sampled(spec, W, prompt, N, samp, seed, cfg, stop=()):\n    \"\"\"Plain decode's sampled tokens (the device sampler's numpy model, generate.reference_pick,\n    on resident decode's logits) with the uniforms of default_rng(seed), as the device takes\n    them (fp32, below 1), that engine (the prompt and the tokens but the last fed), and the\n    number of picks that the penalty of the token before decides (new to the context: a\n    verify's row 1 must count its draft).\"\"\"\n    ref = Engine(spec, W, cap=512, cfg=cfg, resident=True)\n    u = np.minimum(np.random.default_rng(seed).random(N).astype(np.float32),\n                   np.float32(1 - 2.0 ** -24))\n    c, out, lg, hits = list(prompt), [], ref.prefill(prompt), 0\n    for i in range(N):\n        out.append(G.reference_pick(lg, samp, c, u[i]))\n        if i and c[-1] not in c[:-1]:\n            hits += out[-1] != G.reference_pick(lg, samp, c[:-1], u[i])\n        c.append(out[-1])\n        if out[-1] in stop or i == N - 1:\n            return out, ref, hits\n        lg = ref.step(out[-1])\n\n\n@pytest.mark.parametrize(\"P, drafter, how, N, stop\", [\n    (250, \"right\", \"pen\", 16, False),       # across the bucket's end, accepted pairs\n    (251, \"mixed\", \"pen\", 15, False),       # E at 255, then D1 and the next bucket's V\n    (249, \"mtp\", \"pen\", 15, False),\n    (250, \"right\", \"greedy-pen\", 16, False),\n    (250, \"mixed\", \"free\", 16, False),      # no penalty: top-k 20, no top-p\n    (250, \"right\", \"varied-pen\", 16, False),\n    (252, \"right\", \"pen\", 15, True),        # a stop id\n    (30, \"right\", \"kh16\", 6, False)])       # 16 DeltaNet heads (the 0.8B's and 2B's)\ndef test_mtp_sampled_loop_is_plain_sampling(P, drafter, how, N, stop):\n    \"\"\"The sampled MTP loop on the device (docs/mtp.md 11) gives plain sampled decode's tokens\n    for the same uniforms, whatever the drafts: the verify's row 0 samples a0 with position p +\n    1's uniform and accepts the draft iff a0 equals it, row 1 samples a1 with p + 2's, its\n    repetition penalty counting the draft (new to the context, which decides picks here, or\n    not); the context is left as plain decode leaves it.\"\"\"\n    kh16 = how == \"kh16\"\n    init, sp = SAMPLINGS[\"pen\" if kh16 else how]\n    _, W, spec = _tiny_model(16, 16, init=init) if kh16 else _tiny_model(8, init=init)\n    cfg = board_config(DRAM_BYTES=1 << 26, DSTEP=True, STREAM=True, PAIR=True) if kh16 else CFG\n    W = _mtp_weights(W, spec)\n    samp = G.Sampling(*sp)\n    prompt = [int(t) for t in np.random.default_rng(P).integers(0, 1000, P)]\n    want, ref, hits = _plain_sampled(spec, W, prompt, N, samp, 5, cfg)\n    ids = []\n    if stop:                                # the second of an accepted pair stops it: the first\n        k = next(k for k in range(2, len(want), 2) if want[k] not in want[:k])  # new to them\n        ids = [want[k]]\n        want, ref, _ = _plain_sampled(spec, W, prompt, N, samp, 5, cfg, ids)\n        assert len(want) == k + 1\n    assert len(set(want)) > len(want) // 2\n    if how in (\"pen\", \"greedy-pen\") and not stop:\n        assert hits >= 3\n    if how == \"pen\" and not stop:           # drafts in the context already, too\n        assert any(t in want[:i] for i, t in enumerate(want))\n    right = np.zeros(514, np.float32)\n    right[P:P + len(want)] = want\n    drafts = {\"right\": right, \"mtp\": None,\n              \"mixed\": np.where(np.arange(514) % 3, right, (right + 7) % 1000)}[drafter]\n    eng = mtp_engine(spec, W, cap=512, cfg=cfg)\n    dec = MTPDecoder(eng)\n    st = dec.generate_card(prompt, max_new=N, stop=ids, drafts=drafts, sampling=samp,\n                           rng=np.random.default_rng(5))\n    assert st.tokens == want\n    if drafter == \"right\" and not stop:\n        assert sum(st.accepted) >= len(want) // 2 - 2\n    assert eng.pos == ref.pos == P + len(want) - 1\n    assert all(np.array_equal(a, b) for a, b in\n               zip(_states(eng, spec, dec.slot), _states(ref, spec, 0)))\n\n\ndef _mtp_kv(eng, n):\n    \"\"\"The MTP layer's KV cache at positions [0, n): K, its scales and V's, per head.\"\"\"\n    kv = eng.image.descriptors(0, 0).mtp.layer.kv\n    d, D, rd = kv.d, kv.D, eng.backend.read\n    return [x for _, r in sorted(kv.heads.items())\n            for x in (rd(0, Affine.of(r[\"k\"]).const, n * d),\n                      rd(0, Affine.of(r[\"ks\"]).const, n * 4 * (d // D)),\n                      rd(0, Affine.of(r[\"vs\"]).const, 4 * n))]\n\n\n@pytest.mark.parametrize(\"sampled\", [False, True])\ndef test_mtp_continues_its_context(sampled):\n    \"\"\"A chat's next turn: after the loop's run, a prefill from Engine.pos (the last token,\n    then the new ones) and a second run continue the context. The loop's last D (it runs\n    before the HALT) fills the MTP layer's KV cache at the position before the last token, so\n    the cache, the drafts and the tokens equal those of one fresh decoder over the whole\n    conversation, bit for bit (without it, that position's K differs).\"\"\"\n    _, W, spec = _tiny_model(8, init=0.2)\n    W = _mtp_weights(W, spec)\n    r = np.random.default_rng(3)\n    p1, p2 = [int(t) for t in r.integers(0, 1000, 40)], [int(t) for t in r.integers(0, 1000, 9)]\n    samp = G.Sampling(0.8, 5, 0.9, 1.1) if sampled else None\n\n    def kw(seed):\n        return {} if samp is None else dict(sampling=samp, rng=np.random.default_rng(seed))\n    dec = MTPDecoder(mtp_engine(spec, W, cap=512, cfg=CFG))\n    t1 = dec.generate_card(p1, max_new=12, stop=[], **kw(1)).tokens\n    ctx = p1 + t1 + p2\n    st = dec.generate_card([t1[-1]] + p2, max_new=12, stop=[], context=ctx, **kw(2))\n    fresh = MTPDecoder(mtp_engine(spec, W, cap=512, cfg=CFG))\n    want = fresh.generate_card(ctx, max_new=12, stop=[], **kw(2))\n    assert st.tokens == want.tokens and len(set(st.tokens)) > 6\n    assert dec.eng.pos == fresh.eng.pos == len(ctx) + 11 and dec.draft == fresh.draft\n    assert all(np.array_equal(a, b) for a, b in\n               zip(_mtp_kv(dec.eng, dec.eng.pos), _mtp_kv(fresh.eng, fresh.eng.pos)))\n\n\ndef _same_dram(eng, a, b) -> None:\n    \"\"\"The ISA simulator's DRAM a and the RTL's b after the same MTP loop run: equal but the\n    loop's chain area, where the RTL's slots hold each program's WAITC wait entries after its\n    words (RtlBackend.slot_words, the board uarch's SEQ_WC) and the ISA simulator's the words\n    alone (every difference there, r2 4ead4e53 on: 12948 bytes, all after the programs'\n    words); there each written program's words are equal.\"\"\"\n    from opentpu.llm import mtp as MT\n    g = eng.image.lookup[\"mtpgen\"]\n    lo, hi = g[\"progs\"], g[\"progs\"] + g[\"slot\"] * MT.NK * g[\"nb\"]\n    assert np.array_equal(a[:lo], b[:lo]) and np.array_equal(a[hi:], b[hi:])\n    for key, progs in eng._mtp_gen.items():\n        at = MT.prog_addr(g, key[0], key[1]) + (g[\"slot\"] // 2 if len(key) == 3 else 0)\n        w = np.asarray(I.assemble(progs[0]), \"<u4\").view(np.uint8)\n        assert np.array_equal(a[at:at + w.size], w) and np.array_equal(b[at:at + w.size], w), key\n\n\n@pytest.mark.parametrize(\"split\", [False, True])\ndef test_mtp_loop_on_rtl(have_verilator, split):\n    \"\"\"The MTP loop on the Verilator RTL (the board's memory path): from the same DRAM state (a\n    251-token prefill on the ISA simulator), one run of the loop across the first bucket's end (V, E, D, D1 and the next\n    bucket's V through HALT CHAIN, both parities, drafts from the host's table, every third\n    wrong): the tokens and the image's DRAM equal the ISA simulator's. split: layers 0-2's MLP\n    in fp4 (more than one run of layers), each V and E in two parts (MTPDecoder.split: part 0's\n    HALT CHAIN to part 1 through the split table, the rows' residual through DRAM).\"\"\"\n    from opentpu import rtlsim\n    from opentpu.llm.rtl_backend import RtlBackend\n    _, W, spec = _tiny_model(8)\n    W = _mtp_weights(W, spec)\n    if split:\n        spec = dataclasses.replace(spec, formats=\"mlp@0-2=fp4\")\n    P, N = 251, 9\n    prompt = [int(t) for t in np.random.default_rng(P).integers(0, 1000, P)]\n    want = _plain(spec, W, prompt, N, {})\n    right = np.zeros(514, np.float32)\n    right[P:P + N] = want\n    drafts = np.where(np.arange(514) % 3, right, (right + 7) % 1000)\n    eng = mtp_engine(spec, W, cap=512, cfg=CFG)\n    dec = MTPDecoder(eng)\n    dec.split = split or None\n    a0, d = dec.prefill(prompt, MTPStats())\n    isa, n = eng.backend, eng.image.nbytes\n    rtl = RtlBackend(eng.cfg, [isa.machine.slices[0].dram[:n]], uarch=rtlsim.BOARD_UARCH,\n                     axi=True, boot=True)\n    st = dec.loop_card(a0, d, N, drafts=drafts)\n    assert st.tokens == want and 0 < sum(st.accepted) < st.iterations\n    assert any(len(k) == 3 for k in eng._mtp_gen) == split\n    eng.backend, eng.pos, dec.slot = rtl, P, 0\n    eng.__dict__.pop(\"_mtp_gen\")            # the chain area: written again, to the RTL's DRAM\n    got = dec.loop_card(a0, d, N, drafts=drafts)\n    assert got.tokens == want\n    _same_dram(eng, isa.machine.slices[0].dram[:n], rtl.drams[0][:n])\n\n\ndef test_mtp_sampled_loop_on_rtl(have_verilator):\n    \"\"\"The sampled MTP loop on the Verilator RTL: from the same DRAM state (a 251-token\n    prefill on the ISA simulator, a0 the sampler's pick), one run across the first bucket's end\n    with the repetition penalty (row 1's draft counted), drafts from the host's table, every\n    third wrong: the tokens and the image's DRAM equal the ISA simulator's.\"\"\"\n    from opentpu import rtlsim\n    from opentpu.llm.rtl_backend import RtlBackend\n    _, W, spec = _tiny_model(8)\n    W = _mtp_weights(W, spec)\n    P, N = 251, 9\n    samp = G.Sampling(*SAMPLINGS[\"pen\"][1])\n    prompt = [int(t) for t in np.random.default_rng(P).integers(0, 1000, P)]\n    want, _, _ = _plain_sampled(spec, W, prompt, N, samp, 5, CFG)\n    right = np.zeros(514, np.float32)\n    right[P:P + N] = want\n    drafts = np.where(np.arange(514) % 3, right, (right + 7) % 1000)\n    eng = mtp_engine(spec, W, cap=512, cfg=CFG)\n    dec = MTPDecoder(eng)\n    u0 = np.minimum(np.float32(np.random.default_rng(5).random()), np.float32(1 - 2.0 ** -24))\n    a0, d = dec.prefill(prompt, MTPStats(), pick=lambda lg: G.reference_pick(lg, samp, prompt, u0))\n    isa, n = eng.backend, eng.image.nbytes\n    rtl = RtlBackend(eng.cfg, [isa.machine.slices[0].dram[:n]], uarch=rtlsim.BOARD_UARCH,\n                     axi=True, boot=True)\n\n    def rng():                              # the uniforms after a0's\n        r = np.random.default_rng(5)\n        r.random()\n        return r\n    kw = dict(drafts=drafts, samp=samp, context=prompt + [a0])\n    st = dec.loop_card(a0, d, N, rng=rng(), **kw)\n    assert st.tokens == want and 0 < sum(st.accepted) < st.iterations\n    eng.backend, eng.pos, dec.slot = rtl, P, 0\n    eng.__dict__.pop(\"_mtp_gen\")            # the chain area: written again, to the RTL's DRAM\n    got = dec.loop_card(a0, d, N, rng=rng(), **kw)\n    assert got.tokens == want\n    _same_dram(eng, isa.machine.slices[0].dram[:n], rtl.drams[0][:n])\n\n\nclass _Chars:\n    \"\"\"One token per character, both ways: a reply's text gives back its ids, so the next\n    turn's template starts with the fed tokens (the context continues).\"\"\"\n\n    def apply_chat_template(self, history, add_generation_prompt, enable_thinking, tokenize):\n        return [ord(c) for m in history for c in m[\"content\"]]\n\n    def decode(self, ids, skip_special_tokens=True):\n        return \"\".join(map(chr, ids))\n\n\n@pytest.mark.parametrize(\"sampled\", [False, True])\ndef test_chat_with_mtp(sampled):\n    \"\"\"otpu-chat --mtp: Chat on an MTP engine decodes with MTPDecoder (its prefill, the host\n    picking the first token, then the loop on the device), turn after turn. The replies, what\n    is fed and the context equal those of Chat on a plain engine with the same sampler and\n    seed: a reply cut at max_new resumes from its last token (the draft after it kept), and\n    the next turn's prefill continues the context.\"\"\"\n    from opentpu.host.chat import Chat, sampler\n    _, W, spec = _tiny_model(8, init=0.2)\n    W = _mtp_weights(W, spec)\n    args = (0.8, 5, 0.9, 3, 1.1) if sampled else (0, 0, 1.0, None)\n    plain, mtp = (Chat(e, _Chars(), False, sampler(*args), 10) for e in (\n        Engine(spec, W, cap=512, cfg=CFG, resident=True), mtp_engine(spec, W, cap=512, cfg=CFG)))\n    assert mtp.use_mtp and not plain.use_mtp and plain.on_card\n    got = {}\n    for c in (plain, mtp):\n        shown = []\n        r1, t1 = c.ask(\"hello there\", lambda d, turn: shown.append(d))\n        r2, t2 = c.resume()\n        r3, t3 = c.ask(\"and then?\")\n        assert t1.end == \"max_new\" and not t3.restarted and r1 == \"\".join(shown)\n        got[c is mtp] = (r1, r2, r3, list(c.fed), c.eng.pos, [t.gen_tokens for t in (t1, t2, t3)])\n        if c is mtp:\n            assert t1.mtp_iters and \"MTP acceptance\" in t3.line()\n    assert got[True] == got[False]\n    assert len(set(got[True][2])) > 4\n", "tests/test_mtp_moe.py": "\"\"\"Speculative decoding with the MTP drafter on a streamed Qwen3.5-MoE (opentpu/llm/mtp.py,\ndocs/mtp.md 12, docs/offload.md 15.6) on the ISA simulator: the verify run's two rows go through\neach MoE layer as one request for their experts' union (moe.moe_ffn_rows), the MTP layer's MoE\nis one more layer of the expert server's (its experts in the pool after the model's), and the\ngreedy tokens equal plain greedy decode's bit for bit whatever the drafts, with 2k expert slots\na layer (misses on every layer). A tiny random Qwen3.5-MoE (tests/test_qwen35_moe.py) with random\nmtp.* weights in the checkpoint's form (its experts a tensor each).\"\"\"\nimport dataclasses\nimport os\n\nimport numpy as np\nimport pytest\n\nfrom opentpu.isasim import board_config\nfrom opentpu.llm.mtp import MTPDecoder, mtp_engine\nfrom opentpu.llm.qwen3 import Engine\n\nfrom test_qwen35_moe import K, _tiny, _untied\n\nSLOTS = 2 * K               # a layer's slots: a 2-row request's union fits (k of E = 8 each)\n\npytest.importorskip(\"torch\")\n\nCFG = board_config(DRAM_BYTES=1 << 26, DSTEP=True, STREAM=True, PAIR=True)   # (an int8 MTP\n#   image with the default MoE tiles' mask tiles and I/O scratch: 32 MiB, docs/tiled_prefill.md 14)\n\n\ndef _moe_mtp_weights(W, spec, seed=1):\n    \"\"\"Random mtp.* tensors for the tiny MoE (zero-centred norms; the MoE as the 35B's\n    checkpoint has it: the router mlp.gate, the shared expert and its gate, each routed\n    expert's gate / up / down a tensor of its own).\"\"\"\n    r = np.random.default_rng(seed)\n    H, d, mo = spec.hidden, spec.head_dim, spec.moe\n\n    def lin(o, i, s=1.0):\n        return (s * r.uniform(-1, 1, (o, i)) / np.sqrt(i)).astype(np.float32)\n\n    def norm(n):\n        return (0.1 * r.standard_normal(n)).astype(np.float32)\n    a, m = \"mtp.layers.0.self_attn.\", \"mtp.layers.0.mlp.\"\n    out = {\"mtp.pre_fc_norm_embedding.weight\": norm(H), \"mtp.pre_fc_norm_hidden.weight\": norm(H),\n           \"mtp.fc.weight\": lin(H, 2 * H), \"mtp.norm.weight\": norm(H),\n           \"mtp.layers.0.input_layernorm.weight\": norm(H),\n           \"mtp.layers.0.post_attention_layernorm.weight\": norm(H),\n           a + \"q_proj.weight\": lin(2 * spec.n_q * d, H), a + \"k_proj.weight\": lin(spec.n_kv * d, H),\n           a + \"v_proj.weight\": lin(spec.n_kv * d, H), a + \"o_proj.weight\": lin(H, spec.n_q * d),\n           a + \"q_norm.weight\": norm(d), a + \"k_norm.weight\": norm(d),\n           m + \"gate.weight\": lin(mo.E, H, 4.0), m + \"shared_expert_gate.weight\": lin(1, H),\n           m + \"shared_expert.gate_proj.weight\": lin(mo.shared, H),\n           m + \"shared_expert.up_proj.weight\": lin(mo.shared, H),\n           m + \"shared_expert.down_proj.weight\": lin(H, mo.shared)}\n    for e in range(mo.E):\n        out.update({f\"{m}experts.{e}.gate_proj.weight\": lin(mo.ffn, H),\n                    f\"{m}experts.{e}.up_proj.weight\": lin(mo.ffn, H),\n                    f\"{m}experts.{e}.down_proj.weight\": lin(H, mo.ffn)})\n    return {**W, **out}\n\n\n@pytest.fixture(scope=\"module\")\ndef tiny_moe_mtp():\n    \"\"\"(weights, spec): the tiny MoE with an LM head of its own (its int8 embedding table on\n    the host, as the 35B's) and random mtp.* weights.\"\"\"\n    spec, W = _untied(_tiny())\n    return _moe_mtp_weights(W, spec), spec\n\n\nFP4 = dict(wformat=\"fp4\", head_format=\"int8\")\n\n\ndef _plain(spec, W, prompt, N, cfg=CFG, **kw):\n    \"\"\"Plain greedy decode's tokens (resident decode, the host loop, 2k slots a layer).\"\"\"\n    return Engine(spec, W, cap=512, cfg=cfg, rows=1, resident=True, experts=SLOTS,\n                  **kw).generate(prompt, max_new=N)\n\n\n@pytest.mark.parametrize(\"drafter, fmt\", [(\"mtp\", \"int8\"), (\"right\", \"int8\"), (\"wrong\", \"int8\"),\n                                          (\"mixed\", \"int8\"), (\"mixed\", \"fp4\"), (\"mtp\", \"fp4\")])\ndef test_moe_mtp_greedy_is_plain_greedy(tiny_moe_mtp, drafter, fmt):\n    \"\"\"Tokens equal plain greedy decode's for any drafts (the MTP's, all right, all wrong, right\n    but every third) with 2k slots a layer: the verify's two rows request their experts' union\n    in each MoE layer, the MTP layer its own (one more layer of the server's), and every layer\n    misses on the way. The prompt's 9 tokens prefill in runs of 2 rows. fp4: 4-bit weights,\n    whose 2-row MMs pair (PAIR, MCOLS 4) as the decode steps' do.\"\"\"\n    W, spec = tiny_moe_mtp\n    kw = FP4 if fmt == \"fp4\" else {}\n    prompt = [int(t) for t in np.random.default_rng(4).integers(0, 1000, 9)]\n    N = 16\n    want = _plain(spec, W, prompt, N, **kw)\n    P = len(prompt)\n\n    def right(q, out):\n        return want[q - P] if q - P < len(want) else 0\n    drafts = {\"mtp\": None, \"right\": right,\n              \"wrong\": lambda q, out: (right(q, out) + 1) % 1000,\n              \"mixed\": lambda q, out: right(q, out) if q % 3 else (right(q, out) + 7) % 1000}\n    eng = mtp_engine(spec, W, cap=512, cfg=CFG, rows=2, experts=SLOTS, **kw)\n    assert eng.image.offload.layers == spec.layers + 1\n    dec = MTPDecoder(eng)\n    m0 = eng.server.misses\n    st = dec.generate(prompt, max_new=N, drafts=drafts[drafter])\n    assert st.tokens == want\n    assert eng.server.misses > m0\n    if drafter == \"right\":\n        assert all(st.accepted[:-1]) and st.iterations <= N // 2 + 1\n    if drafter == \"wrong\":\n        assert not any(st.accepted)\n    E = spec.moe.E\n    if drafter == \"mtp\":                    # the MTP layer's experts went through the server\n        assert any(g // E == spec.layers for g in eng.server.lru[spec.layers])\n\n\ndef test_the_mtp_layers_experts_pack_from_its_tensors(tiny_moe_mtp):\n    \"\"\"The expert server's layer `layers` is the MTP layer's MoE: its slots after the model's,\n    its experts packed from the checkpoint's mtp.layers.0.mlp.experts.E.* tensors.\"\"\"\n    W, spec = tiny_moe_mtp\n    eng = mtp_engine(spec, W, cap=512, cfg=CFG, rows=2, experts=SLOTS)\n    img, E = eng.image, spec.moe.E\n    g = spec.layers * E + 3\n    a = img.expert(W, g)\n    W2 = dict(W)\n    W2[\"mtp.layers.0.mlp.experts.3.up_proj.weight\"] = W[\"mtp.layers.0.mlp.experts.4.up_proj.weight\"]\n    assert not np.array_equal(a, img.expert(W2, g))\n    assert np.array_equal(img.expert(W, 5), img.expert(W2, 5))\n    plain = Engine(spec, W, cap=512, cfg=CFG, rows=1, resident=True, experts=SLOTS).image\n    assert img.offload.layers == plain.offload.layers + 1\n    assert dataclasses.replace(spec).mtp is False\n\n\n@pytest.mark.parametrize(\"P, drafter, fmt, N\", [\n    (250, \"right\", \"int8\", 16),     # V at 254 accepts: the wrap; the last token alone\n    (251, \"right\", \"int8\", 15),     # 253 -> 255: E, then D1 and the next bucket's V\n    (249, \"mixed\", \"int8\", 15),     # E at the other parity\n    (250, \"wrong\", \"int8\", 12),\n    (249, \"right\", \"fp4\", 15),\n    (250, \"mtp\", \"int8\", 15)])\ndef test_moe_mtp_loop_on_the_device_is_plain_greedy(tiny_moe_mtp, P, drafter, fmt, N):\n    \"\"\"The MTP loop on the device (V, E, D, D1 chained through the buckets' programs) on the\n    streamed MoE gives plain greedy decode's tokens across a bucket's end, whatever the drafts,\n    and leaves the committed DeltaNet states as plain decode does. The embedding rows come from\n    the host: the host writes the first V's (a0, d), then each program posts the next one's\n    tokens as one request (V: a0, a1 for the D; D: t, d for the next V; RowServer's rows 0, 1\n    of the slot), and the expert server serves the MoE layers' misses meanwhile.\"\"\"\n    from test_mtp import _states\n    W, spec = tiny_moe_mtp\n    kw = FP4 if fmt == \"fp4\" else {}\n    prompt = [int(t) for t in np.random.default_rng(P).integers(0, 1000, P)]\n    want = _plain(spec, W, prompt, N, **kw)\n    right = np.zeros(514, np.float32)\n    right[P:P + len(want)] = want\n    drafts = {\"right\": right, \"wrong\": (right + 1) % 1000, \"mtp\": None,\n              \"mixed\": np.where(np.arange(514) % 3, right, (right + 7) % 1000)}[drafter]\n    eng = mtp_engine(spec, W, cap=512, cfg=CFG, rows=2, experts=SLOTS, **kw)\n    dec = MTPDecoder(eng)\n    m0 = eng.server.misses\n    eng.row_server.history = []\n    st = dec.generate_card(prompt, max_new=N, stop=[], drafts=drafts)\n    assert st.tokens == want\n    assert eng.server.misses > m0\n    assert len(eng.row_server.history) >= 2 * st.iterations - 2     # both rows, each program\n    if drafter == \"right\":\n        assert sum(st.accepted) >= len(want) // 2 - 2\n    if drafter == \"wrong\":\n        assert not any(st.accepted)\n    ref = Engine(spec, W, cap=512, cfg=CFG, rows=1, resident=True, experts=SLOTS, **kw)\n    ref.prefill(prompt)\n    for t in want[:-1]:\n        ref.step(t)\n    assert eng.pos == ref.pos == P + len(want) - 1\n    assert all(np.array_equal(a, b) for a, b in\n               zip(_states(eng, spec, dec.slot), _states(ref, spec, 0)))\n\n\n@pytest.mark.parametrize(\"P, drafter, N\", [(249, \"mixed\", 15), (250, \"mtp\", 12)])\ndef test_moe_mtp_loop_in_two_parts_is_plain_greedy(tiny_moe_mtp, P, drafter, N):\n    \"\"\"A V or E over IMEM goes in two parts (MTPDecoder._gen_programs; MiniCPM-V's formats give\n    its layers two runs, and its V 6173 instructions against the card's 4096): part 0 the\n    layers before a run's first (plan_cuts), the rows' residual to DRAM, HALT CHAIN to part 1\n    (the rest, the head, the token). Layers 0-2 with int8 DeltaNet weights, 3-5 fp4 (two runs),\n    every V and E split (split True): the loop's tokens are plain greedy decode's of the same\n    formats across a bucket's end (an E), whatever the drafts, and the committed states plain\n    decode's. The cut: layer 3, the runs' middle.\"\"\"\n    from opentpu.llm.mtp import plan_cuts\n    from test_mtp import _states\n    W, spec = tiny_moe_mtp\n    spec = dataclasses.replace(spec, formats=\"delta@0-2=int8\")\n    prompt = [int(t) for t in np.random.default_rng(P).integers(0, 1000, P)]\n    want = _plain(spec, W, prompt, N, **FP4)\n    right = np.zeros(514, np.float32)\n    right[P:P + len(want)] = want\n    drafts = {\"mtp\": None, \"mixed\": np.where(np.arange(514) % 3, right, (right + 7) % 1000)}[\n        drafter]\n    eng = mtp_engine(spec, W, cap=512, cfg=CFG, rows=2, experts=SLOTS, **FP4)\n    assert plan_cuts(eng.image)[0] == 3            # (runs: layers 0-1, 2, 3-4, 5)\n    dec = MTPDecoder(eng)\n    dec.split = True\n    st = dec.generate_card(prompt, max_new=N, stop=[], drafts=drafts)\n    assert st.tokens == want\n    ve = {k for k in eng._mtp_gen if len(k) == 2 and k[1] < 4}    # (V0, V1, E0, E1)\n    assert ve and {k[:2] for k in eng._mtp_gen if len(k) == 3} == ve    # each in two parts\n    ref = Engine(spec, W, cap=512, cfg=CFG, rows=1, resident=True, experts=SLOTS, **FP4)\n    ref.prefill(prompt)\n    for t in want[:-1]:\n        ref.step(t)\n    assert eng.pos == ref.pos == P + len(want) - 1\n    assert all(np.array_equal(a, b) for a, b in\n               zip(_states(eng, spec, dec.slot), _states(ref, spec, 0)))\n\n\ndef test_a_loop_program_that_fits_is_not_split():\n    \"\"\"The split V / E (docs/mtp.md 10.3) changes neither an MTP image's layout nor a program\n    of a model whose V and E fit IMEM: Qwen3.5-35B-A3B's loop programs of bucket 1 (its\n    formats, the card's configuration, its 38 slots a layer) are byte for byte those of the\n    tree before the split (3af05a43) without the image's mask tiles (OTPU_TILE=0). With them\n    (Qwen3.5-MoE's tiles on by default, em-tile 2bb7bb0b) the image is 1,331,200 bytes longer\n    and the areas the programs address move: the same instructions, only address words\n    differing (by 262,144, 1,331,200 and 1,331,328 bytes), their own sum; the tiles' DeltaNet\n    rows (Image.dnrows: 8 of the image's gr / on rows for 4) move them by 9,216 and 12,288 bytes\n    more. A change of the programs themselves updates the sums here.\"\"\"\n    import hashlib\n    from pathlib import Path\n    from opentpu import isa as I\n    from opentpu.host import streamed as ST\n    from opentpu.llm import load_spec\n    from opentpu.llm import mtp as MT\n    d = Path(__file__).resolve().parents[1] / \"models\" / \"Qwen3.5-35B-A3B\"\n    if not (d / \"config.json\").exists():\n        pytest.skip(\"no models/Qwen3.5-35B-A3B\")\n    cfg = board_config(PAIR=True, DSTEP=True, STREAM=True)\n    spec = dataclasses.replace(load_spec(d), mtp=True)\n    wf, hf, fm = ST.defaults(spec)\n    probe = ST.probe(spec, cfg, 2048, rows=2, wformat=wf, head_format=hf, formats=fm,\n                     lookup=True)\n    n = ST.fit_experts(spec, cfg, 2048, probe)\n    img = spec.image(cfg, 2048, 1, 2, wf, hf, lookup=True, experts=n, formats=fm)\n    h = hashlib.sha256()\n    for k in range(MT.NK):\n        progs = MT.compile_gen(img, 1, k, 256)\n        assert all(len(p) <= cfg.IMEM_WORDS // 8 for p in progs)\n        for p in progs:\n            h.update(np.asarray(I.assemble(p), \"<u4\").tobytes())\n    assert n == 38\n    untiled = os.environ.get(\"OTPU_TILE\", \"\").strip() == \"0\"\n    assert h.hexdigest() == (\"7f3bacfe386c84838742206943cb20db6ea989d2a4eb6cf63fdab651d5ffc103\"\n                             if untiled else\n                             \"99da9dd63f736e7c92e4602d9a5a71ba84ba1b23ee78d5b3b2a4a7a349687e49\")\n\n\n@pytest.mark.parametrize(\"P, drafter, sp\", [\n    (250, \"right\", (0.8, 5, 0.9, 1.1)),     # penalty: row 1's counts the draft\n    (251, \"mixed\", (1.5, 20, 1.0, 1.0)),    # E at 255; no penalty, top-k 20\n    (249, \"mtp\", (0.8, 5, 0.9, 1.1))])\ndef test_moe_mtp_sampled_loop_is_plain_sampling(tiny_moe_mtp, P, drafter, sp):\n    \"\"\"The sampled MTP loop on the device on the streamed MoE gives plain sampled decode's\n    tokens for the same uniforms whatever the drafts (the verify samples a0 with p + 1's\n    uniform and accepts iff a0 is the draft, a1 with p + 2's), and leaves the committed\n    states as plain decode does.\"\"\"\n    from opentpu.llm import generate as G\n    from test_mtp import _states\n    W, spec = tiny_moe_mtp\n    samp, N, seed = G.Sampling(*sp), 15, 5\n    prompt = [int(t) for t in np.random.default_rng(P).integers(0, 1000, P)]\n    ref = Engine(spec, W, cap=512, cfg=CFG, rows=1, resident=True, experts=SLOTS)\n    u = np.minimum(np.random.default_rng(seed).random(N).astype(np.float32),\n                   np.float32(1 - 2.0 ** -24))\n    c, want, lg = list(prompt), [], ref.prefill(prompt)\n    for i in range(N):\n        want.append(G.reference_pick(lg, samp, c, u[i]))\n        c.append(want[-1])\n        if i < N - 1:\n            lg = ref.step(want[-1])\n    assert len(set(want)) > len(want) // 2\n    right = np.zeros(514, np.float32)\n    right[P:P + len(want)] = want\n    drafts = {\"right\": right, \"mtp\": None,\n              \"mixed\": np.where(np.arange(514) % 3, right, (right + 7) % 1000)}[drafter]\n    eng = mtp_engine(spec, W, cap=512, cfg=CFG, rows=2, experts=SLOTS)\n    dec = MTPDecoder(eng)\n    st = dec.generate_card(prompt, max_new=N, stop=[], drafts=drafts, sampling=samp,\n                           rng=np.random.default_rng(seed))\n    assert st.tokens == want\n    if drafter == \"right\":\n        assert sum(st.accepted) >= len(want) // 2 - 2\n    assert eng.pos == ref.pos == P + len(want) - 1\n    assert all(np.array_equal(a, b) for a, b in\n               zip(_states(eng, spec, dec.slot), _states(ref, spec, 0)))\n\n\ndef _layered(spec, W, em, cfg=CFG, **kw):\n    \"\"\"An MTP engine whose prompt goes layer by layer (runs of 2 rows), expert-major or not,\n    6 slots a layer (expert-major's scratch beside 2 k).\"\"\"\n    return mtp_engine(spec, W, cap=512, cfg=cfg, rows=2, experts=6, layer_major=2,\n                      expert_major=em, **kw)\n\n\n@pytest.mark.parametrize(\"em, fmt, drafter\", [(False, \"int8\", \"mtp\"), (True, \"int8\", \"mtp\"),\n                                              (True, \"fp4\", \"mixed\"), (False, \"int8\", \"wrong\")])\ndef test_moe_mtp_layer_major_prefill(tiny_moe_mtp, em, fmt, drafter, monkeypatch):\n    \"\"\"A streamed MoE's prompt layer by layer under MTP (Engine.prefill_layers with the MTP\n    layer's K / V, docs/mtp.md 12): the rows before conv_k - 1 in the rows kernel's runs, then\n    chunks of 24 rows through the model a layer at a time (expert-major or not), after each\n    chunk's last layer runs of up to 4 rows append the MTP layer's K / V (no queries, no MoE),\n    and the last row drafts after the head (its hidden row the head's): the loop's tokens equal\n    plain greedy decode's. int8: the MTP layer's KV cache and the first draft equal those of\n    the 2-row runs' prefill (the MTP layer over every row) bit for bit.\"\"\"\n    from opentpu.llm import qwen35 as Q35\n    from opentpu.llm.mtp import MTPStats\n    from test_mtp import _mtp_kv\n    monkeypatch.setattr(Q35, \"PREFILL_CHUNK\", 24)\n    W, spec = tiny_moe_mtp\n    kw = FP4 if fmt == \"fp4\" else {}\n    prompt = [int(t) for t in np.random.default_rng(11).integers(0, 1000, 40)]\n    P, N = len(prompt), 12\n    want = _plain(spec, W, prompt, N, **kw)\n    right = np.zeros(514, np.float32)\n    right[P:P + len(want)] = want\n    drafts = {\"mtp\": None, \"wrong\": (right + 1) % 1000,\n              \"mixed\": np.where(np.arange(514) % 3, right, (right + 7) % 1000)}[drafter]\n    eng = _layered(spec, W, em, **kw)\n    dec = MTPDecoder(eng)\n    assert dec.by_layers and eng.image.prefill_rows == 24 and eng.expert_major == em\n    st = dec.generate_card(prompt, max_new=N, stop=[], drafts=drafts)\n    assert st.tokens == want\n    m = sorted(k for k in eng._layer_runs if k[0] == \"m\")\n    assert m and max(k[2] for k in m) == 4      # (the host's slot rows)\n    if drafter == \"wrong\":\n        assert not any(st.accepted)\n    if fmt == \"int8\" and drafter == \"mtp\":\n        a, b = MTPDecoder(_layered(spec, W, em)), MTPDecoder(mtp_engine(\n            spec, W, cap=512, cfg=CFG, rows=2, experts=6))\n        assert not b.by_layers\n        ra, rb = a.prefill(prompt, MTPStats()), b.prefill(prompt, MTPStats())\n        assert ra == rb and ra[0] == want[0]\n        assert all(np.array_equal(x, y) for x, y in zip(_mtp_kv(a.eng, P), _mtp_kv(b.eng, P)))\n\n\n@pytest.mark.parametrize(\"P, em, drafter\", [(40, True, \"mtp\"), (256, False, \"mtp\"),\n                                           (255, False, \"mixed\")])\ndef test_moe_mtp_loop_drafts_the_prompts_last_row_first(tiny_moe_mtp, P, em, drafter,\n                                                        monkeypatch):\n    \"\"\"A lazy layer-by-layer prefill (MTPDecoder.prefill(lazy=True), otpu-chat's) returns a0\n    with no draft run, and the loop's first run is the D1 of P - 1's bucket over (hid[0], a0):\n    the same draft, the MTP layer's K / V row at P - 1 and so the same iterations, tokens,\n    accepted drafts, last draft, committed slot and MTP KV cache as the eager prefill's draft\n    run and a loop from the verify, bit for bit. P 256: the D1 at the first bucket's last\n    position chains to the next bucket's V; P 255: to its own bucket's E. A loop that does not\n    run (max_new 1) drafts on its own (_settle), as the eager prefill does.\"\"\"\n    from opentpu.llm import qwen35 as Q35\n    from opentpu.llm.mtp import MTPStats\n    from test_mtp import _mtp_kv\n    monkeypatch.setattr(Q35, \"PREFILL_CHUNK\", 24)\n    W, spec = tiny_moe_mtp\n    prompt = [int(t) for t in np.random.default_rng(P).integers(0, 1000, P)]\n    N = 12\n    want = _plain(spec, W, prompt, N)\n    right = np.zeros(514, np.float32)\n    right[P:P + len(want)] = want\n    drafts = None if drafter == \"mtp\" else np.where(np.arange(514) % 3, right, (right + 7) % 1000)\n    got, drafted = [], []\n    for lazy in (False, True):\n        dec = MTPDecoder(_layered(spec, W, em))\n        st = MTPStats()\n        a0, d = dec.prefill(prompt, st, lazy=lazy)\n        assert (d is None) == lazy and dec.pending == ((P - 1, a0) if lazy else None)\n        drafted.append([k for k, _, _ in st.runs].count(\"mtp prefill\"))\n        out = dec.loop_card(a0, d, max_new=N, stop=[], drafts=drafts)\n        assert dec.pending is None and out.tokens == want\n        got.append((out.accepted, dec.draft, dec.slot, dec.eng.pos, _mtp_kv(dec.eng, dec.eng.pos)))\n    assert drafted[0] == drafted[1] + 1         # (the rows before conv_k - 1 draft as before)\n    (acc, d0, s0, p0, kv0), (acc1, d1, s1, p1, kv1) = got\n    assert (acc, d0, s0, p0) == (acc1, d1, s1, p1)\n    assert all(np.array_equal(x, y) for x, y in zip(kv0, kv1))\n    if P == 40:\n        dec = MTPDecoder(_layered(spec, W, em))\n        a0, _ = dec.prefill(prompt, MTPStats(), lazy=True)\n        assert dec.loop_card(a0, None, max_new=1, stop=[]).tokens == [a0] == want[:1]\n        eager = MTPDecoder(_layered(spec, W, em))\n        assert eager.prefill(prompt, MTPStats()) == (a0, dec.draft) and dec.pending is None\n        assert all(np.array_equal(x, y) for x, y in zip(_mtp_kv(dec.eng, P),\n                                                        _mtp_kv(eager.eng, P)))\n\n\n@pytest.mark.parametrize(\"em\", [False, True])\ndef test_moe_mtp_rollback_to_a_held_snapshot_is_a_rerun(tiny_moe_mtp, em, monkeypatch):\n    \"\"\"A rollback to a snapshot whose next token changed (a chat's next turn): the snapshot\n    after a part (follow: the token after it) holds the part's last row's residual (the K / V\n    run of the expert-major prompt keeps it in its chunk row), the rollback goes back to the\n    snapshot itself, and the next prefill first appends the MTP layer's row before it from\n    that row and the new token (Engine.prefill_layers' fix), then feeds the rest. The MTP\n    layer's KV cache, the committed DeltaNet states, a0 and the first draft equal a fresh\n    decoder's over the new context bit for bit: the row as a run of that position through\n    the model would append it.\"\"\"\n    from opentpu.llm import qwen35 as Q35\n    from opentpu.llm.mtp import MTPStats\n    from test_mtp import _mtp_kv, _states\n    monkeypatch.setattr(Q35, \"PREFILL_CHUNK\", 24)\n    W, spec = tiny_moe_mtp\n    r = np.random.default_rng(5)\n    ids1 = [int(t) for t in r.integers(0, 1000, 40)]\n    at = 30\n    ids2 = ids1[:at] + [int(t) for t in r.integers(0, 1000, 13)]\n    assert ids2[at] != ids1[at]\n    dec = MTPDecoder(_layered(spec, W, em, snapshots=1))\n    assert dec.holds\n    dec.prefill(ids1[:at], MTPStats(), follow=ids1[at])\n    assert dec.snapshot() and at in dec.held\n    dec.prefill(ids1[at:], MTPStats())\n    assert dec.rollback(at) == at == dec.eng.pos and dec.refill[0] == at - 1\n    n0 = len(dec.eng.stats)\n    got = dec.prefill(ids2[at:], MTPStats())\n    assert dec.refill is None and any(k[0] == \"m\" and k[3:] == ((\"xbuf\",) if em else ())\n                                      and k[2] == 1 for k in dec.eng._layer_runs)\n    ref = MTPDecoder(_layered(spec, W, em))\n    assert got == ref.prefill(ids2, MTPStats())\n    L = len(ids2)\n    assert dec.eng.pos == ref.eng.pos == L and len(dec.eng.stats) > n0\n    assert all(np.array_equal(x, y) for x, y in zip(_mtp_kv(dec.eng, L), _mtp_kv(ref.eng, L)))\n    assert all(np.array_equal(x, y) for x, y in zip(_states(dec.eng, spec, dec.slot),\n                                                    _states(ref.eng, spec, ref.slot)))\n\n\ndef test_moe_mtp_layer_major_continues_from_slot_1(tiny_moe_mtp, monkeypatch):\n    \"\"\"A chat's next turn on the layer-major path: the first turn's loop (drafts all right)\n    leaves the states committed in slot 1, and the next prompt's layer runs read and write that\n    slot (the runs of slot 1, compiled apart). The tokens equal one fresh decoder's over the\n    whole conversation, and plain greedy decode's.\"\"\"\n    from opentpu.llm import qwen35 as Q35\n    monkeypatch.setattr(Q35, \"PREFILL_CHUNK\", 24)\n    W, spec = tiny_moe_mtp\n    r = np.random.default_rng(3)\n    p1, p2 = [int(t) for t in r.integers(0, 1000, 30)], [int(t) for t in r.integers(0, 1000, 9)]\n    w1 = _plain(spec, W, p1, 12)\n    right = np.zeros(514, np.float32)\n    right[len(p1):len(p1) + 12] = w1\n    dec = MTPDecoder(_layered(spec, W, True))\n    t1 = dec.generate_card(p1, max_new=12, stop=[], drafts=right).tokens\n    assert t1 == w1 and dec.slot == 1\n    ctx = p1 + t1 + p2\n    st = dec.generate_card([t1[-1]] + p2, max_new=10, stop=[])\n    assert any(k[1:] == (\"slot\", 1) for k in dec.eng._layer_runs if len(k) == 3)\n    assert any(k[0][-1] == \"tile\" for k in dec.eng._layer_runs     # (the turn's tiled runs,\n               if len(k) == 3 and k[1:] == (\"slot\", 1))            # on slot 1)\n    fresh = MTPDecoder(_layered(spec, W, True)).generate_card(ctx, max_new=10, stop=[])\n    assert st.tokens == fresh.tokens == _plain(spec, W, ctx, 10)\n\n\ndef test_streamed_mtp_engine_from_a_checkpoint_and_an_extended_pool(tiny_moe_mtp, tmp_path,\n                                                                      monkeypatch):\n    \"\"\"otpu-chat --mtp on a streamed MoE (streamed.engine(mtp=True)): the checkpoint's mtp.*\n    tensors (LazyWeights(mtp=True)) and the pool pack_pool.py extend makes from the model's own\n    (its experts and marks copied, the MTP layer's after them not packed: the run packs each it\n    asks for from the checkpoint). The loop's tokens equal plain greedy decode's from the\n    model's pool. MiniCPM-V 4.7's case: a checkpoint without mtp.* is refused, and takes them\n    from another (mtp_from), whose identity the pool's key holds: the pool extended for the\n    model's own MTP layer is refused, one extended with --mtp-from serves it. Its expert-major\n    engine runs its layer runs tiled, as the plain one does.\"\"\"\n    import json\n    import runpy\n    import sys\n    from pathlib import Path\n\n    from safetensors.numpy import save_file\n\n    from opentpu.host import streamed as ST\n    from opentpu.host.offload import to_split\n    from opentpu.llm.qwen3 import LazyWeights\n    from test_qwen35_moe import _tiny\n\n    W, spec = tiny_moe_mtp\n    hf = _tiny()[0].config\n    hf.tie_word_embeddings = False\n\n    def checkpoint(d, names):\n        d.mkdir()\n        hf.save_pretrained(d)\n        save_file({k: np.ascontiguousarray(W[k]) for k in names}, str(d / \"model.safetensors\"))\n        return d\n    m = checkpoint(tmp_path / \"model\", list(W))\n    m2 = checkpoint(tmp_path / \"nomtp\", [k for k in W if not k.startswith(\"mtp.\")])\n    tool = str(Path(__file__).resolve().parents[1] / \"tools\" / \"offload\" / \"pack_pool.py\")\n\n    def run(*args):\n        monkeypatch.setattr(sys, \"argv\", [\"pack_pool.py\", *map(str, args)])\n        try:\n            runpy.run_path(tool, run_name=\"__main__\")\n        finally:\n            monkeypatch.undo()\n\n    a, b, c = (tmp_path / f\"{x}.bin\" for x in \"abc\")\n    run(m, a, \"init\")\n    run(m, a, \"pack\", 0, 1)\n    run(m, b, \"extend\", a)\n    v = tmp_path / \"v.bin\"                  # a pool with entries after its experts (vision)\n    v.write_bytes(a.read_bytes() + bytes(range(256)) * (2 * a.stat().st_size // 48 // 256))\n    Path(str(v) + \".packed\").write_bytes(Path(str(a) + \".packed\").read_bytes() + bytes([1, 1]))\n    for x in (\".format\", \".key\"):\n        Path(str(v) + x).write_text(Path(str(a) + x).read_text())\n    run(m2, c, \"extend\", v, \"--mtp-from\", m)\n    nE = spec.layers * spec.moe.E\n    pa, pb = (np.fromfile(str(p) + \".packed\", np.uint8) for p in (a, b))\n    assert pa.tolist() == [1] * nE and pb.tolist() == [1] * nE + [0] * spec.moe.E\n    slot = a.stat().st_size // nE\n    assert b.read_bytes()[:nE * slot] == c.read_bytes()[:nE * slot] == a.read_bytes()\n    assert b.stat().st_size == c.stat().st_size == (nE + spec.moe.E) * slot\n    assert Path(str(c) + \".packed\").read_bytes() == pb.tobytes()\n    kb, kc = (json.loads(Path(str(p) + \".key\").read_text()) for p in (b, c))\n    assert kb[\"layout\"][\"layers\"] == spec.layers + 1 and \"mtp_from\" not in kb\n    assert kc[\"mtp_from\"] and {k: v for k, v in kc.items() if k not in (\"mtp_from\", \"model\")} \\\n        == {k: v for k, v in kb.items() if k != \"model\"}\n\n    prompt = [int(t) for t in np.random.default_rng(4).integers(0, 1000, 9)]\n    N = 12\n    kw = dict(cap=512, experts=SLOTS, wformat=\"fp4\", head_format=\"int8\")     # (the pools')\n    want = ST.engine(m, CFG, pool=a, **kw).generate(prompt, max_new=N)\n    eng = ST.engine(m, CFG, pool=b, mtp=True, **kw)\n    assert eng.image.rows == 2 and eng.image.offload.layers == spec.layers + 1\n    em = dict(kw, expert_major=True, layer_major=2)\n    assert ST.engine(m, CFG, pool=a, **em).layer_tile\n    assert ST.engine(m, CFG, pool=b, mtp=True, **em).layer_tile\n    dec = MTPDecoder(eng)\n    assert dec.generate_card(prompt, max_new=N, stop=[]).tokens == want\n    got = np.fromfile(str(b) + \".packed\", np.uint8)[nE:]\n    assert got.any()                        # the MTP layer's experts it asked for, packed\n    Wm, img = LazyWeights(m, mtp=True), eng.image\n    pool = np.fromfile(b, np.uint8).reshape(-1, slot)\n    for e in np.nonzero(got)[0]:\n        assert np.array_equal(pool[nE + e], np.asarray(to_split(img.expert(Wm, nE + e)))\n                              .view(np.uint8)), e\n    with pytest.raises(ValueError, match=\"no mtp.. tensors\"):\n        ST.engine(m2, CFG, pool=c, mtp=True, **kw)\n    with pytest.raises(ST.PoolError, match=\"mtp_from differ\"):\n        ST.engine(m2, CFG, pool=b, mtp=True, mtp_from=m, **kw)\n    eng = ST.engine(m2, CFG, pool=c, mtp=True, mtp_from=m, **kw)\n    assert MTPDecoder(eng).generate_card(prompt, max_new=N, stop=[]).tokens == want\n\n\ndef test_moe_mtp_chat_turns_roll_back_to_the_reply(tiny_moe_mtp, monkeypatch):\n    \"\"\"otpu-chat's turns with MTP on the streamed MoE (Chat over an MTP engine whose prompt goes\n    layer by layer): from the second turn on the context rolls back to the last reply's start\n    (the snapshot the turn took there, with the residual row before it: the MTP layer's row\n    before it appended again from that row and the new token, MTPDecoder.holds) and feeds the\n    reply and the new message, not the whole conversation (restarted False). Chat.fed holds every token fed, the first\n    prompt's conv_k - 1 rows of the rows kernel too (without them the next turn found no common\n    part and started over). Each turn's reply equals plain greedy decode's of its rendering.\"\"\"\n    from opentpu.host.chat import Chat, sampler\n    from opentpu.llm import qwen35 as Q35\n    from test_chatkv import MESSAGES, _QwenTok\n    monkeypatch.setattr(Q35, \"PREFILL_CHUNK\", 24)\n    W, spec = tiny_moe_mtp\n    tok = _QwenTok()\n    chat = Chat(_layered(spec, W, False, snapshots=1), tok, False, sampler(0, 0, 1.0, None), 6)\n    assert chat.use_mtp and chat.mtp.by_layers\n    start = None\n    for i, msg in enumerate(MESSAGES[:3]):\n        reply, turn = chat.ask(msg)\n        ids = tok.apply_chat_template(chat.history[:-1], True, False, True)\n        assert not turn.restarted, i\n        assert chat.fed[:len(ids)] == ids, i\n        assert turn.reused == (start if i else 0), i\n        want = Engine(spec, W, cap=512, cfg=CFG, rows=1, resident=True,\n                      experts=SLOTS).generate(ids, max_new=6)\n        assert chat._reply == [x for x in want if x not in spec.eos], i\n        start = len(tok.apply_chat_template(chat.history, False, False, True)) - \\\n            len(chat.history[-1][\"content\"]) - len(f\"{tok.E}\\n\")\n\n\ndef test_chatmoe_traces_each_turns_host_phases(tmp_path, monkeypatch, capsys):\n    \"\"\"tools/qual/chatmoe.py --trace's host phases (_Phases) on a tiny MoE of 16 DeltaNet heads\n    with an LM head of its own and its MTP layer, from a checkpoint and pools as the card's\n    (pack_pool.py init, pack, extend), three turns that roll back to the reply's start (a\n    Qwen3-shaped template): each turn's phases from its start to its first token, a0 last, the\n    calls' as `calls` (each with its end_prefill), the first rows of the MTP decoder's prompt\n    in a prefill of their own with their runs, a later turn's rollback before its calls and\n    the snapshot (MTP's with the held row's read) between them. Host bookkeeping: the traced\n    run's tokens are the untraced one's (--check), plain decode's and MTP's the same, and the\n    trace keeps its calls as before.\"\"\"\n    import json\n    import pickle\n    import runpy\n    import sys\n    from pathlib import Path\n\n    from safetensors.numpy import save_file\n\n    from test_chatkv import MESSAGES, _QwenTok\n    root = Path(__file__).resolve().parents[1]\n    m, W, spec = _tiny(nv=16)\n    spec, W = _untied((m, W, spec))\n    W = _moe_mtp_weights(W, spec)\n    m.config.tie_word_embeddings = False\n    d = tmp_path / \"model\"\n    m.config.save_pretrained(d)\n    save_file({k: np.ascontiguousarray(v) for k, v in W.items()}, str(d / \"model.safetensors\"))\n\n    def pack(*args):\n        monkeypatch.setattr(sys, \"argv\", [\"pack_pool.py\", *map(str, args)])\n        try:\n            runpy.run_path(str(root / \"tools\" / \"offload\" / \"pack_pool.py\"), run_name=\"__main__\")\n        finally:\n            monkeypatch.undo()\n    a, b = tmp_path / \"a.bin\", tmp_path / \"b.bin\"\n    pack(d, a, \"init\")\n    pack(d, a, \"pack\", 0, 1)\n    pack(d, b, \"extend\", a)\n    cfg = tmp_path / \"cfg.pkl\"\n    cfg.write_bytes(pickle.dumps(board_config(DRAM_BYTES=1 << 26, DSTEP=True, STREAM=True,\n                                              PAIR=True)))\n\n    class Tok(_QwenTok):                    # (chatmoe's _Pinned passes the template a date)\n        def apply_chat_template(self, history, add_generation_prompt=True,\n                                enable_thinking=False, tokenize=True, **kw):\n            return super().apply_chat_template(history, add_generation_prompt,\n                                               enable_thinking, tokenize)\n    monkeypatch.delenv(\"OTPU_FORMATS\", raising=False)\n    monkeypatch.setattr(\"transformers.AutoTokenizer.from_pretrained\", lambda p: Tok())\n    sys.path.insert(0, str(root / \"tools\" / \"qual\"))\n    try:\n        import chatmoe\n    finally:\n        sys.path.remove(str(root / \"tools\" / \"qual\"))\n    argv = [str(d), \"--cfg\", str(cfg), \"--cap\", \"512\", \"--max-new\", \"6\", \"--em-rows\", \"8\"]\n    argv += [x for msg in MESSAGES[:3] for x in (\"--turn\", msg)]\n\n    def run(*args):\n        assert chatmoe.main(argv + [str(x) for x in args]) == 0\n        return capsys.readouterr().out\n    run(\"--pool\", a, \"--trace\", tmp_path / \"ta.json\", \"--out\", tmp_path / \"a.json\")\n    run(\"--pool\", b, \"--mtp\", \"--out\", tmp_path / \"b.json\")\n    out = run(\"--pool\", b, \"--mtp\", \"--trace\", tmp_path / \"tb.json\", \"--out\", tmp_path / \"bt.json\",\n              \"--check\", tmp_path / \"b.json\")\n    assert \"[PASS]\" in out and out.count(\"    phases: \") == 3\n    ra, rb, rt = (json.loads((tmp_path / f\"{x}.json\").read_text()) for x in (\"a\", \"b\", \"bt\"))\n    assert rb[\"mtp\"] and [t[\"tokens\"] for t in ra[\"turns\"]] == [t[\"tokens\"] for t in rb[\"turns\"]]\n    assert all(not t[\"restarted\"] and t[\"reused\"] for t in rb[\"turns\"][1:])\n    assert any(c[\"em\"] for t in rb[\"turns\"] for c in t[\"calls\"])\n    for x, r in ((\"ta\", ra), (\"tb\", rt)):\n        tr = json.loads((tmp_path / f\"{x}.json\").read_text())\n        assert tr[\"run_fields\"] == [\"key\", \"start\", \"end\", \"cycles\"] and \\\n            tr[\"event_fields\"] == [\"seen\", \"done\", \"kind\", \"layer or expert\", \"misses or bytes\"]\n        assert [(c[\"rows\"], c[\"em\"]) for c in tr[\"calls\"]] == \\\n            [(c[\"rows\"], c[\"em\"]) for t in r[\"turns\"] for c in t[\"calls\"]]\n        assert tr[\"phase_fields\"] == [\"phase\", \"start\", \"end\", \"cycles\"]\n        assert [t[\"calls\"] for t in tr[\"turns\"]] == \\\n            [[k - len(t[\"calls\"]), k] for k, t in\n             zip(np.cumsum([len(t[\"calls\"]) for t in r[\"turns\"]]).tolist(), r[\"turns\"])]\n        for i, (t, rt) in enumerate(zip(tr[\"turns\"], r[\"turns\"])):\n            ph = t[\"phases\"]\n            assert t[\"ttft_s\"] == pytest.approx(rt[\"ttft_s\"], abs=1e-3), (x, i)\n            assert {p[0] for p in ph} <= set(chatmoe.PHASES), (x, i)\n            assert all(0 <= p[1] <= p[2] for p in ph), (x, i)\n            a0 = [p for p in ph if p[0] == \"a0\"]\n            assert len(a0) == 1 and a0[0][2] <= t[\"ttft_s\"] + 1e-3, (x, i)\n            assert all(p[1] <= a0[0][1] for p in ph), (x, i)        # (none starts after a0)\n            calls = [p for p in ph if p[0] == \"prefill_layers\"]\n            assert len(calls) == len(rt[\"calls\"]), (x, i)\n            for p, c in zip(calls, rt[\"calls\"]):        # (a call's s is inside its span)\n                assert p[2] - p[1] >= c[\"s\"] - 1e-3, (x, i)\n                assert sum(q[0] == \"end_prefill\" and p[1] <= q[1] <= q[2] <= p[2]\n                           for q in ph) == 1, (x, i)\n            runs = [p for p in ph if p[0] == \"run\"]\n            assert not any(p[1] < q[1] < p[2] for p in calls for q in runs), (x, i)\n            if i:                       # (the rollback first, the snapshot between the calls)\n                rb_ = [p for p in ph if p[0] == \"rollback\"]\n                assert len(rb_) == 1 and rb_[0][2] <= calls[0][1], (x, i)\n            snap = [p for p in ph if p[0] == \"snapshot\"]\n            assert len(snap) == 1 and calls[0][2] <= snap[0][1] <= snap[0][2] <= calls[-1][1]\n            held = [p for p in ph if p[0] == \"mtp snapshot\"]\n            assert len(held) == (x == \"tb\"), (x, i)\n            assert not held or held[0][1] <= snap[0][1] <= snap[0][2] <= held[0][2], (x, i)\n            nest = [p for p in ph if p[0] == \"mtp prefill\"]\n            if x == \"ta\":\n                assert not nest, i\n            else:                       # (the part before the snapshot, the rest; the first\n                inner = [p for p in nest if any(q is not p and q[1] <= p[1] <= p[2] <= q[2]\n                                                for q in nest)]     # turn's first rows: a\n                assert len(nest) == 2 + (i == 0) and len(inner) == (i == 0), i  # prefill and\n                for p in inner:                                             # runs of their own\n                    assert p[2] <= calls[0][1], i\n                    assert sum(p[1] <= q[1] <= q[2] <= p[2] for q in runs) >= 2, i\n", "tests/test_mx.py": "\"\"\"The MX MXU (docs/isa.md \"MM\", \"Weight formats\", \"Quantization\"; docs/mx_mxu.md): the ISA\nsimulator against a scalar model written from the definition -- QACT's and QST's row scale and\npower-of-two group offsets, and MM's exact integer per output (B = m << (W - dw - da), groups\nwhose shift is negative drop) with one fp32 epilogue, for every weight format, UNIT, RSC, PAIR,\nk0, ACC and ASCALE.\"\"\"\nimport numpy as np\nimport pytest\n\nfrom opentpu import Config, fp32 as F, isa as I, quant as Q\nfrom opentpu.isasim import Machine, SimError\n\nX, WA, SA, OUT, AS = 0, 1 << 15, 3 << 14, 1 << 12, 1 << 11\nDRAM = 1 << 17\n\n\ndef _f(v):\n    return np.float32(F.ftz(np.float32(v)))\n\n\ndef _amax(v):\n    return max((abs(_f(t)) for t in v), key=lambda t: np.float32(t).view(np.uint32))\n\n\ndef _offset(a, amax):\n    \"\"\"The largest d <= 31 with a * 2^d <= amax (a <= amax), 0 for a == 0.\"\"\"\n    if a == 0:\n        return 0\n    d = 0\n    while d < 31 and np.float64(a) * 2.0 ** (d + 1) <= np.float64(amax):\n        d += 1\n    return d\n\n\ndef ref_quantize(row, g, row_mode):\n    \"\"\"docs/isa.md \"Quantization\" of one row, scalar: (q, S, d per group).\"\"\"\n    amax = _amax(row)\n    S = np.float32(0) if amax == 0 else F.mul(amax, F.INV127)\n    inv = np.float32(0) if amax == 0 else F.mul(np.float32(127), F.recip(np.float32(amax)))\n    q, ds = [], []\n    for i in range(0, len(row), g):\n        d = 0 if row_mode else _offset(_amax(row[i:i + g]), amax)\n        ds.append(d)\n        ig = F.mul(inv, np.float32(2.0 ** d))\n        q += [int(F.q8(F.mul(np.float32(t), ig))) for t in row[i:i + g]]\n    return q, np.float32(S), ds\n\n\ndef _run(cfg, dram, prog):\n    return Machine(cfg, [prog + [I.halt()]], [dram.copy()]).run().slices[0]\n\n\n@pytest.mark.parametrize(\"row_mode\", [False, True])\ndef test_qact_row_scale_and_sub_block_offsets(row_mode):\n    cfg = Config(S=1, D=32, MCOLS=4, ACT_BLOCKS=8)\n    rng = np.random.default_rng(1)\n    rows, KB = 3, 3\n    x = (rng.standard_normal((rows, KB * cfg.D)) * np.exp(rng.uniform(-6, 6, (rows, KB * 4, 1)))\n         .repeat(cfg.D // 4, axis=2).reshape(rows, -1)).astype(np.float32)\n    x[1, 8:16] = 0                                        # a zero sub-block: d = 0\n    dram = np.zeros(DRAM, np.uint8)\n    dram[:x.nbytes] = x.view(np.uint8).reshape(-1)\n    s = _run(cfg, dram, [I.ld(0, 0, x.size), I.qact(0, rows, 2, KB, KB * cfg.D, row=row_mode)])\n    for r in range(rows):\n        q, S, d = ref_quantize(x[r], cfg.D // 4, row_mode)\n        assert s.act[r, 2 * cfg.D:(2 + KB) * cfg.D].tolist() == q\n        assert np.array_equal(s.ascale[r, 2:2 + KB].view(np.uint32),\n                              np.full(KB, S).view(np.uint32))\n        assert s.adoff[r, 2:2 + KB].reshape(-1).tolist() == d\n\n\n@pytest.mark.parametrize(\"row_mode\", [False, True])\ndef test_qst_writes_the_int8_scale_rows(row_mode):\n    cfg = Config(S=1, D=32, MCOLS=4, ACT_BLOCKS=8)\n    rng = np.random.default_rng(2)\n    rows, KB = 2, 5\n    x = (rng.standard_normal((rows, KB * cfg.D)) * np.exp(rng.uniform(-5, 5, (rows, KB, 1)))\n         .repeat(cfg.D, axis=2).reshape(rows, -1)).astype(np.float32)\n    dram = np.zeros(DRAM, np.uint8)\n    dram[:x.nbytes] = x.view(np.uint8).reshape(-1)\n    dram[SA:SA + 64] = 0xAB                                 # the pad bytes are written 0\n    s = _run(cfg, dram, [I.ld(0, 0, x.size),\n                         I.qst(0, WA, SA, rows, KB, KB * cfg.D, KB * cfg.D, 1, row=row_mode)])\n    sr = 4 if row_mode else 4 + 4 * -(-KB // 4)\n    for r in range(rows):\n        q, S, d = ref_quantize(x[r], cfg.D, row_mode)\n        assert s.dram[WA + r * KB * cfg.D:][:KB * cfg.D].view(np.int8).tolist() == q\n        row = s.dram[SA + r * sr:SA + (r + 1) * sr]\n        assert row[:4].view(np.float32)[0].view(np.uint32) == np.float32(S).view(np.uint32)\n        if not row_mode:\n            assert row[4:4 + KB].tolist() == d and not row[4 + KB:].any()\n\n\nW_OF = I.MX_W\n\n\ndef _scale_rows(rng, wf, N, KBr, rsc, big_offsets):\n    \"\"\"Random scale rows (bytes [N, srs]) and their (Sw [N], dw [N, KBr, G], m [N, KBr, G]).\"\"\"\n    G = 8 if wf == I.WNV else 4\n    sw = (rng.standard_normal(N) * 0.01).astype(np.float32)\n    hi = 20 if big_offsets else 4\n    if rsc:\n        rows = sw[:, None].view(np.uint8).copy()\n        return rows, sw, np.zeros((N, KBr, G), int), np.ones((N, KBr, G), int)\n    if wf == I.W8:\n        dw = rng.integers(0, hi, (N, KBr))\n        srs = 4 + 4 * -(-KBr // 4)\n        rows = np.zeros((N, srs), np.uint8)\n        rows[:, :4] = sw[:, None].view(np.uint8)\n        rows[:, 4:4 + KBr] = dw\n        return rows, sw, np.repeat(dw[:, :, None], G, 2), np.ones((N, KBr, G), int)\n    if wf in (I.W4I, I.W4F):\n        dw = rng.integers(0, hi, (N, KBr))\n        m = rng.integers(0, 64, (N, KBr, G))\n        word = (dw | sum(m[:, :, b] << (8 + 6 * b) for b in range(G))).astype(np.uint32)\n        srs = 8 + 4 * KBr + (4 * KBr) % 8\n        rows = np.zeros((N, srs), np.uint8)\n        rows[:, :4] = sw[:, None].view(np.uint8)\n        rows[:, 8:8 + 4 * KBr] = word.view(np.uint8).reshape(N, -1)\n        return rows, sw, np.repeat(dw[:, :, None], G, 2), m\n    e4 = rng.integers(0, 0x7F, (N, KBr, G))\n    if big_offsets:\n        e4[rng.random(e4.shape) < 0.3] &= 0x0F           # small exponents: groups drop\n    srs = 16 + 8 * KBr + (8 * KBr) % 16\n    rows = np.zeros((N, srs), np.uint8)\n    rows[:, :4] = sw[:, None].view(np.uint8)\n    rows[:, 16:16 + 8 * KBr] = e4.astype(np.uint8).reshape(N, -1)\n    E, Mt = (e4 >> 3) & 15, e4 & 7\n    return rows, sw, 15 - np.maximum(E, 1), np.where(E > 0, 8 + Mt, Mt)\n\n\ndef ref_mm(act, sa, da, wel, sw, dw, m, wf, pair, M):\n    \"\"\"MM's outputs from the definition, scalar Python integers: act [R, KB, D] int, sa [R]\n    (each row's Sa), da [R, KB, 4], wel [N, KB, D] int, sw [N], dw / m [N, KB, G].\"\"\"\n    R, KB, D = act.shape\n    N, G, W = wel.shape[0], dw.shape[2], W_OF[wf]\n    y = np.zeros((M, N), np.float32)\n    for j in range(M):\n        for n in range(N):\n            acc = 0\n            for k in range(KB):\n                r = j + M if pair and k % 2 else j\n                for g in range(G):\n                    b = g * 4 // G\n                    sl = slice(g * D // G, (g + 1) * D // G)\n                    c = int(np.dot(act[r, k, sl].astype(np.int64), wel[n, k, sl].astype(np.int64)))\n                    sh = W - int(dw[n, k, g]) - int(da[r, k, b])\n                    acc += (int(m[n, k, g]) << sh) * c if sh >= 0 else 0\n            assert abs(acc) < 2 ** 47\n            y[j, n] = F.mul(F.mul(np.float32(acc), sw[n]),\n                            F.mul(sa[j], np.float32(2.0 ** -W)))\n    return y\n\n\nCASES = [  # wf, pair, unit, rsc, k0, big offsets\n    (I.W8, False, False, False, 0, False), (I.W8, False, False, False, 3, True),\n    (I.W8, False, False, True, 0, False), (I.W8, False, True, False, 0, False),\n    (I.W4F, False, False, False, 1, False), (I.W4F, True, False, False, 2, True),\n    (I.W4I, True, False, False, 0, False), (I.W4F, True, True, False, 0, False),\n    (I.W4F, False, False, True, 0, False), (I.WNV, False, False, False, 1, True),\n    (I.WNV, True, False, False, 2, False), (I.WNV, True, True, False, 0, False),\n]\n\n\n@pytest.mark.parametrize(\"wf,pair,unit,rsc,k0,big\", CASES)\n@pytest.mark.parametrize(\"KB\", [1, 3])\ndef test_mm_is_one_integer_per_output(wf, pair, unit, rsc, k0, big, KB):\n    cfg = Config(S=1, D=32, MCOLS=4, ACT_BLOCKS=8, PAIR=True)\n    D, M, N = cfg.D, 2 if pair else 3, 5\n    rng = np.random.default_rng(1000 * wf + 10 * KB + k0 + 7 * pair + 3 * unit + rsc)\n    R = 2 * M if pair else M\n    x = (rng.standard_normal((M, KB * D)) * np.exp(rng.uniform(-8 if big else -2, 2,\n                                                                (M, KB * 4, 1)))\n         .repeat(D // 4, axis=2).reshape(M, -1)).astype(np.float32)\n    KBr = k0 + KB                                          # the scale rows' blocks\n    if wf == I.W8:\n        wel = rng.integers(-127, 128, (N, KB, D))\n        data = wel.astype(np.int8).view(np.uint8).reshape(N, KB * D)\n    else:\n        codes = rng.integers(0, 16, (N, KB * D))\n        wel = Q.DEC[\"int4\" if wf == I.W4I else \"fp4\"][codes].reshape(N, KB, D)\n        data = Q.pack4(codes)\n    rs = -(-data.shape[1] // D) * D\n    rows, sw, dw, m = _scale_rows(rng, wf, N, KBr, rsc, big)\n    dram = np.zeros(DRAM, np.uint8)\n    dram[:x.nbytes] = x.view(np.uint8).reshape(-1)\n    for n in range(N):\n        dram[WA + n * rs:WA + n * rs + data.shape[1]] = data[n]\n    srs = rows.shape[1]\n    dram[SA:SA + rows.size] = rows.reshape(-1)\n    s = _run(cfg, dram, [I.ld(0, 0, x.size), I.qact(0, M, 1, KB, KB * D, dup=pair),\n                         I.mm(WA, SA, OUT, N, KB, rs, N, M, 1, srs, unit=unit, wf=wf, pair=pair,\n                              k0=k0, rsc=rsc)])\n    if unit:\n        sw, dw, m = np.ones(N, np.float32), np.zeros_like(dw), np.ones_like(m)\n    act = s.act[:R, D:(1 + KB) * D].reshape(R, KB, D)\n    want = ref_mm(act, s.ascale[:R, 1], s.adoff[:R, 1:1 + KB], wel, sw,\n                  dw[:, k0:k0 + KB], m[:, k0:k0 + KB], wf, pair, M)\n    got = s.tget(OUT + np.arange(M * N)).reshape(M, N)\n    assert np.array_equal(got.view(np.uint32), want.view(np.uint32))\n\n\ndef test_pair_changes_no_bit():\n    \"\"\"PAIR sums the same integer: a 4-bit MM gives the same bits with and without it.\"\"\"\n    cfg = Config(S=1, D=32, MCOLS=4, ACT_BLOCKS=8, PAIR=True)\n    D, M, N, KB = cfg.D, 2, 4, 5\n    rng = np.random.default_rng(5)\n    x = rng.standard_normal((M, KB * D)).astype(np.float32)\n    codes = rng.integers(0, 16, (N, KB * D))\n    data = Q.pack4(codes)\n    rs = -(-data.shape[1] // D) * D\n    rows, *_ = _scale_rows(rng, I.W4F, N, KB, False, True)\n    dram = np.zeros(DRAM, np.uint8)\n    dram[:x.nbytes] = x.view(np.uint8).reshape(-1)\n    for n in range(N):\n        dram[WA + n * rs:WA + n * rs + data.shape[1]] = data[n]\n    dram[SA:SA + rows.size] = rows.reshape(-1)\n    outs = []\n    for pair in (False, True):\n        s = _run(cfg, dram, [I.ld(0, 0, x.size), I.qact(0, M, 0, KB, KB * D, dup=pair),\n                             I.mm(WA, SA, OUT, N, KB, rs, N, M, 0, rows.shape[1], wf=I.W4F,\n                                  pair=pair)])\n        outs.append(s.tget(OUT + np.arange(M * N)).view(np.uint32).copy())\n    assert np.array_equal(*outs)\n\n\ndef test_acc_and_ascale_use_the_mx_output():\n    cfg = Config(S=1, D=32, MCOLS=4, ACT_BLOCKS=8)\n    D, M, N, KB = cfg.D, 2, 3, 2\n    rng = np.random.default_rng(6)\n    x = rng.standard_normal((M, KB * D)).astype(np.float32)\n    old = rng.standard_normal((M, N)).astype(np.float32)\n    alpha = rng.standard_normal(M).astype(np.float32)\n    wel = rng.integers(-127, 128, (N, KB * D)).astype(np.int8)\n    dram = np.zeros(DRAM, np.uint8)\n    dram[:x.nbytes] = x.view(np.uint8).reshape(-1)\n    dram[WA:WA + wel.size] = wel.view(np.uint8).reshape(-1)\n    pre = [I.ld(0, 0, x.size), I.qact(0, M, 0, KB, KB * D)]\n    mm = dict(sa=WA, ssa=AS, out=OUT, n=N, kb=KB, rs=KB * D, ors=N, m=M, ab=0, srs=0, unit=True)\n    base = _run(cfg, dram, pre + [I.mm(**mm)]).tget(OUT + np.arange(M * N)).reshape(M, N)\n    s = Machine(cfg, [pre + [I.mm(**mm, acc=True)] + [I.halt()]], [dram.copy()])\n    sl = s.slices[0]\n    sl.tput(OUT + np.arange(M * N), old.reshape(-1))\n    s.run()\n    assert np.array_equal(sl.tget(OUT + np.arange(M * N)).reshape(M, N).view(np.uint32),\n                          F.add(old, base).view(np.uint32))\n    s = Machine(cfg, [pre + [I.mm(**{**mm, \"ssa\": 0}, acc=True, ascale=AS)] + [I.halt()]],\n                [dram.copy()])\n    sl = s.slices[0]\n    sl.tput(OUT + np.arange(M * N), old.reshape(-1))\n    sl.tput(AS + np.arange(M), alpha)\n    s.run()\n    want = F.add(F.mul(old, alpha[:, None]), base)\n    assert np.array_equal(sl.tget(OUT + np.arange(M * N)).reshape(M, N).view(np.uint32),\n                          want.view(np.uint32))\n\n\ndef test_an_mm_over_two_quantized_ranges_is_refused():\n    \"\"\"MM reads each row's Sa from its first block: blocks two QACTs wrote (two Sa) raise.\"\"\"\n    cfg = Config(S=1, D=32, MCOLS=4, ACT_BLOCKS=8)\n    D = cfg.D\n    x = np.arange(2 * D, dtype=np.float32)\n    dram = np.zeros(DRAM, np.uint8)\n    dram[:x.nbytes] = x.view(np.uint8)\n    prog = [I.ld(0, 0, x.size), I.qact(0, 1, 0, 1, 2 * D), I.qact(D, 1, 1, 1, 2 * D),\n            I.mm(WA, 0, OUT, 1, 2, 2 * D, 1, 1, 0, 0, unit=True)]\n    with pytest.raises(SimError, match=\"Sa\"):\n        _run(cfg, dram, prog)\n\n\ndef test_mm_field_checks():\n    with pytest.raises(ValueError):\n        I.mm(0, 0, 0, 1, 256, 128, 1, 1, 0, 0)               # KB is 8 bits\n    with pytest.raises(ValueError):\n        I.mm(0, 0, 0, 1, 2, 128, 1, 1, 0, 0, wf=I.W4F, pair=True, k0=1)\n    with pytest.raises(ValueError):\n        I.mm(0, 0, 0, 1, 2, 128, 1, 1, 0, 0, wf=I.WNV, rsc=True)\n    ins = I.mm(0, 0, 0, 7, 3, 128, 1, 1, 0, 0, k0=200)\n    assert ins.w[3] == 7 | 3 << 16 | 200 << 24\n", "tests/test_observability.py": "\"\"\"Observability on the board model (sim/verilator/tb_board.sv; docs/observability.md): the\nversion 5 register map, the free-running activity counters and their snapshots, and the\nhardware trace -- whose records, decoded by opentpu/hwtrace.py, must give exactly the trace\nlines the simulator prints (+trace) for the same run.\n\"\"\"\nimport re\n\nimport numpy as np\nimport pytest\n\nfrom opentpu.host.board import (CTRL_CLEAR, CTRL_RUN, R_B_RD, R_B_WR, R_CTRL, R_CYCLES, R_CYCLES_HI,\n                        R_ICOUNT, R_SCRATCH, R_STATUS, R_VERSION, ST_HALTED, Board, SimTransport)\nfrom opentpu.host import regs as R\nfrom opentpu.host.checks import PROG_AT, demo_image, demo_program\nfrom opentpu import isa as I\nfrom opentpu.hwtrace import (R_TRACE_ADDR, R_TRACE_COUNT, R_TRACE_CTRL, R_TRACE_DROP,\n                             R_TRACE_HI, R_TRACE_LO, TRACE_BUSY, TRACE_CLEAR, TRACE_ENABLE,\n                             TRACE_STOP_WHEN_FULL, records_to_trace, ring_order)\nfrom opentpu.kernels import attention_decode, mlp\nfrom opentpu.runtime import compile_kernel\n\nfrom conftest import sim_board_config\nfrom test_kernels import attn_args, mlp_args\n\nR_REGMAP, R_CAPS, R_CORE_KHZ, R_BUILD_ID, R_TEMP, R_SNAP = 0x3C, 0x40, 0x44, 0x48, 0x4C, 0x50\nR_DDR_MTS = 0x54\nCOUNTERS = [\"UPTIME\", \"RUNNING\", \"MXU_BUSY\", \"MXU_MAC\", \"VPU_BUSY\", \"QNT_BUSY\", \"DMA_BUSY\",\n            \"TMEM_DENY\", \"DRAM_RD\", \"DRAM_WR\", \"DRAM_WAIT\", \"INSTR\", \"MXU_STARVE\"]\nTB_BUILD_ID, TB_TEMP = 0x0B0A4D00, 0xA1A        # tb_board.sv\nLINE = re.compile(r\"^T\\d+ [DSGEUHPQ] \")\nCFG = sim_board_config(DRAM_BYTES=1 << 22)\n\n\ndef sim_lines(out: str) -> list[str]:\n    return [line for line in out.splitlines() if LINE.match(line)]\n\n\ndef run_traced(t: SimTransport, img, prog: list, trace_ctrl: int = TRACE_ENABLE,\n               nrec: int = 0, snap: bool = False) -> dict:\n    \"\"\"One simulation: load and run `prog`, wait for the trace to drain, read the counters and\n    the first `nrec` trace records (raw ring order).\"\"\"\n    b = Board(t, check=False)\n    img = np.asarray(img, np.uint8)\n    at = max(PROG_AT, -(-len(img) // 4096) * 4096)\n    b.write(0, img)\n    b.load(at, prog)                        # (with its wait entries where the board takes them)\n    t.reg_write(R_TRACE_CTRL, TRACE_CLEAR)\n    t.reg_write(R_TRACE_CTRL, trace_ctrl)\n    if snap:\n        t.reg_write(R_SNAP, 1)\n    t.reg_write(R_CTRL, CTRL_CLEAR)\n    t.reg_write(R_CTRL, CTRL_RUN)\n    t.poll(R_STATUS, ST_HALTED, ST_HALTED)\n    t.poll(R_TRACE_CTRL, TRACE_BUSY, 0)\n    if snap:\n        t.reg_write(R_SNAP, 1)\n    t.reg_write(R_TRACE_ADDR, 0)\n    head = [R_STATUS, R_CYCLES, R_CYCLES_HI, R_ICOUNT, R_B_RD, R_B_WR, R_TRACE_COUNT,\n            R_TRACE_DROP, R_SNAP]\n    shadows = [0x100 + 4 * k for k in range(2 * len(COUNTERS))] if snap else []\n    v = t.reg_read_many(head + shadows + [R_TRACE_LO, R_TRACE_HI] * nrec)\n    st, lo, hi, ic, brd, bwr, cnt, drop, nsnap = v[:len(head)]\n    r = {\"status\": st, \"cycles\": lo | hi << 32, \"icount\": ic, \"b_rd\": brd, \"b_wr\": bwr,\n         \"count\": cnt, \"drop\": drop, \"snaps\": nsnap, \"sim\": sim_lines(t.out)}\n    v = v[len(head):]\n    if snap:\n        r[\"counters\"] = {n: v[2 * k] | v[2 * k + 1] << 32 for k, n in enumerate(COUNTERS)}\n        v = v[len(shadows):]\n    r[\"raw\"] = [v[2 * k] | v[2 * k + 1] << 32 for k in range(nrec)]\n    t.reg_write(R_CTRL, 0)\n    return r\n\n\n# ------------------------------------------------------------------------------ registers\ndef test_register_map(have_verilator):\n    t = SimTransport(ch_bytes=1 << 20, params={\"TRACE_DEPTH\": 1024, \"PQ_WIN\": 256,\n                                               \"CORE_KHZ\": 75294, \"DDR_MTS\": 1066})\n    t.reg_write(R_SCRATCH, 0x1234_5678)\n    t.reg_write(R_TRACE_CTRL, TRACE_ENABLE | TRACE_STOP_WHEN_FULL)\n    t.reg_write(R_TRACE_ADDR, 77)\n    t.reg_write(0x60 + 4 * 3, 0xCAFE_F00D)                    # ARG3\n    ident, ver, regmap, caps, khz, bid, temp, snap, mts, scr, tctl, taddr, bad, a3, a4 = \\\n        t.reg_read_many([0x0, R_VERSION, R_REGMAP, R_CAPS, R_CORE_KHZ, R_BUILD_ID, R_TEMP, R_SNAP,\n                         R_DDR_MTS, R_SCRATCH, R_TRACE_CTRL, R_TRACE_ADDR, 0x0FC, 0x6C, 0x70])\n    assert ident == 0x4F545055\n    assert ver == (CFG.D << 16) | (CFG.MCOLS << 8) | CFG.LANES\n    assert regmap == 5\n    # log2 256, log2 1024; WAITW, GEN, MX, STREAM (with DSTEP), run arguments, ACT_ROWS, chash,\n    # DSTEP, PAIR, 4-bit, ddr, i2c, temp, trace\n    assert caps == (0xE7 << 24) | (8 << 16) | (10 << 8) | 0x80 | 0b1111111\n    assert R.caps(caps)[\"mx\"]\n    assert a3 == 0xCAFE_F00D and a4 == 0                      # ARG3 kept, ARG4 reset\n    assert khz == 75294 and bid == TB_BUILD_ID and mts == 1066\n    assert temp == (1 << 31) | TB_TEMP\n    assert 44.5 < TB_TEMP * 503.975 / 4096 - 273.15 < 45.5\n    assert snap == 0 and scr == 0x1234_5678 and taddr == 77\n    assert tctl == TRACE_ENABLE | TRACE_STOP_WHEN_FULL     # CLEAR reads 0, not busy\n    assert bad == 0xDEADBEEF\n\n\ndef test_cfg_registers(have_verilator):\n    \"\"\"Register map 4: the CFG_* registers report the target's build of the board model's\n    configuration (opentpu/target.py), and the host builds that Config from them.\"\"\"\n    from opentpu import rtlsim, target as T\n    from opentpu.host.board import Board, device_config\n    t = SimTransport(ch_bytes=1 << 20)\n    info = Board(t).info()\n    c = info[\"cfg\"]\n    # CAPS2 bit0: the full collective unit, but BAR alone on the board's uarch (the card's\n    # build, rtlsim.BOARD_UARCH COLL_GATHER 0)\n    assert info[\"regmap\"] == 5 and info[\"caps2\"] == {\"gather\": rtlsim.gathers(1)}\n    assert t.gather == rtlsim.gathers(1)\n    assert (c[\"S\"], c[\"TMEM_WORDS\"], c[\"IMEM_WORDS\"], c[\"ACT_BLOCKS\"]) == (1, 1 << 16, 1 << 15, 128)\n    assert (c[\"DRAM_BYTES\"], c[\"channels\"], c[\"channel_bytes\"]) == (1 << 32, 2, 1 << 31)\n    # the TMEM as the target builds it (the board model's: release r2, one copy, TMEM_IMPL 3)\n    assert (c[\"MXU_IMPL\"], c[\"TMEM_IMPL\"], c[\"VPU_CL\"], c[\"ULANES\"]) == \\\n        (2, T.current().uarch[\"TMEM_IMPL\"], 2, 8)\n    assert c[\"platform\"] == T.current().platform_id\n    cfg = device_config(info)                     # CFG_HASH agrees with the registers' Config\n    assert c[\"hash\"] == T.arch_hash(cfg)\n    # the board model's sequencer takes wait entries as the simulators' (rtlsim.UARCH SEQ_WC)\n    assert cfg == T.build_config(T.current(), MCOLS=CFG.MCOLS, LANES=CFG.LANES,\n                                 ACT_ROWS=CFG.act_rows, DSTEP=1,\n                                 SEQ_WC=int(bool(rtlsim.UARCH.get(\"SEQ_WC\"))))\n    assert t.reg_read(R.R_CFG_WIN0) == 0xDEADBEEF    # reserved\n\n\ndef test_register_map_board_defaults(have_verilator):\n    t = SimTransport(ch_bytes=1 << 20)\n    caps, khz, mts = t.reg_read_many([R_CAPS, R_CORE_KHZ, R_DDR_MTS])\n    # 1024-cycle windows, 16384 records; WAITW, GEN, MX, STREAM (with DSTEP), run arguments,\n    # ACT_ROWS, chash, DSTEP, PAIR, 4-bit, temp, trace\n    assert caps == (0xE7 << 24) | (10 << 16) | (14 << 8) | 0x80 | 0b1110111\n    assert khz == 100000 and mts == 0                     # no DDR_MTS given: CAPS bit3 clear\n\n\ndef test_caps_hostcal(have_verilator):\n    \"\"\"HOSTCAL (the LiteDRAM top's) sets CAPS bit27 alone; memcal then sees a host-calibrated\n    bitstream, and with both STATUS CALIB bits up (the model's controllers) has nothing to do,\n    so it never touches the CSR window.\"\"\"\n    from opentpu.host import memcal\n    t = SimTransport(ch_bytes=1 << 20, params={\"HOSTCAL\": 1})\n    caps, st = t.reg_read_many([R_CAPS, R.R_STATUS])\n    assert caps ^ SimTransport(ch_bytes=1 << 20).reg_read(R_CAPS) == 1 << 27\n    assert caps & R.CAP_HOSTCAL and memcal.hostcal(t)\n    assert st & R.ST_CALIB0 and st & R.ST_CALIB1\n    assert memcal.ensure(t) is None\n\n\ndef test_caps2_coll_bar(have_verilator):\n    \"\"\"Register map 5's CAPS2 bit0 (GATHER): set with the full collective unit; clear on a\n    one-slice board built with COLL_GATHER 0 (otpu_coll_bar), which runs a BAR as before, has\n    the host refuse a program with GATHER, and on one loaded past the host moves no data and\n    raises ERROR.\"\"\"\n    from opentpu.host.board import NoGather\n    # (the full unit named: the board's uarch builds the card's, BAR alone; rtlsim.BOARD_UARCH)\n    full = SimTransport(ch_bytes=1 << 20, params={\"COLL_GATHER\": 1})\n    assert full.gather and full.reg_read_many([R_REGMAP, R.R_CAPS2]) == [5, 1]\n    # (SEQ_WC 0: the raw load below loads no wait entries, which the board's uarch would need)\n    t = SimTransport(ch_bytes=1 << 20, params={\"COLL_GATHER\": 0, \"SEQ_WC\": 0},\n                     plusargs=[\"+coll_gerr_ok\"])\n    assert not t.gather\n    assert t.reg_read_many([R_REGMAP, R.R_CAPS2]) == [5, 0]\n    b = Board(t, check=False)\n    assert not b.gather\n    at, src, dst, n = 0x10000, 0, 1024, 32                      # 4 rows of 8 words\n    data = np.arange(1, n + 1, dtype=np.uint32)\n    copy = [I.ld(0, src, n), I.bar(), I.st(0x2000, src, n), I.halt()]\n    gat = [I.ld(0, src, n), I.ld(0x1000, dst, n), I.bar(), I.gather(src, dst, 4, 8, 8, 8, n),\n           I.st(0x2000, dst, n), I.halt()]\n\n    def raw_load(at, w):                    # what load_program does, without the refusal\n        b.write(at, w.view(np.uint8))\n        t.reg_write(R.R_PROG_ADDR, at)\n        t.reg_write(R.R_PROG_N, len(w) // 8)\n        t.reg_write(R_CTRL, R.CTRL_LOAD)\n        t.poll(R_STATUS, R.ST_LOADING, 0)\n\n    def run(prog, load):\n        b.write(0, data.view(np.uint8))\n        b.write(0x1000, np.zeros(4 * n, np.uint8))\n        b.write(0x2000, np.full(4 * n, 0xFF, np.uint8))\n        load(at, np.asarray(I.assemble(prog), np.uint32))\n        t.reg_write(R_CTRL, CTRL_CLEAR)\n        t.reg_write(R_CTRL, CTRL_RUN)\n        t.poll(R_STATUS, ST_HALTED, ST_HALTED)\n        st, ic = t.reg_read_many([R_STATUS, R_ICOUNT])\n        return st, ic, b.read(0x2000, 4 * n).view(np.uint32)\n\n    st, ic, out = run(copy, b.load_program)                     # BAR as before\n    assert st & ST_HALTED and not st & R.ST_ERROR and ic == len(copy)\n    assert (out == data).all()\n    with pytest.raises(NoGather, match=\"instruction 3\"):\n        b.load_program(at, np.asarray(I.assemble(gat), np.uint32))\n    st, ic, out = run(gat, raw_load)                            # GATHER: ERROR, nothing moved\n    assert st & ST_HALTED and st & R.ST_ERROR and ic == len(gat)\n    assert not out.any()\n\n\ndef test_i2c_pins(have_verilator):\n    \"\"\"I2C_CTRL drives lines low, I2C_IN reads them back through the synchronizers; lines held\n    low from outside (+i2c_hold) read low while released. Reset leaves every line released.\"\"\"\n    t = SimTransport(ch_bytes=1 << 20, plusargs=[\"+i2c_hold=18\"])   # SDA1 and ALERT0 held\n    first = [t.queue_read(o) for o in (R.R_I2C_CTRL, R.R_I2C_IN)]\n    got = []\n    for v in (0b0001, 0b0110, 0b1111, 0):\n        t.reg_write(R.R_I2C_CTRL, v)\n        t.wait_cycles(4)\n        got.append((t.queue_read(R.R_I2C_CTRL), t.queue_read(R.R_I2C_IN)))\n    t.flush()\n    res = t.results\n    assert [res[i] for i in first] == [0, 0b00111]\n    held = 0b11000\n    assert [(res[a], res[b]) for a, b in got] == [\n        (v, 0b11111 & ~(v | held)) for v in (0b0001, 0b0110, 0b1111, 0)]\n\n\n# ------------------------------------------------------------------------------ counters\ndef test_free_running_counters(have_verilator):\n    t = SimTransport(ch_bytes=CFG.DRAM_BYTES // 2, stall=30, seed=3, params={\"TRACE_DEPTH\": 1024})\n    prog = demo_program()\n    r = run_traced(t, demo_image(), prog, snap=True)\n    c = r[\"counters\"]\n    assert r[\"status\"] & ST_HALTED and r[\"snaps\"] == 2\n    # the shadows hold the second snapshot: totals since reset (one run, and the program load)\n    assert c[\"UPTIME\"] >= c[\"RUNNING\"] >= c[\"MXU_BUSY\"] >= c[\"MXU_MAC\"] > 0\n    assert c[\"RUNNING\"] >= max(c[\"VPU_BUSY\"], c[\"QNT_BUSY\"], c[\"DMA_BUSY\"]) > 0\n    assert c[\"INSTR\"] == r[\"icount\"] == len(prog)\n    assert c[\"DRAM_RD\"] >= 2 * r[\"b_rd\"] > 0\n\n\ndef _deltas(t, prog, img):\n    \"\"\"Counter deltas over one run: snapshot, run, snapshot (one simulation).\"\"\"\n    b = Board(t, check=False)\n    b.write(0, img)\n    b.load(PROG_AT, prog)\n    t.reg_write(R_SNAP, 1)\n    t.reg_write(R_CTRL, CTRL_CLEAR)\n    t.reg_write(R_CTRL, CTRL_RUN)\n    t.poll(R_STATUS, ST_HALTED, ST_HALTED)\n    # the first snapshot's shadows are read before the second snapshot, in the same simulation\n    shadows = [0x100 + 4 * k for k in range(2 * len(COUNTERS))]\n    idx = [t.queue_read(o) for o in shadows]\n    t.reg_write(R_SNAP, 1)\n    v = t.reg_read_many(shadows + [R_CYCLES, R_ICOUNT, R_B_RD, R_B_WR, R_SNAP])\n    first = [t.results[i] for i in idx]\n    c0 = {n: first[2 * k] | first[2 * k + 1] << 32 for k, n in enumerate(COUNTERS)}\n    c1 = {n: v[2 * k] | v[2 * k + 1] << 32 for k, n in enumerate(COUNTERS)}\n    cyc, ic, brd, bwr, nsnap = v[len(shadows):]\n    return {n: c1[n] - c0[n] for n in COUNTERS}, cyc, ic, brd, bwr, nsnap\n\n\ndef test_counter_snapshots_bracket_a_run(have_verilator):\n    \"\"\"Deltas between two snapshots around a run: RUNNING is the run's CYCLES, INSTR its ICOUNT,\n    and the DRAM beats are the port B requests' (otpu_native_dram.sv): the DMA requests each chunk\n    once, and a read or a whole-chunk write takes a beat on each channel.\"\"\"\n    t = SimTransport(ch_bytes=CFG.DRAM_BYTES // 2, stall=30, seed=4, params={\"TRACE_DEPTH\": 1024})\n    prog = [I.ld(0, 0, 4096), I.st(0x20000, 0, 4096), I.ld(0x8000, 4096, 1024),\n            I.st(0x30000, 4096, 1024), I.halt()]\n    img = np.random.default_rng(5).integers(0, 256, 0x40000).astype(np.uint8)\n    d, cyc, ic, brd, bwr, nsnap = _deltas(t, prog, img)\n    assert nsnap == 2\n    assert d[\"RUNNING\"] == cyc and d[\"UPTIME\"] > cyc\n    assert d[\"INSTR\"] == ic == len(prog)\n    assert brd == (4096 + 1024) // (CFG.D // 4) and bwr == brd  # a request per chunk\n    assert d[\"DRAM_RD\"] == 2 * brd and d[\"DRAM_WR\"] == 2 * bwr\n    assert d[\"DMA_BUSY\"] > 0 and d[\"MXU_BUSY\"] == d[\"MXU_MAC\"] == d[\"VPU_BUSY\"] == 0\n    # the AXI model stalls (30%), but the adapter's 16-entry request queues take every DMA\n    # request at once (DRAM_WAIT counts only requests not taken; see test_mxu_starve_counter)\n    assert 0 <= d[\"DRAM_WAIT\"] < cyc\n    # the demo: every unit, the MXU consumes its 32 chunks\n    t = SimTransport(ch_bytes=CFG.DRAM_BYTES // 2, stall=30, seed=3, params={\"TRACE_DEPTH\": 1024})\n    d, cyc, ic, brd, bwr, nsnap = _deltas(t, demo_program(), demo_image())\n    assert d[\"UPTIME\"] >= d[\"RUNNING\"] == cyc >= d[\"MXU_BUSY\"] >= d[\"MXU_MAC\"] == 32\n    assert min(d[\"VPU_BUSY\"], d[\"QNT_BUSY\"], d[\"DMA_BUSY\"]) > 0\n    assert d[\"INSTR\"] == ic == len(demo_program())\n    assert d[\"DRAM_RD\"] >= 2 * brd and d[\"DRAM_WR\"] >= bwr\n    assert d[\"TMEM_DENY\"] >= 0\n\n\ndef test_mxu_starve_counter(have_verilator):\n    \"\"\"MXU_STARVE: cycles the MXU streams a command and its chunk FIFO is empty -- exactly the\n    ms of the slice's Q records (+trace), summed. With a long read latency on the channels\n    (+axi_lat 400: the read credits run out, the data comes late) the MXU does little but wait for\n    chunks (starved, ms, or blocked on the chunks it holds, mb): its busy time is its MACs and the\n    wait, while DRAM_WAIT stays near 0 (the adapter takes nearly every request). Where the wait\n    lands depends on the MXU: the systolic array starts a row only once all of its chunks are in\n    (a row never stalls in the pipeline; docs/mxu_systolic.md), so it waits on a partial row,\n    blocked, about as long as on an empty FIFO, and MXU_STARVE sees about half of its wait (a\n    quarter with the MX kernels' MLP: 12 MMs of whole QACT ranges, longer rows, against 24). A\n    short latency (20) removes nearly all of the wait.\"\"\"\n    cfg, img, prog = _kernel(\"mlp\")\n    c, cyc, q = {}, {}, {}\n    for lat in (400, 20):\n        t = SimTransport(ch_bytes=cfg.DRAM_BYTES, stall=0, plusargs=[f\"+axi_lat={lat}\", \"+trace\"],\n                         params={\"TRACE_DEPTH\": 1024})\n        r = run_traced(t, img, prog, trace_ctrl=0, snap=True)\n        assert r[\"status\"] & ST_HALTED\n        c[lat], cyc[lat] = r[\"counters\"], r[\"cycles\"]\n        ql = [dict(re.findall(r\"(\\w+)=(\\d+)\", line)) for line in r[\"sim\"] if line.split()[1] == \"Q\"]\n        q[lat] = {k: sum(int(d[k]) for d in ql) for k in (\"n\", \"ms\", \"mb\")}\n        assert q[lat][\"n\"] == cyc[lat] and c[lat][\"MXU_STARVE\"] == q[lat][\"ms\"], (c[lat], q[lat])\n        assert c[lat][\"MXU_BUSY\"] >= c[lat][\"MXU_MAC\"] + q[lat][\"ms\"] + q[lat][\"mb\"], (c[lat], q[lat])\n    wait = {lat: q[lat][\"ms\"] + q[lat][\"mb\"] for lat in q}\n    assert wait[400] > 0.9 * (c[400][\"MXU_BUSY\"] - c[400][\"MXU_MAC\"]), (c[400], q[400])\n    # near 0 at either latency: the card's uarch (r2's TMEM input stage and registered wait release) sees a\n    # few cycles at 20 (3 of 13,398 on release-2 d8fe2c15), the default uarch none\n    assert c[400][\"DRAM_WAIT\"] < wait[400] // 100 and c[20][\"DRAM_WAIT\"] <= cyc[20] // 1000, (c[400], c[20])\n    assert min(q[400][\"ms\"], q[400][\"mb\"]) > wait[400] // 5, q[400]\n    assert wait[20] < wait[400] // 20, (q[400], q[20])\n    assert cyc[20] < 0.3 * cyc[400], cyc\n\n\n# ------------------------------------------------------------------------------ trace\ndef _kernel(name):\n    cfg = sim_board_config(DRAM_BYTES=1 << 23)\n    if name == \"mlp\":\n        a, _ = mlp_args(np.random.default_rng(0), M=1, H=512, Fd=1024)\n        comp, imgs = compile_kernel(mlp, cfg, **a)\n    else:\n        a, _ = attn_args(np.random.default_rng(1), Hq=8, Hkv=4, d=128, T=384, cap=384, block=128)\n        comp, imgs = compile_kernel(attention_decode, cfg, **a)\n    return cfg, imgs[0], comp.programs[0]\n\n\n@pytest.mark.parametrize(\"name,bucket\", [(\"mlp\", None), (\"attention\", None), (\"mlp\", 64),\n                                         (\"attention\", 32)])\ndef test_trace_matches_simulator(have_verilator, name, bucket):\n    \"\"\"The records, read back through TRACE_ADDR / TRACE_LO / TRACE_HI and decoded, are exactly\n    the simulator's trace lines (D S G E U from the sequencer and units, P Q H counters).\"\"\"\n    cfg, img, prog = _kernel(name)\n    depth = 8192\n    plus = [\"+trace\"] + ([f\"+bucket={bucket}\"] if bucket else [])\n    t = SimTransport(ch_bytes=cfg.DRAM_BYTES, stall=20, seed=7, plusargs=plus,   # + program\n                     params={\"TRACE_DEPTH\": depth})\n    r = run_traced(t, img, prog, nrec=depth)\n    assert r[\"status\"] & ST_HALTED\n    assert r[\"drop\"] == 0 and 0 < r[\"count\"] <= depth\n    hw = records_to_trace(ring_order(r[\"raw\"], r[\"count\"], depth)).splitlines()\n    sim = r[\"sim\"]\n    kinds = {line.split()[1] for line in sim}\n    assert kinds == set(\"DSGEUHPQ\") if name == \"mlp\" else kinds >= set(\"DSEUHPQ\")\n    assert hw == sim\n    assert sum(line.split()[1] == \"P\" for line in sim) >= r[\"cycles\"] // (bucket or 1024)\n\n\ndef test_trace_long_wait_is_exact(have_verilator):\n    \"\"\"A start more than 65534 cycles after its instruction became ready (S's 16-bit delay field\n    saturates): the R record that follows carries the ready cycle.\"\"\"\n    n = 60000\n    prog = [I.ld(0, 0, n), I.ld(0, 61000, 64), I.st(0x40000, 61000, 64), I.halt()]\n    img = np.random.default_rng(3).integers(0, 256, 4 * n).astype(np.uint8)\n    t = SimTransport(ch_bytes=CFG.DRAM_BYTES // 2, stall=99, seed=2,\n                     plusargs=[\"+trace\", \"+bucket=1000000\"], params={\"TRACE_DEPTH\": 1024})\n    r = run_traced(t, img, prog, nrec=64)\n    sim = r[\"sim\"]\n    assert r[\"count\"] <= 64\n    waits = [c - rr for c, rr in ((int(x.split(\"c=\")[1].split()[0]), int(x.split(\"r=\")[1]))\n                                  for x in sim if \" S \" in x)]\n    assert max(waits) > 0xFFFF\n    kinds = [(rec >> 60) & 0xF for rec in r[\"raw\"][:r[\"count\"]]]\n    assert 10 in kinds                                      # an R record\n    assert records_to_trace(ring_order(r[\"raw\"], r[\"count\"], 64)).splitlines() == sim\n\n\ndef test_decoder_skips_cut_groups():\n    \"\"\"A group cut by the ring's start (its tail only) or the buffer's end (its head only) is\n    skipped; the complete groups decode.\"\"\"\n    e = (4 << 60) | (3 << 52) | 100                             # T0 E c=100 s=3\n    p = (6 << 60) | (5 << 32) | 200                             # P, n=5, then 9 V records\n    vs = [(11 << 60) | (k << 56) | k for k in range(9)]\n    q = (7 << 60) | (5 << 32) | 200\n    o = (9 << 60) | (1 << 52) | 7                               # an O record's second half\n    d = (1 << 60) | (2 << 52) | (9 << 32) | 300                 # a D without its O records\n    recs = [o] + vs[5:] + [e, p] + vs + [q] + vs[:6] + [e, d]\n    assert records_to_trace(recs) == (\n        \"T0 E c=100 s=3\\n\"\n        \"T0 P c=200 n=5 bm=0 bd=1 am=2 aq=3 mx=4 fm=5 fq=6 fv=7 fc=8\\n\"\n        \"T0 Q c=200 n=5 bs=0 as=1 ms=2 mb=3 ff=4 ld=5\\n\"\n        \"T0 E c=100 s=3\\n\")\n    assert records_to_trace([], sid=1) == \"\"\n\n\ndef test_trace_ring_and_stop_when_full(have_verilator):\n    \"\"\"A ring smaller than the trace keeps the last records (a suffix of the lines); with\n    STOP_WHEN_FULL it keeps the first DEPTH records (a prefix).\"\"\"\n    depth = 128                                   # the demo writes ~320 records: the ring wraps\n    for ctrl in (TRACE_ENABLE, TRACE_ENABLE | TRACE_STOP_WHEN_FULL):\n        t = SimTransport(ch_bytes=CFG.DRAM_BYTES // 2, stall=30, seed=3,\n                         plusargs=[\"+trace\", \"+bucket=64\"], params={\"TRACE_DEPTH\": depth})\n        r = run_traced(t, demo_image(), demo_program(), trace_ctrl=ctrl, nrec=depth)\n        sim = r[\"sim\"]\n        hw = records_to_trace(ring_order(r[\"raw\"], r[\"count\"], depth)).splitlines()\n        assert r[\"drop\"] == 0 and len(hw) > depth // 10        # up to 10 records a line (P)\n        if ctrl & TRACE_STOP_WHEN_FULL:\n            assert r[\"count\"] == depth\n            assert hw == sim[:len(hw)]\n        else:\n            assert r[\"count\"] > 2 * depth                  # wrapped\n            assert hw == sim[len(sim) - len(hw):]\n\n\ndef test_trace_ring_past_2_32_records(have_verilator):\n    \"\"\"The ring past 2^32 records (+trace_count0: the simulation's clear starts the count 200\n    records short of it): TRACE_COUNT saturates in its high bits only, its low log2(DEPTH) bits\n    are still the next record's slot, so the host reads the ring oldest first and gets the last\n    lines of the trace (a count stuck at 2^32 - 1 put the oldest record anywhere); Board's\n    trace stats say the count saturated.\"\"\"\n    from opentpu.host.board import Board\n    depth = 128\n    t = SimTransport(ch_bytes=CFG.DRAM_BYTES // 2, stall=30, seed=3,\n                     plusargs=[\"+trace\", \"+bucket=64\", f\"+trace_count0={(1 << 32) - 200:x}\"],\n                     params={\"TRACE_DEPTH\": depth})\n    r = run_traced(t, demo_image(), demo_program(), nrec=depth)\n    assert r[\"drop\"] == 0 and r[\"count\"] >> 7 == (1 << 25) - 1        # the high bits saturated\n    hw = records_to_trace(ring_order(r[\"raw\"], r[\"count\"], depth)).splitlines()\n    assert len(hw) > depth // 10 and hw == r[\"sim\"][len(r[\"sim\"]) - len(hw):]\n    tr = Board(t, check=False)._trace_out(r[\"count\"], 0, depth, False, np.array(r[\"raw\"], np.uint64))\n    assert tr[\"saturated\"] and tr[\"wrapped\"]\n    assert records_to_trace(tr[\"records\"]).splitlines() == hw\n\n\ndef test_trace_drops_are_counted(have_verilator):\n    \"\"\"A two-bundle capture queue and a P/Q window every 4 cycles overflow: the lost events are\n    counted exactly, and the rest are recorded in order.\"\"\"\n    depth = 4096\n    t = SimTransport(ch_bytes=CFG.DRAM_BYTES // 2, stall=30, seed=3,\n                     plusargs=[\"+trace\", \"+bucket=4\"], params={\"TRACE_DEPTH\": depth, \"TRACE_QD\": 2})\n    r = run_traced(t, demo_image(), demo_program(), nrec=depth)\n    sim = r[\"sim\"]\n    assert 0 < r[\"count\"] < depth\n    hw = records_to_trace(ring_order(r[\"raw\"], r[\"count\"], depth)).splitlines()\n    assert r[\"drop\"] > 0 and len(sim) - len(hw) == r[\"drop\"]\n    it = iter(sim)\n    assert all(line in it for line in hw)                 # a subsequence, in order\n    # not recording: nothing is captured, nothing is dropped\n    t = SimTransport(ch_bytes=CFG.DRAM_BYTES // 2, stall=30, seed=3,\n                     plusargs=[\"+bucket=4\"], params={\"TRACE_DEPTH\": depth, \"TRACE_QD\": 2})\n    r = run_traced(t, demo_image(), demo_program(), trace_ctrl=0)\n    assert r[\"count\"] == 0 and r[\"drop\"] == 0\n", "tests/test_offload.py": "\"\"\"tools/offload/cachesim.py: the expert-cache policies and path (a)'s timing on small\nhand-made traces.\"\"\"\nimport importlib.util\nfrom pathlib import Path\n\nimport numpy as np\n\n_spec = importlib.util.spec_from_file_location(\n    \"cachesim\", Path(__file__).resolve().parent.parent / \"tools/offload/cachesim.py\")\ncs = importlib.util.module_from_spec(_spec)\n_spec.loader.exec_module(cs)\n\n\ndef _req(seq, k=1):\n    \"\"\"One MoE layer, one expert per token: requests [T, 1, k].\"\"\"\n    return np.array(seq, np.int64).reshape(-1, 1, k)\n\n\ndef test_lru_and_opt_on_a_known_sequence():\n    # capacity 2, empty start: LRU misses a, b, c, a, b (every one: the loop is longer than the\n    # cache), OPT keeps a and evicts b at c: misses a, b, c, b\n    req = _req([0, 1, 2, 0, 1])\n    lru, _ = cs.simulate(req, 2, \"lru\", [])\n    opt, _ = cs.simulate(req, 2, \"opt\", [])\n    assert lru.sum() == 5\n    assert opt.sum() == 4\n\n\ndef test_static_never_changes_and_warm_start_counts():\n    req = _req([0, 1, 0, 2, 0])\n    st, at = cs.simulate(req, 1, \"static\", [0])\n    assert st.tolist() == [0, 1, 0, 1, 0]\n    assert at == {(1, 0): [1], (3, 0): [2]}\n\n\ndef test_policies_order_on_random_traces():\n    rng = np.random.default_rng(0)\n    T, L, E, k = 300, 6, 16, 2\n    p = rng.dirichlet(np.ones(E) * 0.3, size=L)\n    req = np.stack([np.stack([rng.choice(E, k, replace=False, p=p[j]) + j * E\n                              for j in range(L)]) for _ in range(T)])\n    prof = cs.freq(req, E * L)\n    for C in (L * k, 30, 60):\n        warm = cs.top_set(prof, C)\n        miss = {pol: cs.simulate(req, C, pol, cs.top_set(prof, E * L) if pol == \"lru_layer\"\n                                 else warm, prof)[0].sum()\n                for pol in (\"static\", \"lru\", \"lru_layer\", \"lfu\", \"opt\")}\n        assert miss[\"opt\"] == min(miss.values())\n        assert all(m <= T * L * k for m in miss.values())\n\n\ndef test_lfu_layer_is_the_servers_lfu():\n    \"\"\"lfu_layer replays ExpertServer(policy=\"lfu\"): the same misses token by token on a skewed\n    random trace of several layers from the same profile's warm start, and linksim's lfu streams\n    as many experts (its demand transfers, no prefetch).\"\"\"\n    from opentpu.host.offload import ExpertServer, Layout, SimDram\n    rng = np.random.default_rng(5)\n    T, L, E, k, cap, half = 300, 3, 16, 2, 5, 4.0\n    p = 1.0 / np.arange(1, E + 1) ** 1.2\n    perm = [rng.permutation(E) for _ in range(L)]\n    req = np.array([[perm[j][rng.choice(E, k, replace=False, p=p / p.sum())] + j * E\n                     for j in range(L)] for _ in range(T)])\n    prof = cs.freq(req[:60], E * L)\n    warm = cs.top_set(prof, E * L)\n    lfu, _ = cs.simulate(req, cap * L, \"lfu_layer\", warm, prof, half)\n    lru, _ = cs.simulate(req, cap * L, \"lru_layer\", warm, prof, half)\n    lay = Layout.build(4096, E, k, (cap,) * L, 128)\n    srv = ExpertServer(SimDram(np.zeros(lay.end + 4096, np.uint8)), lay,\n                       lambda g: bytes(128), policy=\"lfu\", half=half)\n    srv.load(warm)\n    got = []\n    for t in range(T):\n        m0 = srv.misses\n        for j in range(L):\n            srv.serve([int(e) for e in req[t, j]])\n        got.append(srv.misses - m0)\n    assert lfu.tolist() == got\n    assert lfu.tolist() != lru.tolist()\n    by = dict(x=1e6, head=0.0, d_pre=1e6, d_post=0.0)\n    r = cs.linksim(req, {}, [cap] * L, [[e for e in warm if e // E == j] for j in range(L)],\n                   _hw(), by, policy=\"lfu\", half=half)\n    assert abs(r[\"demand\"] * T - sum(got)) < 1e-9\n\n\ndef test_prefetch_is_the_servers_capped_hints():\n    \"\"\"prefetch (docs/offload.md 12.7) replays ExpertServer's capped hints (hint_n / hint_top),\n    each landed before its layer's request: the same misses and experts sent on a noisy\n    prediction. A perfect prediction's experts are all used; a wrong one's cost misses.\"\"\"\n    from opentpu.host.offload import ExpertServer, Layout, SimDram\n    rng = np.random.default_rng(7)\n    T, L, E, k, cap, half = 300, 3, 16, 2, 5, 4.0\n    p = 1.0 / np.arange(1, E + 1) ** 1.2\n    perm = [rng.permutation(E) for _ in range(L)]\n    req = np.array([[perm[j][rng.choice(E, k, replace=False, p=p / p.sum())] + j * E\n                     for j in range(L)] for _ in range(T)])\n    noisy = req.copy()                  # the router on the layer's input: each id right with\n    for t in range(T):                  # p 0.6, else another of the layer's\n        for j in range(L):\n            for i in range(k):\n                if rng.random() > 0.6:\n                    noisy[t, j, i] = rng.choice([g for g in range(j * E, (j + 1) * E)\n                                                 if g not in noisy[t, j]])\n    pred = [noisy[:, j] for j in range(L)]\n    warm = cs.top_set(cs.freq(req[:60], E * L), E * L)\n    lay = Layout.build(4096, E, k, (cap,) * L, 128)\n    for n, top in ((1, 2), (1, 1), (2, 2)):\n        srv = ExpertServer(SimDram(np.zeros(lay.end + 4096, np.uint8)), lay,\n                           lambda g: bytes(128), policy=\"lfu\", half=half)\n        srv.load(warm)\n        srv.hint_n, srv.hint_top = n, top\n        for t in range(T):\n            for j in range(L):\n                srv.hint([int(e) for e in noisy[t, j]])\n                while srv.pending:\n                    srv.step()\n                srv.serve([int(e) for e in req[t, j]])\n        m, s, _ = cs.prefetch(req, pred, E, cap * L, warm, n, top, half)\n        assert (round(m * T), round(s * T)) == (srv.misses, srv.prefetched)\n    none = cs.prefetch(req, None, E, cap * L, warm, 0, 0, half)[0]\n    good = cs.prefetch(req, [req[:, j] for j in range(L)], E, cap * L, warm, 1, k, half)\n    bad = cs.prefetch(req, [(req[:, j] + 7) % E + j * E for j in range(L)], E, cap * L, warm, 1,\n                      k, half)\n    assert good[0] < none < bad[0] and good[1] == good[2] > 0 and bad[2] < bad[1]\n\n\ndef _hw(pcie=1.3e9):\n    return dict(dram=14e9, call=30e-6, req=30e-6, done=15e-6, ssd=0.5e9, pcie_one=pcie)\n\n\ndef _warm(req, L):\n    \"\"\"Each layer's experts in the order they first appear (a warm cache holds them all).\"\"\"\n    return [list(dict.fromkeys(int(e) for e in req[:, j].ravel())) for j in range(L)]\n\n\ndef test_linksim_all_hits_is_the_resident_bound():\n    rng = np.random.default_rng(1)\n    T, L, E, k = 40, 3, 8, 2\n    req = np.stack([np.stack([rng.choice(E, k, replace=False) + j * E for j in range(L)])\n                    for _ in range(T)])\n    by = dict(x=3e6, head=50e6, d_pre=20e6, d_post=5e6)\n    for ov in (\"each\", \"all\"):\n        r = cs.linksim(req, {}, [E] * L, _warm(req, L), _hw(), by, overlap=ov)\n        assert r[\"demand\"] == 0 and r[\"link\"] == 0\n        assert abs(1 / r[\"tok_s\"] - cs.resident_time(L, k, by, _hw())) < 1e-12\n\n\ndef test_linksim_one_miss_costs_the_round_trip():\n    \"\"\"Token 1 misses (cache of 1 holding expert 0): the router, the request, the DMA call and\n    its bytes, the flag, then the expert.\"\"\"\n    req = _req([0, 1], k=1)\n    by = dict(x=3e6, head=0.0, d_pre=20e6, d_post=0.0)\n    hw = _hw()\n    for ov in (\"each\", \"all\"):\n        r = cs.linksim(req, {}, [1], [[0]], hw, by, overlap=ov)\n        t0 = (by[\"d_pre\"] + by[\"x\"]) / hw[\"dram\"]\n        t1 = (by[\"d_pre\"] / hw[\"dram\"] + hw[\"req\"] + by[\"x\"] / hw[\"pcie_one\"] + hw[\"call\"]\n              + hw[\"done\"] + by[\"x\"] / hw[\"dram\"])\n        assert r[\"demand\"] == 0.5\n        assert abs(2 / r[\"tok_s\"] - (t0 + t1)) < 1e-12\n\n\ndef test_linksim_hits_first_hides_the_resident_experts():\n    \"\"\"k = 4 with one miss per layer on a slow link: computing the three it has while the\n    fourth streams saves up to their time; waiting for the last one does not.\"\"\"\n    T, L, E, k = 20, 2, 16, 4\n    req = np.stack([np.stack([np.r_[0, 1, 2, 3 + t % 13] + j * E for j in range(L)])\n                    for t in range(T)])\n    by = dict(x=3e6, head=0.0, d_pre=20e6, d_post=0.0)\n    warm = [[j * E + e for e in range(4)] for j in range(L)]\n    each = cs.linksim(req, {}, [4] * L, warm, _hw(), by, overlap=\"each\")\n    alls = cs.linksim(req, {}, [4] * L, warm, _hw(), by, overlap=\"all\")\n    assert each[\"demand\"] == alls[\"demand\"] == L * (T - 1) / T\n    assert each[\"tok_s\"] > alls[\"tok_s\"]\n    # each missing layer saves k - 1 expert times (the transfer's DRAM writes hide in the wait)\n    saved = L * (T - 1) * (k - 1) * by[\"x\"] / _hw()[\"dram\"]\n    assert abs(T / alls[\"tok_s\"] - T / each[\"tok_s\"] - saved) < 1e-9\n\n\ndef test_linksim_perfect_prediction_prefetches_without_waste():\n    \"\"\"The next layer's experts named exactly, on a link fast enough to land them during the\n    layer: no demand transfers after the first layer, nothing wasted.\"\"\"\n    T, L, E, k = 30, 3, 8, 1\n    rng = np.random.default_rng(2)\n    req = np.stack([np.stack([rng.choice(E, k) + j * E for j in range(L)]) for _ in range(T)])\n    preds = {\"prev_r\": [None] + [req[:, j] for j in range(1, L)]}\n    by = dict(x=1e6, head=0.0, d_pre=200e6, d_post=0.0)\n    r = cs.linksim(req, preds, [1] * L, [[j * E] for j in range(L)], _hw(), by,\n                   pred=\"prev_r\", width=k)\n    s = cs.linksim(req, preds, [1] * L, [[j * E] for j in range(L)], _hw(), by)\n    assert r[\"wasted\"] == 0\n    assert r[\"demand\"] < s[\"demand\"]\n    assert r[\"tok_s\"] > s[\"tok_s\"]\n", "tests/test_offload_server.py": "\"\"\"opentpu/host/offload.py: the expert server against a fake card that posts requests the way\ndocs/offload.md section 5.2 describes (mailbox ring, seq, the directory).\"\"\"\nimport numpy as np\nimport pytest\n\nfrom opentpu.host.offload import LINE, ExpertServer, Layout, SimDram\n\nE, K, SLOT = 8, 2, 128\n\n\ndef _pool(g):\n    return np.full(SLOT, g + 1, np.uint8).tobytes()\n\n\ndef _setup(slots=(3, 3), warm=()):\n    lay = Layout.build(4096, E, K, slots, SLOT)\n    mem = SimDram(np.zeros(lay.end + 4096, np.uint8))\n    srv = ExpertServer(mem, lay, _pool)\n    srv.load(warm)\n    return lay, mem, srv\n\n\ndef _post(mem, lay, seq, ids):\n    \"\"\"The card's side (after its fence): the ids to the row, then seq.\"\"\"\n    mem.write(lay.row, np.array(ids + [0] * (LINE // 4 - len(ids)), np.float32))\n    mem.write(lay.mbox, np.float32(seq).tobytes())\n\n\ndef _entry(mem, lay, g):\n    w = np.frombuffer(mem.read(lay.entry(g), 8), np.uint32)\n    return int(w[0]), float(w[1:].view(np.float32)[0])\n\n\ndef _served(mem, lay):\n    return float(np.frombuffer(mem.read(lay.served, 4), np.float32)[0])\n\n\ndef test_layout_is_aligned_and_disjoint():\n    lay = Layout.build(4096, E, K, (3, 5), SLOT)\n    words = [lay.mbox, lay.served, lay.answer, lay.dir] + [a for a, _ in lay.slots]\n    assert all(a % LINE == 0 for a in words)\n    assert lay.served >= lay.row + LINE and lay.answer >= lay.served + LINE\n    assert lay.dir >= lay.answer + LINE\n    assert lay.slots[0][0] >= lay.dir + 8 * E * 2\n    assert lay.tag == SLOT and lay.pitch == SLOT + 128      # a slot, then its tag chunk\n    assert lay.slots[1][0] == lay.slots[0][0] + 3 * lay.pitch\n    assert lay.all_slots() == [a + i * lay.pitch for a, n in lay.slots for i in range(n)]\n    with pytest.raises(ValueError):\n        Layout.build(4100, E, K, (3,), SLOT)\n\n\ndef test_warm_start_fills_slots_and_the_directory():\n    lay, mem, srv = _setup(warm=[0, 1, 2, 3, E + 5])\n    for g in (0, 1, 2, E + 5):\n        a, p = _entry(mem, lay, g)\n        assert p == 1.0 and mem.read(a, SLOT) == _pool(g)\n    assert _entry(mem, lay, 3) == (0, 0.0)          # layer 0 has 3 slots\n    assert _served(mem, lay) == 0.0\n    assert srv.poll() == 0                          # nothing posted\n\n\ndef test_misses_evict_the_least_recent_not_requested():\n    lay, mem, srv = _setup(warm=[0, 1, 2])          # layer 0 LRU order: 2, 1, 0 (0 newest)\n    _post(mem, lay, 1, [2, 5])                      # 2 hits; 5 evicts the oldest other: 1\n    assert srv.poll() == 1\n    assert _served(mem, lay) == 1.0\n    assert _entry(mem, lay, 1) == (0, 0.0)\n    a, p = _entry(mem, lay, 5)\n    assert p == 1.0 and mem.read(a, SLOT) == _pool(5)\n    assert (srv.hits, srv.misses, srv.bytes) == (1, 1, SLOT)\n    # a request never evicts its own ids: 0 and 6 with {0, 2, 5} resident evicts 2, not 0\n    _post(mem, lay, 2, [0, 6])\n    srv.poll()\n    assert _entry(mem, lay, 2) == (0, 0.0)\n    assert _entry(mem, lay, 0)[1] == 1.0 and _entry(mem, lay, 6)[1] == 1.0\n\n\ndef test_ahead_sees_a_requests_later_misses_once_the_first_is_on_its_way():\n    \"\"\"ExpertServer.ahead (moe_card --willneed: PoolFile.willneed) is called with a request's\n    missing ids but its first, once that one's first part is on its way (with the answer: the\n    link starts on the first expert, the others' reads queued behind it); a request of one\n    miss or of hits only does not call it.\"\"\"\n    lay, mem, srv = _setup(warm=[0, 1, 2])\n    seen, reads = [], []\n    pool = srv.pool\n    srv.pool = lambda g: (reads.append(g), pool(g))[1]\n    srv.ahead = lambda ids: seen.append((list(ids), len(reads)))\n    _post(mem, lay, 1, [5, 4])\n    srv.poll()\n    _post(mem, lay, 2, [0, 6])                      # 0 hits (2 was a victim)\n    srv.poll()\n    assert seen == [([4], 1)] and reads == [5, 4, 6]\n    _post(mem, lay, 3, [6, 0])                      # hits only\n    srv.poll()\n    assert len(seen) == 1\n\n\ndef test_one_request_at_a_time():\n    lay, mem, srv = _setup()\n    for s in range(1, 6):\n        _post(mem, lay, s, [(s % 2) * E + s % E, (s % 2) * E + (s + 1) % E])\n        assert srv.poll() == 1 and srv.poll() == 0\n        assert srv.seq == s and _served(mem, lay) == float(s)\n    _post(mem, lay, 7, [0, 1])                      # 6 skipped: no fence on the card\n    with pytest.raises(RuntimeError, match=\"fence\"):\n        srv.poll()\n\n\ndef test_bad_requests():\n    lay, mem, srv = _setup(slots=(1, 3))\n    with pytest.raises(ValueError):\n        srv.serve([0, E + 1])                       # two layers\n    with pytest.raises(RuntimeError):\n        srv.serve([0, 1])                           # 2 ids, 1 slot\n\n\ndef test_split_format_is_the_slot_bytes_reordered(tmp_path):\n    \"\"\"split_order is a permutation of the slot's beats (a short last block included);\n    to_split and a SplitRecord read back from a file (PoolFile, os.preadv) give the slot's\n    bytes.\"\"\"\n    from opentpu.host.offload import PoolFile, SplitRecord, split_order, to_split\n    for n in (4096 * 3, 128 * 37, 128):\n        o = split_order(n)\n        assert np.array_equal(np.sort(o), np.arange(n // 64))\n        x = np.random.default_rng(n).integers(0, 256, (3, n), dtype=np.uint8)\n        f = tmp_path / f\"pool{n}.bin\"\n        f.write_bytes(b\"\".join(to_split(r).tobytes() for r in x))\n        pf = PoolFile(f, n, split=True)\n        for g in (2, 0, 1):\n            r = pf.get(g)\n            assert isinstance(r, SplitRecord) and len(r) == n\n            assert bytes(r) == x[g].tobytes() and np.array_equal(np.asarray(r), x[g])\n\n\ndef test_preadv_resumes_short_reads(tmp_path, monkeypatch):\n    \"\"\"offload.preadv fills every buffer in order when os.preadv stops short (in the middle of\n    a buffer) and over more buffers than one call takes (IOV_MAX).\"\"\"\n    import os\n\n    from opentpu.host import offload as O\n    data = np.random.default_rng(0).integers(0, 256, 20000, dtype=np.uint8).tobytes()\n    f = tmp_path / \"f.bin\"\n    f.write_bytes(data)\n    sizes = np.random.default_rng(1).integers(1, 9, 3000)\n    bufs = [memoryview(bytearray(int(n))) for n in sizes]\n    real, calls = os.preadv, []\n\n    def stingy(fd, bs, off):                # 6 buffers and half the 7th at most\n        calls.append(len(bs))\n        assert len(bs) <= O.IOV_MAX\n        return real(fd, list(bs[:6]) + ([bs[6][:len(bs[6]) // 2]] if len(bs) > 6 else []), off)\n    monkeypatch.setattr(os, \"preadv\", stingy)\n    fd = os.open(f, os.O_RDONLY)\n    try:\n        O.preadv(fd, bufs, 100)\n    finally:\n        os.close(fd)\n    assert b\"\".join(bytes(b) for b in bufs) == data[100:100 + int(sizes.sum())]\n    assert max(calls) == O.IOV_MAX and len(calls) > len(bufs) // 7\n\n\ndef test_preadv_iov_fills_as_preadv_and_resumes_short_reads(tmp_path, monkeypatch):\n    \"\"\"offload.preadv_iov (an iovec array of addresses and lengths through libc's preadv: no\n    buffer objects, the GIL released for the read) fills the buffers as preadv does: in order,\n    over more of them than one call takes (IOV_MAX), and when a call stops short in the middle\n    of a buffer.\"\"\"\n    import ctypes\n    import os\n\n    from opentpu.host import offload as O\n    if O._libc_preadv() is None:\n        pytest.skip(\"no libc preadv\")\n    data = np.random.default_rng(0).integers(0, 256, 20000, dtype=np.uint8).tobytes()\n    f = tmp_path / \"f.bin\"\n    f.write_bytes(data)\n    sizes = np.random.default_rng(1).integers(1, 9, 3000)\n    buf = np.zeros(int(sizes.sum()), np.uint8)\n    at = np.concatenate([[0], np.cumsum(sizes)[:-1]])\n    iov = np.stack([buf.ctypes.data + at, sizes], 1).astype(np.uint64)\n    want = data[100:100 + int(sizes.sum())]\n    real, calls = O._libc_preadv(), []\n\n    def stingy(fd, a, g, off):              # 6 buffers and half the 7th at most\n        calls.append(g)\n        assert g <= O.IOV_MAX\n        v = np.ctypeslib.as_array((ctypes.c_uint64 * (2 * g)).from_address(a)).reshape(g, 2)\n        v = np.array(v[:7] if g > 6 else v)\n        if g > 6:\n            v[6, 1] //= 2\n        return real(fd, v.ctypes.data, len(v), off)\n    fd = os.open(f, os.O_RDONLY)\n    try:\n        O.preadv_iov(fd, iov, 100)\n        assert buf.tobytes() == want\n        buf[:] = 0\n        monkeypatch.setattr(O, \"_libc_preadv\", lambda: stingy)\n        O.preadv_iov(fd, iov, 100)\n    finally:\n        os.close(fd)\n    assert buf.tobytes() == want\n    assert max(calls) == O.IOV_MAX and len(calls) > len(sizes) // 7\n\n\ndef test_a_requests_answer_follows_its_first_experts_first_part():\n    \"\"\"A request's answer (its missing experts' slots) is written once the first expert's\n    first part is on its way (a memory without write_slot: after that expert), each expert's\n    tag right after its bytes, and the directory's new entries and victims' clears after the\n    last expert, before served (the card waits on the answer and the tags; it reads a victim's\n    entry only in a later request: after served), so the link starts with the first expert's\n    bytes; clear_late False clears each victim before its slot is written, as before\n    docs/offload.md 10.8. Either way the victims' entries read empty once poll returns.\"\"\"\n    for late in (True, False):\n        lay, mem, srv = _setup(warm=[0, 1, 2])      # layer 0 LRU order: 2, 1, 0 (0 newest)\n        srv.clear_late = late\n        log, w = [], mem.write\n        tags = {a + lay.tag for a in lay.all_slots()}\n\n        def rec(addr, data, w=w):\n            log.append(\"served\" if addr == lay.served else \"answer\" if addr == lay.answer else\n                       \"dir\" if lay.dir <= addr < lay.dir + 8 * E * 2 else\n                       \"tag\" if addr in tags else \"slot\")\n            w(addr, data)\n        _post(mem, lay, 1, [5, 6])                  # two misses: victims 2 and 1\n        mem.write = rec\n        assert srv.poll() == 1\n        assert log == ([\"slot\", \"tag\", \"answer\", \"slot\", \"tag\", \"dir\", \"served\"] if late else\n                       [\"dir\", \"dir\", \"slot\", \"tag\", \"answer\", \"slot\", \"tag\", \"dir\", \"served\"])\n        assert _entry(mem, lay, 2) == _entry(mem, lay, 1) == (0, 0.0)\n        assert _entry(mem, lay, 5)[1] == _entry(mem, lay, 6)[1] == 1.0\n        assert not srv._victims\n\n\ndef test_board_dram_sends_a_requests_first_miss_a_fifth_first():\n    \"\"\"BoardDram._cuts: with nothing in flight (a request's first miss) an expert goes in\n    `pieces` parts, the first `lead` of its blocks (the link starts after a fifth is read, not\n    half), the rest in equal parts; lead None: equal parts; one part otherwise.\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu.host.offload import BoardDram\n    lay = Layout.build(4096, E, K, (3, 3), SLOT)\n    m = BoardDram(SimpleNamespace(board=None), lay)\n    assert m.lead == 0.2 and m.pieces == 2\n    assert m._cuts(408, True) == [(0, 82), (82, 408)] and m._cuts(408, False) == [(0, 408)]\n    assert m._cuts(1, True) == [(0, 1)] and m._cuts(3, True) == [(0, 1), (1, 3)]\n    m.pieces = 3\n    assert m._cuts(408, True) == [(0, 82), (82, 245), (245, 408)]\n    m.lead = None\n    assert m._cuts(408, True) == [(0, 136), (136, 272), (272, 408)]\n    with pytest.raises(ValueError, match=\"lead\"):\n        BoardDram(SimpleNamespace(board=None), lay, lead=1.0)\n\n\n@pytest.mark.parametrize(\"hints\", [False, True])\n@pytest.mark.parametrize(\"chash\", [False, True])\n@pytest.mark.parametrize(\"slot,fmt,pieces\", [(128 * 37, \"bytes\", 2), (64 * 75, \"bytes\", 2),\n                                             (4096 * 3, \"split\", 3), (4096 * 3, \"split\", 1),\n                                             (128 * 37, \"split\", 2), (4096 * 3, \"readv\", 3),\n                                             (128 * 37, \"readv\", 2)])\ndef test_board_dram_writes_what_board_write_writes(chash, slot, fmt, pieces, hints, tmp_path):\n    \"\"\"BoardDram (the card's fast path: one-pass channel runs, a worker thread's DMA, the\n    host's words from a shadow without reading the card) leaves the card's two channel memories\n    exactly as BackendDram's Board.write does, request after request: the slots (with CHASH's\n    swaps or not), the directory and served (each entry and served one DMA call: its beat). A\n    slot of a half chunk falls back to Board.write.\n    split: the pool a file in the split format, read with preadv straight into the channel\n    runs under CHASH at a page-aligned slot (pages of either parity; a slot of 37 chunks is\n    two pages apart: Layout's pitch); a request's first miss in `pieces` parts (the first a\n    fifth of it), each DMAed when it is read. readv: the same through os.preadv's buffer list\n    (a record without readiov: PoolFile.iov False) instead of preadv_iov's iovec array.\n    hints: both servers by decayed use, each request after a hint (one of its experts and one\n    it does not name) and 0, 2 or 4 polls with no request: the hinted experts' 4 KiB parts (a\n    staging pair's first bytes) land as Board.write writes them.\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import RUN, BackendDram, BoardDram, PoolFile, to_split\n\n    def board():\n        b = Board(FakeTransport(ch_bytes=1 << 20, devname=None))\n        b.info()[\"caps\"][\"chash\"] = chash\n        return b\n\n    def pool(g):\n        return np.random.default_rng(g).integers(0, 256, slot, dtype=np.uint8)\n\n    lay = Layout.build(4096, 4, 2, (2, 3), slot)\n    fast_pool = pool\n    if fmt in (\"split\", \"readv\"):\n        f = tmp_path / \"pool.bin\"\n        f.write_bytes(b\"\".join(to_split(pool(g)).tobytes() for g in range(8)))\n        pf = PoolFile(f, slot, split=True)\n        pf.iov = fmt == \"split\"\n        fast_pool = pf.get\n        assert (pf.get(0).readiov is not None) == (fmt == \"split\")\n    ba, bb = board(), board()\n    kw = dict(policy=\"lfu\", part=RUN) if hints else {}\n    fast = ExpertServer(BoardDram(SimpleNamespace(board=ba), lay, pieces=pieces), lay,\n                        fast_pool, **kw)\n    dmas, dma = [], fast.mem._dma\n\n    def counted(off, bufs, a=0, b=None, order=(0, 1)):\n        dmas.append(len(bufs[0][a:b]) < len(bufs[0]) - 64)   # (the tag beat after the runs)\n        dma(off, bufs, a, b, order)\n    fast.mem._dma = counted\n    plain = ExpertServer(BackendDram(SimpleNamespace(write=lambda s, a, d: bb.write(a, d),\n                                                     read=lambda s, a, n: bb.read(a, n))),\n                         lay, pool, **kw)\n    for srv in (fast, plain):\n        srv.load([0, 4])\n    assert isinstance(fast.mem, BoardDram) and ba.chash == chash\n\n    def same():\n        for c in (0, 1):\n            assert np.array_equal(ba.t.ch[c], bb.t.ch[c]), c\n    same()\n    m, lo, hi = fast.mem, fast.mem.lo, fast.mem.lo + len(fast.mem.shadow)\n    words, calls, mw, w = [0], [0], ba.t.mem_write, m.write\n\n    def call(ch, off, data):                # DMA calls into the host's words\n        calls[0] += lo // 2 <= off < hi // 2\n        mw(ch, off, data)\n\n    def write(addr, data):                  # the server's writes of them\n        words[0] += lo <= addr < hi\n        w(addr, data)\n    ba.t.mem_write, m.write = call, write\n    reqs = [[0, 1], [4, 6], [2, 3], [5, 7], [1, 2], [6, 4], [3, 0], [7, 5]]\n    seq, G = 0, 4 * 2\n\n    def post(ids):\n        for b in (ba, bb):                  # the card's post: the row, then seq\n            b.write(lay.row, np.array(ids + [0] * (LINE // 4 - len(ids)), np.float32))\n            b.write(lay.mbox, np.float32(seq).tobytes())\n        assert fast.poll() == plain.poll() == 1\n        same()\n    for i, ids in enumerate(reqs):\n        if hints:\n            seq += 1\n            post([G + ids[1], G + next(g for g in range(ids[0] // 4 * 4, 8) if g not in ids)])\n            for _ in range(2 * (i % 3)):\n                assert fast.poll() == plain.poll()\n                same()\n        seq += 1\n        post(ids)\n    assert calls[0] == words[0] > len(reqs)     # an entry or served: one beat, one DMA call\n    assert fast.misses == plain.misses > 0 and fast.bytes == plain.bytes\n    assert (fast.mem.direct > 0) == (fmt != \"bytes\" and chash)\n    if not hints:\n        assert any(dmas) == (fmt != \"bytes\" and chash and pieces > 1)     # a part's DMA\n    else:\n        assert fast.prefetched == plain.prefetched > 0 and fast.promoted == plain.promoted > 0\n    assert float(np.frombuffer(ba.read(lay.served, 4), np.float32)[0]) == seq\n\n\n@pytest.mark.parametrize(\"ahead\", [True, False])\ndef test_idle_parts_go_as_one_call_each_and_are_read_ahead(ahead, tmp_path):\n    \"\"\"read_ahead (docs/offload.md 13.12): on BoardDram (CHASH, a split pool file) an idle\n    poll's part was read by the poll before (stage, beside that poll's DMA: a part's, or the\n    hint's served) and goes as one DMA call per channel; one not read ahead (the first after\n    ahead_layer) keeps the lead cut. A request first drops the staged part (its pair free\n    again). ahead_layer's next expert takes its slot when its part is staged. The card's\n    memories stay as Board.write leaves them, with read_ahead and without (each idle part of 2\n    blocks cut in two).\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import RUN, BackendDram, BoardDram, PoolFile, to_split\n\n    def board():\n        b = Board(FakeTransport(ch_bytes=1 << 21, devname=None))\n        b.info()[\"caps\"][\"chash\"] = True\n        return b\n\n    slot = 4 * RUN\n    x = np.random.default_rng(3).integers(0, 256, (24, slot), dtype=np.uint8)\n    f = tmp_path / \"pool.bin\"\n    f.write_bytes(b\"\".join(to_split(r).tobytes() for r in x))\n    pf = PoolFile(f, slot, split=True)\n    lay = Layout.build(4096, 8, 2, (3, 3, 3), slot)\n    ba, bb = board(), board()\n    fast = ExpertServer(BoardDram(SimpleNamespace(board=ba), lay, pieces=2), lay, pf.get,\n                        policy=\"lfu\", part=2 * RUN)\n    plain = ExpertServer(BackendDram(SimpleNamespace(write=lambda s, a, d: bb.write(a, d),\n                                                     read=lambda s, a, n: bb.read(a, n))),\n                         lay, lambda g: x[g], policy=\"lfu\", part=2 * RUN)\n    fast.read_ahead = ahead\n    m = fast.mem\n    recs, staged, dma, stage = [], [], m._dma, m.stage\n    m._dma = lambda *a, **kw: (recs.append(a[3] if len(a) > 3 else 0), dma(*a, **kw))\n    m.stage = lambda *a: (lambda h: (staged.append(h is not None), h)[1])(stage(*a))\n    for srv in (fast, plain):\n        srv.load([0, 1, 8, 9, 16, 17])\n    seq, G = 0, 24\n\n    def poll():\n        n0 = len(recs)\n        assert fast.poll() == plain.poll()\n        for c in (0, 1):\n            assert np.array_equal(ba.t.ch[c], bb.t.ch[c]), c\n        return len(recs) - n0\n\n    def post(ids):\n        nonlocal seq\n        seq += 1\n        for b in (ba, bb):\n            b.write(lay.row, np.array(ids + [0] * (LINE // 4 - len(ids)), np.float32))\n            b.write(lay.mbox, np.float32(seq).tobytes())\n        return poll()\n    r = 1 if ahead else 2                           # an idle part's DMA calls (or a lead cut)\n    post([G + 2, G + 3])                            # hint: 2 and 3 take slots, 4 parts to send\n    assert staged == ([True] if ahead else [])      # 2's first part read beside served\n    assert poll() == r                              # ... sent, and 2's second part read\n    assert poll() == r and fast.pending == {3: 0}   # 2's second (with its tag): staged\n    assert len(m._held) == ahead                    # 3's first part staged\n    assert post([3, 1]) == 3                        # a request first: 3's staged part dropped;\n    assert not m._held and fast.promoted == 1       # its misses as before: the first (3's rest)\n    assert m._free.qsize() == m.depth               # with the lead cut, the next (1) one call\n    assert post([4, 5]) == 3\n    for srv in (fast, plain):                       # pooled: 20 a free slot, 21 a victim\n        srv.begin_prefill(ahead=True)               # of layer 0 (outside 1 and 2)\n        srv.ahead_layer(2, [20, 21])\n    assert poll() == 2 and 20 in fast.lru[2] and 21 not in fast.lru[2]     # (not read ahead)\n    assert poll() == r and (21 in fast.lru[2]) == ahead     # 21's slot taken as it is staged\n    while fast.pending or fast.queue:\n        assert poll() == r\n    assert poll() == 0 and fast.landed == plain.landed == 2 and not m._held\n    assert fast.bytes == plain.bytes and fast.misses == plain.misses\n    assert sum(staged) == (6 if ahead else 0)       # each idle part but 20's first (3's\n                                                    # first dropped)\n\n\ndef test_halt_aware_idle_parts_wait_near_a_runs_expected_end():\n    \"\"\"halt_aware (docs/offload.md 13.12): no idle part starts while the running program's\n    expected end is nearer than a part takes (part_s, or PART_S0 + part / PART_GBS before any\n    is measured), so its halt is not seen after a part. The end: the memory's run_clock (the\n    run's start and its time with no waits) plus the run's own waits (each request with misses,\n    seen to served; a new run starts them at 0). A request is served at once all the same; a\n    run past its end by HOLD_LATE, or with no clock, gets parts again. Off: no hold. On by\n    default.\"\"\"\n    import time\n\n    from opentpu.host.offload import HOLD_LATE, PART_GBS, PART_S0\n    lay, mem, srv, G = _hint_setup()\n    clock = [None]\n    mem.run_clock = lambda: clock[0]\n\n    def run(left):                                  # a run started now, `left` its time\n        clock[0] = (time.perf_counter(), left)\n    assert srv.read_ahead and srv.halt_aware        # (the defaults: v2, since session 18)\n    _post(mem, lay, 1, [G + 3, G + 4])              # 3 and 4 hinted: 6 parts to send\n    assert srv.poll() == 1 and len(srv.pending) == 2\n    need = PART_S0 + srv.part / PART_GBS\n    run(need / 2)                                   # the run ends before a part would\n    assert srv.poll() == 0 and srv.poll() == 0 and srv.holds == 2\n    assert dict(srv.pending) == {3: 0, 4: 0} and srv._waits == 0.0\n    _post(mem, lay, 2, [E + 0, E + 1])              # a request (layer 1, 2 misses): served at\n    assert srv.poll() == 1 and _served(mem, lay) == 2.0 and srv.holds == 2   # once, its time\n    assert srv._waits > 0                           # the run's own wait\n    srv._wait(2 * need)                             # (a wait of 2 parts: the end moves out)\n    assert srv.poll() == 1 and srv.pending[3] == srv.part and srv.part_s is not None\n    srv.part_s = 1.0                                # (measured parts of a second)\n    run(0.5)                                        # a new run: its waits from 0\n    assert srv.poll() == 0 and srv._waits == 0.0 and srv.holds == 3\n    assert srv.poll() == 0 and srv.holds == 4\n    run(-2 * HOLD_LATE)                             # past its end: parts again\n    assert srv.poll() == 1\n    run(0.5)\n    srv.halt_aware = False                          # off: no hold\n    assert srv.poll() == 1 and srv.holds == 4\n    clock[0], srv.halt_aware = None, True           # no clock: no hold\n    while srv.pending:\n        assert srv.poll() == 1\n    assert _landed(mem, lay, srv, 3) and _landed(mem, lay, srv, 4)\n\n\ndef test_halt_aware_reads_no_part_ahead_near_a_runs_end():\n    \"\"\"halt_aware: near the running program's expected end _stage_next reads no part ahead (the\n    host's read there would make the halt seen late: pfv2's 26B, 0.09 s more of it with read\n    ahead); stage_holds counts them. Far from its end it reads the next part as always.\"\"\"\n    import time\n    lay, mem, srv, G = _hint_setup()\n    staged, clock = [], [None]\n    mem.stage = lambda addr, data, tag=None: staged.append(addr) or len(staged)\n    mem.unstage = lambda h: None\n    mem.run_clock = lambda: clock[0]\n    srv.halt_aware = True\n    clock[0] = (time.perf_counter(), 1e-4)          # the run ends in 0.1 ms\n    _post(mem, lay, 1, [G + 3, G + 4])\n    assert srv.poll() == 1 and not staged and srv.stage_holds == 1\n    clock[0] = (time.perf_counter(), 10.0)          # far from its end: 3's first part, the\n    assert srv.poll() == 1 and len(staged) == 1     # next one read ahead\n    assert srv.stage_holds == 1 and srv.holds == 0\n\n\ndef test_a_held_idle_poll_leaves_no_dma_in_flight():\n    \"\"\"halt_aware holding the first part of an ahead expert that has just taken a victim's\n    slot (_next_ahead clears the victim's entry, a DMA): the poll flushes before it returns 0,\n    so the next poll's read of seq meets no DMA in flight (BoardDram.read raises with one).\"\"\"\n    import time\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import RUN, BoardDram\n\n    class Slow(FakeTransport):\n        def mem_write(self, ch, off, data):\n            time.sleep(5e-3)\n            super().mem_write(ch, off, data)\n\n    lay = Layout.build(4096, 8, 2, (2, 2, 2), RUN)\n    srv = ExpertServer(BoardDram(SimpleNamespace(board=Board(Slow(ch_bytes=1 << 21,\n                                                                  devname=None))), lay),\n                       lay, lambda g: np.full(RUN, g + 1, np.uint8), policy=\"lfu\", part=RUN)\n    srv.load([0, 1, 8, 9, 16, 17])                  # every slot full: 20 needs a victim\n    srv.begin_prefill(ahead=True)\n    srv.ahead_layer(2, [20])\n    srv.halt_aware, srv.mem.run_clock = True, lambda: (time.perf_counter(), 1e-6)\n    assert srv.poll() == 0 and srv.holds == 1 and 20 in srv.pending\n    assert srv.poll() == 0 and srv.holds == 2       # (its read of seq: no DMA in flight)\n    srv.halt_aware = False\n    assert srv.poll() == 1 and not srv.pending and srv.landed == 1\n\n\ndef test_board_dram_raises_a_dma_error_at_flush():\n    \"\"\"A DMA call that fails in BoardDram's worker is raised by the next flush (ExpertServer.poll\n    calls it), not lost.\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import BoardDram\n\n    class Broken(FakeTransport):\n        def mem_write(self, ch, off, data):\n            if len(data) > 1024:\n                raise IOError(\"XDMA h2c write failed\")\n            super().mem_write(ch, off, data)\n\n    lay = Layout.build(4096, 4, 2, (2, 2), 128 * 37)\n    srv = ExpertServer(BoardDram(SimpleNamespace(board=Board(Broken(ch_bytes=1 << 20,\n                                                                    devname=None))), lay),\n                       lay, lambda g: np.zeros(128 * 37, np.uint8))\n    with pytest.raises(IOError, match=\"h2c\"):\n        srv.load([0])\n\n\ndef test_board_dram_reads_only_with_its_queue_drained():\n    \"\"\"BoardDram.read raises while the worker's DMA is queued or in flight (a card->host call\n    beside a host->card one slips the card's writes); after flush it reads. ExpertServer's polls\n    on BoardDram (test_board_dram_writes_what_board_write_writes) never meet it.\"\"\"\n    import threading\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import BoardDram, _f32\n\n    go = threading.Event()\n\n    class Slow(FakeTransport):\n        def mem_write(self, ch, off, data):\n            go.wait(10)\n            super().mem_write(ch, off, data)\n\n    lay = Layout.build(4096, 4, 2, (2, 2), 128 * 37)\n    m = BoardDram(SimpleNamespace(board=Board(Slow(ch_bytes=1 << 20, devname=None))), lay)\n    m.write(lay.served, _f32(3.0))                  # one beat: one DMA call in the worker\n    with pytest.raises(RuntimeError, match=\"flush first\"):\n        m.read(lay.mbox, 4)\n    go.set()\n    m.flush()\n    assert np.frombuffer(m.read(lay.served, 4), np.float32)[0] == 3.0\n\n\ndef test_pool_split_tool_copies_the_packed_experts(tmp_path, monkeypatch):\n    \"\"\"tools/offload/pool_split.py: a slot-format pool file's packed experts, in the split\n    format; MO.serve's reader gives back their bytes.\"\"\"\n    import runpy\n    import sys\n    from pathlib import Path\n\n    from opentpu.host.offload import SPLIT, PoolFile\n    n, slot = 5, 128 * 37\n    x = np.random.default_rng(0).integers(0, 256, (n, slot), dtype=np.uint8)\n    packed = np.array([1, 0, 1, 1, 0], np.uint8)\n    src, dst = tmp_path / \"pool.bin\", tmp_path / \"pool.split.bin\"\n    src.write_bytes((x * packed[:, None]).tobytes())\n    Path(str(src) + \".packed\").write_bytes(packed.tobytes())\n    tool = Path(__file__).parent.parent / \"tools/offload/pool_split.py\"\n    monkeypatch.setattr(sys, \"argv\", [\"pool_split.py\", str(src), str(dst)])\n    runpy.run_path(str(tool), run_name=\"__main__\")\n    assert Path(str(dst) + \".format\").read_text().strip() == SPLIT\n    assert Path(str(dst) + \".packed\").read_bytes() == packed.tobytes()\n    pf = PoolFile(dst, slot, split=True)\n    for g in np.nonzero(packed)[0]:\n        assert bytes(pf.get(int(g))) == x[g].tobytes()\n\n\ndef test_pool_file_residency(tmp_path):\n    \"\"\"PoolFile.resident: the packed experts' bytes in the page cache (mincore). Experts just\n    written are there, a hole of the sparse file (never written or read) is not. On Linux, a\n    file the kernel drops from the cache (POSIX_FADV_DONTNEED after fsync; not tmpfs) comes\n    back with the warm thread.\"\"\"\n    import os\n    import sys\n\n    from opentpu.host.offload import PoolFile\n    slot, n = 4096 * 4, 6\n    f = tmp_path / \"pool.bin\"\n    f.write_bytes(np.random.default_rng(0).integers(0, 256, slot * 4, dtype=np.uint8).tobytes())\n    os.truncate(f, slot * n)                            # experts 4 and 5: a hole\n    pf = PoolFile(f, slot, split=False)\n    if pf.resident(range(n)) is None:\n        pytest.skip(\"no mincore here\")\n    assert pf.resident(range(n)) == 4 * slot and pf.resident([2, 3, 5]) == 2 * slot\n    if sys.platform != \"linux\":\n        return\n    fd = os.open(f, os.O_RDONLY)\n    os.fsync(fd)\n    os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n    os.close(fd)\n    if pf.resident(range(4)) < 4 * slot:                # (tmpfs keeps its pages)\n        pf.warm(range(4)).join(timeout=60)\n        assert pf.resident(range(4)) == 4 * slot\n\n\ndef test_slots_are_whole_run_blocks_apart_so_every_expert_reads_in_place(tmp_path):\n    \"\"\"Layout's pitch: a slot of 3.5 RUN blocks (gemma-4-26B-A4B's 841.5) starts every slot on a\n    RUN block (its tag chunk in the half block after it), so BoardDram reads every expert of a\n    split pool straight into its runs (`direct`), none through the copy path; a slot under RUN\n    keeps its size and tag chunk, rounded up to its own alignment.\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import RUN, BoardDram, PoolFile, to_split\n    slot = 3 * RUN + RUN // 2\n    lay = Layout.build(4096, 4, 2, (2, 3), slot)\n    assert lay.pitch == 4 * RUN and all(a % RUN == 0 for a, _ in lay.slots)\n    assert lay.slots[1][0] == lay.slots[0][0] + 2 * lay.pitch\n    assert lay.tag == slot and lay.end == lay.slots[1][0] + 2 * lay.pitch + slot + 128\n    assert Layout.build(4096, 4, 2, (2, 3), 128 * 7).pitch == 128 * 8     # + its tag chunk\n    assert Layout.build(4096, 4, 2, (2, 3), 256 * 3).pitch == 256 * 4     # at its alignment\n    x = np.random.default_rng(0).integers(0, 256, (8, slot), dtype=np.uint8)\n    f = tmp_path / \"pool.bin\"\n    f.write_bytes(b\"\".join(to_split(r).tobytes() for r in x))\n    b = Board(FakeTransport(ch_bytes=1 << 20, devname=None))\n    b.info()[\"caps\"][\"chash\"] = True\n    m = BoardDram(SimpleNamespace(board=b), lay)\n    srv = ExpertServer(m, lay, PoolFile(f, slot, split=True).get)\n    srv.load(range(8))\n    assert m.direct == 5\n    for g in srv.lru[0].keys() | srv.lru[1].keys():\n        assert srv.lru[g // 4][g] % RUN == 0\n        assert np.array_equal(np.asarray(b.read(srv.lru[g // 4][g], slot)).view(np.uint8), x[g])\n\n\ndef test_pool_file_touches_what_it_reads_through_its_map(tmp_path):\n    \"\"\"PoolFile's `mapped` (the default): each expert read (get, warm) is touched through a\n    read-only map of the pool, so its pages stand as mapped ones under MGLRU (docs/offload.md\n    10.7); the bytes are preadv's either way. On Linux the map's resident pages\n    (/proc/self/smaps) cover what was read, and mapped=False leaves no map.\"\"\"\n    import sys\n\n    from opentpu.host.offload import PoolFile\n    slot, n = 4096 * 3 + 2048, 6                      # (experts off a page too)\n    x = np.random.default_rng(0).integers(0, 256, (n, slot), dtype=np.uint8)\n    f = tmp_path / \"pool.bin\"\n    f.write_bytes(x.tobytes())\n\n    def rss():                                        # the pool's maps' resident bytes\n        if sys.platform != \"linux\":\n            return None\n        out, cur = 0, False\n        for ln in open(\"/proc/self/smaps\"):\n            if ln[0] in \"0123456789abcdef\" and \"-\" in ln.split()[0]:\n                cur = ln.rstrip().endswith(str(f))\n            elif cur and ln.startswith(\"Rss:\"):\n                out += int(ln.split()[1]) * 1024\n        return out\n    for mapped in (True, False):\n        pf = PoolFile(f, slot, split=False, mapped=mapped)\n        for g in (1, 4):\n            assert bytes(pf.get(g)) == x[g].tobytes()\n        pf.warm([5]).join(timeout=60)\n        if mapped:                                    # (read-only: nothing writes through it)\n            assert pf._mc and (rss() is None or rss() >= 3 * slot)\n            assert not pf._mc[1].flags.writeable\n        else:\n            assert pf._mc is None\n        del pf\n\n\ndef test_a_requests_reads_are_touched_once_it_is_served(tmp_path):\n    \"\"\"PoolFile.defer_touch (moe.serve sets it): a read's touch waits until the request is\n    served (ExpertServer, after served and the DMA's flush: while the card computes), not\n    between the read and its DMA; with io counting (moe_card's decode) each read still says\n    whether its pages were in the page cache.\"\"\"\n    from opentpu.host.offload import PoolFile\n    lay = Layout.build(4096, E, K, (3, 3), 4096)\n    x = np.random.default_rng(0).integers(0, 256, (2 * E, 4096), dtype=np.uint8)\n    f = tmp_path / \"pool.bin\"\n    f.write_bytes(x.tobytes())\n    pf = PoolFile(f, 4096, split=False)\n    pf.defer_touch, pf.io = True, {}\n    mem = SimDram(np.zeros(lay.end + 4096, np.uint8))\n    srv = ExpertServer(mem, lay, lambda g: pf.get(g).tobytes())\n    srv.pool_file = pf\n    srv.load()\n    log, touch, w = [], pf._touch, mem.write\n    pf._touch = lambda off, n: (log.append((\"touch\", off // 4096)), touch(off, n))\n    mem.write = lambda addr, d: (log.append(\"served\") if addr == lay.served else None,\n                                 w(addr, d))\n    _post(mem, lay, 1, [5, 4])\n    srv.poll()\n    assert log == [\"served\", (\"touch\", 4), (\"touch\", 5)] and not pf._touches\n    assert sum(v[0] for v in pf.io.values()) == 2\n    for g in (4, 5):\n        assert mem.read(srv.lru[0][g], 4096) == x[g].tobytes()\n\n\ndef test_board_dram_keeps_a_staging_pair_until_its_last_part(tmp_path):\n    \"\"\"A staging pair goes back to the free list only after its expert's last part is on the\n    card: with one pair and a slow link, the next expert's read waits for it (else it would\n    overwrite the parts still queued).\"\"\"\n    import time\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import BoardDram, PoolFile, to_split\n\n    class Slow(FakeTransport):\n        def mem_write(self, ch, off, data):\n            if len(data) > 1024:\n                time.sleep(2e-3)\n            super().mem_write(ch, off, data)\n\n    slot = 4096 * 3\n    x = np.random.default_rng(0).integers(0, 256, (8, slot), dtype=np.uint8)\n    f = tmp_path / \"pool.bin\"\n    f.write_bytes(b\"\".join(to_split(r).tobytes() for r in x))\n    b = Board(Slow(ch_bytes=1 << 20, devname=None))\n    b.info()[\"caps\"][\"chash\"] = True\n    lay = Layout.build(4096, 4, 2, (2, 3), slot)\n    m, pf = BoardDram(SimpleNamespace(board=b), lay, depth=1, pieces=3), PoolFile(f, slot, True)\n    pf.io = {}\n    srv = ExpertServer(m, lay, pf.get)\n    srv.load(range(8))\n    for g in srv.lru[0].keys() | srv.lru[1].keys():\n        s = srv.lru[g // 4][g]\n        assert np.array_equal(np.asarray(b.read(s, slot)).view(np.uint8), x[g]), g\n    assert m.wait_s > 2e-3                              # (moe_card's stage_wait)\n    assert sum(v[2] for v in pf.io.values()) == 5 * slot   # each read counted once, in parts\n\n\ndef test_pool_file_counts_its_reads_by_the_page_cache(tmp_path):\n    \"\"\"PoolFile.io (moe_card's decode): each read counted as \"cached\" (all its pages in the\n    page cache just before it) or \"disk\", [reads, seconds, bytes, bytes not in the cache];\n    nothing without io. A hole of the sparse file (never written or read) is not cached.\"\"\"\n    import os\n\n    from opentpu.host.offload import PoolFile, to_split\n    slot, n = 4096 * 4, 6\n    x = np.random.default_rng(0).integers(0, 256, (4, slot), dtype=np.uint8)\n    f = tmp_path / \"pool.bin\"\n    f.write_bytes(x.tobytes())\n    os.truncate(f, slot * n)                            # experts 4 and 5: holes\n    for split, hole in ((False, 4), (True, 5)):\n        pf = PoolFile(f, slot, split=split)\n        pf.willneed([1, 2])                             # (a hint to the kernel, or nothing)\n        if pf.resident(range(n)) is None:\n            pytest.skip(\"no mincore here\")\n        np.asarray(pf.get(1))\n        assert pf.io is None\n        pf.io = {}\n        got = np.asarray(pf.get(2))\n        assert np.array_equal(to_split(got) if split else got, x[2])    # (x as written)\n        np.asarray(pf.get(hole))\n        assert pf.io[\"cached\"][0] == 1 and pf.io[\"cached\"][2:] == [slot, 0], pf.io\n        assert pf.io[\"disk\"][0] == 1 and pf.io[\"disk\"][2:] == [slot, slot], pf.io\n\n\ndef test_lfu_policy_evicts_the_least_decayed_use():\n    \"\"\"policy=\"lfu\": the victim is the cached expert, not in the request, whose uses (each\n    halving every `half` requests of its layer; a warm expert one use at the start) sum least,\n    ties to the least recently used; checked request by request against that sum computed\n    directly, on a skewed random stream. LRU stays the default.\"\"\"\n    half, slots = 4.0, 5\n    lay = Layout.build(4096, E, K, (slots,), SLOT)\n    srv = ExpertServer(SimDram(np.zeros(lay.end + 4096, np.uint8)), lay, _pool, policy=\"lfu\",\n                       half=half)\n    srv.load([0, 1, 2, 3, 4])\n    assert ExpertServer(srv.mem, lay, _pool).policy == \"lru\"\n    rng = np.random.default_rng(3)\n    p = 1.0 / np.arange(1, E + 1) ** 1.2\n    uses = {g: [0] for g in range(5)}                  # request times of each expert's uses\n    cache, order = set(range(5)), [4, 3, 2, 1, 0]      # recency: least recent first\n    for t in range(1, 300):\n        ids = [int(g) for g in rng.choice(E, K, replace=False, p=p / p.sum())]\n        for g in ids:\n            uses.setdefault(g, []).append(t)\n        miss = [g for g in ids if g not in cache]\n        for g in ids:\n            if g in cache:\n                order.remove(g)\n                order.append(g)\n        want = []\n        for g in miss:\n            if len(cache) >= slots:\n                cand = [v for v in order if v not in ids]\n                sc = [sum(0.5 ** ((t - u) / half) for u in uses[v]) for v in cand]\n                v = cand[int(np.argmin(sc))]\n                cache.discard(v)\n                order.remove(v)\n                want.append(v)\n            cache.add(g)\n            order.append(g)\n        before = set(srv.lru[0])\n        srv.serve(ids)\n        assert before - set(srv.lru[0]) == set(want), (t, ids, want)\n        assert set(srv.lru[0]) == cache\n\n\ndef _hint_setup(policy=\"lfu\", warm=(0, 1, 2), slot=2 * 4096 + 128, **kw):\n    \"\"\"Layer 0 of 3 slots with `warm` (LRU order 2, 1, 0: 0 newest), experts of three 4 KiB parts\n    (the last 128 bytes).\"\"\"\n    from opentpu.host.offload import RUN\n    lay = Layout.build(4096, E, K, (3, 3), slot)\n    mem = SimDram(np.zeros(lay.end + 4096, np.uint8))\n    srv = ExpertServer(mem, lay, lambda g: np.full(slot, g + 1, np.uint8).tobytes(),\n                       policy=policy, part=RUN, **kw)\n    srv.load(list(warm))\n    return lay, mem, srv, E * 2\n\n\ndef _landed(mem, lay, srv, g):\n    a, p = _entry(mem, lay, g)\n    return p == 1.0 and mem.read(a, lay.slot_bytes) == srv.pool(g)\n\n\ndef test_a_hint_takes_its_slots_at_once_and_lands_on_idle_polls():\n    \"\"\"A hint (ids at G = layers x E and above): each named expert not in a slot gets one at\n    once (here the least recent of the equally used warm ones that the hint does not name),\n    the victim's entry cleared, and served written; no use is counted. Each poll that finds no\n    request then sends one part of it, its entry once the last part is in. A request naming it\n    afterwards hits.\"\"\"\n    lay, mem, srv, G = _hint_setup()\n    _post(mem, lay, 1, [G + 3, G + 1])              # 1 resident; 3 replaces 2\n    assert srv.poll() == 1 and _served(mem, lay) == 1.0\n    assert _entry(mem, lay, 2) == (0, 0.0) and _entry(mem, lay, 3) == (0, 0.0)\n    assert dict(srv.pending) == {3: 0} and srv.t == [0, 0] and 3 not in srv.use[0]\n    assert (srv.hints, srv.hits, srv.misses) == (1, 0, 0)\n    for sent in (4096, 8192):\n        assert srv.poll() == 1 and dict(srv.pending) == {3: sent}\n        assert _entry(mem, lay, 3) == (0, 0.0)\n    assert srv.poll() == 1 and not srv.pending and _landed(mem, lay, srv, 3)\n    assert srv.poll() == 0 and srv.prefetched == 1 and srv.bytes == lay.slot_bytes\n    _post(mem, lay, 2, [3, 1])\n    assert srv.poll() == 1 and (srv.hits, srv.misses) == (2, 0)\n\n\ndef test_a_request_sends_the_rest_of_a_hinted_expert_or_replaces_it():\n    \"\"\"A request naming a hinted expert still on its way sends the rest of it at once (a miss,\n    `promoted`); one that names neither hinted expert may replace one (no use: the first\n    victim under decayed use), dropping what was sent of it.\"\"\"\n    lay, mem, srv, G = _hint_setup()\n    _post(mem, lay, 1, [G + 3, G + 4])              # 3 replaces 2, 4 replaces 1\n    srv.poll()\n    assert _entry(mem, lay, 1) == (0, 0.0) and list(srv.pending) == [3, 4]\n    srv.poll()                                      # one part of 3\n    assert dict(srv.pending) == {3: 4096, 4: 0}\n    _post(mem, lay, 2, [4, 0])\n    assert srv.poll() == 1 and _landed(mem, lay, srv, 4) and _landed(mem, lay, srv, 0)\n    assert (srv.hits, srv.misses, srv.promoted) == (1, 1, 1) and dict(srv.pending) == {3: 4096}\n    _post(mem, lay, 3, [5, 4])                      # 3 (no use) is the victim, half sent\n    assert srv.poll() == 1 and not srv.pending and srv.dropped == 1\n    assert _entry(mem, lay, 3) == (0, 0.0) and _landed(mem, lay, srv, 5)\n    assert srv.poll() == 0 and srv.prefetched == 0\n    assert srv.bytes == 4096 + 2 * lay.slot_bytes   # 3's first part, 4, 5\n\n\ndef test_lru_ignores_hints_and_a_hint_is_one_layers():\n    \"\"\"The \"lru\" policy answers a hint with served alone (an LRU victim of a wrong hint is a\n    recent expert, docs/offload.md 5.4); a hint naming two layers is refused.\"\"\"\n    lay, mem, srv, G = _hint_setup(policy=\"lru\")\n    before = mem.read(lay.dir, 8 * E * 2)\n    _post(mem, lay, 1, [G + 3, G + 4])\n    assert srv.poll() == 1 and _served(mem, lay) == 1.0 and srv.poll() == 0\n    assert mem.read(lay.dir, 8 * E * 2) == before and not srv.pending and srv.hints == 1\n    _post(mem, lay, 2, [G + 3, G + E + 4])\n    with pytest.raises(ValueError, match=\"one layer\"):\n        srv.poll()\n\n\ndef test_a_request_withdraws_its_layers_unnamed_hints_with_drop():\n    \"\"\"drop=True: a request withdraws its layer's hinted experts it does not name that have not\n    landed (their slots free again, nothing more sent), and keeps the others' layers' hints; the\n    next miss in the layer takes a freed slot without replacing a cached expert.\"\"\"\n    lay, mem, srv, G = _hint_setup(drop=True, warm=(0, 1, 2, E))\n    _post(mem, lay, 1, [G + E + 5, G + E + 6])     # layer 1: two free slots, 5 and 6\n    srv.poll()\n    _post(mem, lay, 2, [G + 3, G + 4])             # layer 0: 3 replaces 2, 4 replaces 1\n    srv.poll()\n    srv.poll()                                      # one part of 5 (the oldest)\n    assert dict(srv.pending) == {E + 5: 4096, E + 6: 0, 3: 0, 4: 0}\n    _post(mem, lay, 3, [4, 0])                      # 3 withdrawn; layer 1's stay\n    assert srv.poll() == 1 and srv.withdrawn == 1 and srv.dropped == 0\n    assert list(srv.pending) == [E + 5, E + 6] and 3 not in srv.lru[0]\n    assert _entry(mem, lay, 3) == (0, 0.0) and len(srv.free[0]) == 1\n    _post(mem, lay, 4, [7, 4])                      # 7 takes 3's slot: 0 stays\n    srv.poll()\n    assert set(srv.lru[0]) == {0, 4, 7} and _landed(mem, lay, srv, 7)\n\n\ndef test_an_expert_landed_in_the_poll_before_a_request_is_answered():\n    \"\"\"docs/offload.md 12.8: a request posted while an idle poll lands one of its experts\n    (after the poll read seq, before the expert's entry landed): the card may read that entry\n    as missing and wait on its answer word. The host serves that expert as a hit, so the\n    request's answer names its slot all the same (its tag landed with it), even with no miss.\n    An expert landed two polls before a request is not answered (the card reads its entry\n    after the poll between read seq, by when the entry had landed).\"\"\"\n    from opentpu.host.offload import RUN\n    lay, mem, srv, G = _hint_setup(slot=RUN)        # experts of one part\n    _post(mem, lay, 1, [G + 3, G + 4])              # hint: 3 and 4 take slots (2 and 1 leave)\n    assert srv.poll() == 1 and dict(srv.pending) == {3: 0, 4: 0}\n    read, posted = mem.read, []\n\n    def late(a, n):                                 # the card posts right after the poll's\n        r = read(a, n)                              # read of seq\n        if a == lay.mbox and not posted:\n            posted.append(1)\n            _post(mem, lay, 2, [0, 3])\n        return r\n    mem.read = late\n    assert _entry(mem, lay, 3) == (0, 0.0)          # what the card reads: 3 missing\n    assert srv.poll() == 1 and dict(srv.pending) == {4: 0}  # this poll lands 3 (its entry)\n    mem.read = read\n    assert _landed(mem, lay, srv, 3)\n    assert srv.poll() == 1 and srv.misses == 0 and srv.late == 1    # 0 and 3: hits\n    ans = np.frombuffer(mem.read(lay.answer, 8), np.uint32)\n    assert ans[1] == srv.lru[0][3] and ans[0] == 0  # 3's slot named, 0's not\n    mem.write(lay.answer, np.zeros(2, np.uint32))   # (the card zeroes it)\n    assert srv.poll() == 1 and not srv.pending      # 4 lands, then a poll with nothing\n    assert srv.poll() == 0\n    _post(mem, lay, 3, [4, 0])\n    assert srv.poll() == 1 and srv.late == 1\n    assert not np.frombuffer(mem.read(lay.answer, 8), np.uint32).any()\n\n\ndef test_hint_caps_send_the_first_n_of_its_top_ids_not_in_a_slot():\n    \"\"\"hint_n / hint_top (docs/offload.md 12.7): of a hint's first hint_top ids (the router's\n    best first), the first hint_n not in a slot get one, at once (the victim's entry cleared\n    before served covers the hint), the others nothing: no slot, no eviction.\"\"\"\n    lay, mem, srv, G = _hint_setup()                # layer 0: 0, 1, 2 in slots\n    srv.hint_n, srv.hint_top = 1, 3\n    _post(mem, lay, 1, [G + 1, G + 3, G + 4, G + 5])    # top 3: 1 (in a slot), 3, 4: 3 only\n    assert srv.poll() == 1 and _served(mem, lay) == 1.0\n    assert list(srv.pending) == [3] and 4 not in srv.lru[0] and 5 not in srv.lru[0]\n    assert _entry(mem, lay, 2) == (0, 0.0) and set(srv.lru[0]) == {0, 1, 3}\n    while srv.poll():\n        pass\n    assert _landed(mem, lay, srv, 3) and srv.prefetched == 1\n    srv.hint_top = 1                                # top 1: 0, in a slot: nothing\n    _post(mem, lay, 2, [G + 0, G + 6])\n    assert srv.poll() == 1 and not srv.pending and 6 not in srv.lru[0]\n    srv.hint_n = srv.hint_top = 0                   # uncapped: every one not in a slot\n    _post(mem, lay, 3, [G + 6, G + 7])\n    assert srv.poll() == 1 and list(srv.pending) == [6, 7]\n\n\n@pytest.mark.parametrize(\"chash\", [False, True])\ndef test_board_dram_reads_a_beat_as_board_read_does(chash):\n    \"\"\"BoardDram.read of bytes within one 64-byte beat (a poll's seq, a request's row) reads that\n    beat alone from its channel (CHASH's swap or not) and gives Board.read's bytes; a longer\n    read is Board.read's.\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import BoardDram\n\n    b = Board(FakeTransport(ch_bytes=1 << 16, devname=None))\n    b.info()[\"caps\"][\"chash\"] = chash\n    x = np.random.default_rng(1).integers(0, 256, 1 << 14, dtype=np.uint8)\n    b.write(0, x)\n    m = BoardDram(SimpleNamespace(board=b), Layout.build(4096, 4, 2, (2,), 128))\n    calls, mr = [], b.t.mem_read\n    b.t.mem_read = lambda *a, **k: calls.append(a) or mr(*a, **k)\n    for addr, n in [(0, 4), (64, 4), (4096 + 64, 16), (100 * 128 + 60, 4), (5 * 128 + 64, 64),\n                    (7 * 128 + 60, 8), (3 * 128, 128)]:\n        calls.clear()\n        assert m.read(addr, n) == x[addr:addr + n].tobytes(), (addr, n)\n        assert len(calls) == (1 if addr % 64 + n <= 64 else 2), (addr, n)\n\n\ndef _post_n(mem, lay, seq, ids):\n    \"\"\"A post of len(ids) ids (repeats kept): the row, then row2, then the count and seq.\"\"\"\n    h = LINE // 4\n    mem.write(lay.row, np.array(ids[:h] + [0] * (h - len(ids[:h])), np.float32))\n    if len(ids) > h:\n        mem.write(lay.row2, np.array(ids[h:] + [0] * (2 * h - len(ids)), np.float32))\n    mem.write(lay.mbox, np.array([seq, len(ids)], np.float32))\n\n\ndef _consistent(mem, lay, srv):\n    \"\"\"The directory is the server's map: each expert in a slot reads {slot, 1.0}, every other\n    {0, 0.0}; no slot twice; each layer's slots and free slots are its own number outside\n    pooled mode.\"\"\"\n    held = {g: a for lru in srv.lru for g, a in lru.items()}\n    assert len(set(held.values())) == len(held)\n    for g in range(lay.E * lay.layers):\n        assert _entry(mem, lay, g) == ((held[g], 1.0) if g in held else (0, 0.0)), g\n    for g, a in held.items():\n        assert mem.read(a, lay.slot_bytes) == srv.pool(g), g\n    if not srv.pooled:\n        for j, (_, n) in enumerate(lay.slots):\n            assert len(srv.lru[j]) + len(srv.free[j]) == n, j\n\n\ndef test_two_line_layout_moves_nothing_else():\n    \"\"\"lines=2: a second line of the answer before the directory and a second line of ids on\n    its own 128-byte block after it, the slots after that.\"\"\"\n    one, two = (Layout.build(4096, E, K, (3, 5), SLOT, lines=n) for n in (1, 2))\n    assert one == Layout.build(4096, E, K, (3, 5), SLOT) and one.row2 == 0\n    assert (one.mbox, one.served, one.answer) == (two.mbox, two.served, two.answer)\n    assert two.dir == one.dir + LINE\n    assert two.row2 % (2 * LINE) == 0 and two.row2 >= two.dir + 8 * E * 2\n    assert two.slots[0][0] >= two.row2 + LINE and two.slots[0][0] % 4096 == 0\n    assert (one.max_ids, two.max_ids) == (16, 32)\n    with pytest.raises(ValueError):\n        Layout.build(4096, E, K, (3,), SLOT, lines=3)\n\n\ndef test_a_two_line_directory_write_leaves_the_answer_alone():\n    \"\"\"lines=2: the directory starts at the odd beat of the block holding the answer's second\n    line, which the card zeroes after its experts. BoardDram writes a directory span's beats\n    only: widened to whole 128-byte blocks from its shadow, a span from entry 0 put the stale\n    answer back, for a later request's miss to take a slot it does not name.\"\"\"\n    from types import SimpleNamespace\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import BoardDram\n    for lines in (1, 2):\n        lay = Layout.build(4096, 64, 8, (8, 8), 4096, lines=lines)\n        board = Board(FakeTransport(ch_bytes=1 << 20, devname=None))\n        bd = BoardDram(SimpleNamespace(board=board), lay)\n        bd.write(lay.answer, np.arange(1, lay.max_ids + 1, dtype=np.uint32) * 0x1000)\n        bd.flush()\n        board.write(lay.answer, np.zeros(lay.max_ids, np.uint32))     # the card zeroes it\n        bd.write(lay.entry(0), np.full((24, 2), 7, np.uint32))        # 3 beats of entries\n        bd.flush()\n        assert not board.read(lay.answer, 4 * lay.max_ids).any(), lines\n        assert (board.read(lay.entry(0), 8 * 24).view(np.uint32) == 7).all()\n\n\ndef test_seq_goes_back_to_zero_between_runs(tmp_path, monkeypatch):\n    \"\"\"The card posts seq + 1.0 in fp32, exact up to 2^24 only: there the post repeats the last\n    seq, the host sees no request, and every miss after waits out its WAITW. From SEQ_REBASE\n    on, before each run (BoardBackend.start), the servers set the mailbox's seq and served back\n    to 0, a request left unserved (all hits) served first; the card's next post is 1.\"\"\"\n    import opentpu.host.offload as O\n    from opentpu.host.board import BoardBackend\n    from opentpu.host.fake import FakeTransport\n    from opentpu.isasim import board_config\n    assert np.float32(2 ** 24) + np.float32(1.0) == np.float32(2 ** 24)\n    monkeypatch.setenv(\"OTPU_RUN_DIR\", str(tmp_path))\n    monkeypatch.setattr(O, \"SEQ_REBASE\", 4)\n    be = BoardBackend(board_config(DRAM_BYTES=1 << 21), [np.zeros(4096, np.uint8)],\n                      transport=FakeTransport(ch_bytes=1 << 20, devname=None), status=False)\n    lay = Layout.build(1 << 16, E, K, (3, 3), SLOT)\n    mem = O.BackendDram(be)\n    srv = ExpertServer(mem, lay, _pool)\n    srv.load()\n    srv.history = []\n    rl = O.RowLayout(1 << 17, (1 << 17) + 4096, 64)\n    rows = O.RowServer(mem, rl, lambda g: np.full(64, g, np.uint8).tobytes())\n    rows.load()\n    rows.history = []\n    be.servers = [srv, rows]\n\n    def post(mbox, row, ids):               # the card: its fence, the ids, then seq + 1.0\n        seq = np.frombuffer(mem.read(mbox, 4), np.float32)[0]\n        mem.write(row, np.array(ids + [0] * (LINE // 4 - len(ids)), np.float32))\n        mem.write(mbox, (seq + np.float32(1.0)).tobytes())\n    for i in range(5):\n        post(lay.mbox, lay.row, [0, 1])\n        post(rl.mbox, rl.row, [i])\n        if i < 4:                           # (the fifth left for the next run's start)\n            assert srv.poll() == 1 and rows.poll() == 1\n    assert srv.seq == rows.seq == 4\n    be.run(np.zeros(16, np.uint32))\n    assert len(srv.history) == len(rows.history) == 5 and srv.seq == rows.seq == 0\n    for mbox, served in ((lay.mbox, lay.served), (rl.mbox, rl.served)):\n        assert np.frombuffer(mem.read(mbox, 4), np.float32)[0] == 0\n        assert np.frombuffer(mem.read(served, 4), np.float32)[0] == 0\n    post(lay.mbox, lay.row, [2, 3])\n    assert srv.poll() == 1 and _served(mem, lay) == 1.0\n    be.close()\n\n\ndef test_a_request_of_more_than_16_ids_reads_its_second_line():\n    \"\"\"A 4-row run's request (moe.moe_ffn_rows: R k ids, repeats included) of 20 ids: 16 on the\n    row, 4 on row2; each served once. A one-line layout refuses more than 16.\"\"\"\n    for lines in (2, 1):\n        lay = Layout.build(4096, 40, K, (24,), SLOT, lines=lines)\n        mem = SimDram(np.zeros(lay.end + 4096, np.uint8))\n        srv = ExpertServer(mem, lay, _pool)\n        srv.load()\n        ids = list(range(18)) + [3, 17]\n        _post_n(mem, lay, 1, ids)\n        if lines == 1:\n            with pytest.raises(RuntimeError, match=\"lines hold 16\"):\n                srv.poll()\n            continue\n        assert srv.poll() == 1 and _served(mem, lay) == 1.0\n        assert srv.misses == 18 and srv.history is None\n        _consistent(mem, lay, srv)\n\n\ndef _pooled_run(srv, mem, lay, restore):\n    \"\"\"A layer-major prefill of three layers (each its union over two runs of 2 rows), the\n    restore, then decode requests.\"\"\"\n    seq = 0\n    srv.begin_prefill()\n    for run in ([0, 1, 1, 2], [1, 2, 2, 0], [8, 9, 9, 10], [9, 9, 8, 10],\n                [16, 17, 17, 18], [17, 17, 16, 18]):\n        seq += 1\n        _post_n(mem, lay, seq, run)\n        assert srv.poll() == 1\n        _consistent(mem, lay, srv)\n    srv.end_prefill(restore)\n    _consistent(mem, lay, srv)\n    for ids in ([4, 5], [12, 13], [20, 21], [1, 2]):\n        seq += 1\n        _post_n(mem, lay, seq, ids)\n        assert srv.poll() == 1\n        _consistent(mem, lay, srv)\n    return seq\n\n\ndef test_pooled_prefill_takes_any_layers_slots_then_restores_each_layers():\n    \"\"\"begin_prefill: a layer's experts take any layer's slots (2 a layer, 6 in all: each\n    layer's union of 3 fits), the least recent of another layer the victim. end_prefill: each\n    layer back to its 2, keeping its experts of most use (a request's repeats count once);\n    lazy loads nothing, eager each layer's most used; decode's requests then evict within\n    their layer.\"\"\"\n    for restore in (\"lazy\", \"eager\"):\n        lay, mem, srv = _setup(slots=(2, 2, 2))\n        srv.begin_prefill()\n        assert srv.pooled\n        runs = ([0, 1, 1, 2], [1, 1, 2, 2], [8, 9, 9, 10], [10, 10, 9, 9])\n        for seq, run in enumerate(runs, 1):\n            _post_n(mem, lay, seq, run)\n            assert srv.poll() == 1\n        assert set(srv.lru[0]) == {0, 1, 2} and set(srv.lru[1]) == {8, 9, 10}  # 3 > 2 each\n        _post_n(mem, lay, 5, [16, 17, 17, 18])          # layer 0's three, the oldest, leave\n        srv.poll()\n        _post_n(mem, lay, 6, [18, 17, 18, 17])\n        srv.poll()\n        assert not srv.lru[0] and set(srv.lru[2]) == {16, 17, 18}\n        _consistent(mem, lay, srv)\n        b = srv.bytes\n        srv.end_prefill(restore)\n        assert not srv.pooled\n        assert set(srv.lru[1]) == {9, 10} and set(srv.lru[2]) == {17, 18}     # two uses each\n        assert set(srv.lru[0]) == ({1, 2} if restore == \"eager\" else set())\n        assert srv.bytes - b == (2 * SLOT if restore == \"eager\" else 0)\n        _consistent(mem, lay, srv)\n        _post_n(mem, lay, 7, [11, 12])                  # layer 1's two slots, its own victims\n        srv.poll()\n        assert set(srv.lru[1]) == {11, 12} and set(srv.lru[2]) == {17, 18}\n        _consistent(mem, lay, srv)\n\n\ndef test_pooled_prefill_on_board_dram_writes_what_board_write_writes():\n    \"\"\"The pooled prefill and both restores through BoardDram (the card's: the worker, the\n    shadow of the host's words, CHASH) leave the board's DRAM as Board.write's server does.\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import BackendDram, BoardDram\n\n    slot = 2 * 4096 + 128\n    lay = Layout.build(4096, E, K, (2, 2, 2), slot, lines=2)\n\n    def pool(g):\n        return np.random.default_rng(g).integers(0, 256, slot, dtype=np.uint8).tobytes()\n    for restore in (\"lazy\", \"eager\"):\n        ba, bb = (Board(FakeTransport(ch_bytes=1 << 20, devname=None)) for _ in range(2))\n        for b in (ba, bb):\n            b.info()[\"caps\"][\"chash\"] = True\n        fast = ExpertServer(BoardDram(SimpleNamespace(board=ba), lay), lay, pool, policy=\"lfu\")\n        plain = ExpertServer(BackendDram(SimpleNamespace(write=lambda s, a, d: bb.write(a, d),\n                                                         read=lambda s, a, n: bb.read(a, n))),\n                             lay, pool, policy=\"lfu\")\n        seqs = []\n        for srv in (fast, plain):\n            srv.load()\n            seqs.append(_pooled_run(srv, srv.mem, lay, restore))\n        assert seqs[0] == seqs[1] and fast.misses == plain.misses and fast.bytes == plain.bytes\n        for c in (0, 1):\n            assert np.array_equal(ba.t.ch[c], bb.t.ch[c]), (restore, c)\n\n\ndef test_poll_pacer_sleeps_through_the_quiet_part_of_each_gap():\n    \"\"\"PollPacer (moe_card --poll-idle predict): after a request it sleeps share x the shortest\n    of the last gaps after that kind of request (less its lateness), then polls; each request is\n    still seen within a poll of its post, with far fewer polls than spinning. A gap shorter than\n    expected is seen at the sleep's end and shortens the next sleep; nothing sleeps while hinted\n    experts wait (pending), and a hinted part (last None) is not a request.\"\"\"\n    from opentpu.host.offload import PollPacer\n    now = [0.0]\n    POLL = 30e-6                            # a poll's card read\n\n    class Card:                             # posts kind k's request gap[k] after the last served\n        def __init__(self, gaps):\n            self.gaps, self.k, self.due, self.last, self.pending = gaps, 0, 0.0, None, {}\n            self.seen = []\n\n        def poll(self):\n            now[0] += POLL\n            if now[0] < self.due:\n                return 0\n            self.seen.append(now[0] - self.due)\n            self.last = (\"d\", self.k)\n            now[0] += 1e-3                  # serving\n            self.k = (self.k + 1) % len(self.gaps)\n            self.due = now[0] + self.gaps[self.k]\n            return 1\n\n    def run(card, pacer, n):\n        polls = 0\n        while len(card.seen) < n:\n            pacer.poll()\n            polls += 1\n        return polls\n\n    def sleep(d):\n        now[0] += d\n    gaps = [2.7e-3, 1.5e-3, 3.0e-3]\n    card = Card(gaps)\n    pacer = PollPacer([card], sleep=sleep, clock=lambda: now[0])\n    first = run(card, pacer, len(gaps) + 1)         # learning: one gap of each kind\n    polls = run(card, pacer, 61)\n    assert max(card.seen) <= POLL + 1e-12            # within a poll of the post, every time\n    spin = sum(int(g / POLL) + 1 for g in gaps) * 20\n    assert polls < 0.4 * spin and pacer.sleeps >= 55 and first > 0\n    assert pacer.slept > 0.7 * 20 * sum(g * 0.75 - 2e-4 for g in gaps)\n    card.gaps[1] = 0.8e-3                           # a shorter gap: seen at the sleep's end\n    run(card, pacer, len(card.seen) + 6)\n    late = max(card.seen[-6:])\n    assert POLL < late < 0.75 * 1.5e-3\n    run(card, pacer, len(card.seen) + 6)            # then learned: within a poll again\n    assert max(card.seen[-3:]) <= POLL + 1e-12\n    card.pending = {7: 0}                           # hinted experts waiting: no sleep\n    run(card, pacer, len(card.seen) + 1)            # (after the sleep already set)\n    s0 = pacer.sleeps\n    run(card, pacer, len(card.seen) + 6)\n    assert pacer.sleeps == s0\n    with pytest.raises(ValueError, match=\"share\"):\n        PollPacer([card], share=1.0)\n\n\ndef _tag(mem, lay, slot):\n    return int(np.frombuffer(mem.read(slot + lay.tag, 4), np.uint32)[0])\n\n\ndef _answer(mem, lay):\n    return [int(v) for v in np.frombuffer(mem.read(lay.answer, LINE), np.uint32)]\n\n\ndef test_the_answer_names_the_missing_experts_slots_and_their_tags_land():\n    \"\"\"docs/offload.md 10.11: load zeroes every slot's tag and the answer. A request's answer\n    holds each missing expert's slot at the id's place (0 for the hits); each one's tag reads\n    g + 1 once poll returns. The card zeroes the tags of the experts it used and then the\n    answer before its next post: tags the host wrote are armed until a later request comes.\"\"\"\n    lay, mem, srv = _setup(warm=[0, 1, 2])\n    assert all(_tag(mem, lay, a) == 0 for a in lay.all_slots())\n    assert _answer(mem, lay) == [0] * 16\n    _post(mem, lay, 1, [2, 5])                      # 2 hits; 5 misses\n    srv.poll()\n    s5 = srv.lru[0][5]\n    assert _answer(mem, lay) == [0, s5] + [0] * 14\n    assert _tag(mem, lay, s5) == 6 and srv.armed == {s5}\n    assert _tag(mem, lay, srv.lru[0][2]) == 0       # (a hit's tag is left alone)\n    for g in (2, 5):                                # the card: each used expert's tag, then\n        mem.write(srv.lru[0][g] + lay.tag, np.zeros(1, np.uint32))    # the answer, zeroed\n    mem.write(lay.answer, np.zeros(16, np.uint32))\n    _post(mem, lay, 2, [6, 2])                      # 6 misses\n    srv.poll()\n    s6 = srv.lru[0][6]\n    assert srv.armed == {s6} and _answer(mem, lay) == [s6] + [0] * 15\n    assert _tag(mem, lay, s6) == 7 and _tag(mem, lay, s5) == 0\n\n\ndef test_an_armed_victims_tag_is_cleared_before_its_slot_takes_another_expert():\n    \"\"\"A hinted expert that lands on idle polls (its tag with its last part) and that no\n    request uses keeps its tag nonzero: the card never zeroed it. When its slot is a victim,\n    its tag is cleared before the new expert's bytes, so the card cannot take the old tag for\n    the new expert's.\"\"\"\n    lay, mem, srv, G = _hint_setup()\n    _post(mem, lay, 1, [G + 6, G + 7])              # 6, 7 hinted: victims 2 and 1\n    srv.poll()\n    while srv.poll():                               # both land on idle polls\n        pass\n    s6 = srv.lru[0][6]\n    assert _tag(mem, lay, s6) == 7 and s6 in srv.armed\n    _post(mem, lay, 2, [0, 7])                      # the card zeroes 0's and 7's tags\n    srv.poll()\n    for g in (0, 7):\n        mem.write(srv.lru[0][g] + lay.tag, np.zeros(1, np.uint32))\n    log, w = [], mem.write\n\n    def rec(addr, data, w=w):\n        b = np.frombuffer(np.asarray(data).tobytes() if not isinstance(data, bytes) else data,\n                          np.uint8)\n        log.append((\"tag\", int(b[:4].view(np.uint32)[0])) if addr == s6 + lay.tag else\n                   \"slot\" if addr == s6 else None)\n        w(addr, data)\n    mem.write = rec\n    _post(mem, lay, 3, [0, 3])                      # 3 misses: the victim is 6 (never used)\n    srv.poll()\n    assert srv.lru[0][3] == s6\n    assert [x for x in log if x] == [(\"tag\", 0), \"slot\", (\"tag\", 4)]\n    assert s6 in srv.armed and srv.lru[0][7] not in srv.armed\n\n\ndef test_an_all_hit_request_left_at_a_runs_end_is_served_before_the_slots_change():\n    \"\"\"A request whose experts are all present does not wait for the host, so the run that\n    posted it can halt first (a layer-major prefill's last run). end_prefill and begin_prefill\n    serve it before they change the slots, as the card ran it: all hits, no answer, no tags.\n    Served after the restore it could name misses, and the next request would read their\n    answer for its own (the card never zeroes it).\"\"\"\n    for restore in (\"lazy\", \"eager\"):\n        lay, mem, srv = _setup(slots=(2, 2, 2))\n        srv.begin_prefill()\n        for seq, run in enumerate(([0, 1, 1, 2], [1, 1, 2, 2], [8, 9, 9, 10]), 1):\n            _post_n(mem, lay, seq, run)\n            assert srv.poll() == 1\n            mem.write(lay.answer, np.zeros(16, np.uint32))      # (the card, after its experts)\n        _post_n(mem, lay, 4, [0, 0, 0, 0])              # all present; the run halts unseen\n        srv.end_prefill(restore)\n        assert srv.seq == 4 and _served(mem, lay) == 4.0 and srv.misses == 6\n        assert _answer(mem, lay) == [0] * 16\n        _consistent(mem, lay, srv)\n        missing = [g not in srv.lru[0] for g in (0, 3)]\n        _post_n(mem, lay, 5, [0, 3])                    # the next request's answer: its own\n        assert srv.poll() == 1\n        assert _answer(mem, lay)[:2] == [srv.lru[0][g] if m else 0\n                                         for g, m in zip((0, 3), missing)]\n        _consistent(mem, lay, srv)\n    lay, mem, srv = _setup(warm=[0, 1, 2])\n    _post(mem, lay, 1, [0, 1])                          # a step's last request, unseen\n    srv.begin_prefill()\n    assert srv.seq == 1 and srv.misses == 0 and _answer(mem, lay) == [0] * 16\n\n\n@pytest.mark.parametrize(\"fmt\", [\"bytes\", \"split\"])\n@pytest.mark.parametrize(\"chash\", [False, True])\ndef test_board_dram_sends_each_tag_as_its_experts_last_beat(fmt, chash, tmp_path):\n    \"\"\"The link's side of docs/offload.md 10.11, call by call: per request each missing\n    expert's DMA calls (a fifth first for the request's first: two parts), its last part on\n    the other channel and then on its tag's channel, the tag that call's last 64 bytes\n    (nothing of the expert after it); the answer's beat right after the first expert's first\n    part (its two calls); then the directory, then served.\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu.host.board import Board\n    from opentpu.host.fake import FakeTransport\n    from opentpu.host.offload import RUN, BoardDram, PoolFile, to_split\n    slot = 3 * RUN\n    lay = Layout.build(4096, 4, 2, (2, 3), slot)\n    x = np.random.default_rng(1).integers(0, 256, (8, slot), dtype=np.uint8)\n    pool = lambda g: x[g].tobytes()                 # noqa: E731\n    if fmt == \"split\":\n        f = tmp_path / \"pool.bin\"\n        f.write_bytes(b\"\".join(to_split(r).tobytes() for r in x))\n        pool = PoolFile(f, slot, split=True).get\n    b = Board(FakeTransport(ch_bytes=1 << 20, devname=None))\n    b.info()[\"caps\"][\"chash\"] = chash\n    m = BoardDram(SimpleNamespace(board=b), lay)\n    srv = ExpertServer(m, lay, pool)\n    srv.load([0, 1])\n    calls, mw = [], b.t.mem_write\n\n    def call(ch, off, data):\n        calls.append((ch, off, len(data), bytes(np.asarray(data, np.uint8)[-64:])))\n        mw(ch, off, data)\n    b.t.mem_write = call\n\n    def where(a):                                   # a beat's (channel, channel offset)\n        return m._tag_channel(a), a // 128 * 64\n\n    def covers(c, a):                               # call c writes the beat at a\n        ch, off = where(a)\n        return c[0] == ch and c[1] <= off < c[1] + c[2]\n    for seq, ids in enumerate(([2, 3], [0, 3]), 1):\n        b.write(lay.row, np.array(ids + [0] * 14, np.float32))\n        b.write(lay.mbox, np.float32(seq).tobytes())\n        calls.clear()                               # (the card's post: not the server's)\n        miss = [g for g in ids if g not in srv.lru[0]]\n        assert srv.poll() == 1\n        ans = [i for i, c in enumerate(calls) if covers(c, lay.answer)]\n        assert covers(calls[-1], lay.served)\n        last = -1\n        for g in miss:\n            s = srv.lru[0][g]\n            mine = [i for i, c in enumerate(calls)\n                    if any(covers(c, a) for a in range(s, s + lay.tag + 128, 64))]\n            if g == miss[0]:\n                assert mine[0] == 0 and ans == [2]\n            assert mine[0] > last and [i for i in range(mine[0], mine[-1] + 1)\n                                       if i not in ans] == mine\n            *_, other, final = mine\n            ct, ot = where(s + lay.tag)\n            assert calls[final][0] == ct and calls[other][0] == 1 - ct\n            assert calls[final][1] + calls[final][2] == ot + 64       # the tag: its last beat\n            assert calls[final][3][:4] == np.uint32(g + 1).tobytes()\n            parts = 2 if g == miss[0] and m.direct > 2 else 1   # (the first: a fifth, the rest)\n            assert len(mine) == 2 * parts\n            last = mine[-1]\n        rest = [c for i, c in enumerate(calls[:-1]) if i > last and i not in ans]    # the\n        # directory's beats, after them all\n        assert rest and all(any(covers(c, a) for a in range(lay.dir, lay.dir + 64, 64))\n                            for c in rest)\n    assert (m.direct > 2) == (fmt == \"split\" and chash)\n    for g in srv.lru[0]:                            # the bytes as Board.write would have them\n        assert bytes(b.read(srv.lru[0][g], slot)) == x[g].tobytes()\n\n\ndef test_a_multi_row_requests_answer_is_at_each_ids_first_place():\n    \"\"\"A layer-major run's request (moe.moe_ffn_rows: R k ids, repeats included, the count at\n    mbox + 4): each missing expert's slot is at its id's first place in the request, where the\n    card's union loop reads it; the repeats' words stay 0.\"\"\"\n    lay, mem, srv = _setup(slots=(4, 3), warm=[0, 1, 2])\n    mem.write(lay.mbox + 4, np.float32(6).tobytes())\n    _post(mem, lay, 1, [5, 2, 5, 6, 2, 6])          # rows (5, 2), (5, 6), (2, 6)\n    srv.poll()\n    assert srv.history is None and (srv.hits, srv.misses) == (1, 2)\n    assert _answer(mem, lay) == [srv.lru[0][5], 0, 0, srv.lru[0][6]] + [0] * 12\n\n\ndef _ahead_setup(slots=(2, 2, 2), ahead=True):\n    \"\"\"A pooled prefill on layers of `slots` (empty), experts of three 4 KiB parts (the last\n    128 bytes), an idle poll's part 4 KiB.\"\"\"\n    from opentpu.host.offload import RUN\n    slot = 2 * RUN + 128\n    lay = Layout.build(4096, E, K, slots, slot)\n    mem = SimDram(np.zeros(lay.end + 4096, np.uint8))\n    srv = ExpertServer(mem, lay, lambda g: np.full(slot, g + 1, np.uint8).tobytes(),\n                       policy=\"lfu\")\n    srv.load()\n    srv.begin_prefill(ahead=ahead, part=RUN)\n    return lay, mem, srv\n\n\ndef _empty(mem, lay, g):\n    return _entry(mem, lay, g) == (0, 0.0)\n\n\ndef test_ahead_layer_lands_a_layers_experts_on_idle_polls_most_wanted_first():\n    \"\"\"ahead_layer(j, ids): layer j's experts, most wanted first, each given a slot when its\n    first part goes on an idle poll (a free one here), its tag with its last part, then its\n    entry; a landed one joins the pooled order. With no slot left outside the layers the runs\n    may read (j - 1 and j) the queue stops.\"\"\"\n    lay, mem, srv = _ahead_setup()\n    _post_n(mem, lay, 1, [0, 1, 1, 0])              # layer 0's run: two of the six slots\n    assert srv.poll() == 1\n    srv.ahead_layer(1, [9, 8, 10, 11, 12])\n    assert list(srv.queue) == [9, 8, 10, 11, 12] and not srv.pending\n    for i in range(3):                              # 9: three parts, the tag with the last\n        assert srv.poll() == 1\n        assert _empty(mem, lay, 9) == (i < 2) and (9 in srv.pending) == (i < 2)\n    s9 = srv.lru[1][9]\n    assert _landed(mem, lay, srv, 9) and _tag(mem, lay, s9) == 10 and s9 in srv.armed\n    while srv.poll():\n        pass\n    assert all(_landed(mem, lay, srv, g) for g in (9, 8, 10, 11))\n    assert 12 not in srv.lru[1] and _empty(mem, lay, 12) and not srv.queue  # (no slot left)\n    assert (srv.landed, srv.aheads) == (4, 1) and set(srv.lru[0]) == {0, 1}\n    assert list(srv.order)[-4:] == [9, 8, 10, 11]\n\n\ndef test_a_new_ahead_layer_call_replaces_the_queue():\n    \"\"\"Each call replaces what the last one queued: those without a slot leave, the one on its\n    way is dropped (its slot free again; its tag and entry never written).\"\"\"\n    lay, mem, srv = _ahead_setup()\n    srv.ahead_layer(1, [9, 8])\n    assert srv.poll() == 1                          # 9's first part\n    s9 = srv.lru[1][9]\n    srv.ahead_layer(2, [17, 16])\n    assert 9 not in srv.lru[1] and not srv.pending and list(srv.queue) == [17, 16]\n    assert _empty(mem, lay, 9) and _tag(mem, lay, s9) == 0 and srv.dropped == 1\n    while srv.poll():\n        pass\n    assert _landed(mem, lay, srv, 17) and _landed(mem, lay, srv, 16)\n    assert 8 not in srv.lru[1] and _empty(mem, lay, 8)\n\n\ndef test_a_request_takes_a_queued_expert_as_a_miss_and_one_on_its_way_its_rest():\n    \"\"\"A run's request that names a queued expert takes it as an ordinary miss; one on its way\n    is promoted: the rest of its bytes with its tag, its slot in the answer. Either way the\n    queue does not send it again.\"\"\"\n    lay, mem, srv = _ahead_setup()\n    srv.ahead_layer(1, [9, 8])\n    assert srv.poll() == 1                          # 9 on its way, 8 queued\n    _post_n(mem, lay, 1, [9, 8, 8, 9])\n    assert srv.poll() == 1\n    assert (srv.promoted, srv.misses) == (1, 2) and not srv.pending\n    assert _answer(mem, lay)[:2] == [srv.lru[1][9], srv.lru[1][8]]\n    assert _landed(mem, lay, srv, 9) and _landed(mem, lay, srv, 8)\n    assert srv.poll() == 0 and not srv.queue\n\n\ndef test_ahead_victims_spare_the_layers_the_runs_may_read():\n    \"\"\"With no free slot, an ahead expert takes the oldest expert of a layer outside j - 1 and\n    j (the runs until the next call read only those): what the running layer may read never\n    changes under it.\"\"\"\n    lay, mem, srv = _ahead_setup(slots=(1, 1, 1, 1))\n    for seq, g in enumerate((0, 8, 16, 24), 1):     # one run a layer: every slot taken\n        _post_n(mem, lay, seq, [g])\n        assert srv.poll() == 1\n    srv.ahead_layer(1, [9])                         # spared: layers 0 and 1; 16 the oldest\n    while srv.poll():\n        pass\n    assert _landed(mem, lay, srv, 9) and _empty(mem, lay, 16) and 16 not in srv.lru[2]\n    assert all(_landed(mem, lay, srv, g) for g in (0, 8, 24))\n    srv.ahead_layer(0, [1])                         # spared: layers 3 and 0; 8 the oldest left\n    while srv.poll():\n        pass\n    assert _landed(mem, lay, srv, 1) and _empty(mem, lay, 8)\n\n\ndef test_a_hint_for_the_ahead_layer_adds_to_the_end_of_its_queue():\n    \"\"\"A hint for ahead_layer's layer (the card's router on the layer before it) adds its ids\n    to the end of the queue in arrival order: once each, none in a slot or on its way, none\n    queued already; it takes no slot (each when its first part goes) and is served as a hint.\n    A hint for another layer is ignored (pooled), as is any hint with no queue.\"\"\"\n    lay, mem, srv = _ahead_setup()\n    G = lay.E * lay.layers\n    _post_n(mem, lay, 1, [0, 1])                    # layer 0's run\n    assert srv.poll() == 1\n    srv.ahead_layer(1, [9, 8])\n    assert srv.poll() == 1 and 9 in srv.pending     # 9 on its way, 8 queued\n    _post_n(mem, lay, 2, [g + G for g in (9, 10, 8, 10, 11)])\n    assert srv.poll() == 1 and _served(mem, lay) == 2\n    assert list(srv.queue) == [8, 10, 11] and srv.hinted_ahead == 2\n    assert 10 not in srv.lru[1] and 11 not in srv.lru[1]\n    _post_n(mem, lay, 3, [11 + G, 12 + G])\n    assert srv.poll() == 1 and list(srv.queue) == [8, 10, 11, 12] and srv.hinted_ahead == 3\n    _post_n(mem, lay, 4, [17 + G, 16 + G])          # layer 2's: not the queue's layer\n    assert srv.poll() == 1 and _served(mem, lay) == 4\n    assert list(srv.queue) == [8, 10, 11, 12] and 17 not in srv.lru[2] and srv.hints == 3\n    while srv.poll():\n        pass\n    assert all(_landed(mem, lay, srv, g) for g in (9, 8, 10, 11))\n    assert 12 not in srv.lru[1] and not srv.queue   # (no slot left outside layers 0 and 1)\n    srv.end_prefill()\n    lay, mem, srv = _ahead_setup(ahead=False)       # no queue: a hint as before (pooled)\n    srv.ahead_layer(1, [9])\n    _post_n(mem, lay, 1, [9 + G, 10 + G])\n    assert srv.poll() == 1 and not srv.queue and srv.hinted_ahead == 0 and not srv.lru[1]\n\n\ndef test_ahead_layer_serves_the_last_request_first_and_end_prefill_drops_the_queue():\n    \"\"\"ahead_layer settles first (a run's all-hit request the host has not seen). end_prefill\n    drops the queue and the expert on its way and gives the server its part back; a prefill\n    begun with ahead=False ignores the calls.\"\"\"\n    from opentpu.host.offload import RUN\n    lay, mem, srv = _ahead_setup()\n    part = srv._part\n    _post_n(mem, lay, 1, [0, 1])\n    assert srv.poll() == 1\n    _post_n(mem, lay, 2, [1, 0])                    # all hits: the run halts unseen\n    srv.ahead_layer(1, [9, 8])\n    assert srv.seq == 2 and srv.hits == 2\n    assert srv.poll() == 1 and 9 in srv.pending\n    srv.end_prefill()\n    assert not srv.pending and not srv.queue and 9 not in srv.lru[1] and _empty(mem, lay, 9)\n    assert srv.part == part != RUN and not srv.pooled\n    lay, mem, srv = _ahead_setup(ahead=False)\n    srv.ahead_layer(1, [9, 8])\n    assert not srv.queue and srv.poll() == 0\n\n\ndef _em_setup(slots=(2, 2, 2, 2), scratch=0, warm=()):\n    \"\"\"An expert-major prefill (docs/offload.md 13.11) on layers of `slots`, experts of three\n    4 KiB parts (the last 128 bytes), an idle poll's part 4 KiB; begin_prefill's scratch.\"\"\"\n    from opentpu.host.offload import RUN\n    slot = 2 * RUN + 128\n    lay = Layout.build(4096, E, K, slots, slot, lines=2)\n    mem = SimDram(np.zeros(lay.end + 4096, np.uint8))\n    srv = ExpertServer(mem, lay, lambda g: np.full(slot, g + 1, np.uint8).tobytes(),\n                       policy=\"lfu\")\n    srv.load(list(warm))\n    base = srv.begin_prefill(ahead=True, part=RUN, expert_major=True, scratch=scratch)\n    return lay, mem, srv, base\n\n\ndef test_a_need_line_queues_its_experts_and_idle_polls_land_them_ahead_of_the_queue():\n    \"\"\"A need line (ids from Layout.need_off = 2 x layers x E up): served at once, no answer,\n    no use counted, no slot taken; each id in no slot joins `needs` once, in arrival order.\n    Idle polls send them before ahead_layer's queue: each takes a slot when its first part\n    goes, its tag with its last part, then its entry. Outside an expert-major prefill a need\n    line is an error.\"\"\"\n    lay, mem, srv, _ = _em_setup()\n    N = lay.need_off\n    assert N == 2 * lay.E * lay.layers\n    srv.ahead_layer(1, [9, 8])\n    _post_n(mem, lay, 1, [g + N for g in (1, 0, 1, 3)])\n    assert srv.poll() == 1 and _served(mem, lay) == 1 and srv.last == (\"n\", 0)\n    assert list(srv.needs) == [1, 0, 3] and not srv.lru[0] and not srv.pending\n    assert _answer(mem, lay) == [0] * 16 and srv.use[0] == {} and srv.t[0] == 0\n    assert (srv.need_lines, srv.needs_queued, srv.misses, srv.hits) == (1, 3, 0, 0)\n    for i in range(9):                              # 1, 0, 3: three parts each\n        assert srv.poll() == 1\n    assert all(_landed(mem, lay, srv, g) for g in (1, 0, 3)) and not srv.needs\n    assert _tag(mem, lay, srv.lru[0][1]) == 2 and not srv.lru[1] and srv.needs_landed == 3\n    while srv.poll():                               # then the queue's\n        pass\n    assert _landed(mem, lay, srv, 9) and _landed(mem, lay, srv, 8)\n    assert list(srv.order)[-5:] == [1, 0, 3, 9, 8]\n    _post_n(mem, lay, 2, [g + N for g in (1, 2)])   # 1 in a slot: a hit\n    assert srv.poll() == 1 and list(srv.needs) == [2] and srv.need_hits == 1\n    lay, mem, srv = _ahead_setup()                  # layer-major, not expert-major\n    _post_n(mem, lay, 1, [lay.need_off])\n    with pytest.raises(RuntimeError, match=\"need line outside\"):\n        srv.poll()\n\n\ndef test_a_need_takes_over_an_ahead_expert_and_no_ahead_layer_call_drops_it():\n    \"\"\"A need naming an expert ahead_layer queued moves it to `needs`; one ahead_layer has on\n    its way becomes a need's, so the next call (which drops its own on their way) keeps it.\n    A hint for the queue's layer does not queue a need again.\"\"\"\n    lay, mem, srv, _ = _em_setup()\n    N, G = lay.need_off, lay.E * lay.layers\n    srv.ahead_layer(1, [9, 8, 10])\n    assert srv.poll() == 1 and 9 in srv.pending     # 9's first part\n    _post_n(mem, lay, 1, [9 + N, 8 + N])\n    assert srv.poll() == 1\n    assert list(srv.needs) == [8] and list(srv.queue) == [10] and srv.need_hits == 1\n    _post_n(mem, lay, 2, [8 + G, 11 + G])           # the queue's layer: 11 only\n    assert srv.poll() == 1 and list(srv.queue) == [10, 11]\n    srv.ahead_layer(2, [17])\n    assert 9 in srv.pending and srv.dropped == 0 and list(srv.queue) == [17]\n    while srv.poll():\n        pass\n    assert all(_landed(mem, lay, srv, g) for g in (9, 8, 17)) and srv.needs_landed == 2\n    assert 10 not in srv.lru[1] and 11 not in srv.lru[1]\n\n\ndef test_expert_major_victims_spare_the_running_layer_and_its_neighbours():\n    \"\"\"Expert-major, every slot taken during layer j's runs (a need's, a request's miss, an\n    ahead expert's) has its victim outside layers j - 1, j and j + 1, the running layer the\n    last need line's or request's. A need with no such victim is an error, not dropped.\"\"\"\n    lay, mem, srv, _ = _em_setup(slots=(1, 1, 1, 1, 1))\n    N = lay.need_off\n    for seq, g in enumerate((0, 8, 16, 24, 32), 1):     # one need a layer: every slot taken\n        _post_n(mem, lay, seq, [g + N])\n        assert srv.poll() == 1\n        while srv.poll():\n            pass\n    _post_n(mem, lay, 6, [1 + N])                   # layer 0: spared 4, 0, 1; 16 the oldest\n    srv.poll()\n    while srv.poll():\n        pass\n    assert _landed(mem, lay, srv, 1) and _empty(mem, lay, 16) and 16 not in srv.lru[2]\n    _post_n(mem, lay, 7, [9 + N])                   # layer 1: spared 0, 1, 2; 24 the oldest\n    srv.poll()\n    while srv.poll():\n        pass\n    assert _landed(mem, lay, srv, 9) and _empty(mem, lay, 24)\n    _post_n(mem, lay, 8, [17])                      # a request of layer 2: spared 1, 2, 3\n    assert srv.poll() == 1 and srv.misses == 1\n    assert _landed(mem, lay, srv, 17) and _empty(mem, lay, 0) and 32 in srv.lru[4]\n    srv.ahead_layer(3, [25])                        # ahead: also outside 2 and 3; 32 is layer 4\n    while srv.poll():\n        pass\n    assert _landed(mem, lay, srv, 25) and _empty(mem, lay, 32)\n    lay, mem, srv, _ = _em_setup(slots=(1, 1, 1))\n    N = lay.need_off\n    for seq, g in enumerate((0, 8, 16), 1):\n        _post_n(mem, lay, seq, [g + N])\n        srv.poll()\n        while srv.poll():\n            pass\n    _post_n(mem, lay, 4, [9 + N])                   # every layer spared\n    with pytest.raises(RuntimeError, match=\"need 9\"):\n        while srv.poll():\n            pass\n\n\ndef test_the_next_layers_need_line_disarms_the_tags_the_expert_run_zeroed():\n    \"\"\"The first need line of layer j + 1 means layer j's expert run is done, and it zeroed\n    the tags of the experts its need lines named: their slots are no longer armed, so a slot\n    reused later does not cost a write of a zero tag first.\"\"\"\n    lay, mem, srv, _ = _em_setup()\n    N = lay.need_off\n    _post_n(mem, lay, 1, [0 + N, 1 + N])\n    srv.poll()\n    while srv.poll():\n        pass\n    s0, s1 = srv.lru[0][0], srv.lru[0][1]\n    assert {s0, s1} <= srv.armed\n    for s in (s0, s1):                              # the expert run zeroes them\n        mem.write(s + lay.tag, np.zeros(1, np.uint32))\n    _post_n(mem, lay, 2, [8 + N])\n    srv.poll()\n    assert s0 not in srv.armed and s1 not in srv.armed\n\n\ndef _em_pitch():\n    \"\"\"_em_setup's slot pitch (two 4 KiB blocks and a tag chunk, in whole blocks).\"\"\"\n    from opentpu.host.offload import RUN\n    return Layout.build(4096, E, K, (1,), 2 * RUN + 128, lines=2).pitch\n\n\ndef test_end_prefill_drains_the_needs_and_hands_the_scratch_back_with_zeroed_tags():\n    \"\"\"begin_prefill(scratch=n): the slot region's first ceil(n / pitch) slots (Layout.scratch,\n    as moe.em_slots: here layer 0's two and layer 1's first) leave the free lists, their\n    experts evicted with their entries cleared on the card before the base is returned, and no\n    need or miss is given one. end_prefill sends every need still queued or on its way whole\n    (drained), zeroes the scratch's tag beats (the card's scratch data there would read as a\n    landed expert's tag) and gives each layer its slots back.\"\"\"\n    lay, mem, srv, base = _em_setup(scratch=2 * _em_pitch() + 1, warm=(0, 1))\n    p, a0, a1 = lay.pitch, lay.slots[0][0], lay.slots[1][0]\n    scratch = [a0, a0 + p, a1]\n    assert base == a0 == lay.scratch(2 * p + 1)[0] and srv.scratch_slots == scratch\n    assert _empty(mem, lay, 0) and _empty(mem, lay, 1) and not srv.lru[0]\n    assert not srv.free[0] and srv.free[1] == [a1 + p] and 0 not in srv.order\n    mem.write(base, np.full(3 * p, 0xAB, np.uint8))     # the card's scratch\n    N = lay.need_off\n    for seq, ids in enumerate(([8, 9], [16, 17], [24, 25, 26]), 1):\n        _post_n(mem, lay, seq, [g + N for g in ids])\n        assert srv.poll() == 1\n    assert len(srv.needs) == 7 and srv.poll() == 1  # 8's first part only\n    while len(srv.needs) > 1:                       # (up to 25: a victim of layer 1)\n        srv.poll()\n    assert not {a for lru in srv.lru for a in lru.values()} & set(scratch)\n    srv.end_prefill()\n    assert not srv.needs and not srv.pending and 0 < srv.drained < 7 and srv.needs_landed == 7\n    assert all(_tag(mem, lay, a) == 0 for a in scratch)\n    assert not srv.scratch_slots and not srv.expert_major and not srv.pooled\n    _consistent(mem, lay, srv)\n    back = {a for lru in srv.lru for a in lru.values()} | {a for fr in srv.free for a in fr}\n    assert set(scratch) <= back and back == set(lay.all_slots())\n\n\ndef test_need_report_names_the_running_layers_experts_without_an_entry():\n    \"\"\"For an expert run's WAITW timeout: the running layer's needed experts whose entries are\n    not present, and where each stands.\"\"\"\n    lay, mem, srv, _ = _em_setup()\n    N = lay.need_off\n    assert \"no need line\" in srv.need_report()\n    _post_n(mem, lay, 1, [1 + N, 0 + N, 3 + N])\n    srv.poll()\n    srv.poll()                                      # 1's first part\n    r = srv.need_report()\n    assert r.startswith(\"layer 0: 3 experts needed, 3 without an entry\")\n    assert \"1 (expert 1): on its way, 4096 of\" in r and \"0 (expert 0): queued\" in r\n    while srv.poll():\n        pass\n    assert srv.need_report() == \"layer 0: 3 experts needed, 0 without an entry\"\n\n\ndef test_the_isa_hosts_hook_polls_until_the_expert_runs_wait_holds():\n    \"\"\"qwen3._isa_host, the ISA simulator's WAITW hook (called once when every slice waits; a\n    wait still not holding after it is the timeout): it polls until a waiting slice's WAITW\n    holds, as the host keeps polling while a card waits. An expert run waiting on a need's\n    entry takes one idle poll a part. With nothing to do it stops after one poll.\"\"\"\n    from types import SimpleNamespace\n    from opentpu.llm.qwen3 import _isa_host\n    lay, mem, srv, _ = _em_setup()\n    N = lay.need_off\n    _post_n(mem, lay, 1, [3 + N, 1 + N])\n\n    class Pass:                                     # the expert run, waiting on 1's entry\n        polling = \"WAITW\"\n\n        def holds(self, ins):\n            return _entry(mem, lay, 1)[0] != 0\n    m = SimpleNamespace(slices=[Pass()])\n    _isa_host(srv.poll)(m)\n    assert _landed(mem, lay, srv, 3) and _landed(mem, lay, srv, 1)    # (3 first: in order)\n    assert not srv.needs and not srv.pending and srv.needs_landed == 2\n    calls = []\n    _isa_host(lambda: calls.append(1) or 0)(m)\n    assert calls == [1]\n\n\n@pytest.mark.parametrize(\"policy\", [\"lfu\", \"lru\"])\ndef test_place_takes_free_slots_then_the_least_wanted_across_layers(policy):\n    \"\"\"place (docs/minicpmv.md 4.2: a host run's pieces, the pool's entries past the experts):\n    free slots first, then the experts of least decayed use (\"lru\": the least recent of each\n    layer alike), each layer keeping k slots; the victims' entries cleared, the entries'\n    bytes in their slots, no tag; an entry already placed keeps its slot; more than the slots\n    past k is refused with nothing changed; release gives the slots back to their layers,\n    free, and the next misses take them.\"\"\"\n    lay = Layout.build(4096, E, K, (4, 4), SLOT)\n    mem = SimDram(np.zeros(lay.end + 4096, np.uint8))\n    srv = ExpertServer(mem, lay, _pool, policy=policy)\n    srv.load([0, 1, 2, E, E + 1, E + 2])            # 3 of 4 slots a layer, one free\n    for seq, ids in enumerate(([0, 1], [E, E + 1], [1, 0], [E + 1, E]), 1):\n        _post(mem, lay, seq, ids)                   # all hits: 2 and E + 2 the least wanted\n        srv.poll()\n    G = 2 * E\n    with pytest.raises(RuntimeError):               # 2 a layer past k: 4 at most\n        srv.place([G, G + 1, G + 2, G + 3, G + 4])\n    assert srv.placed == {} and all(len(fr) == 1 for fr in srv.free)\n    at = srv.place([G + 3, G, G + 1, G + 2], sizes={G + i: 100 for i in range(4)})\n    assert len(set(at)) == 4 and all(mem.read(a, SLOT) == _pool(g) for g, a in\n                                      zip([G + 3, G, G + 1, G + 2], at))\n    for g in (2, E + 2):\n        assert _entry(mem, lay, g) == (0, 0.0)\n    for g in (0, 1, E, E + 1):\n        assert _entry(mem, lay, g)[1] == 1.0\n    assert all(np.frombuffer(mem.read(a + lay.tag, 4), np.uint32)[0] == 0 for a in at)\n    assert srv.place_victims == 2 and srv.place([G + 1]) == [at[2]]\n    with pytest.raises(RuntimeError):\n        srv.place([G + 4])\n    srv.release()\n    assert srv.placed == {} and [len(fr) for fr in srv.free] == [2, 2]\n    _post(mem, lay, 5, [2, 3])                      # misses into the freed slots\n    srv.poll()\n    assert {_entry(mem, lay, g)[0] for g in (2, 3)} <= set(at)\n    with pytest.raises(ValueError):\n        srv.place([E - 1])                          # an expert is no placed entry\n\n\ndef test_rewarm_reads_again_what_left_the_page_cache(tmp_path, monkeypatch):\n    \"\"\"moe.rewarm (the Engine's, once its image is built and the build's memory freed): the\n    open's warm stopped if it still runs, then the packed experts with bytes out of the page\n    cache (PoolFile.absent: mincore) read on a new thread in the order given (absent's: file\n    order). The open's thread is kept when it had ended with nothing out; one stopped with\n    nothing out gives an empty read (its record: done); where the host cannot tell (no\n    mincore) the open's read is left to run. On Linux, experts dropped from the page cache\n    come back.\"\"\"\n    import os\n    import sys\n    import threading\n\n    from opentpu.host import offload as OF\n    from opentpu.llm.moe import rewarm\n    slot, n = 4096 * 2, 8\n    f = tmp_path / \"pool.bin\"\n    f.write_bytes(np.random.default_rng(0).integers(0, 256, n * slot, dtype=np.uint8).tobytes())\n    pf = OF.PoolFile(f, slot, split=False)\n    pf.ids = np.arange(n)\n    if pf.resident(pf.ids) is None:\n        pytest.skip(\"no mincore here\")\n    assert list(pf.absent(pf.ids)) == []\n    os.truncate(f, (n + 2) * slot)                      # experts 8, 9: a hole, not cached\n    assert list(pf.absent(range(n + 2))) == [8, 9] and list(pf.absent([9, 3, 8])) == [8, 9]\n    t = pf.warm(pf.ids)\n    t.join(60)\n    assert rewarm(pf) is t and pf.warm_t is t           # ended, nothing out: kept\n    held, real = [threading.Semaphore(0)], OF.preadv\n\n    def read(fd, bufs, off):                            # a slow disk: reads held until released\n        assert held[0].acquire(timeout=60)\n        real(fd, bufs, off)\n    monkeypatch.setattr(OF, \"preadv\", read)\n    release = lambda k: [held[0].release() for _ in range(k)]   # noqa: E731\n\n    t = pf.warm(pf.ids)                                 # still running: stopped, what is out\n    monkeypatch.setattr(pf, \"absent\", lambda ids: np.array([2, 5]))     # read again\n    threading.Timer(0.2, release, (3,)).start()         # (the read it waits in, then 2)\n    t2 = rewarm(pf)\n    assert t.stop.is_set() and not t.is_alive() and t.bytes == slot\n    assert t2 is pf.warm_t and t2 is not t and t2.total == 2 * slot\n    t2.join(60)\n    assert t2.bytes == 2 * slot and OF.warm_report(t2)[\"error\"] is None\n\n    held[0] = threading.Semaphore(0)                    # stopped with nothing out: an empty read\n    t = pf.warm(pf.ids)\n    monkeypatch.setattr(pf, \"absent\", lambda ids: np.zeros(0, np.int64))\n    threading.Timer(0.2, release, (1,)).start()\n    t3 = rewarm(pf)\n    assert t.stop.is_set() and t3 is not t and t3.total == 0\n    t3.join(60)\n    r = OF.warm_report(t3)\n    assert r[\"end\"] is not None and r[\"error\"] is None and not r[\"stopped\"]\n\n    held[0] = threading.Semaphore(0)                    # no mincore: the open's read left to run\n    t = pf.warm(pf.ids)\n    monkeypatch.setattr(pf, \"_pages\", lambda: None)\n    assert rewarm(pf) is t and not t.stop.is_set() and t.is_alive()\n    release(n)\n    t.join(60)\n    assert t.bytes == n * slot\n    monkeypatch.undo()\n    if sys.platform != \"linux\":\n        return\n    pf = OF.PoolFile(f, slot, split=False)\n    pf.ids = np.arange(n)\n    fd = os.open(f, os.O_RDONLY)\n    os.fsync(fd)\n    os.posix_fadvise(fd, 0, 0, os.POSIX_FADV_DONTNEED)\n    os.close(fd)\n    if pf.resident(pf.ids) < n * slot:                  # (tmpfs keeps its pages)\n        pf.warm_t = None\n        rewarm(pf).join(60)\n        assert pf.resident(pf.ids) == n * slot and list(pf.absent(pf.ids)) == []\n", "tests/test_omarchy_test.py": "\"\"\"tools/omarchy_test.sh without omarchy: ssh is a stub that runs the remote command here, with\nHOME a scratch directory (~/otpu-test/<name> under it), and flock one that always takes the\nslot. The script ships the worktree it is in, whatever the current directory, says which tree\nand commit, and deletes there what the worktree no longer tracks.\"\"\"\nimport os\nimport shutil\nimport subprocess\nimport sys\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parent.parent\n\n\ndef _git(repo, *args):\n    return subprocess.run([\"git\", \"-C\", str(repo), \"-c\", \"user.name=t\", \"-c\", \"user.email=t@t\",\n                           \"-c\", \"commit.gpgsign=false\", *args], check=True, capture_output=True,\n                          text=True).stdout.strip()\n\n\n@pytest.mark.skipif(sys.platform != \"darwin\", reason=\"the script ships from the Mac (bsdtar)\")\ndef test_ships_its_own_tree_and_drops_what_it_no_longer_tracks(tmp_path):\n    wt = tmp_path / \"wt\"\n    (wt / \"tools\").mkdir(parents=True)\n    shutil.copy(ROOT / \"tools/omarchy_test.sh\", wt / \"tools/omarchy_test.sh\")\n    (wt / \"pkg\").mkdir()\n    for f, text in [(\"a.py\", \"A = 1\\n\"), (\"pkg/__init__.py\", \"\"), (\"pkg/mod.py\", \"M = 1\\n\"),\n                    (\"tests/test_gone.py\", \"def test_x(): pass\\n\")]:\n        (wt / f).parent.mkdir(parents=True, exist_ok=True)\n        (wt / f).write_text(text)\n    _git(wt, \"init\", \"-q\")\n    _git(wt, \"add\", \"-A\")\n    _git(wt, \"commit\", \"-q\", \"-m\", \"one\")\n    bin_, home, elsewhere = tmp_path / \"bin\", tmp_path / \"home\", tmp_path / \"elsewhere\"\n    for d in (bin_, home, elsewhere):\n        d.mkdir()\n    (bin_ / \"ssh\").write_text('#!/bin/bash\\nshift\\nexec bash -c \"$*\"\\n')     # ssh HOST CMD\n    (bin_ / \"flock\").write_text(\"#!/bin/sh\\nexit 0\\n\")\n    for f in (\"ssh\", \"flock\"):\n        (bin_ / f).chmod(0o755)\n    env = dict(os.environ, PATH=f\"{bin_}:{os.environ['PATH']}\", HOME=str(home),\n               OTPU_REMOTE_NAME=\"t\")\n\n    def run():                          # from another directory: the script's tree counts\n        r = subprocess.run([\"bash\", str(wt / \"tools/omarchy_test.sh\"), \"--exec\", \"true\"],\n                           cwd=elsewhere, env=env, capture_output=True, text=True, timeout=120)\n        assert r.returncode == 0, r.stderr\n        return r.stderr\n    err = run()\n    there = home / \"otpu-test/t\"\n    assert f\"omarchy_test: {wt.resolve()} at {_git(wt, 'rev-parse', '--short', 'HEAD')} ->\" in err\n    assert (there / \"pkg/mod.py\").exists() and (there / \"tests/test_gone.py\").exists()\n    (there / \"pkg/__pycache__\").mkdir()\n    (there / \"pkg/__pycache__/mod.cpython-312.pyc\").write_text(\"\")\n    (there / \"build\").mkdir()                           # the Verilator cache stays\n    (there / \"build/Vtb_top\").write_text(\"\")\n    # a package and a test removed, a file edited and not committed\n    _git(wt, \"rm\", \"-q\", \"-r\", \"pkg\", \"tests/test_gone.py\")\n    _git(wt, \"commit\", \"-q\", \"-m\", \"two\")\n    (wt / \"a.py\").write_text(\"A = 2\\n\")\n    err = run()\n    assert \"+ 1 uncommitted\" in err\n    assert not (there / \"pkg\").exists() and not (there / \"tests\").exists()\n    assert (there / \"a.py\").read_text() == \"A = 2\\n\" and (there / \"build/Vtb_top\").exists()\n    assert (there / \"tools/omarchy_test.sh\").exists() and (there / \"models\").is_symlink()\n", "tests/test_pair.py": "\"\"\"Column reuse (docs/isa.md, \"Column reuse\"): a 4-bit MM of M <= MCOLS/2 rows with PAIR takes\ntwo K-blocks per cycle, the even ones from ACT rows 0..M-1 and the odd ones from ACT rows\nM..2M-1, which QACT DUP fills with the same rows. The sums are one exact integer per output\neither way (tests/test_mx.py: PAIR changes no bit); here the ISA simulator's row choice, the\nepilogues on a PAIR result, QACT DUP and the field checks.\"\"\"\nimport dataclasses\n\nimport numpy as np\nimport pytest\n\nfrom opentpu import Config, fp32 as F, isa as I, quant as Q\nfrom opentpu.isasim import Machine\n\nWA, SA, XA, OUT, AS = 16384, 32768, 1 << 17, 8192, 1536\n\n\ndef _setup(rng, fmt, KB, N, D, x):\n    \"\"\"x's rows at XA, W [N, KB D] in `fmt` at WA (rows rs apart) and its scale rows at SA (srs\n    apart): (rs, srs, dram).\"\"\"\n    W = (rng.standard_normal((N, KB * D)) * 0.1).astype(np.float32)\n    wrows, srows = Q.quantize_mxu(W, fmt, D)\n    assert WA + wrows.size <= SA and SA + srows.size <= XA\n    dram = np.zeros(1 << 18, np.uint8)\n    dram[XA:XA + x.nbytes] = x.view(np.uint8).reshape(-1)\n    dram[WA:WA + wrows.size] = wrows.reshape(-1)\n    dram[SA:SA + srows.size] = srows.reshape(-1)\n    return wrows.shape[1], srows.shape[1], dram\n\n\ndef _run(cfg, dram, prog):\n    cfg = dataclasses.replace(cfg, DRAM_BYTES=max(cfg.DRAM_BYTES, dram.size))\n    return Machine(cfg, [prog + [I.halt()]], [dram.copy()]).run().slices[0]\n\n\n@pytest.mark.parametrize(\"fmt\", [\"int4\", \"fp4\", \"nvfp4\"])\n@pytest.mark.parametrize(\"MCOLS,M\", [(2, 1), (4, 1), (4, 2)])\n@pytest.mark.parametrize(\"KB\", [1, 2, 3, 5, 8])\ndef test_pair_takes_the_odd_blocks_from_row_j_plus_m(fmt, MCOLS, M, KB):\n    \"\"\"ACT rows j + M = -(row j): the same Sa and offsets, other data. PAIR's output j is then\n    the MM without PAIR of row j with its odd blocks negated, bit for bit (every quantized value\n    and scale of -x is that of x negated).\"\"\"\n    D = 128 if fmt == \"nvfp4\" else 32\n    cfg = Config(S=1, D=D, MCOLS=MCOLS, PAIR=True)\n    rng = np.random.default_rng(100 * KB + 10 * MCOLS + M + 7 * len(fmt))\n    N = 7\n    x = rng.standard_normal((M, KB * D)).astype(np.float32)\n    x[:, ::D // 4] *= 2.0 ** -9                    # some sub-blocks with large offsets\n    neg = np.where((np.arange(KB * D) // D) % 2 == 1, -1.0, 1.0).astype(np.float32)\n    rows = np.concatenate([x, -x, x * neg])        # [x; -x] for PAIR, x with odd blocks negated\n    rs, srs, dram = _setup(rng, fmt, KB, N, D, rows)\n    wf = Q.mxu_wf(fmt)\n    for unit in (False, True):\n        s = _run(cfg, dram, [I.ld(XA, 0, rows.size), I.qact(0, 2 * M, 0, KB, KB * D),\n                             I.mm(WA, SA, OUT, N, KB, rs, N, M, 0, srs, unit=unit, wf=wf,\n                                  pair=True)])\n        got = s.tget(OUT + np.arange(M * N)).reshape(M, N)\n        s = _run(cfg, dram, [I.ld(XA, 0, rows.size), I.qact(2 * M * KB * D, M, 0, KB, KB * D),\n                             I.mm(WA, SA, OUT, N, KB, rs, N, M, 0, srs, unit=unit, wf=wf)])\n        want = s.tget(OUT + np.arange(M * N)).reshape(M, N)\n        assert np.array_equal(got.view(np.uint32), want.view(np.uint32))\n\n\n@pytest.mark.parametrize(\"fmt\", [\"int4\", \"fp4\", \"nvfp4\"])\ndef test_pair_epilogues(fmt):\n    \"\"\"ACC, RMAX and ASCALE act on the pair result as on any MM result.\"\"\"\n    D = 128 if fmt == \"nvfp4\" else 32\n    cfg = Config(S=1, D=D, MCOLS=2, PAIR=True)\n    rng = np.random.default_rng(5)\n    KB, N, M = 5, 9, 1\n    x = rng.standard_normal((1, KB * D)).astype(np.float32)\n    rs, srs, dram = _setup(rng, fmt, KB, N, D, x)\n    base = [I.ld(XA, 0, x.size), I.qact(0, 1, 0, KB, KB * D, dup=True),\n            I.vop(I.V_FILL, OUT, 0, 0, 1, N + 1, N + 1, 0, 0, I.B_SCALAR, 0.75),\n            I.vop(I.V_FILL, AS, 0, 0, 1, 1, 1, 0, 0, I.B_SCALAR, -1.5)]\n    mm = lambda **k: I.mm(WA, SA, OUT, N, KB, rs, N, M, 0, srs, wf=Q.mxu_wf(fmt), pair=True,\n                          **k)\n    y = _run(cfg, dram, base + [mm()]).tget(OUT + np.arange(N))\n    yu = _run(cfg, dram, base + [mm(unit=True)]).tget(OUT + np.arange(N))\n    s = _run(cfg, dram, base + [mm(acc=True, rmax=True)])\n    want = F.add(np.float32(0.75), y)\n    assert np.array_equal(s.tget(OUT + np.arange(N)), want)\n    assert s.tget(OUT + N) == F.chain_max(want[None])[0]\n    s = _run(cfg, dram, base + [mm(unit=True, acc=True, ascale=AS)])\n    assert np.array_equal(s.tget(OUT + np.arange(N)),\n                          F.add(F.mul(np.float32(0.75), np.float32(-1.5)), yu))\n\n\n@pytest.mark.parametrize(\"row\", [False, True])\ndef test_qact_dup_writes_both_rows(row):\n    cfg = Config(S=1, D=32, MCOLS=4, PAIR=True)\n    x = np.random.default_rng(1).standard_normal((2, 96)).astype(np.float32)\n    dram = np.zeros(1 << 16, np.uint8)\n    dram[:x.nbytes] = x.view(np.uint8).reshape(-1)\n    rsc = 512\n    prog = [I.ld(0, 0, x.size), I.vop(I.V_FILL, rsc, 0, 0, 1, 2, 2, 0, 0, I.B_SCALAR, 3.0),\n            I.qact(0, 2, 5, 3, 96, row=row, rscale=rsc, dup=True)]\n    s = _run(cfg, dram, prog)\n    one = _run(cfg, dram, prog[:2] + [I.qact(0, 2, 5, 3, 96, row=row, rscale=rsc)])\n    assert np.array_equal(s.act[:2], one.act[:2]) and np.array_equal(s.act[2:], one.act[:2])\n    assert np.array_equal(s.ascale[2:], one.ascale[:2])\n    with pytest.raises(Exception, match=\"bounds\"):\n        _run(Config(S=1, D=32, MCOLS=2), dram, prog[:2] + [I.qact(0, 2, 5, 3, 96, dup=True)])\n\n\n@pytest.mark.parametrize(\"wf,ssa,srs,align\", [(I.W4F, SA + 4, 16, 8), (I.W4I, SA, 12, 8),\n                                              (I.WNV, SA + 8, 32, 16), (I.WNV, SA, 24, 16)])\ndef test_pair_scales_are_aligned(wf, ssa, srs, align):\n    \"\"\"A chunk's two blocks' scale words are read together: ssa and srs multiples of 8 (NVFP4:\n    16).\"\"\"\n    D = 128 if wf == I.WNV else 32\n    dram = np.zeros(1 << 16, np.uint8)\n    with pytest.raises(Exception, match=f\"multiples of {align}\"):\n        _run(Config(S=1, D=D, MCOLS=2), dram,\n             [I.mm(WA, ssa, OUT, 1, 3, 2 * D, 1, 1, 0, srs, wf=wf, pair=True)])\n    _run(Config(S=1, D=D, MCOLS=2), dram,             # UNIT reads no scales\n         [I.mm(WA, ssa, OUT, 1, 3, 2 * D, 1, 1, 0, srs, wf=wf, pair=True, unit=True)])\n\n\ndef test_pair_needs_4bit_and_room():\n    with pytest.raises(ValueError, match=\"PAIR needs 4-bit\"):\n        I.mm(0, 0, 0, 1, 1, 32, 1, 1, 0, 4, pair=True)\n    with pytest.raises(ValueError, match=\"even k0\"):\n        I.mm(0, 0, 0, 1, 2, 32, 1, 1, 0, 16, wf=I.W4F, pair=True, k0=1)\n    dram = np.zeros(1 << 16, np.uint8)\n    with pytest.raises(Exception, match=\"PAIR needs 2\\\\*M <= MCOLS|bounds\"):\n        _run(Config(S=1, D=32, MCOLS=2), dram,\n             [I.mm(WA, SA, OUT, 1, 2, 32, 1, 2, 0, 16, wf=I.W4F, pair=True)])\n", "tests/test_perf.py": "\"\"\"Performance on the RTL: lower bounds on how close MLP and attention decode get to the DRAM roofline.\n\nThe roofline of a program is the number of transfers it needs on the slice's DRAM burst port\n(one D-byte chunk per cycle; the MXU consumes chunks at the same rate) -- see profile.py. These\ntests pin the achieved fraction so that an RTL or compiler change cannot silently lose it.\n\nThe simulated DRAM delivers one D-byte chunk per cycle, the MXU's peak rate; the FPGA's DDR3\ndelivers well under half of that, so on the board the (deeply pipelined) vector and quantizer\nwork has correspondingly more room behind the weight stream.\n\"\"\"\nimport numpy as np\nimport pytest\n\nfrom opentpu.isasim import design_config\nfrom opentpu.kernels import attention_decode, attention_layer, mlp\nfrom opentpu.profile import profile\n\nfrom test_kernels import attn_args, layer_args, mlp_args\n\n\ndef _eff(p):\n    return p.roofline()[\"efficiency\"]\n\n\ndef test_mlp_decode_at_roofline(have_verilator):\n    a, _ = mlp_args(np.random.default_rng(0), M=1, H=1024, Fd=2048)\n    p = profile(mlp, design_config(), **a)\n    # 0.94, was 0.945 (0.95 before that): the timing registers added for the board (VPU/quantizer\n    # inputs and writes, MXU combine operands, then the 120 MHz image's WBUF and the MXU row\n    # register before the result FIFO) add a fixed few cycles per instruction -- 94.4% on this\n    # small kernel; a Qwen3 token changes by +0.02%\n    assert _eff(p) > 0.94, p.summary()\n\n\ndef test_mlp_small_batch_near_roofline(have_verilator):\n    a, _ = mlp_args(np.random.default_rng(0), M=4, H=1024, Fd=2048)\n    p = profile(mlp, design_config(), **a)\n    # 0.915, was 0.92: the MXU tree is two stages longer for 4-bit weights (a register after the\n    # weight decode, the sub-block multipliers), +64 cycles here (92.1% -> 91.9%); a two-layer\n    # Qwen3 token does not change (-20 cycles of 1.9M). 0.914, was 0.915: the pair sums moved\n    # into the DSP cascade, one more stage (+32 cycles here, 91.6% -> 91.45%); Qwen3.5 and LFM2\n    # decode at MCOLS=4 are unchanged (-865 / -310 cycles)\n    assert _eff(p) > 0.914, p.summary()\n\n\n@pytest.mark.parametrize(\"Hq,Hkv,T,E\", [\n    (16, 4, 1024, \"full\"), (6, 1, 2048, \"full\"),\n    pytest.param(6, 1, 2048, \"half\", marks=pytest.mark.xfail(strict=True, reason=(\n        \"E = MCOLS / 2 lanes drain the 6 rows of a q.K^T K row at d 128 in 2 cycles against the \"\n        \"array's 1 and the KV cache's ~1.1: drain-bound (docs/mx_mxu.md 9, attention decode at \"\n        \"MCOLS 8)\")))])\ndef test_attention_decode_at_roofline(have_verilator, Hq, Hkv, T, E):\n    a, _ = attn_args(np.random.default_rng(1), Hq=Hq, Hkv=Hkv, d=128, T=T, cap=T, block=128)\n    cfg = design_config()\n    # \"full\": the MXU's epilogue at full rate, E = MCOLS lanes, as the card builds it. q.K^T at d\n    # 128 (KB 1) gives G = Hq / Hkv outputs a K row and E lanes drain them in ceil(G / E) cycles,\n    # so \"half\", the RTL's default E = MCOLS / 2 (4 at the design point's 8 columns), makes the\n    # 6-row case drain-bound: kept as a strict xfail, the limit docs/mx_mxu.md 9 states\n    p = profile(attention_decode, cfg, uarch={\"MXU_E\": cfg.MCOLS} if E == \"full\" else None, **a)\n    # exp2 runs on LANES/4 composite lanes (the split VPU trades these exp2-heavy shapes --\n    # 4 and 6 query rows per KV head -- for 70K LUTs; Qwen3's 2 rows per head barely notice)\n    assert _eff(p) > 0.60, p.summary()\n\n\ndef test_attention_layer_near_roofline(have_verilator):\n    cfg = design_config()\n    a, _ = layer_args(np.random.default_rng(2), cfg.S, H=1024, Hq=16, Hkv=4, d=128, pos=511,\n                      cap=640)\n    a[\"block\"] = 128\n    p = profile(attention_layer, cfg, **a)\n    assert _eff(p) > 0.88, p.summary()\n\n\ndef test_dram_efficiency_definition():\n    from opentpu.profile import ddr3_peak, ddr3_plusargs, dram_efficiency\n    assert ddr3_peak(3200 / 3) == pytest.approx(17.0667e9, rel=1e-4)\n    # a token that moves 128 B per 100 MHz cycle at DDR3-1066 uses 75% of the DDR3 peak\n    assert dram_efficiency(128 * 1000, 1000, 3200 / 3, 100) == pytest.approx(0.75)\n    a = dict(x[len(\"+axi_\"):].split(\"=\") for x in ddr3_plusargs(3200 / 3, 100)[2:])\n    # the timings the model was calibrated with (DDR3-1066, 100 MHz core: controller clock 133 MHz)\n    assert {k: int(v) for k, v in a.items()} == dict(\n        tpc=10000, tpu=7500, trp=3, trcd=3, tras=5, trc=7, trfc=22, trefi=1040, trmw=23, tturn=4)\n    a = dict(x[len(\"+axi_\"):].split(\"=\") for x in ddr3_plusargs(800, 100)[2:])\n    assert (int(a[\"tras\"]), int(a[\"trc\"]), int(a[\"trfc\"]), int(a[\"trefi\"])) == (4, 6, 16, 780)\n", "tests/test_perf_ddr.py": "\"\"\"tools/perf_ddr.py's boot image, without a simulation: the program as rtlsim._run boots it.\"\"\"\nimport sys\n\nimport numpy as np\n\nfrom opentpu import Config, isa as I, rtlsim\nfrom opentpu.waits import wait_counts\n\nsys.path.insert(0, str(rtlsim.ROOT / \"tools\"))\nimport perf_ddr  # noqa: E402\n\n\n# Under WAITC (the card's otpu_seq since release-2) the image carries the compiler's wait entries\n# after the program's last chunk, as rtlsim._run writes them. perf_ddr's image had the program\n# alone, so every point stopped at its first dependency (\"otpu_seq: WAITC: pc 12's wait 0 (k 0)\n# misses slot 0\"). A VPU copy of what a load wrote waits for the load, and a store of the copy\n# waits for the copy: their entries are not zero.\ndef test_boot_program_carries_the_wait_entries_under_waitc(monkeypatch):\n    cfg = Config(S=1, D=128, ACT_BLOCKS=16)\n    prog = [I.ld(0, 0, 64), I.vop(I.V_COPY, 128, 0, 0, 1, 64, 64, 64, 64), I.st(4096, 128, 64),\n            I.halt()]\n    asm = np.asarray(I.assemble(prog), \"<u4\")\n    ww = wait_counts(prog, cfg.D, cfg.S)\n    assert ww.any()\n    monkeypatch.setitem(rtlsim.BOARD_UARCH, \"SEQ_WC\", 1)\n    words, n = perf_ddr.boot_program(prog, cfg)\n    pad = -len(asm) % (cfg.D // 4)\n    assert n == len(prog) and np.array_equal(words[:len(asm)], asm)\n    assert not words[len(asm):len(asm) + pad].any()\n    assert np.array_equal(words[len(asm) + pad:], ww.astype(\"<u8\").view(\"<u4\"))\n    # without WAITC the program alone (the scoreboard needs no entries)\n    monkeypatch.setitem(rtlsim.BOARD_UARCH, \"SEQ_WC\", 0)\n    words, n = perf_ddr.boot_program(prog, cfg)\n    assert n == len(prog) and np.array_equal(words, asm)\n", "tests/test_prefill.py": "\"\"\"A prompt's prefill from programs at run-time positions (docs/prefill.md, opentpu/llm/prefill.py)\non the ISA simulator: the logits and the image's DRAM (KV caches, DeltaNet states and windows,\nthe MTP layer's cache) equal those of compile-time runs of the same split bit for bit, from\nposition 0 and from a later position (a chat's next turn), across an attention bucket's end,\nplain and MTP; the programs are compiled once per bucket, kind and rows.\"\"\"\nimport dataclasses\n\nimport numpy as np\nimport pytest\n\nfrom opentpu.isasim import board_config\nfrom opentpu.llm import prefill as PF\nfrom opentpu.llm.mtp import MTPDecoder, MTPStats, mtp_engine\nfrom opentpu.llm.qwen3 import PREFILL_ROWS, RUN_WORDS, Engine, device_config\n\nfrom test_mtp import CFG, FP4, _mtp_kv, _mtp_weights, _states\nfrom test_qwen35 import _tiny_model\n\npytest.importorskip(\"torch\")\n\n\n@pytest.fixture(autouse=True)\ndef _todays_runs(monkeypatch):\n    \"\"\"Today's prompt runs (OTPU_TILE=0): the tiled ones, the default, are tests/test_tiled.py's,\n    against these.\"\"\"\n    monkeypatch.setenv(\"OTPU_TILE\", \"0\")\n\n\ndef test_split():\n    \"\"\"R_max rows a run; the rows before conv_k - 1 in a compile-time run; a run-time run's rows\n    in one bucket; the last run L.\"\"\"\n    assert PF.split(0, 10, 4, 256, 4) == [(0, 4, \"P\"), (4, 4, \"P\"), (8, 2, \"L\")]\n    assert PF.split(1, 3, 4, 256, 4) == [(1, 2, \"L\")]\n    assert PF.split(250, 263, 4, 256, 4) == [(250, 4, \"P\"), (254, 2, \"P\"), (256, 4, \"P\"),\n                                             (260, 3, \"L\")]\n    assert PF.split(37, 38, 4, 256, 4) == [(37, 1, \"L\")]\n    # R_max per bucket: 3 rows in bucket 1, 1 in bucket 2\n    assert PF.split(250, 259, lambda b: 3 if b == 1 else 1, 256, 4) == [\n        (250, 3, \"P\"), (253, 3, \"P\"), (256, 1, \"P\"), (257, 1, \"P\"), (258, 1, \"L\")]\n\n\ndef _static(eng, toks, R_max):\n    \"\"\"Engine.prefill as compile-time runs (compile_rows) of the prompt runs' split.\"\"\"\n    p0, img, B = eng.pos, eng.image, eng.block\n    for p, R, kind in PF.split(p0, p0 + len(toks), R_max, B, PF.conv_k(eng)):\n        rows, lr, tk = [(0, p + j) for j in range(R)], [R - 1] if kind == \"L\" else [], \\\n            toks[p - p0:p - p0 + R]\n        lg = eng._run_rows(rows, tk, lr, img.compile_rows(rows, lr, B, tokens=tk))\n        eng.pos = p + R\n    return lg[0]\n\n\ndef _drams(eng, P):\n    \"\"\"Each slice's DRAM but the prompt runs' own words: out[0 .. P] and the state's run\n    words (tpos, LFM2's ring words: qwen3.RUN_WORDS).\"\"\"\n    g = eng.image.lookup[\"gen\"]\n    out = []\n    for s in eng.backend.machine.slices:\n        d = s.dram.copy()\n        d[g[\"out\"]:g[\"out\"] + 4 * (P + 1)] = 0\n        for w in RUN_WORDS.values():\n            d[g[\"state\"] + 4 * w:g[\"state\"] + 4 * w + 4] = 0\n        out.append(d)\n    return out\n\n\ndef _model(case):\n    if case.startswith((\"qwen3\", \"lfm2\")):  # Qwen3 (no convolutions: every run at a run-time\n        from test_autodecode import _tiny   # position), LFM2 (its 3-tap convolutions' ring)\n        W, spec = _tiny(case.split(\"-\")[0])\n        if case == \"qwen3-emb8\":\n            spec = dataclasses.replace(spec, embed=\"int8\")\n        S = 2 if case.endswith(\"-design\") else 1\n        if case.endswith(\"-board\"):         # MCOLS 4: runs of two passes (8 rows)\n            return W, spec, CFG, {}\n        return W, spec, device_config(spec, 512, rows=PREFILL_ROWS, lookup=True, S=S), {}\n    if case == \"kh16\":\n        _, W, spec = _tiny_model(16, 16, init=0.2)\n        return W, spec, board_config(DRAM_BYTES=1 << 26, DSTEP=True, STREAM=True, PAIR=True), {}\n    _, W, spec = _tiny_model(8, init=0.2)\n    if case == \"emb8\":\n        spec = dataclasses.replace(spec, embed=\"int8\")\n    if case == \"design\":\n        return W, spec, device_config(spec, 512, rows=PREFILL_ROWS, lookup=True, S=2), {}\n    return W, spec, CFG, FP4 if case == \"fp4\" else {}\n\n\n@pytest.mark.parametrize(\"case, P1, P2\", [\n    (\"kh8\", 250, 20),       # the second prompt from 250 across the bucket's end at 256\n    (\"kh16\", 37, 30),       # the 0.8B's / 2B's 16 DeltaNet heads\n    (\"emb8\", 37, 30),       # the int8 embedding (a scaled row gather per token)\n    (\"fp4\", 37, 30),        # 4-bit weights with PAIR: runs of more than MCOLS / 2 rows\n    (\"design\", 37, 30),     # two slices, 8 MXU columns: runs of 8 rows\n    (\"qwen3\", 250, 20),     # Qwen3 (qwen3_rows), one slice\n    (\"qwen3-design\", 37, 30),\n    (\"qwen3-emb8\", 37, 30),     # the int8 embedding (Llama-likes: SmolLM3, Phi-4-mini)\n    (\"qwen3-board\", 250, 20),   # the board's MXU (MCOLS 4): runs of 8 rows, two passes\n    (\"lfm2\", 250, 20),\n    (\"lfm2-design\", 37, 30),\n])\ndef test_prompt_runs_are_compile_time_runs(case, P1, P2):\n    \"\"\"Two prompts, the second from where the first left (a chat's next turn): each one's last\n    logits and then every slice's DRAM equal those of compile-time runs (compile_rows) of the\n    same split, word for word; the programs: one per kind, rows and bucket (and the compile-time\n    first run), none per prompt.\"\"\"\n    W, spec, cfg, kw = _model(case)\n    r = np.random.default_rng(P1)\n    p1, p2 = ([int(t) for t in r.integers(0, 1000, n)] for n in (P1, P2))\n    a = Engine(spec, W, cap=512, cfg=cfg, resident=True, prompt_runs=True, **kw)\n    assert PF.supported(a)\n    got = [a.prefill(p1), a.prefill(p2)]\n    rm = a._prompt_rmax                      # the tiny models: every bucket's the most rows\n    full = a.image.rows if not hasattr(spec, \"mtp\") else min(cfg.MCOLS, a.image.rows)\n    assert set(rm.values()) == {(full, True)}\n    R_max = lambda blocks: rm[blocks][0]\n    b = Engine(spec, W, cap=512, cfg=cfg, resident=True, **kw)\n    want = [_static(b, p1, R_max), _static(b, p2, R_max)]\n    assert all(np.array_equal(x, y) for x, y in zip(got, want))\n    assert [s[\"rows\"] for s in a.stats] == [s[\"rows\"] for s in b.stats]\n    assert a.pos == b.pos == P1 + P2\n    assert all(np.array_equal(x, y) for x, y in zip(_drams(a, P1 + P2), _drams(b, P1 + P2)))\n    K = PF.conv_k(a)\n    runs = PF.split(0, P1, R_max, 256, K) + PF.split(P1, P1 + P2, R_max, 256, K)\n    keys = {(k, R, \"at\", p) if p < K - 1 else (k, R, p // 256 + 1) for p, R, k in runs}\n    assert sorted(rm) == sorted({0 if p < K - 1 else p // 256 + 1 for p, _, _ in runs})\n    # the programs: the runs', and r_max's (every kind at every R' <= R_max of the bucket),\n    # none per prompt\n    have = {(k[1], k[2], k[3], k[4]) if k[3] == \"at\" else (k[1], k[2], k[3])\n            for k in a._prompt_progs}\n    assert keys <= have == {(k, r, \"at\", p) if b == 0 else (k, r, b) for b, (R, _) in rm.items()\n                           for r in range(1, R + 1) for k in \"PL\"\n                           for p in (range(K - 1) if b == 0 else [None])}\n    if case == \"fp4\":\n        return\n    # int8 weights: a row's arithmetic is the decode kernel's in any split, so today's prefill\n    # (fit_chunk's runs) gives the same logits, states and windows, and the next step's logits\n    c = Engine(spec, W, cap=512, cfg=cfg, resident=True, **kw)\n    assert all(np.array_equal(x, c.prefill(t)) for x, t in zip(got, (p1, p2)))\n    if \"linear\" in getattr(spec, \"kinds\", ()):     # Qwen3.5's DeltaNet states and windows\n        assert all(np.array_equal(x, y) for x, y in zip(_states(a, spec, 0), _states(c, spec, 0)))\n    assert np.array_equal(a.step(5), c.step(5))\n\n\n\ndef _lfm2(kinds):\n    \"\"\"A tiny LFM2 of these layer kinds (test_autodecode._tiny's dims and weights' spread).\"\"\"\n    import torch\n    import transformers\n    from opentpu.llm.lfm2 import Spec\n    torch.manual_seed(0)\n    hc = transformers.Lfm2Config(\n        hidden_size=256, num_hidden_layers=len(kinds), num_attention_heads=4,\n        num_key_value_heads=2, intermediate_size=512, vocab_size=1000, norm_eps=1e-5,\n        layer_types=[\"full_attention\" if k == \"attn\" else \"conv\" for k in kinds],\n        conv_L_cache=3, conv_bias=False, block_auto_adjust_ff_dim=False,\n        tie_word_embeddings=True, max_position_embeddings=4096, initializer_range=0.2,\n        rope_parameters={\"rope_type\": \"default\", \"rope_theta\": 1e6})\n    m = transformers.Lfm2ForCausalLM(hc).float().eval()\n    with torch.no_grad():\n        for n, p in m.named_parameters():\n            if \"norm\" in n:\n                p.copy_(1.0 + 0.1 * torch.randn_like(p))\n    spec = Spec(256, tuple(kinds), 4, 2, 64, 512, 1000)\n    W = {k: v.float().numpy() for k, v in m.state_dict().items()}\n    return W, spec, device_config(spec, 512, rows=PREFILL_ROWS, lookup=True, S=1)\n\n\ndef test_a_run_word_read_only_through_a_loop_register():\n    \"\"\"LFM2 (conv, attn) x 2: every convolution in the layers' hardware loop, so a prompt run\n    reads its ring word (the state ring's row of position p - K + 1, (p + 1) mod K) only into a\n    register the loop steps ({ring, the loop}: loaded from the word before the loop, no run-time\n    argument of Builder.run_args). The program names it (Program.run_seen) and prefill.run\n    writes it before each run; when only the arguments' words were written, a run read the ring\n    word an earlier run left. Two prompts (a chat's turns) against compile-time runs of the\n    same split, as test_prompt_runs_are_compile_time_runs: the logits and every slice's DRAM.\"\"\"\n    W, spec, cfg = _lfm2((\"conv\", \"attn\", \"conv\", \"attn\"))\n    r = np.random.default_rng(5)\n    p1, p2 = ([int(t) for t in r.integers(0, 1000, n)] for n in (37, 30))\n    a = Engine(spec, W, cap=512, cfg=cfg, resident=True, prompt_runs=True)\n    got = [a.prefill(p1), a.prefill(p2)]\n    progs, names = PF.programs(a, 40, a._prompt_rmax[1][0], \"P\")\n    assert \"ring\" in {v.name for v, _ in progs[0].run_seen} - \\\n        {v.name for v, _ in progs[0].run_args} and \"ring\" in names\n    R_max = lambda blocks: a._prompt_rmax[blocks][0]                # noqa: E731\n    b = Engine(spec, W, cap=512, cfg=cfg, resident=True)\n    want = [_static(b, p1, R_max), _static(b, p2, R_max)]\n    assert [s[\"rows\"] for s in a.stats] == [s[\"rows\"] for s in b.stats]\n    assert all(np.array_equal(x, y) for x, y in zip(got, want))\n    assert all(np.array_equal(x, y) for x, y in zip(_drams(a, 67), _drams(b, 67)))\n\n\ndef test_todays_route_where_it_fits_more_rows(monkeypatch):\n    \"\"\"prefill.covers: where today's prefill (compile_rows) fits more rows in a bucket than its\n    prompt run (here bucket 2's prompt programs held to 2 rows), a prompt that reaches the\n    bucket takes today's runs (their rows, logits and the next step); one in bucket 1 still\n    takes prompt runs.\"\"\"\n    from opentpu.compiler import CompileError\n    W, spec, cfg, _ = _model(\"qwen3\")\n    r = np.random.default_rng(3)\n    p1, p2 = ([int(t) for t in r.integers(0, 1000, n)] for n in (30, 240))\n    a = Engine(spec, W, cap=512, cfg=cfg, resident=True, prompt_runs=True)\n    real = a.image.compile_prompt_run\n\n    def held(blocks, R, *args, **kw):\n        if blocks == 2 and R > 2:\n            raise CompileError(\"TMEM exhausted (the test's bucket 2)\")\n        return real(blocks, R, *args, **kw)\n    monkeypatch.setattr(a.image, \"compile_prompt_run\", held)\n    c = Engine(spec, W, cap=512, cfg=cfg, resident=True)\n    R = min(cfg.MCOLS, a.image.rows)\n    assert R > 3\n    assert np.array_equal(a.prefill(p1), c.prefill(p1))\n    assert [s[\"rows\"] for s in a.stats] == [n for _, n, _ in PF.split(0, 30, R, 256, 1)]\n    na, nc = len(a.stats), len(c.stats)\n    assert np.array_equal(a.prefill(p2), c.prefill(p2))\n    assert a._prompt_rmax == {1: (R, True), 2: (2, False)}\n    assert [s[\"rows\"] for s in a.stats[na:]] == [s[\"rows\"] for s in c.stats[nc:]]\n    assert {k[1:3] for k in a._prompt_progs if k[3] == 2} == {(k, r) for k in \"PL\"\n                                                                for r in (1, 2)}  # r_max's\n    assert np.array_equal(a.step(5), c.step(5))\n\n\ndef test_a_new_contexts_first_run_is_sized_on_its_own(monkeypatch):\n    \"\"\"prefill.r_max(eng, 0) with convolutions (LFM2): a new context's first run, at\n    compile-time positions from 0, takes the rows its own program fits (here held to 4;\n    LFM2.5-230M's on the board fits 8 rows at a run-time position, 4 from 0), bucket 1's runs\n    the most; the split, from 0, then the logits of compile-time runs of it.\"\"\"\n    from opentpu.compiler import CompileError\n    W, spec, cfg, _ = _model(\"lfm2-board\")\n    a = Engine(spec, W, cap=512, cfg=cfg, resident=True, prompt_runs=True)\n    real = a.image.compile_prompt_run\n\n    def held(blocks, R, *args, p0=None, **kw):\n        if p0 is not None and R > 4:\n            raise CompileError(\"TMEM exhausted (the test's first run)\")\n        return real(blocks, R, *args, p0=p0, **kw)\n    monkeypatch.setattr(a.image, \"compile_prompt_run\", held)\n    R, K = a.image.rows, PF.conv_k(a)\n    assert R > 4 and K > 1\n    assert PF.r_max(a, 0) == 4 and PF.r_max(a, 1) == R and PF.covers(a, 0, 30)\n    toks = [int(t) for t in np.random.default_rng(11).integers(0, 1000, 30)]\n    rm = lambda blocks: PF.r_max(a, blocks)\n    assert PF.split(0, 30, rm, 256, K) == [(0, 4, \"P\"), (4, 8, \"P\"), (12, 8, \"P\"),\n                                           (20, 8, \"P\"), (28, 2, \"L\")]\n    b = Engine(spec, W, cap=512, cfg=cfg, resident=True)\n    assert np.array_equal(a.prefill(toks), _static(b, toks, rm))\n\n\ndef test_r_max_holds_every_run_a_prompt_asks_for(monkeypatch):\n    \"\"\"prefill.r_max: the bucket's R_max is the largest size at which every run a prompt can\n    ask for fits (P and L at every R' <= R: the split cuts runs at the prompt's and the\n    bucket's end), not its L program alone (here bucket 1's P held to 2 rows, bucket 2's L\n    at 3 rows).\"\"\"\n    from opentpu.compiler import CompileError\n    W, spec, cfg, _ = _model(\"qwen3\")\n    a = Engine(spec, W, cap=512, cfg=cfg, resident=True, prompt_runs=True)\n    real = a.image.compile_prompt_run\n\n    def held(blocks, R, kind, *args, **kw):\n        if (blocks, kind) == (1, \"P\") and R > 2 or (blocks, kind, R) == (2, \"L\", 3):\n            raise CompileError(\"TMEM exhausted (the test's)\")\n        return real(blocks, R, kind, *args, **kw)\n    monkeypatch.setattr(a.image, \"compile_prompt_run\", held)\n    assert a.image.rows > 3\n    assert PF.r_max(a, 1) == 2 and PF.r_max(a, 2) == 2\n\n\ndef test_a_bucket_takes_the_form_with_more_rows_a_run(monkeypatch):\n    \"\"\"prefill.tiled: a bucket's P and L runs are tiled where a tile fits, unless today's\n    prompt runs, covering the bucket, take as many rows or more (each run streams the weights\n    once: LFM2-2.6B's tile took 1-2 rows where today's runs take 4, half the chat prefill's\n    speed; at equal rows today's were the faster, docs/tiled_prefill.md 12.4); tiled where\n    today's do not cover the bucket, and with a tile as large as today's runs could be nothing\n    more is probed.\"\"\"\n    W, spec, cfg, _ = _model(\"qwen3\")\n    a = Engine(spec, W, cap=512, cfg=cfg, resident=True, prompt_runs=True)\n    a.tile_runs = True                          # (this file's runs are today's: OTPU_TILE=0)\n    assert PF.tiling(a)\n    monkeypatch.setattr(PF, \"_tile_fit\", lambda eng, b: 2)\n    for fit, tiled in (((4, True), False), ((4, False), True), ((2, True), False),\n                       ((1, True), True)):\n        monkeypatch.setattr(PF, \"_fit\", lambda eng, b, fit=fit: fit)\n        assert PF.tiled(a, 1) == tiled and PF.r_max(a, 1) == (2 if tiled else fit[0])\n        assert PF._what(a, 300, 2, \"P\")[0][0] == (\"prompt tile\" if tiled else \"prompt\")\n    assert PF.covers(a, 0, 30)                  # (the tile)\n    monkeypatch.setattr(PF, \"_tile_fit\", lambda eng, b: PF._probe_top(eng, b))\n\n    def probed(eng, b):\n        raise AssertionError(\"today's runs probed\")\n    monkeypatch.setattr(PF, \"_fit\", probed)\n    assert PF.tiled(a, 1) and PF.tiled(a, 2)\n    assert not PF.tiled(a, 0)                   # (a new context's first run: today's)\n\n\n@pytest.mark.parametrize(\"fp4\", [True, False], ids=[\"fp4\", \"int8\"])\ndef test_odd_rows_take_one_less_where_pair_makes_it_cheaper(fp4):\n    \"\"\"qwen3.prefer_rows: with PAIR a 4-bit MM of at most MCOLS / 2 rows (h) streams two blocks\n    a cycle, so h + 1 rows (3 at MCOLS 4, 5 at MCOLS 8) take a whole pass's MXU time and h cost\n    less per row (the 4B at MCOLS 4: -13.8% a row in the RTL co-sim); an int8 MM streams once\n    per MCOLS rows, so h + 1 rows cost less per row than h. Even sizes stay.\"\"\"\n    from opentpu.llm.qwen3 import PREFER_MARGIN, mxu_time, prefer_rows\n    _, W, spec = _tiny_model(16, 16, init=0.2)\n    a = Engine(spec, W, cap=512, cfg=CFG, resident=True, **(FP4 if fp4 else {}))\n    img = a.image\n    h = CFG.MCOLS // 2\n    assert h >= 2                           # (h + 1 odd)\n\n    def rows(r):\n        return img.compile_rows([(0, j) for j in range(r)], [], a.block,\n                                tokens=list(range(1, r + 1)))\n    th, t1 = (mxu_time(rows(r)) / r for r in (h, h + 1))\n    assert (th <= (1 - PREFER_MARGIN) * t1) == fp4\n    assert prefer_rows(img, h + 1, rows) == (h if fp4 else h + 1)\n    assert prefer_rows(img, 2 * h, rows) == 2 * h\n\ndef _static_mtp(dec, R_max):\n    \"\"\"MTPDecoder.prefill as compile-time runs of the prompt runs' split: the rows (hidden,\n    the decoder's slot), then the MTP layer over them.\"\"\"\n    def prefill(tokens, st, chunk=None, pick=None, on_run=None):\n        eng, img = dec.eng, dec.img\n        toks = [int(t) for t in tokens]\n        p0 = eng.pos\n        P = p0 + len(toks)\n        if p0 == 0:\n            dec.slot = 0\n        for p, R, kind in PF.split(p0, P, R_max, eng.block, PF.conv_k(eng)):\n            i = p - p0\n            dec._run(img.compile_rows([(0, p + j) for j in range(R)],\n                                      [R - 1] if kind == \"L\" else [], eng.block,\n                                      tokens=toks[i:i + R], slot=dec.slot, hidden=True),\n                     \"prefill\", R, st)\n            nxt = toks[i + 1:i + R + 1]\n            if kind == \"L\":\n                a0 = int(np.argmax(dec._logits(R)[R - 1]))\n                nxt = nxt + [a0]\n            draft = dec._draft(p, nxt, st, \"mtp prefill\")[R - 1]\n        eng.pos, dec.draft = P, draft\n        return a0, draft\n    return prefill\n\n\n@pytest.mark.parametrize(\"P1\", [40, 245])\ndef test_mtp_prompt_runs_are_compile_time_runs(P1):\n    \"\"\"MTP: a prompt, greedy decoding, then the next turn's prompt (the last token and new\n    ones, from the decoder's committed slot; at P1 245 across the bucket's end): the tokens,\n    the first drafts and every slice's DRAM (the MTP layer's KV cache too) equal those of\n    compile-time runs of the same split; plain prompt runs give the same first token and\n    tokens (one split for plain and MTP).\"\"\"\n    _, W, spec = _tiny_model(8, init=0.2)\n    W = _mtp_weights(W, spec)\n    r = np.random.default_rng(P1)\n    p1, p2 = [int(t) for t in r.integers(0, 1000, P1)], [int(t) for t in r.integers(0, 1000, 9)]\n    a = MTPDecoder(mtp_engine(spec, W, cap=512, cfg=CFG, prompt_runs=True))\n    b = MTPDecoder(mtp_engine(spec, W, cap=512, cfg=CFG))\n    b.prefill = _static_mtp(b, lambda blocks: PF.r_max(a.eng, blocks))\n    sa, sb = a.generate(p1, max_new=6), b.generate(p1, max_new=6)\n    assert sa.tokens == sb.tokens and a.slot == b.slot and a.eng.pos == b.eng.pos\n    plain = Engine(spec, W, cap=512, cfg=CFG, resident=True, prompt_runs=True)\n    assert plain.generate(p1, max_new=6) == sa.tokens\n    assert [x[:2] for x in sa.runs] == [x[:2] for x in sb.runs]\n    q = [sa.tokens[-1]] + p2\n    got, want = a.prefill(q, MTPStats()), b.prefill(q, MTPStats())\n    assert got == want and a.eng.pos == b.eng.pos == P1 + 5 + len(q)\n    n = a.eng.pos\n    assert all(np.array_equal(x, y) for x, y in zip(_drams(a.eng, n), _drams(b.eng, n)))\n    assert all(np.array_equal(x, y) for x, y in\n               zip(_states(a.eng, spec, a.slot), _states(b.eng, spec, b.slot)))\n    assert all(np.array_equal(x, y) for x, y in zip(_mtp_kv(a.eng, n), _mtp_kv(b.eng, n)))\n    assert {k[-1] for k in a.eng._prompt_progs} == {0, a.slot}    # (M's: slot 0)\n    # int8: today's prefill (fit_chunk's runs, the MTP layer over 4 rows a run) the same\n    c = MTPDecoder(mtp_engine(spec, W, cap=512, cfg=CFG))\n    assert c.generate(p1, max_new=6).tokens == sa.tokens and c.prefill(q, MTPStats()) == got\n    assert all(np.array_equal(x, y) for x, y in\n               zip(_states(a.eng, spec, a.slot), _states(c.eng, spec, c.slot)))\n    assert all(np.array_equal(x, y) for x, y in zip(_mtp_kv(a.eng, n), _mtp_kv(c.eng, n)))\n\n\ndef test_prompt_programs_come_from_the_cache(tmp_path, monkeypatch):\n    \"\"\"The prompt runs' programs through the program cache (Engine prog_cache): a new process's\n    MTP engine reads every one from disk, none compiled; the device loops after prompt runs\n    (MTP's and plain's) give the tokens of today's prefill (int8 weights).\"\"\"\n    from opentpu import progcache as PC\n    from opentpu.llm.mtp import NK\n    monkeypatch.setenv(\"OTPU_PROG_CACHE\", str(tmp_path))\n    PC.clear()\n    _, W, spec = _tiny_model(8, init=0.2)\n    W = _mtp_weights(W, spec)\n    prompt = [int(t) for t in np.random.default_rng(5).integers(0, 1000, 20)]\n\n    def run(cache, prompt_runs=True):\n        dec = MTPDecoder(mtp_engine(spec, W, cap=512, cfg=CFG, prog_cache=cache,\n                                    prompt_runs=prompt_runs))\n        return dec.generate_card(prompt, max_new=10, stop=[]).tokens, dec.eng\n\n    want, _ = run(False, False)\n    assert run(False)[0] == want and len(set(want)) > 4\n    plain = Engine(spec, W, cap=512, cfg=CFG, resident=True, prompt_runs=True)\n    t0 = int(np.argmax(plain.prefill(prompt)))\n    assert [t0] + plain.generate_card(t0, 9, stop_ids=[]) == want\n    run(True)\n    PC.clear()\n    s = dict(PC.stats)\n    got, eng = run(True)\n    assert got == want and PC.stats[\"compile\"] == s[\"compile\"]\n    # (and R_max: progcache.fact)\n    assert PC.stats[\"disk\"] - s[\"disk\"] == NK + len(eng._prompt_progs) + len(eng._prompt_rmax)\n    PC.clear()\n\n\ndef test_bucket_1_programs_are_warmed_at_start(tmp_path, monkeypatch):\n    \"\"\"prefill.warm: an engine with the pipeline compiles bucket 1's prompt programs on a thread\n    as it starts, so a prompt in bucket 1 compiles none and gives the logits of an engine\n    without it; a new process's engine takes R_max and the programs from the program cache\n    (no compile).\"\"\"\n    from opentpu import progcache as PC\n    monkeypatch.setenv(\"OTPU_PROG_CACHE\", str(tmp_path))\n    PC.clear()\n    _, W, spec = _tiny_model(8, init=0.2)\n    prompt = [int(t) for t in np.random.default_rng(6).integers(0, 1000, 21)]\n    eng = Engine(spec, W, cap=512, cfg=CFG, resident=True, prompt_runs=True, pipeline=True,\n                 prog_cache=True)\n    eng._prompt_warm.join(timeout=600)\n    warmed = set(eng._prompt_progs)\n    K, R0, R1 = PF.conv_k(eng), PF.r_max(eng, 0), PF.r_max(eng, 1)\n    assert len(warmed) == 2 * (K - 1) * R0 + 2 * R1     # r_max's: P and L of every R' <= R\n    lg = eng.prefill(prompt)\n    assert set(eng._prompt_progs) == warmed\n    assert np.array_equal(lg, Engine(spec, W, cap=512, cfg=CFG, resident=True,\n                                     prompt_runs=True).prefill(prompt))\n    PC.clear()\n    s = dict(PC.stats)\n    again = Engine(spec, W, cap=512, cfg=CFG, resident=True, prompt_runs=True, prog_cache=True)\n    assert np.array_equal(again.prefill(prompt), lg) and PC.stats[\"compile\"] == s[\"compile\"]\n    PC.clear()\n\n\n@pytest.mark.parametrize(\"case\", [\"qwen3\", \"lfm2\"])\ndef test_prompt_runs_at_a_partial_last_bucket(guarded, case):\n    \"\"\"A KV capacity of 384 (a multiple of D, not of the attention block): bucket 2's masked\n    block spans the cache's last 128 tokens and takes the first 128 entries of each row of its\n    mask tile (row by row). Prompts across 256 and on to the cache's end give the compile-time\n    runs' logits and DRAM bit for bit, reading nothing past the cache (every KV region is\n    followed by -NaN words here).\"\"\"\n    W, spec, cfg, kw = _model(case)\n    cap = 384\n    r = np.random.default_rng(5)\n    p1, p2 = ([int(t) for t in r.integers(0, 1000, n)] for n in (250, cap - 250))\n    a = Engine(spec, W, cap=cap, cfg=cfg, resident=True, prompt_runs=True, **kw)\n    b = Engine(spec, W, cap=cap, cfg=cfg, resident=True, **kw)\n    assert PF.supported(a) and guarded(a) and guarded(b)\n    got = [a.prefill(p1), a.prefill(p2)]\n    R_max = lambda blocks: a._prompt_rmax[blocks][0]       # noqa: E731\n    want = [_static(b, p1, R_max), _static(b, p2, R_max)]\n    assert all(np.isfinite(y).all() and np.array_equal(x, y) for x, y in zip(got, want))\n    assert a.pos == b.pos == cap and max(a._prompt_rmax) == 2\n    assert all(np.array_equal(x, y) for x, y in zip(_drams(a, cap), _drams(b, cap)))\n\n\n@pytest.mark.parametrize(\"case\", [\"qwen3-board\", \"lfm2\", \"kh8\"])\ndef test_prompt_runs_add_the_mask_tile(case):\n    \"\"\"docs/prefill.md 9: a prompt run's masked block loads its row's tile of the image's mask\n    table (qwen3.amask_table: -0 where a token counts, -inf past it, MCOLS rows of a score\n    buffer's stride) into the score buffer and accumulates q.K^T into it with the row maxima\n    (MM ACC + RMAX): one LD and one MM, no VOP MIN; a run-time decode step keeps its mask\n    row.\"\"\"\n    from opentpu import isa as I\n    from opentpu.llm.qwen3 import amask_table\n    W, spec, cfg, kw = _model(case)\n    a = Engine(spec, W, cap=512, cfg=cfg, resident=True, prompt_runs=True, **kw)\n    img, B = a.image, a.block\n    t = amask_table(B, cfg.MCOLS)\n    assert t.shape == (B, cfg.MCOLS, B + 1)\n    assert np.array_equal(np.signbit(t), np.ones_like(t, bool))         # -0 and -inf only\n    assert (np.isneginf(t[5, :, 6:B])).all() and not np.isinf(t[5, :, :6]).any()\n    assert not np.isinf(t[:, :, B]).any()                                # the pad word\n\n    def mins(progs):\n        return sum(ins.op == I.VOP and (ins.w[5] >> 16) & 0xFF == I.V_MIN\n                   and (ins.w[5] >> 24) & 3 == I.B_COL for pg in progs for ins in pg)\n\n    progs, _ = img.compile_prompt_run(2, 2, \"P\", B)\n    acc = [ins for pg in progs for ins in pg\n           if ins.op == I.MM and ins.flags & I.F_ACC and ins.flags & I.F_RMAX]\n    assert acc and mins(progs) == 0\n    assert mins(img.compile_decode(2, B, B)[0]) > 0\n", "tests/test_prefill_gemma4.py": "\"\"\"Gemma 4's prompt runs (docs/prefill.md, gemma4.gemma4_prompt_run) on the ISA simulator, on\ntest_gemma4's tiny model (sliding and global layers, the KV-shared ones, per-layer inputs): the\nlogits and the layers' DRAM (weights and KV caches) equal those of compile-time runs of the same\nsplit bit for bit, with the PLE table on the card (int8, fp4) and on the host (the host writes\neach run's records into the slot first), from position 0 and from a later one (a chat's next\nturn) across the first bucket's end; and across the sliding ring's wrap at 768.\"\"\"\nimport numpy as np\nimport pytest\n\nfrom opentpu.llm import prefill as PF\nfrom opentpu.llm.qwen3 import Engine\n\nfrom test_gemma4 import _cfg, tiny  # noqa: F401 (tiny: the fixture)\nfrom test_prefill import _static, _todays_runs  # noqa: F401 (today's prompt runs: OTPU_TILE=0)\n\n\n@pytest.mark.parametrize(\"wf, host, P1, P2\", [\n    (\"int8\", \"0\", 250, 20),     # the second prompt across the bucket's end at 256\n    (\"fp4\", \"0\", 37, 30),       # 4-bit layers, the int8 head and PLE records\n    (\"fp4\", \"1\", 37, 30),       # the PLE table on the host (OTPU_PLE_HOST=1)\n    (\"int8\", \"0\", 760, 20),     # the sliding ring's wrap (768 slots)\n], ids=[\"int8\", \"fp4\", \"ple-host\", \"ring-wrap\"])\ndef test_prompt_runs_are_compile_time_runs(tiny, wf, host, P1, P2, monkeypatch):\n    \"\"\"Two prompts, the second from where the first left: each one's last logits, the layers'\n    DRAM (KV caches) and the next step's logits equal those of compile-time runs (compile_rows,\n    their tokens compiled in) of the same split; with int8 weights also today's prefill's.\"\"\"\n    _, W, spec = tiny\n    monkeypatch.setenv(\"OTPU_PLE_HOST\", host)\n    r = np.random.default_rng(P1)\n    p1, p2 = ([int(t) for t in r.integers(0, 1000, n)] for n in (P1, P2))\n    kw = dict(wformat=wf, head_format=\"int8\" if wf == \"fp4\" else None)\n    a = Engine(spec, W, cap=1024, cfg=_cfg(), resident=True, prompt_runs=True, **kw)\n    assert PF.supported(a) and a.image.ple_host == (host == \"1\")\n    got = [a.prefill(p1), a.prefill(p2)]\n    R_max = lambda blocks: PF.r_max(a, blocks)\n    assert R_max(1) == a.image.rows             # two passes (MCOLS 4): fit_chunk's 8 rows\n    b = Engine(spec, W, cap=1024, cfg=_cfg(), resident=True, **kw)\n    want = [_static(b, p1, R_max), _static(b, p2, R_max)]\n    assert all(np.array_equal(x, y) for x, y in zip(got, want))\n    assert [s[\"rows\"] for s in a.stats] == [s[\"rows\"] for s in b.stats]\n    img = a.image\n\n    def layers(e):\n        return e.backend.machine.slices[0].dram[img.layer0:img.head[0]]\n    assert np.array_equal(layers(a), layers(b))\n    assert {k[3] for k in a._prompt_progs} == {p // 256 + 1 for p in range(P1 + P2)}\n    assert np.array_equal(a.step(5), b.step(5))\n    if wf == \"int8\":\n        c = Engine(spec, W, cap=1024, cfg=_cfg(), resident=True, **kw)\n        assert all(np.array_equal(x, c.prefill(t)) for x, t in zip(got, (p1, p2)))\n", "tests/test_progcache.py": "\"\"\"The program cache (opentpu/progcache.py): an engine with prog_cache compiles a bucket's programs\nonce per process and image layout, and a later process reads them from the disk cache; the programs\nread back run as the compiled ones.\"\"\"\nimport os\n\nimport numpy as np\nimport pytest\n\nfrom opentpu import isa as I\nfrom opentpu import progcache as PC\nfrom opentpu.compiler import RunVar\n\nfrom test_autodecode import _tiny\n\n\ndef _prog(n, seed):\n    r = np.random.default_rng(seed)\n    return [I.li(int(r.integers(1, 16)), int(r.integers(0, 1 << 20))) for _ in range(n)] + \\\n        [I.halt()]\n\n\ndef _words(progs):\n    if isinstance(progs, np.ndarray):\n        return [progs.tolist()]\n    if isinstance(progs, tuple):\n        return [w for p in progs for w in _words(p)]\n    return [I.assemble(p).tolist() for p in progs]\n\n\n@pytest.mark.parametrize(\"value\", [\n    ([_prog(5, 1)], None),                                  # one slice\n    ([_prog(5, 1), _prog(7, 2)], None),                     # two slices\n    (([_prog(4, 3)], [_prog(6, 4)]), None),                 # a split program's two parts\n    (np.asarray(I.assemble(_prog(9, 5)), np.uint32),        # a compile worker's words and the\n     [(RunVar(\"tok\"), 4096), (RunVar(\"tpos\", 512), -4)])],  # run arguments (one bounded)\n    ids=[\"slice\", \"slices\", \"split\", \"words\"])\ndef test_disk_round_trip(tmp_path, value):\n    f = tmp_path / \"ab\" / \"ab.npz\"\n    PC._store(tmp_path, f, value)\n    progs, ra = PC._load(f)                 # a worker's words come back as a slice's list\n    assert type(progs) is (list if isinstance(value[0], np.ndarray) else type(value[0]))\n    assert _words(progs) == _words(value[0])\n    assert (ra is None) == (value[1] is None)\n    if ra is not None:\n        assert [(v.name, v.bound, c) for v, c in ra] == [(v.name, v.bound, c) for v, c in value[1]]\n    # each slice's program carries the arguments (opentpu.waits bounds them by their variables)\n    for part in (progs if isinstance(progs, tuple) else (progs,)):\n        for p in part:\n            assert [(v.name, v.bound, c) for v, c in p.run_args] == \\\n                [(v.name, v.bound, c) for v, c in (ra or ())]\n\n\ndef test_the_key_sees_the_layout_the_environment_and_what(monkeypatch):\n    monkeypatch.delenv(\"OTPU_FORMATS\", raising=False)\n    k = PC.key((\"spec\", 512), (\"gen\", 1))\n    assert k == PC.key((\"spec\", 512), (\"gen\", 1))\n    assert k != PC.key((\"spec\", 1024), (\"gen\", 1)) != PC.key((\"spec\", 512), (\"gen\", 2))\n    monkeypatch.setenv(\"OTPU_FORMATS\", \"attn=fp4\")\n    assert PC.key((\"spec\", 512), (\"gen\", 1)) != k\n    k = PC.key((\"spec\", 512), (\"gen\", 1))\n    for var, val in ((\"OTPU_QUIET\", \"/tmp/q\"), (\"OTPU_BUILD_JOBS\", \"3\"),\n                     (\"OTPU_IMG_CACHE\", \"/tmp/i\"), (\"OTPU_LOCK_HELD\", \"xdma0\"),\n                     (\"OTPU_LOCK_PID\", str(os.getpid())), (\"OTPU_VISION_WARM\", \"0\")):\n        monkeypatch.setenv(var, val)        # read by the host's tools only (otpu-lock sets its\n        assert PC.key((\"spec\", 512), (\"gen\", 1)) == k, var  # pid: each session's misses;\n                                            # vision_warm's switch: its entries, the engine's)\n\n\ndef test_the_key_sees_the_host_modules_the_programs_take(monkeypatch):\n    \"\"\"The programs take constants from opentpu/host/offload.py (LINE, TAG, RUN, Layout and\n    RowLayout: where the mailboxes, slots and tags are): a change there misses, one in a host\n    driver does not; every host module the compiler, kernels and models import is in the key.\"\"\"\n    import ast\n    from pathlib import Path\n    root = Path(PC.__file__).resolve().parent\n    k = PC.key((\"spec\", 512), (\"gen\", 1))\n    read = Path.read_bytes\n\n    def edited(name):\n        return lambda f: read(f) + (b\"\\n# changed\\n\" if f == root / \"host\" / name else b\"\")\n\n    for name, misses in ((\"offload.py\", True), (\"board.py\", False)):\n        monkeypatch.setattr(PC, \"_SRC\", None)\n        monkeypatch.setattr(Path, \"read_bytes\", edited(name))\n        assert (PC.key((\"spec\", 512), (\"gen\", 1)) != k) == misses, name\n    keyed = {f.relative_to(root).as_posix() for f in PC.keyed()}\n    for f in PC.keyed():                        # (opentpu/serve's are not keyed)\n        rel = f.relative_to(root).parts\n        if rel[0] == \"host\":\n            continue\n        for node in ast.parse(f.read_text()).body:          # the module-level imports\n            if not isinstance(node, ast.ImportFrom):\n                continue\n            mod = (node.module or \"\").split(\".\")\n            if node.level:\n                mod = list(rel[:len(rel) - node.level]) + mod\n            elif mod[0] == \"opentpu\":\n                mod = mod[1:]\n            if mod and mod[0] == \"host\":\n                for m in ([mod] if len(mod) > 1 else [mod + [a.name] for a in node.names]):\n                    assert \"/\".join(m) + \".py\" in keyed, (f, m)\n\n\ndef test_the_key_leaves_out_the_tools_no_build_runs(monkeypatch):\n    \"\"\"An edit to a profiler, trace, reference or RTL simulation module (UNKEYED) keeps the\n    cached programs and images; one to the compiler misses. No keyed module imports an UNKEYED\n    one, at module level or in a function, but runtime's RTL run (rtlsim: a run, not a build).\"\"\"\n    import ast\n    from pathlib import Path\n    root = Path(PC.__file__).resolve().parent\n    k = PC.key((\"spec\", 512), (\"gen\", 1))\n    read = Path.read_bytes\n\n    def edited(name):\n        return lambda f: read(f) + (b\"\\n# changed\\n\" if f == root / name else b\"\")\n\n    for name, misses in ((\"lens.py\", False), (\"rtlsim.py\", False), (\"compiler.py\", True)):\n        monkeypatch.setattr(PC, \"_SRC\", None)\n        monkeypatch.setattr(Path, \"read_bytes\", edited(name))\n        assert (PC.key((\"spec\", 512), (\"gen\", 1)) != k) == misses, name\n    monkeypatch.undo()\n    unkeyed = {u[:-3].replace(\"/\", \".\") for u in PC.UNKEYED}\n    allowed = {(\"runtime.py\", \"rtlsim\")}\n    for f in PC.keyed():\n        rel = f.relative_to(root)\n        pkg = list(rel.parts[:-1])\n        for node in ast.walk(ast.parse(f.read_text())):\n            if isinstance(node, ast.Import):\n                mods = [a.name.split(\".\")[1:] for a in node.names if a.name.startswith(\"opentpu.\")]\n            elif isinstance(node, ast.ImportFrom):\n                mod = node.module.split(\".\") if node.module else []\n                if node.level:\n                    mod = pkg[:len(pkg) - node.level + 1] + mod\n                elif mod[:1] == [\"opentpu\"]:\n                    mod = mod[1:]\n                else:\n                    continue\n                mods = [mod] + [mod + [a.name] for a in node.names]\n            else:\n                continue\n            for m in mods:\n                if \".\".join(m) in unkeyed:\n                    assert (rel.as_posix(), \".\".join(m)) in allowed, (rel.as_posix(), m)\n\n\ndef test_engines_share_the_bucket_programs(tmp_path, monkeypatch):\n    \"\"\"A second engine of the layout in this process compiles none of the generate loop's and\n    resident decode's bucket programs; after clear() (a new process) one reads them from the\n    disk cache; each gives the tokens of an engine without the cache.\"\"\"\n    from opentpu.llm.qwen3 import PREFILL_ROWS, Engine, device_config\n    monkeypatch.setenv(\"OTPU_PROG_CACHE\", str(tmp_path))\n    PC.clear()\n    W, spec = _tiny(\"qwen3\")\n    cfg = device_config(spec, 512, rows=PREFILL_ROWS, lookup=True)\n    toks = [int(t) for t in np.random.default_rng(1).integers(0, 1000, 248)]\n\n    def run(cache):\n        e = Engine(spec, W, cap=512, cfg=cfg, resident=True, prog_cache=cache)\n        t0 = int(np.argmax(e.prefill(toks)))\n        got = e.generate_card(t0, 12, stop_ids=[])      # buckets 1 and 2\n        return got + [int(np.argmax(e.step(got[-1])))]  # resident decode, bucket 2\n\n    want = run(False)\n    s0 = dict(PC.stats)\n    assert run(True) == want\n    assert PC.stats[\"compile\"] - s0[\"compile\"] == 3     # gen 1, gen 2, decode 2\n    assert PC.stats[\"write\"] - s0[\"write\"] == 3\n    s1 = dict(PC.stats)\n    assert run(True) == want\n    assert PC.stats[\"compile\"] == s1[\"compile\"] and PC.stats[\"memory\"] - s1[\"memory\"] == 3\n    PC.clear()\n    s2 = dict(PC.stats)\n    assert run(True) == want\n    assert PC.stats[\"compile\"] == s2[\"compile\"] and PC.stats[\"disk\"] - s2[\"disk\"] == 3\n    PC.clear()\n\n\ndef test_the_generate_buckets_warmed_ahead_are_read_back(tmp_path, monkeypatch):\n    \"\"\"opentpu/host/gen_warm.py: its process (spawned, the engine's arguments pickled) compiles\n    every bucket's generate programs, greedy and the default sampler's, into the disk cache\n    under the engine's layout; a new process's engine then compiles none of them for its\n    replies in buckets 1 and 2 (read back from the disk) and gives the tokens of an engine\n    without the cache. With wait entries (warm's waitc), the board's computation of a read-back\n    program's entries finds them on the disk. A second warm compiles nothing; start() leaves an\n    engine without the program cache alone.\"\"\"\n    from types import SimpleNamespace\n\n    from opentpu import waits as WC\n    from opentpu.host import gen_warm as GW\n    from opentpu.llm import generate as G\n    from opentpu.llm.qwen3 import PREFILL_ROWS, Engine, device_config\n    monkeypatch.setenv(\"OTPU_PROG_CACHE\", str(tmp_path))\n    PC.clear()\n    W, spec = _tiny(\"qwen3\")\n    cfg = device_config(spec, 512, rows=PREFILL_ROWS, lookup=True)\n    toks = [int(t) for t in np.random.default_rng(4).integers(0, 1000, 248)]\n    sp = dict(temperature=0.7, top_k=20, top_p=0.9, repetition_penalty=1.1)\n\n    def run(e, samp=None):\n        t0 = int(np.argmax(e.prefill(toks)))\n        return e.generate_card(t0, 12, stop_ids=[], sampling=samp, context=toks + [t0],\n                               rng=np.random.default_rng(5))     # buckets 1 and 2\n\n    want = [run(Engine(spec, W, cap=512, cfg=cfg, resident=True, prog_cache=False), s)\n            for s in GW.samplings(sp)]\n    e = Engine(spec, W, cap=512, cfg=cfg, resident=True, prog_cache=True)\n    assert GW.start(SimpleNamespace(can_generate=True, prog_cache=False)) is None\n    assert [None if s is None else s.key for s in GW.samplings(sp)] == [None, (24, True)]\n    p = GW.start(e, sp)\n    p.join(300)\n    assert p.exitcode == 0\n    chain = bool(getattr(e.backend, \"chains\", False))\n    for b in range(1, G.buckets(512, e.block) + 1):\n        for s in GW.samplings(sp):\n            assert not GW.warm(e.image, e.layout, e.block, e._conv_lo, b, chain, s,\n                               e.gen_debug, e.gen_split)\n    PC.clear()\n    s0 = dict(PC.stats)\n    got = [run(Engine(spec, W, cap=512, cfg=cfg, resident=True, prog_cache=True), s)\n           for s in GW.samplings(sp)]\n    assert got == want\n    assert PC.stats[\"compile\"] == s0[\"compile\"] and PC.stats[\"disk\"] - s0[\"disk\"] == 4\n    PC.clear()\n    GW.warm(e.image, e.layout, e.block, e._conv_lo, 1, chain, waitc=True)\n    WC._mem.clear()\n    c0 = WC.stats[\"computed\"]\n    progs = PC.get(e.layout, GW.gen_what(e.block, e._conv_lo, 1, chain, None, e.gen_debug,\n                                         e.gen_split), None)[0]\n    for part in progs if isinstance(progs, tuple) else (progs,):\n        for prog in part:\n            WC.entries(I.assemble(prog), cfg.D, cfg.S, prog=prog)\n    assert WC.stats[\"computed\"] == c0\n    PC.clear()\n\n\ndef test_filling_and_plain_decodes_are_cached_apart(tmp_path, monkeypatch):\n    \"\"\"A streamed decode's programs fill their logits (qwen3.fill_logits), the others not: the\n    cache keeps the two apart for one layout and bucket (a card engine and its ISA reference in\n    one process), and a filling program read back from the disk cache (no comments) gives the\n    fill's gate as compiled.\"\"\"\n    from opentpu.llm.qwen3 import Engine, device_config, fill_gate\n    monkeypatch.setenv(\"OTPU_PROG_CACHE\", str(tmp_path))\n    PC.clear()\n    W, spec = _tiny(\"qwen3\")\n    cfg = device_config(spec, 256, lookup=True)\n    toks = [int(t) for t in np.random.default_rng(2).integers(0, 1000, 3)]\n\n    def engine(fill):\n        e = Engine(spec, W, cap=256, cfg=cfg, resident=True, prog_cache=True)\n        e.image.stream_fill = fill\n        return e\n\n    plain, filling = engine(False), engine(True)\n    s0 = dict(PC.stats)\n    for t in toks:\n        assert np.array_equal(plain.step(t).view(np.uint32), filling.step(t).view(np.uint32))\n    assert PC.stats[\"compile\"] - s0[\"compile\"] == 2\n    gate = fill_gate(filling._decode(0)[0][0])\n    with pytest.raises(ValueError):\n        fill_gate(plain._decode(0)[0][0])\n    PC.clear()\n    again = engine(True)\n    s1 = dict(PC.stats)\n    assert np.array_equal(again.step(toks[0]).view(np.uint32),\n                          engine(False).step(toks[0]).view(np.uint32))\n    assert PC.stats[\"disk\"] - s1[\"disk\"] == 2 and PC.stats[\"compile\"] == s1[\"compile\"]\n    assert fill_gate(again._decode(0)[0][0]) == gate\n    PC.clear()\n\n\ndef test_the_mtp_loop_programs_come_from_the_cache(tmp_path, monkeypatch):\n    \"\"\"MTP's loop programs (V, E, D, D1 of a bucket) through the cache: a new process's engine\n    reads them from disk and gives the tokens of an engine without the cache.\"\"\"\n    import dataclasses\n\n    from test_mtp import _mtp_weights\n    from opentpu.isasim import board_config\n    from opentpu.llm.mtp import NK, MTPDecoder, mtp_engine\n    monkeypatch.setenv(\"OTPU_PROG_CACHE\", str(tmp_path))\n    PC.clear()\n    W, spec = _tiny(\"qwen35\")\n    spec = dataclasses.replace(spec, mtp=True)\n    W = _mtp_weights(W, spec)\n    cfg = board_config(DRAM_BYTES=1 << 25, DSTEP=True, STREAM=True, PAIR=True)\n    prompt = [int(t) for t in np.random.default_rng(3).integers(0, 1000, 20)]\n\n    def run(cache):\n        eng = mtp_engine(spec, W, cap=512, cfg=cfg, prog_cache=cache)\n        return MTPDecoder(eng).generate_card(prompt, max_new=10).tokens\n\n    want = run(False)\n    s0 = dict(PC.stats)\n    assert run(True) == want\n    assert PC.stats[\"compile\"] - s0[\"compile\"] == NK      # bucket 1's\n    PC.clear()\n    s1 = dict(PC.stats)\n    assert run(True) == want\n    assert PC.stats[\"compile\"] == s1[\"compile\"] and PC.stats[\"disk\"] - s1[\"disk\"] == NK\n    PC.clear()\n", "tests/test_pytest_tmp.py": "\"\"\"The test session's temporary root (tests/conftest.py): one per pytest process, so gates running\nside by side on one host never remove each other's directories.\"\"\"\nimport os\nfrom pathlib import Path\n\nimport pytest\n\n\ndef test_the_session_has_a_temporary_root_of_its_own(request, tmp_path):\n    own = getattr(request.config, \"_otpu_basetemp\", None)\n    if own is None:\n        pytest.skip(\"--basetemp given: the caller chose the root\")\n    assert Path(own).name == f\"pid-{os.getpid()}\"\n    assert Path(own).resolve() in tmp_path.resolve().parents\n", "tests/test_qcache.py": "\"\"\"opentpu/qcache.py, the disk cache of the 4-bit quantizer's results, and opentpu/host/prebuild.py:\nthe cached result is the quantizer's, bit for bit; the key follows the content, the format and\nD; the size cap, the free-disk floor, a damaged entry, the off switch; and an image prebuilt\nfor the card's tools comes out of the cache, whole, for every layout a tool builds.\"\"\"\nimport os\nimport pickle\nfrom pathlib import Path\n\nimport numpy as np\nimport pytest\n\nfrom opentpu import qcache\nfrom opentpu.host import prebuild as PB\nfrom opentpu import quant as Q\nfrom opentpu.llm.qwen3 import Engine, Spec, device_config\n\n@pytest.fixture\ndef cache(tmp_path, monkeypatch):\n    \"\"\"A fresh cache for every matrix size; the counts from zero.\"\"\"\n    monkeypatch.setenv(\"OTPU_IMAGE_CACHE\", str(tmp_path))\n    monkeypatch.setattr(qcache, \"MIN_ELEMS\", 0)\n    monkeypatch.setattr(qcache, \"FREE_FLOOR\", 0)\n    monkeypatch.setattr(qcache, \"stats\", dict.fromkeys(qcache.stats, 0))\n    return tmp_path\n\n\ndef _w(seed, n=96, k=256):\n    return np.random.default_rng(seed).normal(0, 0.05, (n, k)).astype(np.float32)\n\n\ndef _entries(d):\n    return sorted(p for p in Path(d).glob(\"*/*.npz\") if not p.name.startswith(\".\"))\n\n\ndef _entry(d, W):\n    k = qcache.key(W, \"fp4\", 128)\n    return Path(d) / k[:2] / f\"{k}.npz\"\n\n\n@pytest.mark.parametrize(\"fmt\", [\"fp4\", \"int4\", \"nvfp4\"])\ndef test_cached_result_is_the_quantizers(cache, fmt):\n    W = _w(0)\n    want = Q.quantize_mxu(W, fmt, 128)\n    for n in range(2):                          # a miss that writes, then a hit\n        q, s = qcache.quantize_mxu(W, fmt, 128)\n        assert q.dtype == want[0].dtype and s.dtype == want[1].dtype\n        assert np.array_equal(q, want[0]) and np.array_equal(s, want[1])\n    assert qcache.stats == {\"hit\": 1, \"miss\": 1, \"write\": 1, \"skip\": 0}\n    assert len(_entries(cache)) == 1\n\n\ndef test_key_follows_content_format_d_and_numerics(monkeypatch):\n    W = _w(1)\n    k = qcache.key(W, \"fp4\", 128)\n    assert qcache.key(W.copy(), \"fp4\", 128) == k\n    assert qcache.key(np.asfortranarray(W), \"fp4\", 128) == k        # the values, not the layout\n    assert qcache.key(W.astype(np.float64), \"fp4\", 128) == k        # the quantizer's fp32 input\n    V = W.copy()\n    V[5, 7] = np.nextafter(V[5, 7], np.float32(1))\n    assert qcache.key(V, \"fp4\", 128) != k\n    assert qcache.key(W, \"int4\", 128) != k\n    assert qcache.key(W, \"fp4\", 64) != k\n    assert qcache.key(W.reshape(192, 128), \"fp4\", 128) != k         # the shape\n    assert qcache.key(W, \"nvfp4\", 128) != k\n    monkeypatch.setattr(Q, \"MX_NUMERICS\", \"pre-mx\")                 # the MXU's numerics\n    monkeypatch.setattr(qcache, \"_SRC\", None)\n    assert qcache.key(W, \"fp4\", 128) != k\n    monkeypatch.undo()\n    assert qcache.key(W, \"fp4\", 128) == k\n\n\ndef test_off_small_and_int8_are_not_cached(cache, monkeypatch):\n    W = _w(2)\n    qcache.quantize_mxu(W, \"int8\", 128)\n    monkeypatch.setattr(qcache, \"MIN_ELEMS\", W.size + 1)\n    qcache.quantize_mxu(W, \"fp4\", 128)\n    monkeypatch.setattr(qcache, \"MIN_ELEMS\", 0)\n    monkeypatch.setenv(\"OTPU_IMAGE_CACHE\", \"0\")\n    assert qcache.cache_dir() is None\n    q, s = qcache.quantize_mxu(W, \"fp4\", 128)\n    assert np.array_equal(q, Q.quantize_mxu(W, \"fp4\", 128)[0])\n    assert _entries(cache) == [] and qcache.stats[\"miss\"] == 0\n\n\ndef test_no_write_under_the_free_disk_floor(cache, monkeypatch):\n    monkeypatch.setattr(qcache, \"FREE_FLOOR\", 1 << 62)\n    qcache.quantize_mxu(_w(3), \"fp4\", 128)\n    assert _entries(cache) == [] and qcache.stats[\"skip\"] == 1\n\n\ndef test_least_recently_used_go_over_the_cap(cache, monkeypatch):\n    import os\n    import time\n    Ws = [_w(10 + i) for i in range(5)]\n    for W in Ws[:4]:\n        qcache.quantize_mxu(W, \"fp4\", 128)\n    size = _entry(cache, Ws[0]).stat().st_size\n    t = time.time() - 100\n    for i, W in enumerate(Ws[:4]):              # used in this order, then the first again\n        os.utime(_entry(cache, W), (t + i, t + i))\n    qcache.quantize_mxu(Ws[0], \"fp4\", 128)      # a hit: now the most recent\n    monkeypatch.setenv(\"OTPU_IMAGE_CACHE_GB\", str(3.5 * size / 2**30))\n    qcache.quantize_mxu(Ws[4], \"fp4\", 128)      # the fifth entry: over the cap of 3.5\n    left = set(_entries(cache))\n    assert _entry(cache, Ws[1]) not in left and _entry(cache, Ws[2]) not in left  # the oldest\n    assert {_entry(cache, Ws[i]) for i in (0, 3, 4)} <= left\n\n\ndef test_damaged_entry_is_quantized_again(cache):\n    W = _w(4)\n    qcache.quantize_mxu(W, \"fp4\", 128)\n    f = _entries(cache)[0]\n    f.write_bytes(b\"not an npz\")\n    q, _ = qcache.quantize_mxu(W, \"fp4\", 128)\n    assert np.array_equal(q, Q.quantize_mxu(W, \"fp4\", 128)[0])\n    assert qcache.stats[\"miss\"] == 2 and qcache.stats[\"write\"] == 2\n    with np.load(f) as z:\n        assert np.array_equal(z[\"q\"], q)\n\n\n@pytest.mark.parametrize(\"fmt\", [\"fp4\", \"int4\", \"int8\", \"nvfp4\"])\ndef test_quantize_rows_is_the_quantizers(fmt, monkeypatch):\n    \"\"\"quantize_rows, the quantizer on PIECE elements' rows at a time, gives the whole matrix's\n    result bit for bit (rows of one piece, of several, a short last piece; scale ties and\n    zero blocks included).\"\"\"\n    W = _w(5, 97, 512)\n    W[3] = 0\n    W[7, :128] = 1.5\n    want = Q.quantize_mxu(W, fmt, 128)\n    for piece in (512, 1500, 4096, 1 << 20):\n        monkeypatch.setattr(qcache, \"PIECE\", piece)\n        q, s = qcache.quantize_rows(W, fmt, 128)\n        assert q.dtype == want[0].dtype and s.dtype == want[1].dtype\n        assert np.array_equal(q, want[0]) and np.array_equal(s, want[1])\n\n\ndef test_batch_quantizes_in_workers_through_the_cache(cache, monkeypatch):\n    \"\"\"Batch: every matrix's done() gets the quantizer's result, bit for bit, whether it came\n    from the cache, was quantized here (under INLINE elements; int8 small) or in the worker\n    processes, its rows in several jobs; the misses are written; a second batch finds every\n    4-bit matrix in the cache and starts no worker.\"\"\"\n    monkeypatch.setattr(qcache, \"INLINE\", 96 * 256 + 1)     # 96 x 256 here, 160 x 256 there\n    monkeypatch.setattr(qcache, \"JOB\", 7 * 256)         # 7 rows a job\n    mats = [(_w(20 + i, 160 if i % 2 else 96), fmt) for i, fmt in\n            enumerate((\"fp4\", \"int4\", \"int8\", \"fp4\", \"int8\", \"fp4\"))]\n    for n in range(2):\n        got = {}\n        b = qcache.Batch(jobs=2)\n        for i, (W, fmt) in enumerate(mats):\n            b.submit(W, fmt, 128, lambda q, s, i=i: got.setdefault(i, (q, s)))\n        b.wait()\n        assert sorted(got) == list(range(len(mats)))\n        for i, (W, fmt) in enumerate(mats):\n            want = Q.quantize_mxu(W, fmt, 128)\n            assert np.array_equal(got[i][0], want[0]) and np.array_equal(got[i][1], want[1])\n        if n == 0:\n            assert qcache.stats == {\"hit\": 0, \"miss\": 4, \"write\": 4, \"skip\": 0}\n    assert qcache.stats == {\"hit\": 4, \"miss\": 4, \"write\": 4, \"skip\": 0}\n    b = qcache.Batch(jobs=2)\n    b.submit(mats[0][0], \"fp4\", 128, lambda q, s: None)\n    assert b._pool is None\n    b.wait()\n\n\n@pytest.fixture(scope=\"module\")\ndef tiny():\n    torch = pytest.importorskip(\"torch\")\n    transformers = pytest.importorskip(\"transformers\")\n    torch.manual_seed(0)\n    hc = transformers.Qwen3Config(hidden_size=256, num_hidden_layers=2, num_attention_heads=4,\n                                  num_key_value_heads=2, head_dim=128, intermediate_size=512,\n                                  vocab_size=1000, rms_norm_eps=1e-6, rope_theta=1e6,\n                                  tie_word_embeddings=True, max_position_embeddings=4096)\n    m = transformers.Qwen3ForCausalLM(hc).float().eval()\n    W = {k: v.float().numpy() for k, v in m.state_dict().items()}\n    return W, Spec(256, 2, 4, 2, 128, 512, 1000)\n\n\n@pytest.mark.parametrize(\"head\", [\"int8\", \"fp4\"])\ndef test_card_tools_find_the_prebuilt_image(cache, tiny, head, monkeypatch):\n    \"\"\"prebuild's image fills the cache with every 4-bit matrix; then the tools' Engines,\n    per-position or resident, at another KV capacity and prefill rows, quantize nothing, and\n    their images are the uncached build's, byte for byte.\"\"\"\n    W, spec = tiny\n    cfg = device_config(spec, 512, lookup=True)         # the card's: room for every layout\n    n = PB.prebuild(cfg, spec, W, \"fp4\", head)\n    assert n[\"miss\"] > 0 and n[\"write\"] == n[\"miss\"] and n[\"hit\"] == 0\n    for kw in ({\"cap\": 256, \"resident\": True}, {\"cap\": 512, \"resident\": False, \"rows\": 2}):\n        s0 = dict(qcache.stats)\n        eng = Engine(spec, W, cfg=cfg, wformat=\"fp4\", head_format=head, **kw)\n        got = eng.image.build(W)                # the Engine's build plus this one\n        assert qcache.stats[\"miss\"] == s0[\"miss\"]\n        assert qcache.stats[\"hit\"] - s0[\"hit\"] == 2 * n[\"miss\"]\n        monkeypatch.setenv(\"OTPU_IMAGE_CACHE\", \"0\")\n        want = eng.image.build(W)\n        monkeypatch.setenv(\"OTPU_IMAGE_CACHE\", str(cache))\n        assert len(got) == len(want)\n        assert all(np.array_equal(a, b) for a, b in zip(got, want))\n\n\ndef test_build_jobs_fit_in_memory(monkeypatch):\n    monkeypatch.delenv(\"OTPU_BUILD_JOBS\", raising=False)\n    monkeypatch.setattr(qcache.os, \"sched_getaffinity\", lambda pid: set(range(8)), raising=False)\n    monkeypatch.setattr(qcache, \"mem_gb\", lambda: 10.0)\n    assert qcache.build_jobs() == 8             # (workers of no stated size: the CPUs)\n    assert qcache.build_jobs(1.5) == 4          # (10 GiB - RESERVE_GB) / 1.5\n    monkeypatch.setattr(qcache, \"mem_gb\", lambda: 2.0)\n    assert qcache.build_jobs(1.5) == 1\n    monkeypatch.setattr(qcache, \"mem_gb\", lambda: None)\n    assert qcache.build_jobs(1.5) == 8          # (no /proc/meminfo)\n    monkeypatch.setenv(\"OTPU_BUILD_JOBS\", \"6\")\n    monkeypatch.setattr(qcache, \"mem_gb\", lambda: 2.0)\n    assert qcache.build_jobs(1.5) == 6          # (the variable decides)\n\n\n@pytest.mark.parametrize(\"wf\", [\"fp4\", \"int8\"])\ndef test_build_in_workers_is_the_serial_build(tiny, wf, monkeypatch):\n    \"\"\"An image built with its matrices quantized in worker processes (Batch: OTPU_BUILD_JOBS\n    2, every matrix there, in jobs of a few rows) is the build in one process, byte for byte.\"\"\"\n    W, spec = tiny\n    eng = Engine(spec, W, cap=256, wformat=wf, head_format=\"int8\", resident=True)\n    monkeypatch.setenv(\"OTPU_BUILD_JOBS\", \"1\")\n    want = eng.image.build(W)\n    monkeypatch.setenv(\"OTPU_BUILD_JOBS\", \"2\")\n    monkeypatch.setattr(qcache, \"INLINE\", 0)\n    monkeypatch.setattr(qcache, \"JOB\", 5 * 256)\n    got = eng.image.build(W)\n    assert len(got) == len(want) and all(np.array_equal(a, b) for a, b in zip(got, want))\n\n\ndef test_prebuild_main_picks_runs_configuration_and_memory(tmp_path, monkeypatch, capsys):\n    \"\"\"prebuild's command line: only the 4-bit runs; --cfg, else OTPU_PREBUILD_CFG, else the\n    production deploy's, else the newest kept card configuration; no build under MIN_GB.\"\"\"\n    assert [PB.is_4bit(r) for r in (\"a:int8:-\", \"a:fp4:int8\", \"a:int8:fp4\", \"a:int4:-\")] == \\\n        [False, True, True, True]\n    monkeypatch.setenv(\"HOME\", str(tmp_path))\n    monkeypatch.delenv(\"OTPU_PREBUILD_CFG\", raising=False)\n    assert PB.default_cfg() is None\n    kept = tmp_path / \"otpu-build/refcache/configs\"\n    kept.mkdir(parents=True)\n    for i, n in enumerate((\"old\", \"new\")):\n        (kept / f\"{n}.pkl\").write_bytes(pickle.dumps(i))\n        os.utime(kept / f\"{n}.pkl\", (1000 + i, 1000 + i))\n    assert PB.default_cfg() == kept / \"new.pkl\"\n    prod = tmp_path / \"otpu-build/production/qual\"\n    prod.mkdir(parents=True)\n    (prod / \"cfg.pkl\").write_bytes(pickle.dumps(2))\n    assert PB.default_cfg() == prod / \"cfg.pkl\"\n    monkeypatch.setenv(\"OTPU_PREBUILD_CFG\", str(kept / \"old.pkl\"))\n    assert PB.default_cfg() == kept / \"old.pkl\"\n    monkeypatch.setenv(\"OTPU_IMAGE_CACHE\", str(tmp_path / \"c\"))\n    monkeypatch.setattr(PB, \"mem_gb\", lambda: 3.0)\n    built = []\n    monkeypatch.setattr(PB, \"prebuild\", lambda *a, **k: built.append(a))\n    assert PB.main([\"qwen3:int8:-\", \"qwen3:fp4:int8\"]) == 0\n    out = capsys.readouterr().out\n    assert \"configuration \" + str(kept / \"old.pkl\") in out and \"; qwen3:fp4:int8\" in out\n    assert \"qwen3:fp4:int8: not built, MemAvailable 3.0 GiB\" in out and built == []\n    monkeypatch.setenv(\"OTPU_IMAGE_CACHE\", \"0\")\n    assert PB.main([\"qwen3:fp4:int8\"]) == 0 and \"cache is off\" in capsys.readouterr().out\n\n\ndef test_otpu_lock_prebuilds_before_the_lock(tmp_path, monkeypatch):\n    \"\"\"otpu-lock --prebuild: opentpu.host.prebuild at nice 19 first, then CMD under the lock.\"\"\"\n    import subprocess\n    from opentpu.host import runstate\n    monkeypatch.setenv(\"OTPU_RUN_DIR\", str(tmp_path))\n    calls = []\n    monkeypatch.setattr(subprocess, \"call\", lambda cmd, env=None: calls.append((cmd, env)) or 0)\n    monkeypatch.setattr(runstate, \"_run\", lambda cmd, env: calls.append((cmd, env)) or 0)\n    assert runstate.hold_main([\"--dev\", \"/dev/fake9\", \"--wait\", \"0\", \"--prebuild\", \"m:fp4:int8\",\n                               \"--prebuild-cfg\", \"c.pkl\", \"--\", \"true\", \"x\"]) == 0\n    (pre, _), (cmd, env) = calls\n    assert pre[:3] == [\"nice\", \"-n\", \"19\"] and pre[4:] == [\"-m\", \"opentpu.host.prebuild\", \"--cfg\",\n                                                           \"c.pkl\", \"m:fp4:int8\"]\n    assert cmd == [\"true\", \"x\"] and env[\"OTPU_LOCK_HELD\"] == \"fake9\"\n    assert env[\"OTPU_LOCK_PID\"] == str(os.getpid())\n    calls.clear()\n    assert runstate.hold_main([\"--dev\", \"/dev/fake9\", \"--\", \"true\"]) == 0\n    assert [c for c, _ in calls] == [[\"true\"]]\n\n\nclass _Child:\n    \"\"\"A run's build process for prebuild.main: done after `steps` polls; `during(n)` is called\n    at the n-th poll (a session going quiet mid-build).\"\"\"\n    log: list = []\n\n    def __init__(self, cmd, steps=3, during=None):\n        self.run, self.left, self.during, self.n, self.returncode = cmd[-1], steps, during, 0, None\n        _Child.log.append((\"start\", self.run))\n\n    def poll(self):\n        self.n += 1\n        if self.during:\n            self.during(self.n)\n        self.left -= 1\n        if self.left <= 0 and self.returncode is None:\n            self.returncode = 0\n            _Child.log.append((\"done\", self.run))\n        return self.returncode\n\n    def terminate(self):\n        _Child.log.append((\"stop\", self.run))\n\n    def wait(self):\n        self.returncode = -15\n\n\ndef test_prebuild_keeps_quiet_while_a_session_measures(tmp_path, monkeypatch, capsys):\n    \"\"\"The quiet file (~/otpu-build/QUIET with a live pid: a session measures host-sensitive\n    performance): prebuild starts no build while it is there, stops a build when it appears and\n    builds that run again after it, ignores a file whose pid is gone, and gives up after\n    OTPU_PREBUILD_QUIET_WAIT seconds, leaving the quantizing to the tools.\"\"\"\n    import subprocess\n    import threading\n    q = tmp_path / \"QUIET\"\n    monkeypatch.setenv(\"OTPU_QUIET\", str(q))\n    monkeypatch.setenv(\"OTPU_IMAGE_CACHE\", str(tmp_path / \"c\"))\n    cfg = tmp_path / \"cfg.pkl\"\n    cfg.write_bytes(pickle.dumps(0))\n    monkeypatch.setattr(PB, \"POLL\", 0.01)\n    monkeypatch.setattr(PB, \"mem_gb\", lambda: 64.0)\n    runs = [\"--cfg\", str(cfg), \"a:fp4:int8\", \"b:fp4:int8\"]\n\n    def later(f, s=0.2):\n        threading.Timer(s, f).start()\n\n    _Child.log = []                             # quiet at the start: no build until it goes\n    q.write_text(str(os.getpid()))\n    monkeypatch.setattr(PB, \"_spawn\", lambda cmd: (_Child.log.append((\"quiet\", q.exists())),\n                                                   _Child(cmd))[1])\n    later(q.unlink)\n    assert PB.main(runs) == 0\n    assert _Child.log[0] == (\"quiet\", False) and (\"done\", \"b:fp4:int8\") in _Child.log\n    assert \"waiting while\" in capsys.readouterr().out\n\n    _Child.log = []                             # quiet mid-build: stopped, then again after it\n\n    def go_quiet(n):\n        if n == 2 and not _Child.log.count((\"stop\", \"a:fp4:int8\")):\n            q.write_text(str(os.getpid()))\n            later(q.unlink, 1.0)            # long after _watch's look, even on a busy host\n    monkeypatch.setattr(PB, \"_spawn\", lambda cmd: _Child(cmd, during=go_quiet))\n    assert PB.main(runs) == 0\n    assert _Child.log == [(\"start\", \"a:fp4:int8\"), (\"stop\", \"a:fp4:int8\"),\n                          (\"start\", \"a:fp4:int8\"), (\"done\", \"a:fp4:int8\"),\n                          (\"start\", \"b:fp4:int8\"), (\"done\", \"b:fp4:int8\")]\n    assert \"a:fp4:int8: stopped\" in capsys.readouterr().out\n\n    _Child.log = []                             # a quiet file whose session is gone: ignored\n    p = subprocess.Popen([\"true\"])\n    p.wait()\n    q.write_text(str(p.pid))\n    monkeypatch.setattr(PB, \"_spawn\", lambda cmd: _Child(cmd))\n    assert PB.main(runs) == 0 and len(_Child.log) == 4\n\n    _Child.log = []                             # a quiet session that stays: prebuild gives up\n    q.write_text(str(os.getpid()))\n    monkeypatch.setenv(\"OTPU_PREBUILD_QUIET_WAIT\", \"0.05\")\n    assert PB.main(runs) == 0 and _Child.log == []\n    assert \"the tools quantize the rest under the lock\" in capsys.readouterr().out\n\n\ndef test_prebuild_removes_old_temporary_files(tmp_path, monkeypatch, capsys):\n    \"\"\"A build killed while writing a cache entry leaves `.<key>.<pid>.npz`, which the size cap\n    does not count: prebuild removes those older than an hour, and not a fresh one (a write in\n    progress).\"\"\"\n    import time\n    c = tmp_path / \"c\"\n    (c / \"ab\").mkdir(parents=True)\n    old, new, entry = c / \"ab/.abc.12.npz\", c / \"ab/.abd.13.npz\", c / \"ab/abe.npz\"\n    for f in (old, new, entry):\n        f.write_bytes(b\"x\")\n    t = time.time() - 7200\n    os.utime(old, (t, t))\n    os.utime(entry, (t, t))\n    monkeypatch.setenv(\"OTPU_IMAGE_CACHE\", str(c))\n    cfg = tmp_path / \"cfg.pkl\"\n    cfg.write_bytes(pickle.dumps(0))\n    assert PB.main([\"--cfg\", str(cfg), \"a:int8:-\"]) == 0\n    assert not old.exists() and new.exists() and entry.exists()\n    assert \"removed 1 temporary files\" in capsys.readouterr().out\n", "tests/test_qual_refs.py": "\"\"\"tools/qual/refs.py: the reference cache key, the references (tokens past EOS, every logits\nvector's digest), the card check's comparison and its fail-fast wait (no card: a fake engine).\"\"\"\nimport importlib.util\nimport json\nimport os\nimport pickle\nimport re\nimport socket\nimport threading\nimport time\nfrom pathlib import Path\nfrom types import SimpleNamespace\n\nimport numpy as np\nimport pytest\n\nROOT = Path(__file__).resolve().parent.parent\nspec = importlib.util.spec_from_file_location(\"qual_refs\", ROOT / \"tools/qual/refs.py\")\nrefs = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(refs)\n\n\ndef test_source_hash_ignores_host_code(tmp_path):\n    pkg = tmp_path / \"opentpu\"\n    (pkg / \"host\").mkdir(parents=True)\n    (pkg / \"compiler.py\").write_text(\"a = 1\\n\")\n    (pkg / \"host\" / \"board.py\").write_text(\"POLL = 1\\n\")\n    (pkg / \"host\" / \"offload.py\").write_text(\"LINE = 64\\n\")\n    h0 = refs.source_hash(pkg)\n    (pkg / \"host\" / \"board.py\").write_text(\"POLL = 2\\n\")       # a poll fix: same references\n    assert refs.source_hash(pkg) == h0\n    (pkg / \"compiler.py\").write_text(\"a = 2\\n\")                 # a compiler change: new ones\n    h1 = refs.source_hash(pkg)\n    assert h1 != h0\n    (pkg / \"host\" / \"offload.py\").write_text(\"LINE = 128\\n\")    # host code the models import\n    assert refs.source_hash(pkg) != h1                          # (before: the same)\n\n\ndef test_the_host_code_the_models_import_is_hashed():\n    \"\"\"Every opentpu.host module that the hashed sources import (the reference's path) is in\n    HOST_IN_REF: an edit to it computes new references.\"\"\"\n    pat = re.compile(r\"from (?:\\.\\.|opentpu\\.)host\\.(\\w+) import|import opentpu\\.host\\.(\\w+)\")\n    used = set()\n    for rel, p in refs.sources():\n        if not rel.startswith(\"host/\"):\n            used |= {f\"host/{a or b}.py\" for a, b in pat.findall(p.read_text())}\n    assert used and used <= set(refs.HOST_IN_REF), used\n\n\ndef test_env_key_has_the_kernels_variables_not_the_runtime_ones(tmp_path, monkeypatch):\n    pkg = tmp_path / \"opentpu\"\n    (pkg / \"llm\").mkdir(parents=True)\n    (pkg / \"host\").mkdir()\n    (pkg / \"llm\" / \"gemma4.py\").write_text('os.environ.get(\"OTPU_PLE_FORMAT\")\\n'\n                                           'os.environ.get(\"OTPU_FORMATS\")\\n')\n    (pkg / \"progcache.py\").write_text('os.environ.get(\"OTPU_PROG_CACHE\")\\n')\n    (pkg / \"simtmp.py\").write_text('os.environ.get(\"OTPU_SIM_TMP\")\\n')\n    (pkg / \"host\" / \"runstate.py\").write_text('os.environ.get(\"OTPU_LOCK_HELD\")\\n')\n    for k in list(os.environ):\n        if k.startswith(\"OTPU_\"):\n            monkeypatch.delenv(k)\n    assert refs.env_key(pkg) == {}\n    for k in (\"OTPU_PROG_CACHE\", \"OTPU_SIM_TMP\", \"OTPU_LOCK_HELD\"):     # runtime, host-only\n        monkeypatch.setenv(k, \"1\")\n    assert refs.env_key(pkg) == {}\n    monkeypatch.setenv(\"OTPU_PLE_FORMAT\", \"fp4\")\n    monkeypatch.setenv(\"OTPU_FORMATS\", \"\")                              # set, empty\n    assert refs.env_key(pkg) == {\"OTPU_FORMATS\": \"\", \"OTPU_PLE_FORMAT\": \"fp4\"}\n\n\ndef test_parse_run():\n    assert refs.parse_run(\"qwen3:int8:-\") == (\"qwen3\", \"int8\", \"-\", False, False, False)\n    assert refs.parse_run(\"lfm2:int8\") == (\"lfm2\", \"int8\", \"-\", False, False, False)\n    assert refs.parse_run(\"lfm2:int8:-:long,pr\") == (\"lfm2\", \"int8\", \"-\", True, True, False)\n    assert refs.parse_run(\"phi4-mini:mix:-:xl,pr\") == (\"phi4-mini\", \"mix\", \"-\", False, True,\n                                                        True)\n    with pytest.raises(ValueError):\n        refs.parse_run(\"lfm2:int8:-:loong\")\n    with pytest.raises(ValueError):                             # one prompt a run\n        refs.parse_run(\"lfm2:int8:-:long,xl\")\n\n\ndef test_the_xl_prompt_ends_in_its_bucket():\n    \"\"\"The xl prompt (XL_TOKENS at most) reaches bucket XL_BUCKET (Phi-4-mini's 12-row looped\n    tiles from bucket 6, docs/tiled_prefill.md 13) and NTOK tokens' decode stays in it, within\n    CAP_XL; xl_fits is the card check's test of a prompt's length.\"\"\"\n    lo = (refs.XL_BUCKET - 1) * refs.ATTN_BLOCK\n    assert lo < refs.XL_TOKENS - 64 and refs.xl_fits(refs.XL_TOKENS - 64, refs.NTOK)\n    assert refs.xl_fits(refs.XL_TOKENS, refs.NTOK) and not refs.xl_fits(lo, refs.NTOK)\n    assert not refs.xl_fits(refs.XL_BUCKET * refs.ATTN_BLOCK - refs.NTOK + 2, refs.NTOK)\n    assert refs.cap(True) == refs.CAP_XL >= refs.XL_BUCKET * refs.ATTN_BLOCK\n    assert refs.cap() == refs.CAP\n\n\ndef _pending(kp, pid, age=0.0, host=None):\n    refs.side(kp, \".pending\").write_text(json.dumps(\n        {\"host\": host or socket.gethostname(), \"pid\": pid, \"t\": time.time() - age}))\n\n\ndef test_wait_ref_fails_fast_without_a_job(tmp_path):\n    kp = tmp_path / \"r.pkl\"\n    t0 = time.time()\n    assert \"no job computing it\" in refs.wait_ref(kp)\n    assert time.time() - t0 < 1\n\n\ndef test_wait_ref_fails_fast_on_a_dead_job(tmp_path):\n    kp = tmp_path / \"r.pkl\"\n    _pending(kp, pid=2 ** 22 + 12345)                           # no such process\n    assert \"died\" in refs.wait_ref(kp)\n    _pending(kp, pid=os.getpid(), age=refs.STALE + 5)           # alive but no heartbeat\n    assert \"died\" in refs.wait_ref(kp)\n\n\ndef test_wait_ref_reports_a_failed_job(tmp_path):\n    kp = tmp_path / \"r.pkl\"\n    refs.side(kp, \".failed\").write_text(\"killed by signal 9 (the OOM killer?)\")\n    assert \"OOM\" in refs.wait_ref(kp)\n\n\ndef test_wait_ref_waits_for_a_live_job(tmp_path, monkeypatch):\n    kp = tmp_path / \"r.pkl\"\n    _pending(kp, pid=os.getpid())\n    nap = time.sleep\n    monkeypatch.setattr(refs.time, \"sleep\", lambda s: nap(0.05))\n    threading.Timer(0.3, lambda: kp.write_bytes(b\"x\")).start()\n    assert refs.wait_ref(kp) is None\n\n\n@pytest.mark.skipif(not (ROOT / \"models/LFM2.5-230M\").exists(), reason=\"no LFM2 checkpoint\")\ndef test_key_is_stable_and_format_specific(monkeypatch):\n    from opentpu.isasim import board_config\n    cfg = board_config()\n    a, parts = refs.key(cfg, \"lfm2\", \"int8\", \"-\", 32)\n    b, _ = refs.key(cfg, \"lfm2\", \"int8\", \"-\", 32)\n    c, _ = refs.key(cfg, \"lfm2\", \"fp4\", \"int8\", 32)\n    assert a == b and a != c and parts[\"v\"] == refs.VERSION\n    assert str(ROOT) not in json.dumps(parts)                   # no machine-specific paths\n    long_, lp = refs.key(cfg, \"lfm2\", \"int8\", \"-\", 32, long=True)\n    pr, _ = refs.key(cfg, \"lfm2\", \"int8\", \"-\", 32, long=True, pr=True)\n    assert len({a, long_, pr}) == 3 and \"_long_pr_\" in pr.name and lp[\"ids\"] != parts[\"ids\"]\n    xl, xp = refs.key(cfg, \"lfm2\", \"int8\", \"-\", 32, pr=True, xl=True)\n    assert xl not in (a, long_, pr) and \"_xl_pr_\" in xl.name and xp[\"cap\"] == refs.CAP_XL\n    assert refs.run_key(cfg, \"lfm2:int8:-:xl,pr\", 32) == xl       # qual.sh's run: the same key\n    monkeypatch.setenv(\"OTPU_LOCK_HELD\", \"xdma0\")              # under otpu-lock: the same one\n    assert refs.key(cfg, \"lfm2\", \"int8\", \"-\", 32)[0] == a\n    monkeypatch.setenv(\"OTPU_MLP_UNROLL_BODIES\", \"4\")           # lfm2's programs: another one\n    assert refs.key(cfg, \"lfm2\", \"int8\", \"-\", 32)[0] != a       # (before: the same)\n\n\n@pytest.mark.skipif(not (ROOT / \"models/LFM2.5-230M\").exists(), reason=\"no LFM2 checkpoint\")\ndef test_the_long_prompt_crosses_the_bucket():\n    from transformers import AutoTokenizer\n    tok = AutoTokenizer.from_pretrained(ROOT / \"models/LFM2.5-230M\")\n    n = len(refs.prompt_ids(tok, long=True))\n    assert refs.LONG_TOKENS - 8 <= n <= refs.LONG_TOKENS < refs.ATTN_BLOCK\n    assert n + refs.NTOK - 2 >= refs.ATTN_BLOCK + 8             # decoded positions past 256\n    assert len(refs.prompt_ids(tok)) < 32\n    n = len(refs.prompt_ids(tok, xl=True))                      # the xl prompt: bucket 6\n    assert refs.XL_TOKENS - 8 <= n <= refs.XL_TOKENS and refs.xl_fits(n, refs.NTOK)\n\n\n# ---- the reference and the card check, with a fake engine\nV = 64\n\n\ndef _logits(pos, tok):\n    return np.random.default_rng(1000 * pos + tok).standard_normal(V).astype(np.float32)\n\n\nclass FakeEngine:\n    \"\"\"prefill / step / generate_card over seeded logits; `off` = {position: ulps} changes the\n    logits there (a card that is not bit-exact), `engaged` whether resident decode engages.\"\"\"\n    off, engaged = {}, True\n\n    def __init__(self, spec, W, cap, cfg, wformat, head_format, resident=False, backend=None,\n                 prompt_runs=False):\n        self.resident = resident and self.engaged\n        self.can_generate = self.resident\n        self.stats, self.pos = [], 0\n        self.backend = SimpleNamespace(close=lambda: None)\n\n    def _at(self, tok):\n        lg = _logits(self.pos, tok)\n        if self.pos in self.off:\n            lg.view(np.uint32)[0] += self.off[self.pos]\n        return lg\n\n    def prefill(self, ids):\n        self.pos = len(ids)\n        self.stats.append({\"rows\": len(ids), \"cycles\": 1e6})\n        return self._at(ids[-1])\n\n    def step(self, tok):\n        self.pos += 1\n        self.stats.append({\"cycles\": 1e6})\n        return self._at(tok)\n\n    def generate_card(self, tok, n, stop_ids=None):\n        assert stop_ids == []                   # past EOS\n        out = []\n        for _ in range(n):\n            tok = int(np.argmax(self.step(tok)))\n            out.append(tok)\n        return out\n\n    def _drain(self):\n        pass\n\n\n@pytest.fixture\ndef fake(tmp_path, monkeypatch):\n    from opentpu.host import board\n    from opentpu.llm import qwen3\n    kp = tmp_path / \"ref.pkl\"\n    tok = SimpleNamespace(decode=lambda ids, **kw: \"\".join(f\"<{i}>\" for i in ids))\n    monkeypatch.setattr(refs, \"key\", lambda *a, **kw: (kp, {\"model\": \"fake\"}))\n    monkeypatch.setattr(refs, \"load\", lambda m: (tmp_path, SimpleNamespace(eos=(0,)), {}, tok))\n    monkeypatch.setattr(refs, \"prompt_ids\", lambda t, long=False, xl=False: list(\n        range(1, refs.XL_TOKENS if xl else 240 if long else 22)))\n    monkeypatch.setattr(refs, \"prompt_runs_taken\", lambda eng, ids: True)\n    monkeypatch.setattr(qwen3, \"Engine\", FakeEngine)\n    monkeypatch.setattr(board, \"sim_config\", lambda *a, **kw: None)\n    monkeypatch.setattr(board, \"XdmaTransport\", lambda *a, **kw: None)\n    monkeypatch.setattr(FakeEngine, \"off\", {})\n    monkeypatch.setattr(FakeEngine, \"engaged\", True)\n    cfg = tmp_path / \"cfg.pkl\"\n    cfg.write_bytes(pickle.dumps(\"cfg\"))\n    return kp, cfg\n\n\ndef test_a_reference_is_ntok_tokens_past_eos_and_every_logits_digest(fake, tmp_path):\n    kp, cfg = fake\n    refs.side(kp, \".pending\").write_text(\"{}\")                  # compute queued it\n    assert refs.one(\"cfg\", \"m\", \"int8\", \"-\", 32) == 0\n    want = pickle.loads(kp.read_bytes())\n    assert want[\"v\"] == refs.VERSION and len(want[\"tokens\"]) == len(want[\"logits\"]) == 32\n    toks, digs = refs.greedy(FakeEngine(None, None, 0, None, \"int8\", None), list(range(1, 22)),\n                             32)\n    assert want[\"tokens\"] == toks and want[\"logits\"] == [d for d, _ in digs]\n    assert want[\"top\"][0][0] == (toks[0], float(_logits(21, 21)[toks[0]]))\n    assert not refs.side(kp, \".pending\").exists() and not list(tmp_path.glob(\"*.tmp\"))\n    refs.side(kp, \".pending\").write_text(\"{}\")                  # cached: no .pending left\n    assert refs.one(\"cfg\", \"m\", \"int8\", \"-\", 32) == 0 and not refs.side(kp, \".pending\").exists()\n\n\ndef test_the_card_check_compares_every_logits_vector(fake, capsys):\n    kp, cfg = fake\n    refs.one(\"cfg\", \"m\", \"int8\", \"-\", 32)\n    capsys.readouterr()\n    assert refs.card(cfg, \"m\", \"int8\", \"-\", 32, resident=True) == 0\n    assert \"[PASS] model m int8/- resident: 32 tokens and the logits of all 32 bit-exact\" \\\n        in capsys.readouterr().out\n    FakeEngine.off = {30: 1}                    # one ulp of one logit: the tokens stay\n    assert refs.card(cfg, \"m\", \"int8\", \"-\", 32, resident=False) == 1\n    out = capsys.readouterr().out\n    assert \"[FAIL] model m int8/-: token 9's logits differ\" in out, out\n    FakeEngine.off = {21: 1}                    # the prefill's: the card loop sees it too\n    assert refs.card(cfg, \"m\", \"int8\", \"-\", 32, resident=True, loop=True) == 1\n    assert \"[FAIL] model m int8/- resident card loop: token 0's logits differ\" in \\\n        capsys.readouterr().out\n\n\ndef test_a_check_that_does_not_test_what_it_says_fails(fake, capsys, monkeypatch):\n    kp, cfg = fake\n    refs.one(\"cfg\", \"m\", \"int8\", \"-\", 32)\n    FakeEngine.engaged = False          # before: \"[PASS] ... (resident decode not engaged)\"\n    assert refs.card(cfg, \"m\", \"int8\", \"-\", 32, resident=True) == 1\n    assert \"resident decode not engaged\" in capsys.readouterr().out\n    FakeEngine.engaged = True\n    monkeypatch.setattr(refs, \"prompt_runs_taken\", lambda eng, ids: False)\n    assert refs.card(cfg, \"m\", \"int8\", \"-\", 32, resident=True, prompt_runs=True) == 1\n    assert \"prompt runs not taken\" in capsys.readouterr().out\n    monkeypatch.setattr(refs, \"prompt_ids\", lambda t, long=False, xl=False: list(range(1, 200)))\n    assert refs.card(cfg, \"m\", \"int8\", \"-\", 32, resident=True, long=True) == 1\n    assert \"does not cross position 256\" in capsys.readouterr().out\n    assert refs.card(cfg, \"m\", \"int8\", \"-\", 32, resident=True, xl=True) == 1\n    assert \"the xl prompt (199 tokens) and its decode do not end in bucket 6\" in \\\n        capsys.readouterr().out\n\n\ndef test_an_old_reference_is_no_pass(fake, capsys):\n    kp, cfg = fake\n    kp.write_bytes(pickle.dumps([785, 6722, 315]))              # refs.py v1: a token list\n    assert refs.card(cfg, \"m\", \"int8\", \"-\", 32, resident=False) == 1\n    assert \"not of format 2\" in capsys.readouterr().out\n", "tests/test_qual_sh.py": "\"\"\"tools/qual/qual.sh without a card: a crashed step counts as a FAIL line, the model phases need\ntheir checkpoints, the card must run the candidate's build, and the exit status is 0 only for a\nqual that ran to its end without a FAIL line. The script runs from a scratch tree whose python\nis a stub: each tool prints what the real one would on a pass, or crashes (a traceback, exit\nstatus QUAL_CRASH_EXIT) when its command line contains QUAL_CRASH, or hangs when it contains\nQUAL_HANG. The card is a state file: the build it runs (QUAL_BUILD at first, then each JTAG\nload's: the bitstream's directory's last 8 hex digits; a load whose path contains QUAL_JTAG_FAIL\nfails, one that contains QUAL_JTAG_NOOP leaves the card as it was), the probe of BUILD_ID and\nCAPS reads it (QUAL_PROBE_FAIL: it crashes; QUAL_CAPS: bits 30 and 31), and dmesg prints\nQUAL_DMESG, then QUAL_DMESG_NEW too from its second call on. The model check (python -c) runs\nfor real, against the scratch tree's copy of opentpu/llm and its models/.\"\"\"\nimport os\nimport re\nimport shutil\nimport signal\nimport subprocess\nimport sys\nimport time\nfrom pathlib import Path\n\nimport pytest\n\nROOT = Path(__file__).resolve().parent.parent\nsys.path.insert(0, str(ROOT))\nfrom opentpu.llm import MODELS  # noqa: E402\n\nSTUB = r'''#!{python}\nimport os, sys, time\na = sys.argv[1:]\nstate = os.environ[\"QUAL_STATE\"]\nif a[0] == \"-c\" and \"Board(\" in a[1]:              # qual.sh's probe of BUILD_ID and CAPS\n    if os.environ.get(\"QUAL_PROBE_FAIL\"):\n        print(\"Traceback (most recent call last):\")\n        print(\"OSError: [Errno 2] No such file or directory: '/dev/xdma0_user'\")\n        sys.exit(1)\n    build = open(state).read().strip() if os.path.exists(state) else os.environ[\"QUAL_BUILD\"]\n    print(\"PROBE\", build, os.environ.get(\"QUAL_CAPS\", \"0 0\"))\n    sys.exit(0)\nif a[0] == \"-c\":                                    # qual.sh's model check: the real thing\n    os.execv(sys.executable, [sys.executable] + a)\ncrash = os.environ.get(\"QUAL_CRASH\")\nif crash and crash in \" \".join(a):\n    print(\"Traceback (most recent call last):\")\n    print('  File \"tool.py\", line 1, in <module>')\n    print(\"FileNotFoundError: [Errno 2] No such file or directory: 'models/Qwen3-0.6B/config.json'\")\n    sys.exit(int(os.environ.get(\"QUAL_CRASH_EXIT\", \"1\")))\nhang = os.environ.get(\"QUAL_HANG\")\nif hang and hang in \" \".join(a):\n    open(os.environ[\"QUAL_HUNG\"], \"w\").write(str(os.getpid()))\n    print(\"hanging\", flush=True)\n    time.sleep(600)\nif a[:2] == [\"-m\", \"opentpu.host.selftest\"]:\n    print(\"  [PASS] link       ID 0x4f545055  (0.0s)\")\n    print(\"ALL PASS\")\nelif a[:2] == [\"-m\", \"opentpu.host.diag\"]:\n    print(\"summary\")\n    print(\"ALL PASS\")\nelif a[:2] == [\"-m\", \"opentpu.host.smi\"]:\n    print(\"Temp 60 C\")\nelif a[:2] == [\"-m\", \"opentpu.host.runstate\"]:      # otpu-lock: prebuild, then CMD under the lock\n    k = a.index(\"--\")\n    pre = [a[i + 1] for i, x in enumerate(a[:k]) if x == \"--prebuild\"]\n    if pre:\n        print(\"prebuilt\", *pre, flush=True)\n    os.execvpe(a[k + 1], a[k + 1:], dict(os.environ, OTPU_LOCK_HELD=\"xdma0\"))\nelse:\n    tool = os.path.basename(a[0])\n    if tool == \"refs.py\" and a[1] == \"cfg\":\n        open(a[2], \"w\").write(\"cfg\")\n        print(\"config\")\n    elif tool == \"refs.py\" and a[1] == \"card\":\n        res = {\"--resident\", \"--card-loop\", \"--prompt-runs\"} & set(a)     # as refs.py's label\n        what = \"\".join(f\" {w}\" for w, on in ((\"long\", \"--long\" in a), (\"xl\", \"--xl\" in a),\n                                              (\"resident\", res),\n                                              (\"card loop\", \"--card-loop\" in a),\n                                              (\"prompt runs\", \"--prompt-runs\" in a)) if on)\n        print(f\"  [PASS] model {a[3]} {a[4]}/{a[5]}{what}: 32 tokens and the logits bit-exact\")\n    elif tool == \"turnaround.py\":\n        print(\"  [PASS] DRAM turnarounds, data: 1500 runs in 30.0 s\")\n        print(\"  [PASS] DRAM turnarounds, ECC: ch0 sec 0 ded 0, ch1 sec 0 ded 0\")\n    elif tool == \"waitw.py\":\n        print(\"  [PASS] WAITW on the host's writes: 200 rounds\")\n        print(\"  [PASS] WAITW timeout: ERROR at the timeout\")\n    elif tool == \"refs.py\" and a[1] == \"compute\":\n        print(\"compute\", *a[3:])\n    elif tool == \"decode_profile.py\":\n        print(\"wall 10.00 tok/s, device 10.00 tok/s\")\n    else:\n        print(f\"{tool} ok\")\n'''\n\nLOADER = r'''#!{python}\nimport os, re, sys\nbit = sys.argv[-1]\nfor k in (\"QUAL_JTAG_FAIL\", \"QUAL_JTAG_NOOP\"):\n    v = os.environ.get(k)\n    if v and v in bit:\n        if k == \"QUAL_JTAG_FAIL\":\n            print(\"unable to open ftdi device: -3 (device not found)\")\n            sys.exit(1)\n        break\nelse:\n    m = re.search(r\"_([0-9a-f]{8})$\", os.path.basename(os.path.dirname(os.path.realpath(bit))))\n    open(os.environ[\"QUAL_STATE\"], \"w\").write(m.group(1) if m else \"00000000\")\nprint(\"Load SRAM: [==================================================] 100.00%\")\nprint(\"ir: 1 isc_done 1 isc_ena 0 init 1 done 1\")\n'''\n\nSUDO = r'''#!{python}\nimport os, sys\na = \" \".join(sys.argv[1:])\nif \"dmesg\" in a:\n    n = os.environ[\"QUAL_STATE\"] + \".dmesg\"\n    calls = int(open(n).read()) + 1 if os.path.exists(n) else 1\n    open(n, \"w\").write(str(calls))\n    for k in (\"QUAL_DMESG\",) + ((\"QUAL_DMESG_NEW\",) if calls > 1 else ()):\n        if os.environ.get(k):\n            print(os.environ[k])\nelif \"rescan\" in a:\n    print(\"otpu device 0000:01:00.0 ID 0x4f545055\")\n'''\n\n\n@pytest.fixture\ndef qual(tmp_path):\n    \"\"\"run(models=True, **env) -> (stdout + stderr, checks.txt, exit status) of a fast qual.sh\n    run of deploy_t_e776703a.\"\"\"\n    tree = tmp_path / \"tree\"\n    (tree / \"tools/qual\").mkdir(parents=True)\n    shutil.copy(ROOT / \"tools/qual/qual.sh\", tree / \"tools/qual/qual.sh\")\n    (tree / \"opentpu/llm\").mkdir(parents=True)\n    (tree / \"opentpu/__init__.py\").write_text(\"\")\n    shutil.copy(ROOT / \"opentpu/llm/__init__.py\", tree / \"opentpu/llm/__init__.py\")\n    bin_ = tmp_path / \"bin\"\n    bin_.mkdir()\n    for name, text in [(\"python\", STUB), (\"openFPGALoader\", LOADER), (\"sudo\", SUDO),\n                       (\"timeout\", \"#!/bin/sh\\nshift\\nexec \\\"$@\\\"\\n\")]:   # timeout SECONDS CMD...\n        (bin_ / name).write_text(text.replace(\"{python}\", sys.executable))\n        (bin_ / name).chmod(0o755)\n    for d in (\"deploy_t_e776703a\", \"deploy_prod_542fc43a\"):\n        (tmp_path / d).mkdir()\n        (tmp_path / d / \"otpu.bit\").write_text(\"bit\")\n    (tmp_path / \"production\").symlink_to(tmp_path / \"deploy_prod_542fc43a\")\n\n    def env(models=True, **kw):\n        if models:\n            for d in MODELS.values():\n                (tree / \"models\" / d).mkdir(parents=True, exist_ok=True)\n                (tree / \"models\" / d / \"config.json\").write_text(\"{}\")\n        out = tmp_path / \"out\"\n        for f in (tmp_path / \"state\", tmp_path / \"state.dmesg\"):\n            f.unlink(missing_ok=True)\n        e = dict(os.environ, PATH=f\"{bin_}:{os.environ['PATH']}\", PYTHON=str(bin_ / \"python\"),\n                 LOAD=\"0\", OUT=str(out), SOAK=\"1\", QUAL_STATE=str(tmp_path / \"state\"),\n                 QUAL_BUILD=\"e776703a\", QUAL_HUNG=str(tmp_path / \"hung\"))\n        e.update(kw)\n        return e, out\n\n    def run(models=True, **kw):\n        e, out = env(models, **kw)\n        r = subprocess.run([\"bash\", str(tree / \"tools/qual/qual.sh\"),\n                            str(tmp_path / \"deploy_t_e776703a\"), \"fast\"], env=e,\n                           capture_output=True, text=True, timeout=300)\n        return r.stdout + r.stderr, (out / \"checks.txt\").read_text(), r.returncode\n    run.env, run.tree = env, tree\n    return run\n\n\ndef summary(text):\n    return re.search(r\"; (\\d+) FAIL lines \\((\\d+) PASS\\)\", text).groups()\n\n\ndef verdict(text):\n    return re.search(r\"QUAL DONE deploy_t_e776703a \\S+: (PASS|FAIL)\", text).group(1)\n\n\ndef test_a_clean_run(qual):\n    text, checks, rc = qual()\n    # the 2 selftests', the build checks' (start, end), the 12 token-exact runs', the long\n    # prompt's 3 and the 2 DRAM turnaround lines\n    assert summary(text) == (\"0\", \"21\"), text[-2000:]\n    assert checks.count(\"[PASS] model\") == 15 and \"[FAIL]\" not in checks\n    assert \"prefill + decode counters\" in text and \"warm soak: \" in text\n    assert \"[PASS] load + selftest: the candidate: the card runs build e776703a\" in checks\n    assert \"[PASS] final selftest: the candidate, at the end: the card runs build e776703a\" \\\n        in checks\n    assert \"[PASS] model lfm2 int8/- long resident prompt runs\" in checks\n    assert rc == 0 and verdict(text) == \"PASS\"\n\n\n@pytest.mark.parametrize(\"crash, exit_code, where\", [\n    (\"perf.py qwen3 int8\", \"1\", \"prefill + decode counters (6): perf qwen3 int8 -: exit 1\"),\n    (\"decode_profile.py --model lfm2\", \"0\", \"decode_profile (3): decode_profile lfm2 fp4 int8: exit 0\"),\n    (\"opentpu.host.diag\", \"1\", \"diag warm (quick memory test): diag warm: exit 1\"),\n])\ndef test_a_crashed_step_is_a_fail_line(qual, crash, exit_code, where):\n    # a non-zero exit, or a traceback under exit 0, counts; before, the filters dropped both\n    text, checks, rc = qual(QUAL_CRASH=crash, QUAL_CRASH_EXIT=exit_code)\n    assert f\"[FAIL] {where}, FileNotFoundError: [Errno 2]\" in checks, checks\n    assert summary(text)[0] == \"1\", text[-2000:]\n    assert rc == 1 and verdict(text) == \"FAIL\"            # before: always 0\n\n\ndef test_a_failed_token_exact_run(qual):\n    text, checks, rc = qual(QUAL_CRASH=\"qwen35 fp4 int8 32 --resident\")\n    assert \"token-exact qwen35 fp4 int8--resident: exit 1\" in checks\n    assert \"14 of 15 token-exact runs passed\" in checks\n    assert summary(text)[0] == \"2\" and rc == 1, text[-2000:]\n    text, checks, rc = qual(QUAL_CRASH=\"lfm2 int8 - 32 --long --resident --prompt-runs\")\n    assert \"token-exact long lfm2 int8 - --resident --prompt-runs: exit 1\" in checks\n    assert \"14 of 15 token-exact runs passed\" in checks and rc == 1\n\n\ndef test_the_decode_loop_on_the_card(qual):\n    # a bitstream with CAPS bit30: the six token-exact runs and the long prompt's two (plain\n    # and in prompt runs) again on the card's decode loop\n    text, checks, rc = qual(QUAL_CAPS=\"1 0\")\n    assert summary(text) == (\"0\", \"29\"), text[-2000:]\n    assert \"decode loop on the card (6 + 2 long token-exact + 3 x 2 decode_profile)\" in text\n    assert \"[PASS] model lfm2 int8/- long resident card loop prompt runs\" in checks\n    text, checks, rc = qual(GEN=\"1\", QUAL_CRASH=\"--model qwen35 --tokens 96\")    # the sampled run\n    assert \"decode_profile card loop qwen35 fp4 int8 sampled: exit 1\" in checks\n    text, checks, rc = qual(GEN=\"1\", QUAL_CRASH=\"lfm2 int8 - 32 --card-loop\")\n    assert \"card loop lfm2 int8 -: exit 1\" in checks\n    assert \"7 of 8 card-loop token-exact runs passed\" in checks\n    text, _, _ = qual(QUAL_CAPS=\"1 0\", GEN=\"0\")                   # GEN overrides the bit\n    assert \"decode loop on the card (CAPS bit30): no\" in text and \"=== decode loop\" not in text\n\n\ndef test_waitw_on_the_host_writes(qual):\n    # a bitstream with CAPS bit31: tools/qual/waitw.py after the warm diag, its lines counted\n    text, checks, rc = qual(QUAL_CAPS=\"0 1\")\n    assert summary(text) == (\"0\", \"23\"), text[-2000:]\n    assert \"WAITW (CAPS bit31): yes\" in text and \"=== WAITW on the host's writes\" in text\n    assert \"[PASS] WAITW timeout\" in checks\n    text, checks, rc = qual(WAITW=\"1\", QUAL_CRASH=\"waitw.py\")\n    assert \"[FAIL] WAITW on the host's writes: waitw: exit 1\" in checks\n    text, _, _ = qual()\n    assert \"WAITW (CAPS bit31): no\" in text and \"=== WAITW\" not in text\n\n\ndef test_the_dram_turnarounds(qual):\n    # tools/qual/turnaround.py before the final selftest, in every qual: its lines counted, a\n    # crash a FAIL line\n    text, checks, rc = qual()\n    assert \"=== DRAM turnarounds + ECC (30 s)\" in text\n    assert \"[PASS] DRAM turnarounds, ECC: ch0 sec 0 ded 0\" in checks\n    assert text.index(\"=== DRAM turnarounds\") < text.index(\"=== final selftest\")\n    text, checks, rc = qual(QUAL_CRASH=\"turnaround.py\", TURN=\"5\")\n    assert \"=== DRAM turnarounds + ECC (5 s)\" in text\n    assert \"[FAIL] DRAM turnarounds + ECC (5 s): turnaround: exit 1\" in checks\n\n\ndef test_a_failed_soak_run_ends_the_soak(qual):\n    text, checks, rc = qual(QUAL_CRASH=\"history of France\", SOAK=\"30\")\n    assert checks.count(\"[FAIL]\") == 1 and \"soak run 1: exit 1\" in checks\n    assert \"warm soak: 1 runs\" in text\n\n\ndef test_runs_picks_the_models(qual, tmp_path):\n    \"\"\"RUNS: the references, prefill, decode_profile (4-bit only) and token-exact runs of the\n    models it names, and no others; LONG names the long prompt's run (empty: none).\"\"\"\n    text, checks, rc = qual(RUNS=\"lfm2-2.6b:int8:- smollm3:fp4:int8\")\n    # 2 selftests, 2 build checks, 4 token-exact, 3 for the long prompt, 2 turnaround\n    assert summary(text) == (\"0\", \"13\"), text[-2000:]\n    assert \"[PASS] model lfm2-2.6b int8/-\" in checks and \"[PASS] model smollm3 fp4/int8 \" \\\n        \"resident\" in checks and \"qwen3\" not in checks\n    assert \"compute --ntok 32 --runs lfm2-2.6b:int8:- smollm3:fp4:int8 lfm2:int8:-:long \" \\\n        \"lfm2:int8:-:long,pr\" in (tmp_path / \"out/refs.log\").read_text()\n    logs = sorted(f.name[4:-4] for f in (tmp_path / \"out/logs\").iterdir())\n    assert [n for n in logs if n.startswith((\"perf\", \"decode_profile\"))] == [\n        \"decode_profile_smollm3_fp4_int8\", \"perf_lfm2-2.6b_int8_-\", \"perf_smollm3_fp4_int8\"]\n    text, checks, rc = qual(RUNS=\"lfm2:int8:-\", LONG=\"\", NTOK=\"8\")\n    assert summary(text) == (\"0\", \"8\") and \"long\" not in checks, text[-2000:]\n    assert \"compute --ntok 8 --runs lfm2:int8:-\\n\" in (tmp_path / \"out/refs.log\").read_text()\n\n\ndef test_xl_runs(qual, tmp_path):\n    \"\"\"XL: each run's xl prompt (refs.py MODEL:WF:HF:xl,pr: ~1,400 tokens, buckets 1-6) resident\n    in prompt runs, and on the card's decode loop with CAPS bit30; its references are computed\n    with the others, under the keys the card check asks for; a mix run is prebuilt.\"\"\"\n    text, checks, rc = qual(XL=\"qwen3:int8:- phi4-mini:mix:-\", OTPU_LOCK_HELD=\"\")\n    # the clean run's 21, and the 2 xl runs\n    assert summary(text) == (\"0\", \"23\"), text[-2000:]\n    assert \"[PASS] model qwen3 int8/- xl resident prompt runs\" in checks\n    assert \"[PASS] model phi4-mini mix/- xl resident prompt runs\" in checks\n    assert \"lfm2:int8:-:long lfm2:int8:-:long,pr qwen3:int8:-:xl,pr phi4-mini:mix:-:xl,pr\" in \\\n        (tmp_path / \"out/refs.log\").read_text()\n    assert \"prebuilt qwen3:fp4:int8 lfm2:fp4:int8 qwen35:fp4:int8 phi4-mini:mix:-\" in text\n    text, checks, rc = qual(XL=\"phi4-mini:mix:-\", QUAL_CAPS=\"1 0\")\n    assert summary(text) == (\"0\", \"31\"), text[-2000:]\n    assert \"decode loop on the card (6 + 2 long + 1 xl token-exact\" in text\n    assert \"[PASS] model phi4-mini mix/- xl resident card loop prompt runs\" in checks\n    text, checks, rc = qual(XL=\"phi4-mini:mix:-\", QUAL_CRASH=\"phi4-mini mix - 32 --xl\")\n    assert \"token-exact xl phi4-mini mix - --resident --prompt-runs: exit 1\" in checks\n    assert \"15 of 16 token-exact runs passed\" in checks and rc == 1\n\n\ndef test_without_models_the_model_phases_are_skipped(qual):\n    # the staged tree of 2026-09-29 had no models link: every model phase crashed, 0 FAIL lines\n    text, checks, rc = qual(models=False)\n    assert \"[FAIL] load + selftest: no checkpoint for lfm2\" in checks and \"models link\" in checks\n    assert \"prefill + decode counters\" not in text and \"token-exact\" not in text\n    assert \"diag warm\" in text and summary(text) == (\"1\", \"6\"), text[-2000:]\n    assert rc == 1\n\n\ndef test_prebuild_outside_the_lock_then_the_lock(qual):\n    # started without the lock: the 4-bit runs into the image cache, then qual.sh again under\n    # otpu-lock; PREBUILD=0 skips the prebuild; started under the lock, neither\n    text, checks, rc = qual()\n    assert \"prebuilt qwen3:fp4:int8 lfm2:fp4:int8 qwen35:fp4:int8\" in text\n    assert text.index(\"=== prebuild outside the card lock\") < text.index(\"################\")\n    assert summary(text) == (\"0\", \"21\"), text[-2000:]\n    assert rc == 0                                      # through otpu-lock's exit status\n    text, _, rc = qual(PREBUILD=\"0\")\n    assert \"=== prebuild outside the card lock;\" in text and \"prebuilt\" not in text\n    assert summary(text) == (\"0\", \"21\"), text[-2000:]\n    text, _, rc = qual(OTPU_LOCK_HELD=\"xdma0\")\n    assert \"=== prebuild\" not in text and summary(text) == (\"0\", \"21\"), text[-2000:]\n\n\ndef test_the_jtag_load_and_the_build_on_the_card(qual, tmp_path):\n    # LOAD=1: the candidate's JTAG load, then its build on the card (the rescan only shows that\n    # some openTPU bitstream answers); REST: its load and its build (production -> the deploy\n    # directory) before the final selftest\n    text, checks, rc = qual(LOAD=\"1\", REST=str(tmp_path / \"production/otpu.bit\"))\n    assert \"[PASS] load + selftest: the candidate: the card runs build e776703a\" in checks\n    assert f\"[PASS] final selftest: REST ({tmp_path}/production/otpu.bit): the card runs \" \\\n        \"build 542fc43a\" in checks\n    assert rc == 0 and summary(text) == (\"0\", \"21\"), text[-2000:]\n    assert \"deploy_t_e776703a/otpu.bit\" in (tmp_path / \"out/jtag.log\").read_text()\n\n\ndef test_a_failed_jtag_load_stops_the_qual(qual):\n    # openFPGALoader failed (the cable busy, a wrong path): before, its exit status was lost\n    # in a pipe, the rescan found the old bitstream's ID, and the qual passed the candidate\n    text, checks, rc = qual(LOAD=\"1\", QUAL_BUILD=\"542fc43a\", QUAL_JTAG_FAIL=\"deploy_t_\")\n    assert \"[FAIL] load + selftest: the JTAG load of\" in checks\n    assert \"openFPGALoader exit 1\" in text and \"the qual stops here\" in text\n    assert \"token-exact\" not in text and \"[PASS] link\" not in checks       # no selftest\n    assert rc == 1 and summary(text)[0] == \"1\", text[-2000:]\n\n\ndef test_another_build_on_the_card_stops_the_qual(qual, tmp_path):\n    # the loader said yes but the old bitstream runs on; LOAD=0 on a card that runs another\n    # build; EXPECT names the build when the deploy's name does not\n    text, checks, rc = qual(LOAD=\"1\", QUAL_BUILD=\"542fc43a\", QUAL_JTAG_NOOP=\"deploy_t_\")\n    assert \"[FAIL] load + selftest: the candidate: the card runs build 542fc43a, not \" \\\n        \"e776703a\" in checks\n    assert rc == 1 and \"token-exact\" not in text and \"the qual stops here\" in text\n    text, checks, rc = qual(QUAL_BUILD=\"542fc43a\")\n    assert \"the card runs build 542fc43a, not e776703a\" in checks and rc == 1\n    text, checks, rc = qual(QUAL_BUILD=\"0badc0de\", EXPECT=\"0badc0de\")\n    assert rc == 0 and \"the card runs build 0badc0de\" in checks\n    # a REST that does not load: a FAIL line, no final selftest\n    text, checks, rc = qual(LOAD=\"1\", REST=str(tmp_path / \"production/otpu.bit\"),\n                            QUAL_JTAG_FAIL=\"production\")\n    assert \"[FAIL] final selftest: the JTAG load of REST\" in checks and rc == 1\n\n\ndef test_a_failed_probe_stops_the_qual(qual):\n    # before, a probe that failed gave GEN=0 WAITW=0: the card-loop and WAITW phases were\n    # skipped without a FAIL line\n    text, checks, rc = qual(QUAL_PROBE_FAIL=\"1\")\n    assert \"[FAIL] load + selftest: probe (the candidate): exit 1\" in checks\n    assert \"[FAIL] load + selftest: the candidate: the probe of BUILD_ID and CAPS failed\" \\\n        in checks\n    assert rc == 1 and \"token-exact\" not in text\n\n\ndef test_new_xdma_errors_are_fail_lines(qual):\n    # the kernel's xdma errors since the load, each a FAIL line; older ones are not the qual's\n    text, checks, rc = qual(QUAL_DMESG=\"[ 1234.500000] xdma:xdma_xfer_submit: xfer timed out\",\n                            QUAL_DMESG_NEW=\"[ 5678.250000] xdma:engine_status: engine error\")\n    assert checks.count(\"[FAIL]\") == 1 and rc == 1\n    assert \"[FAIL] DRAM turnarounds + ECC (30 s): dmesg: [ 5678.250000] xdma:engine_status: \" \\\n        \"engine error\" in checks\n\n\ndef test_the_references_job_is_bounded(qual, tmp_path):\n    # a references' job that never ends: killed REFS_WAIT s after the last token-exact run\n    # (before, qual.sh's wait for it had no bound), and a FAIL line\n    text, checks, rc = qual(QUAL_HANG=\"refs.py compute\", REFS_WAIT=\"2\")\n    assert \"refs compute: still running 2 s after the last token-exact run: killed\" in checks\n    pid = int((tmp_path / \"hung\").read_text())\n    with pytest.raises(ProcessLookupError):\n        os.kill(pid, 0)\n    assert rc == 1 and \"=== DRAM turnarounds\" in text\n\n\ndef test_a_killed_qual_kills_the_references_job_and_fails(qual, tmp_path):\n    # SIGTERM while the references compute: the job goes too, the summary says FAIL, status 1\n    e, out = qual.env(QUAL_HANG=\"refs.py compute\")\n    p = subprocess.Popen([\"bash\", str(qual.tree / \"tools/qual/qual.sh\"),\n                          str(tmp_path / \"deploy_t_e776703a\"), \"fast\"], env=e,\n                         stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)\n    t0 = time.time()\n    while not (tmp_path / \"hung\").exists() and time.time() - t0 < 60:\n        time.sleep(0.2)\n    time.sleep(0.5)\n    p.send_signal(signal.SIGTERM)\n    text = p.communicate(timeout=120)[0]\n    assert p.returncode == 1, text[-2000:]\n    assert \"qual.sh exited early (status 143)\" in (out / \"checks.txt\").read_text()\n    assert \"killed the references' job\" in text and \"QUAL DONE\" in text\n    with pytest.raises(ProcessLookupError):\n        os.kill(int((tmp_path / \"hung\").read_text()), 0)\n", "tests/test_quant.py": "\"\"\"Weight formats (opentpu/quant.py): the MX MXU's packers and scale rows, its MM on the ISA\nsimulator against the float64 emulation (docs/isa.md \"MM\", docs/mx_mxu.md), column parts and\nslices, the gathers' tables, and the checkpoint imports (OCP MXFP4, NVIDIA NVFP4).\"\"\"\nimport importlib.util\nfrom pathlib import Path\n\nimport numpy as np\nimport pytest\n\nfrom opentpu import Config, isa as I, quant as Q\nfrom opentpu import language as ol\nfrom opentpu import reference as ref\nfrom opentpu.compiler import Affine, Tensor, current\nfrom opentpu.isasim import Machine\nfrom opentpu.kernels import gather as GA\nfrom opentpu.kernels import mlp\nfrom opentpu.runtime import Input, Output, Weight, launch\n\nfrom conftest import rel\nfrom test_kernels import mlp_args\n\nROOT = Path(__file__).resolve().parent.parent\n\n\n# ------------------------------------------------------------------------- the study formats\ndef test_e2m1_and_e4m3_rounding():\n    # ties go to the even code (the even mantissa bit), values past the top saturate\n    got = Q.round_to_grid(np.array([0.25, 0.75, 1.25, 1.75, 2.5, 3.5, 5.0, 7.0, 100.0]), Q.E2M1)\n    assert got.tolist() == [0, 2, 2, 4, 4, 6, 6, 7, 7]\n    assert Q.e4m3(np.array([1.0625, 1.1875, 500.0, 2.0 ** -9])).tolist() == \\\n        [1.0, 1.25, 448.0, 2.0 ** -9]\n    assert len(Q.E4M3) == 127 and Q.E4M3[-1] == 448.0\n\n\n@pytest.mark.parametrize(\"fmt,g,bits\", [(\"int8\", 128, 8.25), (\"int4\", 32, 4.5), (\"mxfp4\", 32, 4.25),\n                                        (\"nvfp4\", 16, 4.5), (\"int4k\", 32, 4.25)])\ndef test_formats_bits_and_error(fmt, g, bits):\n    rng = np.random.default_rng(0)\n    W = (rng.standard_normal((64, 256)) * 0.02).astype(np.float32)\n    q = Q.quantize(W, fmt)\n    assert q.bits == bits and q.g == g\n    assert Q.rel_err(W, q.deq) < (1e-4 if fmt == \"int8\" else 0.02)\n\n\ndef test_mxfp4_elements_are_e2m1_times_power_of_two():\n    W = (np.random.default_rng(1).standard_normal((8, 64))).astype(np.float32)\n    q = Q.quantize(W, \"mxfp4\")\n    s = q.scales                                                # [8, 2] powers of two\n    assert np.all(np.log2(s) == np.round(np.log2(s)))\n    x = np.abs(q.deq.reshape(8, 2, 32) / s[..., None])\n    assert np.isin(x, Q.E2M1).all()\n\n\n# ------------------------------------------------------------------------- the MXU's formats\ndef _spread(rng, N, K, s=3.0, g=32):\n    \"\"\"Rows with log-normal scales per g elements (offsets up to the window and past it).\"\"\"\n    return (rng.standard_normal((N, K)) * np.exp(s * rng.standard_normal((N, K // g, 1)))\n            .repeat(g, 2).reshape(N, K) * 0.02).astype(np.float32)\n\n\ndef _mx_formats():\n    s = importlib.util.spec_from_file_location(\"mx_formats\", ROOT / \"tools/exp/mx_formats.py\")\n    m = importlib.util.module_from_spec(s)\n    s.loader.exec_module(m)\n    return m\n\n\ndef test_quantizers_are_the_studys():\n    \"\"\"int8x, fp4x6 and nvfp4 (per-row) are tools/exp/mx_formats.py's w_int8x, w_fp4x(a, 6)\n    and w_nvfp4(a, per_row=True), the formats docs/mx_mxu.md 3.3 measured: the same values\n    (to fp32 rounding: the device's are fp32 products) and the same offsets per 16 elements\n    (an all-zero group's never counts).\"\"\"\n    MXF = _mx_formats()\n    rng = np.random.default_rng(0)\n    W = _spread(rng, 64, 512)\n    W[3, 100:132] = 0\n    W[5, :128] = 0\n    for fmt, want in ((\"int8\", MXF.w_int8x(W)), (\"fp4\", MXF.w_fp4x(W, 6)),\n                      (\"nvfp4\", MXF.w_nvfp4(W, True))):\n        rows, srows = Q.quantize_mxu(W, fmt, 128)\n        deq = Q.dequantize_mxu(rows, srows, fmt, 512, 128)\n        assert np.abs(deq - want.deq).max() <= 1e-6 * np.abs(want.deq).max(), fmt\n        live = np.abs(W).reshape(64, 32, 16).max(-1) > 0\n        dw = Q.group_offsets(srows, fmt, 512, 128)\n        assert np.array_equal(dw[live], np.asarray(want.dw)[live]), fmt\n        assert Q.mxu_wf(fmt) == I.WFORMATS[fmt] and I.MX_W[I.WFORMATS[fmt]] == want.W\n\n\n@pytest.mark.parametrize(\"fmt\", Q.MXU_FORMATS)\ndef test_layout_and_error(fmt):\n    \"\"\"Element rows and scale rows (docs/isa.md \"MM\"): int8 a byte an element, Sw then a dw\n    byte per block (4-byte words); int4 / fp4 a nibble an element, Sw, a reserved word, then a\n    word per block (dw, four 6-bit multipliers, the m search's); nvfp4 Sw, three reserved\n    words, then eight E4M3 bytes per block (every one's sign clear). The relative error is the\n    format's.\"\"\"\n    rng = np.random.default_rng(2)\n    W = _spread(rng, 16, 640, 1.0)\n    W[3, 128:256] = 0                                           # an all-zero block\n    rows, srows = Q.quantize_mxu(W, fmt, 128)\n    K, KB = 640, 5\n    assert rows.shape == (16, Q.row_bytes(K, fmt, 128)) and rows.dtype == np.uint8\n    assert srows.shape == (16, Q.scale_bytes(K, fmt, 128))\n    assert Q.scale_bytes(K, fmt, 128) == {\"int8\": 4 + 4 * 2, \"int4\": 8 + 8 * 3,\n                                          \"fp4\": 8 + 8 * 3, \"nvfp4\": 16 + 16 * 3}[fmt]\n    Sw, dw, m = Q.unpack_scales(srows, fmt, KB)\n    assert np.array_equal(Q.pack_scales(fmt, Sw, dw=dw[..., 0].astype(np.uint8),\n                                        m=m.astype(np.uint8),\n                                        e4=srows[:, 16:16 + 8 * KB].reshape(16, KB, 8)\n                                        if fmt == \"nvfp4\" else None), srows)\n    if fmt in (\"int4\", \"fp4\"):\n        assert m.min() >= 1 and m.max() <= Q.MMAX\n    if fmt == \"nvfp4\":\n        assert not np.any(srows[:, 16:] & 0x80)\n    deq = Q.dequantize_mxu(rows, srows, fmt, K, 128)\n    assert np.all(deq[3, 128:256] == 0)\n    assert Q.rel_err(W, deq) < {\"int8\": 0.006, \"int4\": 0.12, \"fp4\": 0.1, \"nvfp4\": 0.09}[fmt]\n    if fmt != \"int8\":\n        assert np.array_equal(Q.pack4(Q.unpack4(rows[:, :K // 2])), rows[:, :K // 2])\n\n\n@pytest.mark.parametrize(\"fmt\", Q.MXU_FORMATS)\ndef test_quantize_mxu_in_row_pieces_is_the_same(fmt, monkeypatch):\n    \"\"\"quantize_mxu quantizes a tall matrix QUANT_ROWS rows at a time (a big vocabulary's LM\n    head): the same bytes and scales as all rows at once.\"\"\"\n    rng = np.random.default_rng(0)\n    W = (rng.standard_normal((1000, 512)) * np.exp(rng.standard_normal((1000, 1)))).astype(\n        np.float32)\n    W[3, :128] = 0\n    whole = Q.quantize_mxu(W, fmt)\n    monkeypatch.setattr(Q, \"QUANT_ROWS\", 96)\n    pieces = Q.quantize_mxu(W, fmt)\n    assert all(np.array_equal(a, b) and a.dtype == b.dtype for a, b in zip(whole, pieces))\n\n\n@pytest.mark.parametrize(\"fmt\", Q.MXU_FORMATS)\ndef test_column_parts_are_the_whole_rows(fmt):\n    \"\"\"A matrix stored in column parts (W_down's chunks) keeps its rows' quantization: each\n    part's scale rows hold the rows' Sw and its blocks' offsets (and multipliers), so the parts\n    stand for the whole rows' columns exactly, as a column slice's k0 reads them.\"\"\"\n    rng = np.random.default_rng(3)\n    W = _spread(rng, 8, 1024)\n    rows, srows = Q.quantize_mxu(W, fmt, 128)\n    whole = Q.dequantize_mxu(rows, srows, fmt, 1024, 128)\n    for C in (256, 512):\n        parts = Q.column_parts(rows, srows, fmt, 1024, C, 128)\n        assert len(parts) == 1024 // C\n        for j, (pr, ps) in enumerate(parts):\n            assert pr.shape[1] == Q.row_bytes(C, fmt, 128)\n            assert ps.shape[1] == Q.scale_bytes(C, fmt, 128)\n            assert np.array_equal(Q.dequantize_mxu(pr, ps, fmt, C, 128),\n                                  whole[:, j * C:(j + 1) * C])\n            assert np.array_equal(Q.part_scales(srows, fmt, j * C // 128, C // 128), ps)\n\n\n# ------------------------------------------------------------------------- MM on the ISA\n@ol.jit\ndef k_dot(x, w, out):\n    ol.store(out, ol.dot(ol.load(x), w))\n\n\n@ol.jit\ndef k_dot_cols(x, w, out, c0, c1):\n    ol.store(out, ol.dot(ol.load(x)[:, c0:c1], w[:, c0:c1]))\n\n\ndef _x(rng, M, K, s):\n    return (rng.standard_normal((M, K)) * np.exp(s * rng.standard_normal((M, K // 8, 1)))\n            .repeat(8, 2).reshape(M, K)).astype(np.float32)\n\n\n@pytest.mark.parametrize(\"fmt\", Q.MXU_FORMATS)\n@pytest.mark.parametrize(\"D\", [32, 128])\ndef test_mm_follows_the_emulation(fmt, D):\n    \"\"\"One MM per format (activations and weights with offsets wide enough for the window to\n    drop groups): the ISA simulator's sums are the float64 emulation's (quant.fake_act, the\n    weights dequantized, mx_matmul's drops) to fp32 rounding, and the drops matter (without\n    them the emulation is 100x as far off); a column slice of the weights (MM k0) the same.\"\"\"\n    rng = np.random.default_rng(D)\n    M, N, K = 3, 24, 8 * D\n    x, W = _x(rng, M, K, 6.0), _spread(rng, N, K, 6.0, 8)\n    cfg = Config(S=1, D=D, MCOLS=4)\n    got = launch(k_dot, cfg, x=Input(x), w=Weight(W, fmt=fmt), out=Output((M, N))).outputs[\"out\"]\n    wd, xa = Q.fake_w(W, fmt, D), Q.fake_act(x, D)\n    want = xa @ wd.T\n    plain = np.asarray(xa).view(np.ndarray) @ np.asarray(wd).view(np.ndarray).T\n    assert np.abs(got - want).max() < 1e-6 * np.abs(want).max()\n    assert np.abs(got - plain).max() > 100 * np.abs(got - want).max()\n    c0, c1 = 2 * D, 4 * D\n    got = launch(k_dot_cols, cfg, x=Input(x), w=Weight(W, fmt=fmt), out=Output((M, N)),\n                 c0=c0, c1=c1).outputs[\"out\"]\n    srows = Q.quantize_mxu(W, fmt, D)[1]\n    want = Q.mx_matmul(Q.fake_act(x[:, c0:c1], D), np.asarray(wd)[:, c0:c1],\n                       Q.group_offsets(Q.part_scales(srows, fmt, 2, 2), fmt, c1 - c0, D),\n                       I.MX_W[I.WFORMATS[fmt]], D)\n    assert np.abs(got - want).max() < 1e-6 * np.abs(want).max()\n\n\n@pytest.mark.parametrize(\"fmt\", [\"int8\", \"fp4\", \"nvfp4\"])\ndef test_mm_runs_a_pass_per_qact_range(fmt):\n    \"\"\"A stationary operand quantized again by two QACTs (blocks [0, 2) and [2, 4): two row\n    scales, as compiler.Stationary.qranges records them) is multiplied by one MM per range, the\n    second accumulating into the first's output (MM ACC); one MM over both ranges would read\n    two scales of a row (the ISA simulator refuses it). The result is the emulation's with the\n    two ranges quantized on their own.\"\"\"\n    D, M, N, K = 128, 2, 16, 512\n    rng = np.random.default_rng(5)\n    x, W = _x(rng, M, K, 2.0), _spread(rng, N, K, 2.0, 8)\n    x[:, 256:] *= 300.0                         # the ranges' scales far apart\n\n    @ol.jit\n    def k(x, w, out):\n        b = current()\n        xt = ol.load(x)\n        st = b.quantize(xt)                     # blocks 0..3, then 0..1 and 2..3 on their own\n        (ab, mc), = st.chunks\n        b.emit(I.qact(xt.base, mc, ab, 2, xt.rs, comment=\"first range\"))\n        b.emit(I.qact(xt.base + 2 * D, mc, ab + 2, 2, xt.rs, comment=\"second range\"))\n        st.add_qrange(0, 2)\n        st.add_qrange(2, 4)\n        ol.store(out, ol.dot(st, w))\n\n    cfg = Config(S=1, D=D, MCOLS=4)\n    r = launch(k, cfg, x=Input(x), w=Weight(W, fmt=fmt), out=Output((M, N)))\n    want = Q.fake_act(x, D, [256, 256]) @ Q.fake_w(W, fmt, D).T\n    assert np.abs(r.outputs[\"out\"] - want).max() < 1e-6 * np.abs(want).max()\n    mms = [p for p in r.compiled.programs[0] if p.op == I.MM]\n    assert len(mms) == 2 and not mms[0].flags & I.F_ACC and mms[1].flags & I.F_ACC\n\n\n@pytest.mark.parametrize(\"fmt\", Q.FOUR)\ndef test_mlp_kernel_4bit(fmt):\n    \"\"\"The MLP kernel with 4-bit weights, against float64 math on the dequantized 4-bit weights\n    (what remains is the int8 activations' error, as with int8 weights).\"\"\"\n    args, _ = mlp_args(np.random.default_rng(3), M=4, H=256, Fd=512)\n    deq = {}\n    for k in (\"w_gate\", \"w_up\", \"w_down\"):\n        args[k].fmt = fmt\n        deq[k] = np.asarray(Q.fake_w(args[k].array, fmt, 32)).view(np.ndarray)\n    want = ref.mlp(args[\"h\"].array, args[\"gamma\"].array, deq[\"w_gate\"], deq[\"w_up\"],\n                   deq[\"w_down\"], 1e-6)\n    got = launch(mlp, Config(S=2), **args).outputs[\"out\"]\n    assert rel(got, want) < 0.01\n\n\n# ------------------------------------------------------------------------- gathers\ndef _gather_run(D, M, fmt, rows, record):\n    cfg = Config(S=1, D=D, MCOLS=M, ACT_BLOCKS=64, TMEM_WORDS=1 << 16, DRAM_BYTES=1 << 22)\n    N, K = rows.shape\n    img = np.zeros(cfg.DRAM_BYTES, np.uint8)\n    oh = GA.onehot(D, M, \"int8\" if fmt == \"int8\" else \"fp4\")\n    OH, TAB, OUT = 0, 1 << 18, 1 << 21\n    img[OH:OH + oh.nbytes] = oh.view(np.uint8).reshape(-1)\n    if record:\n        S = GA.record_blocks(-(-K // D), fmt)\n        rec = GA.pack_records(rows, fmt, D, S)\n        img[TAB:TAB + rec.size] = rec.reshape(-1)\n        tab = GA.record_table(TAB, N, S, fmt, D)\n        want, width = GA.dequant_records(rec, fmt, D, S)[:, :K], S * D\n    else:\n        q, s = Q.quantize_mxu(rows, fmt, D)\n        g = Q.gather_scales(s, fmt, K, D)\n        img[TAB:TAB + q.size] = q.reshape(-1)\n        GS = -(-(TAB + q.size) // 4096) * 4096\n        img[GS:GS + g.nbytes] = np.ascontiguousarray(g).view(np.uint8).reshape(-1)\n        tab = GA.table(TAB, GS, N, K, fmt, D)\n        want, width = GA.dequant_gathered(q, g, fmt, K, D), K\n    out = Tensor(Affine(OUT), (N, width), (width, 1))\n\n    @ol.jit\n    def k(ohd, out):\n        op = GA.operand(ohd)\n        for r in range(N):\n            v = GA.gather_record(op, tab, r, fmt, S) if record else \\\n                GA.gather_row(op, tab, r, fmt)\n            ol.store(out[r:r + 1, :], v.reshape(1, width))\n\n    prog = k.trace(cfg, 0, {\"ohd\": Tensor(Affine(OH), oh.shape, (oh.shape[1], 1)),\n                            \"out\": out}).finish()\n    s = Machine(cfg, [prog], [img]).run().slices[0]\n    return s.dram[OUT:OUT + 4 * N * width].view(np.float32).reshape(N, width)[:, :K], want\n\n\n@pytest.mark.parametrize(\"fmt\", Q.MXU_FORMATS)\n@pytest.mark.parametrize(\"record\", [False, True], ids=[\"row\", \"record\"])\n@pytest.mark.parametrize(\"D\", [32, 128])\ndef test_gathers_are_the_hosts_bit_for_bit(fmt, record, D):\n    \"\"\"kernels.gather's one-hot MMs on the ISA simulator: a table row (its element row and\n    gather scales: quant.gather_scales) or a packed record, dequantized bit for bit as the\n    host's dequant_gathered / dequant_records says (the embedding rows and PLE records the\n    references take), with no VPU dequantization: the MM's scale arithmetic does it.\"\"\"\n    rng = np.random.default_rng(D)\n    K = 6 * D\n    rows = _spread(rng, 5, K, 3.0, 8) * 50\n    rows[1, :D] = 0\n    got, want = _gather_run(D, 4, fmt, rows, record)\n    assert np.array_equal(got.view(np.uint32), want.view(np.uint32))\n    assert rel(got, rows) < {\"int8\": 0.02, \"int4\": 0.15, \"fp4\": 0.12, \"nvfp4\": 0.12}[fmt]\n\n\n# ------------------------------------------------------------------------- checkpoint imports\ndef _e2m1(codes):\n    v = Q.E2M1[codes & 7]\n    return np.where(codes & 8, -v, v)\n\n\ndef test_import_mxfp4_exact():\n    \"\"\"OCP MXFP4 (E2M1 per element, E8M0 per 32) comes in exactly: as fp4 (fp4x6, m = 2^(e -\n    the block's smallest e)) where each 128-block's exponents span at most 5 (all-zero\n    sub-blocks have any), as nvfp4 (mantissa-0 E4M3 bytes, subnormals at the bottom) where a\n    block spans more but no row more than 17 octaves; past that NotExact. The values are the\n    checkpoint's, and the ISA simulator's MM with them is the float64 product.\"\"\"\n    rng = np.random.default_rng(7)\n    N, K = 6, 512\n    codes = rng.integers(0, 16, (N, K)).astype(np.uint8)\n    codes[2, 64:96] &= 8                                        # a zero sub-block (signs only)\n    base = rng.integers(110, 140, (N, 1))\n    e = base + rng.integers(0, 6, (N, K // 32))                 # a block spans <= 5\n    e[2, 2] = 0                                                 # (the zero sub-block's)\n    want = _e2m1(codes) * np.exp2(np.repeat(e, 32, 1) - 127.0)\n    rows, srows, fmt = Q.import_mxfp4(codes, e)\n    assert fmt == \"fp4\"\n    assert np.array_equal(Q.dequantize_mxu(rows, srows, \"fp4\", K), want)\n    e2 = e.copy()\n    e2[:, 1] = base[:, 0] + 17                                  # spans 6..17 in a block\n    want2 = _e2m1(codes) * np.exp2(np.repeat(e2, 32, 1) - 127.0)\n    rows2, srows2, fmt2 = Q.import_mxfp4(codes, e2)\n    assert fmt2 == \"nvfp4\"\n    assert np.array_equal(Q.dequantize_mxu(rows2, srows2, \"nvfp4\", K), want2)\n    e3 = e.copy()\n    e3[0, 5] = base[0, 0] + 23                                  # a row spans 18 or more\n    with pytest.raises(Q.NotExact, match=\"span\"):\n        Q.import_mxfp4(codes, e3)\n    with pytest.raises(Q.NotExact, match=\"NaN\"):\n        Q.import_mxfp4(codes, np.full_like(e, 0xFF))\n    # the MM: fp4's sums are the exact products of the imported values (int8 activations with\n    # a 127 in every group: offsets 0, nothing dropped); nvfp4's drop what its window does\n    # (17 octaves of scales against W = 13): the emulation's sums\n    x = rng.integers(-127, 128, (2, K)).astype(np.float32)\n    x[:, ::32] = 127\n    cfg = Config(S=1, D=128, MCOLS=4)\n    for r, s, f, w in ((rows, srows, fmt, want), (rows2, srows2, fmt2, want2)):\n        img = np.zeros(1 << 20, np.uint8)\n        img[:x.nbytes] = x.view(np.uint8).reshape(-1)\n        WA, SA = 1 << 16, 1 << 17\n        img[WA:WA + r.size] = r.reshape(-1)\n        img[SA:SA + s.size] = s.reshape(-1)\n        prog = [I.ld(0, 0, x.size), I.qact(0, 2, 0, K // 128, K),\n                I.mm(WA, SA, 4096, N, K // 128, r.shape[1], N, 2, 0, s.shape[1],\n                     wf=Q.mxu_wf(f)), I.halt()]\n        m = Machine(cfg, [prog], [img]).run().slices[0]\n        got = m.tget(4096 + np.arange(2 * N)).reshape(2, N)\n        if f == \"fp4\":\n            exact = x.astype(np.float64) @ w.T\n        else:\n            exact = Q.mx_matmul(Q.fake_act(x, 128), w, Q.group_offsets(s, f, K),\n                                I.MX_W[Q.mxu_wf(f)])\n        assert np.abs(got - exact).max() <= 2e-7 * np.abs(exact).max()\n\n\ndef test_import_nvfp4_exact():\n    \"\"\"NVFP4 (E2M1, an E4M3 scale per 16, an fp32 per tensor) comes in exactly, each row's\n    scales re-based so that its largest has dw 0: subnormal scales renormalize, a largest of\n    mantissa 7 is the MXU's 0x7F (15 2^0; NVFP4's NaN code is not a scale here), and a\n    subnormal 17 octaves below a row's 448 is an MXU subnormal again (E4M3's own range fits:\n    every valid checkpoint comes in). NotExact: a negative or NaN scale.\"\"\"\n    rng = np.random.default_rng(8)\n    N, K = 5, 256\n    codes = rng.integers(0, 16, (N, K)).astype(np.uint8)\n    s = rng.integers(1, 127, (N, K // 16)).astype(np.uint8)    # positive, not NaN\n    s[0, :] = rng.integers(1, 8, K // 16)                       # a row of subnormals\n    s[1, 0] = 0x77                                              # 480/2: mantissa 7\n    s[2, 3] = 0                                                 # a zero scale\n    ts = np.float32(0.0123)\n    want = _e2m1(codes) * np.repeat(Q.E4M3[s], 16, 1) * np.float64(ts)\n    rows, srows = Q.import_nvfp4(codes, s, ts)\n    got = Q.dequantize_mxu(rows, srows, \"nvfp4\", K)\n    assert np.array_equal(got, want)\n    assert not np.any(srows[:, 16:] & 0x80)\n    for bad, what in ((0x80 | 0x30, \"negative\"), (0x7F, \"NaN\")):\n        b = s.copy()\n        b[3, 1] = bad\n        with pytest.raises(Q.NotExact, match=what):\n            Q.import_nvfp4(codes, b, ts)\n    far = s.copy()\n    far[4, :] = 0x60                                            # 32\n    far[4, 0] = 0x7E                                            # 448 = 1.75 2^8 at the top\n    far[4, 1] = 0x01                                            # 2^-9: 17 octaves down\n    far[4, 2] = 0x03                                            # 3 2^-9\n    rows, srows = Q.import_nvfp4(codes, far, ts)\n    assert np.array_equal(Q.dequantize_mxu(rows, srows, \"nvfp4\", K),\n                          _e2m1(codes) * np.repeat(Q.E4M3[far], 16, 1) * np.float64(ts))\n    assert srows[4, 17] == 0x01 and srows[4, 18] == 0x03       # MXU subnormals\n", "tests/test_quant_rtl.py": "\"\"\"The MX column and the quantizer on the RTL against the ISA simulator (docs/isa.md \"MM\",\n\"Weight formats\", \"Quantization\", \"QACT\", \"QST\"; docs/mx_mxu.md): MMs in every weight format\n(int8x with -128, int4x, fp4x6, NVFP4) with UNIT, RSC, PAIR, k0, ACC, RMAX and ASCALE, the\nscale words' corners (Sw negative, signed zeros, denormals, the largest finite, inf, NaN), groups\nat the shift window's edge (sh = 0 kept, sh = -1 dropped), at MCOLS 4 and 8 and 1, 2 or 4\nepilogue lanes; QACT and QST in every mode (ROW, CSCALE, RSCALE, DUP, HALF, element strides,\nunaligned rows, KB not a multiple of 4, zero, inf and denormal rows, a chunk holding two QACT\ngroups at D = 32 with 16 lanes), and the quantizer's rounding ties (q8 rounds x * (inv * 2^d)\nhalf to even), read back through MMs with identity weights. Each runs the same program on both\nand compares DRAM and TMEM bit for bit.\"\"\"\nimport numpy as np\nimport pytest\n\nfrom opentpu import Config, fp32 as F, isa as I, quant as Q, rtlsim\nfrom opentpu.isasim import Machine\n\nfrom test_mx import _scale_rows\n\nF32_CORNERS = [0xBF400000, 0x00000000, 0x80000000, 0x00000001, 0x007FFFFF, 0x00800000,\n               0x7F7FFFFF, 0x7F800000, 0x7FC00000]\n\n\ndef _both(cfg, prog, dram, uarch=None):\n    m = Machine(cfg, [prog], [dram.copy()]).run()\n    drams, tmems, _ = rtlsim.run(cfg, [prog], [dram.copy()], uarch=uarch)\n    bad = np.nonzero(tmems[0] != m.slices[0].tmem)[0]\n    assert len(bad) == 0, (f\"{len(bad)} TMEM words differ, first {bad[:6]}: RTL \"\n                           f\"{[hex(int(v)) for v in tmems[0][bad[:6]]]} ISA \"\n                           f\"{[hex(int(v)) for v in m.slices[0].tmem[bad[:6]]]}\")\n    bad = np.nonzero(drams[0] != m.slices[0].dram)[0]\n    assert len(bad) == 0, (f\"{len(bad)} DRAM bytes differ, first at {bad[:6]}: RTL \"\n                           f\"{drams[0][bad[:6]]} ISA {m.slices[0].dram[bad[:6]]}\")\n    return m\n\n\ndef _put(dram, at, a):\n    b = np.ascontiguousarray(a).view(np.uint8).reshape(-1)\n    dram[at:at + b.size] = b\n\n\nX, WA, SA, OUT, SC, AL = 0, 0x40000, 0x80000, 0x8000, 0xA0000, 0xB0000\n\n\ndef _xrows(rng, rows, n, g, spread=6.0):\n    \"\"\"Rows of n elements whose groups of g span a wide range of magnitudes (offsets d from 0 to\n    beyond the shift window), with a zero group.\"\"\"\n    x = (rng.standard_normal((rows, n)) *\n         np.exp(rng.uniform(-spread, spread, (rows, n // g, 1))).repeat(g, 2).reshape(rows, n))\n    x = x.astype(np.float32)\n    x[0, g:2 * g] = 0\n    return x\n\n\n# wf, D, MCOLS, pair, rsc, k0, E\nMM_CASES = [\n    (I.W8, 32, 4, False, False, 0, 0), (I.W8, 128, 4, False, False, 3, 1),\n    (I.W8, 32, 8, False, False, 1, 4), (I.W8, 128, 4, False, True, 0, 2),\n    (I.W4I, 32, 4, False, False, 1, 0), (I.W4I, 128, 4, True, False, 2, 2),\n    (I.W4F, 128, 4, False, False, 0, 1), (I.W4F, 32, 8, True, False, 0, 4),\n    (I.W4F, 128, 4, False, True, 0, 0), (I.WNV, 128, 4, False, False, 1, 2),\n    (I.WNV, 128, 8, True, False, 2, 1), (I.WNV, 32, 4, False, False, 0, 0),\n]\n\n\n@pytest.mark.parametrize(\"wf,D,mcols,pair,rsc,k0,E\", MM_CASES)\ndef test_mm_mx_rtl(have_verilator, wf, D, mcols, pair, rsc, k0, E):\n    \"\"\"QACT, then MMs over its rows: with scales (rows 0 and 1 of each block at the window's\n    edge for ACT row 0, sh = 0 and sh = -1; random offsets elsewhere, many past the window),\n    UNIT, ACC onto the first, RMAX, ASCALE; Sw corners in rows 16.. . KB = 3 (PAIR's last chunk\n    holds one block).\"\"\"\n    cfg = Config(S=1, D=D, MCOLS=mcols, PAIR=pair, DRAM_BYTES=1 << 20)\n    rng = np.random.default_rng(100 * wf + D + mcols + 3 * pair + 5 * rsc + k0)\n    KB, M = 3, (mcols // 2 if pair else mcols)\n    N = 16 + (0 if rsc else len(F32_CORNERS))\n    W = I.MX_W[wf]\n    x = _xrows(rng, M, KB * D, D // 4)\n    KBr = k0 + KB\n    if wf == I.W8:\n        wel = rng.integers(-128, 128, (N, KB * D))\n        wel[:, ::7] = -128\n        data = wel.astype(np.int8).view(np.uint8)\n    else:\n        data = Q.pack4(rng.integers(0, 16, (N, KB * D)))\n    rs = -(-data.shape[1] // D) * D\n    rows, *_ = _scale_rows(rng, wf, N, KBr, rsc, True)\n    rows = rows.copy()\n    sw = rows[:, :4].copy().view(np.uint32)\n    if not rsc:\n        sw[16:, 0] = F32_CORNERS\n        # rows 0 / 1: every block's group 0 at sh = 0 / -1 for ACT row 0's offsets\n        _, _, d = F.quantize_mx(x, D // 4)\n        for n, off in ((0, 0), (1, 1)):\n            for k in range(KB):\n                da = int(d[0, 4 * k])\n                kk = k0 + k\n                if wf == I.W8:\n                    rows[n, 4 + kk] = max(0, W - da + off)\n                elif wf == I.WNV:\n                    rows[n, 16 + 8 * kk] = (rows[n, 16 + 8 * kk] & 7) | (min(15, da + 2 - off) << 3)\n                else:\n                    rows[n, 8 + 4 * kk] = max(0, W - da + off)\n    rows[:, :4] = sw.view(np.uint8)\n    srs = rows.shape[1]\n    dram = np.zeros(cfg.DRAM_BYTES, np.uint8)\n    _put(dram, X, x)\n    for n in range(N):\n        dram[WA + n * rs:WA + n * rs + data.shape[1]] = data[n]\n    _put(dram, SA, rows)\n    alpha = rng.uniform(-1.5, 1.5, M).astype(np.float32)\n    _put(dram, AL, alpha)\n    mm = dict(sa=WA, n=N, kb=KB, rs=rs, ors=N + 1, m=M, ab=1, srs=srs, wf=wf, pair=pair, k0=k0,\n              rsc=rsc)\n    prog = [I.ld(X, 0, x.size), I.ld(AL, 0x7000, M), I.qact(0, M, 1, KB, KB * D, dup=pair),\n            I.mm(ssa=SA, out=OUT, **mm),\n            I.mm(ssa=SA, out=OUT + 4096, **mm, unit=True, rmax=True),\n            I.mm(ssa=SA, out=OUT, **mm, acc=True, rmax=True),\n            I.mm(ssa=0, out=OUT + 4096, **mm, unit=True, acc=True, ascale=0x7000),\n            I.halt()]\n    m = _both(cfg, prog, dram, uarch={\"MXU_E\": E})\n    if not rsc:                                    # the window's edge was reached, both ways\n        s = m.slices[0]\n        da = s.adoff[0, 1:1 + KB, 0].astype(int)\n        if wf == I.WNV:\n            E4 = rows[:2, 16 + 8 * (k0 + np.arange(KB))] >> 3\n            sh = np.maximum(E4, 1) - 2 - da\n        else:\n            col = 4 + k0 + np.arange(KB) if wf == I.W8 else 8 + 4 * (k0 + np.arange(KB))\n            sh = W - rows[:2, col].astype(int) - da\n        assert (sh[0] == 0).any() and (sh[1] == -1).any(), sh\n\n\n@pytest.mark.parametrize(\"mcols,rows,wf,D\", [(4, 8, I.W8, 32), (2, 6, I.W4F, 32),\n                                             (4, 12, I.WNV, 32), (4, 16, I.W4F, 32),\n                                             (4, 16, I.WNV, 128)])\ndef test_mm_mx_replay_rtl(have_verilator, mcols, rows, wf, D):\n    \"\"\"M > MCOLS: each streamed chunk and its scale entry serve every group of MCOLS rows (up to\n    ACT_ROWS 16, the production build's, at the card's D = 128).\"\"\"\n    cfg = Config(S=1, D=D, MCOLS=mcols, ACT_ROWS=rows, DRAM_BYTES=1 << 20)\n    rng = np.random.default_rng(300 + rows)\n    KB, N = 4, 9\n    x = _xrows(rng, rows, KB * D, D // 4, 3.0)\n    data = (rng.integers(-128, 128, (N, KB * D)).astype(np.int8).view(np.uint8) if wf == I.W8\n            else Q.pack4(rng.integers(0, 16, (N, KB * D))))\n    rs = -(-data.shape[1] // D) * D\n    srows, *_ = _scale_rows(rng, wf, N, KB + 1, False, False)\n    dram = np.zeros(cfg.DRAM_BYTES, np.uint8)\n    _put(dram, X, x)\n    for n in range(N):\n        dram[WA + n * rs:WA + n * rs + data.shape[1]] = data[n]\n    _put(dram, SA, srows)\n    prog = [I.ld(X, 0, x.size), I.qact(0, rows, 0, KB, KB * D),\n            I.mm(WA, SA, OUT, N, KB, rs, N + 3, rows, 0, srows.shape[1], wf=wf, k0=1),\n            I.mm(WA, SA, OUT, N, KB, rs, N + 3, rows, 0, srows.shape[1], wf=wf, acc=True),\n            I.halt()]\n    _both(cfg, prog, dram)\n\n\ndef _qrows(rng, R, n, g):\n    \"\"\"Rows for the quantizer: wide-ranging groups (and a zero group), then a zero row, a row\n    with an infinity, a row of denormals and normals (denormals flush), a NaN row.\"\"\"\n    x = _xrows(rng, R, n, g)\n    x[1] = 0\n    x[2, 3] = np.inf\n    x[3, :] = F.from_bits(rng.integers(1, 0x800000, n).astype(np.uint32))\n    x[3, ::5] *= 0\n    x[3, ::5] += 1e-30\n    x[4, 7] = np.nan\n    return x\n\n\n@pytest.mark.parametrize(\"D,lanes,xd\", [(32, 8, None), (32, 16, None), (128, 8, None),\n                                         (128, 16, None), (32, 8, 0), (32, 8, 32), (128, 8, 128)])\ndef test_quantizer_modes_rtl(have_verilator, D, lanes, xd):\n    \"\"\"QACT (ROW or not, CSCALE, RSCALE, DUP) read back by identity MMs, UNIT (y = q * Sa *\n    2^-da; groups past the window drop) and int8x; QST (ROW or not, HALF, element strides 1 to\n    3, rows not word aligned, KB 1 to 6) into DRAM with its scale rows. xd: the quantizer's row\n    buffer (QUANT_XD; default 1024 chunks: every QACT here goes through it), 0 (none: two passes\n    over TMEM), or one row and a third of the next (the reads wait for free entries).\"\"\"\n    cfg = Config(S=1, D=D, MCOLS=4, LANES=lanes, DRAM_BYTES=1 << 20)\n    rng = np.random.default_rng(D + lanes)\n    R, KB = 6, 3\n    x = _qrows(rng, R, 2 * KB * D, D // 4)\n    cs = rng.uniform(0.25, 4.0, 2 * KB * D).astype(np.float32)\n    rsf = rng.uniform(0.25, 4.0, R).astype(np.float32)\n    dram = np.zeros(cfg.DRAM_BYTES, np.uint8)\n    _put(dram, X, x)\n    _put(dram, X + x.nbytes, cs)\n    _put(dram, X + x.nbytes + cs.nbytes, rsf)\n    _put(dram, WA, np.eye(D, dtype=np.int8))\n    int8x = np.zeros((D, 8), np.uint8)\n    int8x[:, :4] = np.array([1.0], np.float32).view(np.uint8)   # Sw 1, dw 0\n    _put(dram, SC, int8x)\n    T = 2 * KB * D * R\n    prog = [I.ld(X, 0, x.size + cs.size + rsf.size)]\n    out = 0x2000                                   # after the rows and factors\n    # (src row, ROW, CSCALE, RSCALE, DUP): rows 0..3 (a zero group, a zero row, an infinity,\n    # denormals), rows 2..5 (a NaN)\n    for r0, row, csf, rscf, dup in [(0, False, False, False, False), (0, True, False, False, False),\n                                    (0, False, True, True, False), (2, True, True, False, False),\n                                    (0, False, False, True, True), (2, False, False, False, False)]:\n        rows = 2 if dup else 4\n        prog.append(I.qact(r0 * 2 * KB * D, rows, 0, 2 * KB, 2 * KB * D, row=row, dup=dup,\n                           cscale=T if csf else None,\n                           rscale=T + 2 * KB * D + r0 if rscf else None))\n        for k in range(2 * KB):\n            prog.append(I.mm(WA, 0, out, D, 1, D, D, 2 * rows if dup else rows, k, 0,\n                             unit=True))\n            prog.append(I.mm(WA, SC, out + 4 * D, D, 1, D, D, rows, k, 8))\n            out += 8 * D\n    assert out < cfg.TMEM_WORDS\n    sd = 0x50000\n    for row, half, es, off, kb in [(False, False, 1, 0, KB), (True, False, 1, 0, 2 * KB),\n                                   (True, True, 1, 0, 2 * KB), (False, False, 2, 1, 5),\n                                   (False, False, 3, 2, 1), (True, False, 1, 3, 2),\n                                   (False, False, 1, 4, 6)]:\n        n = R\n        drs = kb * D * es + 4\n        prog.append(I.qst(0, sd + off, sd + 0x6000, n, kb, 2 * KB * D, drs, es, row=row,\n                          half=half))\n        sd += 0x8000\n    prog.append(I.halt())\n    _both(cfg, prog, dram, uarch=None if xd is None else {\"QUANT_XD\": xd})\n\n\ndef _ties(amax, rng):\n    \"\"\"Values x with F.mul(x, inv) exactly k + 0.5 (inv = 127 * recip(amax), the quantizer's)\n    for the k where such an x <= amax exists, their 1-ulp neighbours, and +-0, shuffled.\"\"\"\n    inv = F.mul(F.f32(127), F.recip(F.f32(amax)))\n    out = []\n    for k in range(-128, 128):\n        t = F.f32(k + 0.5)\n        x0 = F.f32(np.float64(t) / np.float64(inv))\n        for d in range(-4, 5):\n            x = F.from_bits(np.uint32(int(F.bits(x0)) + d))\n            if F.mul(x, inv) == t:\n                out += [x, F.from_bits(F.bits(x) + np.uint32(1)),\n                        F.from_bits(F.bits(x) - np.uint32(1))]\n                break\n    out = np.array(out + [F.f32(v) for v in (0.0, -0.0)], np.float32)\n    out = out[np.abs(out) <= amax]\n    return out[rng.permutation(len(out))]\n\n\ndef _tie_rows(D, g, rng, nrows=8, KB=6):\n    \"\"\"Rows of KB blocks with groups of g: the row's amax A at element 0, each group its offset\n    d (0 to 5; element 0 of the group is +-A 2^-d, so the group's d is d) and the ties of A\n    scaled by 2^-d elsewhere: x * (inv * 2^d) is a tie of A's. Returns x and its tie count\n    (with the groups' offsets).\"\"\"\n    x = np.zeros((nrows, KB * D), np.float32)\n    for r in range(nrows):\n        A = F.f32([1.0, 2.0, 0.75, 127.0][r] if r < 4 else rng.uniform(0.5, 3.0))\n        t = _ties(A, rng)\n        for i in range(0, KB * D, g):\n            d = 0 if i == 0 else int(rng.integers(0, 6))\n            blk = np.resize(np.roll(t, -i), g) * np.float32(2.0 ** -d)\n            blk[0] = A * np.float32(2.0 ** -d) * (1 if (r + i // g) % 2 else -1)\n            x[r, i:i + g] = blk\n    q_, s_, d = F.quantize_mx(x, g)\n    inv = F.mul(F.f32(127), F.recip(np.abs(x).max(1)))\n    ig = F.mul(inv[:, None], np.ldexp(F.f32(1), d.astype(np.int32)).astype(np.float32))\n    p = F.mul(x.reshape(nrows, -1, g), ig[:, :, None])\n    return x, int((p - np.floor(p) == 0.5).sum())\n\n\n@pytest.mark.parametrize(\"D,row\", [(32, False), (32, True), (128, False), (128, True)])\ndef test_quantizer_ties_qst_rtl(have_verilator, D, row):\n    \"\"\"QST (D-block offsets, or ROW) on exact ties of x * (inv * 2^d) and their neighbours: the\n    bytes and scale rows land in DRAM.\"\"\"\n    cfg = Config(S=1, D=D, DRAM_BYTES=1 << 20)\n    rng = np.random.default_rng(D + row)\n    x, ties = _tie_rows(D, D, rng)\n    assert ties > 100\n    R, KB = x.shape[0], x.shape[1] // D\n    dram = np.zeros(cfg.DRAM_BYTES, np.uint8)\n    _put(dram, X, x)\n    prog = [I.ld(X, 0, x.size),\n            I.qst(0, 0x40000, 0x48000, R, KB, KB * D, KB * D, 1, row=row),\n            I.qst(0, 0x50000, 0x58000, R, KB, KB * D, 2 * KB * D, 2, row=row),\n            I.halt()]\n    _both(cfg, prog, dram)\n\n\n@pytest.mark.parametrize(\"row\", [False, True])\ndef test_quantizer_ties_qact_rtl(have_verilator, row):\n    \"\"\"QACT (sub-block offsets, or ROW) on the same ties, read back by MMs with identity int8\n    weights and UNIT: T[out + j, n] = q[j][n] * Sa[j] * 2^-da for each block.\"\"\"\n    cfg = Config(S=1, D=32, MCOLS=8, DRAM_BYTES=1 << 20)\n    D = cfg.D\n    rng = np.random.default_rng(5 + row)\n    x, ties = _tie_rows(D, D // 4, rng)\n    assert ties > 100\n    R, KB = x.shape[0], x.shape[1] // D\n    dram = np.zeros(cfg.DRAM_BYTES, np.uint8)\n    _put(dram, X, x)\n    _put(dram, WA, np.eye(D, dtype=np.int8))\n    prog = [I.ld(X, 0, x.size), I.qact(0, R, 0, KB, KB * D, row=row)]\n    for k in range(KB):\n        prog.append(I.mm(WA, 0, OUT + k * R * D, D, 1, D, D, R, k, 0, unit=True))\n    prog.append(I.halt())\n    m = _both(cfg, prog, dram)\n    got = m.slices[0].tget(OUT + np.arange(KB * R * D)).reshape(KB, R, D)\n    q, s, d = F.quantize_mx(x, D // 4, row)\n    q = q.reshape(R, KB, D).astype(np.int64)\n    d = np.repeat(d.reshape(R, KB, 4), D // 4, 2).astype(np.int64)\n    acc = np.where(d <= 16, q << np.maximum(16 - d, 0), 0)\n    want = F.mul(F.i2f(acc), F.mul(s, F.f32(2.0 ** -16))[:, None, None])\n    assert np.array_equal(got.view(np.uint32), want.transpose(1, 0, 2).view(np.uint32))\n", "tests/test_qwen3.py": "\"\"\"Qwen3 on openTPU: the full decoder (layer loop, QK-norm, GQA, RoPE, tied LM head) against\nHugging Face transformers. A tiny random model always runs; the real Qwen3-0.6B runs when its\ncheckpoint is in models/Qwen3-0.6B.\"\"\"\nfrom pathlib import Path\n\nimport numpy as np\nimport pytest\n\nfrom opentpu.llm.qwen3 import (Engine, Spec, device_config, emulated_logits, load_weights,\n                                reference_logits, rope_tables)\n\ntorch = pytest.importorskip(\"torch\")\ntransformers = pytest.importorskip(\"transformers\")\n\nREAL = Path(__file__).resolve().parent.parent / \"models\" / \"Qwen3-0.6B\"\n\n\ndef _cos(a, b):\n    return (a * b).sum(-1) / np.linalg.norm(a, axis=-1) / np.linalg.norm(b, axis=-1)\n\n\n@pytest.fixture(scope=\"module\")\ndef tiny():\n    torch.manual_seed(0)\n    hc = transformers.Qwen3Config(hidden_size=256, num_hidden_layers=2, num_attention_heads=4,\n                                  num_key_value_heads=2, head_dim=128, intermediate_size=512,\n                                  vocab_size=1000, rms_norm_eps=1e-6, rope_theta=1e6,\n                                  tie_word_embeddings=True, max_position_embeddings=4096)\n    m = transformers.Qwen3ForCausalLM(hc).float().eval()\n    with torch.no_grad():\n        for n, p in m.named_parameters():\n            if \"norm\" in n:\n                p.copy_(1 + 0.1 * torch.randn_like(p))\n    W = {k: v.float().numpy() for k, v in m.state_dict().items()}\n    return m, W, Spec(256, 2, 4, 2, 128, 512, 1000)\n\n\ndef test_the_embedding_table_goes_to_the_host_when_it_does_not_fit(tiny):\n    \"\"\"A dense model's int8 embedding table of its own stays on the card (embed_host off),\n    unless the image does not fit with it: then the Engine keeps it on the host, the card\n    holding a slot of the prefill's rows, with the same logits (8-row prefill, steps); asked\n    to keep it on the card, the image does not fit.\"\"\"\n    from dataclasses import replace\n    _, W, spec = tiny\n    spec = replace(spec, tied=False, embed=\"int8\")\n    W = dict(W, **{\"lm_head.weight\": W[\"model.embed_tokens.weight\"] * np.float32(1.25)})\n    big = device_config(spec, 256, rows=8, lookup=True, embed_host=False)\n    a = Engine(spec, W, cap=256, cfg=big, rows=8)\n    assert a.device_inputs and not a.image.embed_host and a.row_server is None\n    host = spec.image(big, 256, 1, 8, lookup=True, embed_host=True).nbytes\n    small = replace(big, DRAM_BYTES=-(-host // 4096) * 4096)\n    assert small.DRAM_BYTES < a.image.nbytes\n    b = Engine(spec, W, cap=256, cfg=small, rows=8)\n    assert b.image.embed_host and b.image.nbytes == host\n    with pytest.raises(MemoryError):\n        Engine(spec, W, cap=256, cfg=small, rows=8, embed_host=False)\n    toks = [int(t) for t in np.random.default_rng(4).integers(0, 1000, 13)]\n    assert np.array_equal(a.prefill(toks).view(np.uint32), b.prefill(toks).view(np.uint32))\n    for t in toks[:3]:\n        assert np.array_equal(a.step(t).view(np.uint32), b.step(t).view(np.uint32))\n\n\ndef test_from_hf_refuses_what_it_would_run_unlike_hf(tmp_path):\n    \"\"\"Spec.from_hf takes the RoPE theta where transformers writes it (rope_parameters; the top\n    level's rope_theta is null) and refuses what this code would run unlike Hugging Face: a\n    RoPE scaling (Qwen3's YaRN recipe rescales the frequencies and cos / sin at every\n    position), the sliding window, attention biases.\"\"\"\n    import json\n    base = transformers.Qwen3Config(hidden_size=256, num_hidden_layers=2, num_attention_heads=4,\n                                    num_key_value_heads=2, head_dim=128, intermediate_size=512,\n                                    vocab_size=1000, rope_theta=5e5).to_dict()\n\n    def spec(**kw):\n        (tmp_path / \"config.json\").write_text(json.dumps(dict(base, **kw)))\n        return Spec.from_hf(tmp_path)\n    assert spec().theta == 5e5\n    assert spec(rope_parameters=None, rope_theta=1e6).theta == 1e6     # an older config\n    yarn = {\"rope_type\": \"yarn\", \"factor\": 4.0, \"original_max_position_embeddings\": 32768}\n    for kw in (dict(rope_parameters=dict(yarn, rope_theta=1e6)),\n               dict(rope_parameters=None, rope_theta=1e6, rope_scaling=yarn),\n               dict(rope_parameters=None, rope_scaling={\"type\": \"linear\", \"factor\": 2.0})):\n        with pytest.raises(ValueError, match=\"RoPE type\"):\n            spec(**kw)\n    with pytest.raises(ValueError, match=\"sliding\"):\n        spec(use_sliding_window=True, sliding_window=4096)\n    with pytest.raises(ValueError, match=\"bias\"):\n        spec(attention_bias=True)\n\n\ndef test_tiny_matches_hf(tiny):\n    m, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(0).integers(0, 1000, 140)]  # > one KV block\n    with torch.no_grad():\n        hf = m(torch.tensor([toks])).logits[0].numpy()\n    assert np.abs(reference_logits(spec, W, toks) - hf).max() < 1e-4\n    eng = Engine(spec, W, cap=256)\n    dev = np.array([eng.step(t) for t in toks])\n    assert _cos(dev, hf).min() > 0.998\n    # the device follows the quantized math (it differs only in fp32 rounding)\n    emu = emulated_logits(spec, W, toks[:12])\n    assert _cos(dev[:12], emu).min() > 0.9995\n\n\nOUTLIERS = [5, 69, 30, 94]          # two RoPE pairs (c, c + head_dim / 2)\n\n\ndef _planted(W, spec):\n    \"\"\"Qwen3's K outliers planted in every layer: k_norm gains 60 on two RoPE pairs, their q\n    gains 0.01 (Qwen3-0.6B's k_norm reaches 42x its layer's median where q_norm is near 0).\"\"\"\n    W = dict(W)\n    for i in range(spec.layers):\n        p = f\"model.layers.{i}.self_attn.\"\n        gq, gk = W[p + \"q_norm.weight\"].copy(), W[p + \"k_norm.weight\"].copy()\n        gq[OUTLIERS], gk[OUTLIERS] = 0.01, 60.0\n        W[p + \"q_norm.weight\"], W[p + \"k_norm.weight\"] = gq, gk\n    return W\n\n\ndef _kl(ref, dev):\n    lp, lq = ((x - x.max(-1, keepdims=True)) for x in (np.float64(ref), np.float64(dev)))\n    lp, lq = (x - np.log(np.exp(x).sum(-1, keepdims=True)) for x in (lp, lq))\n    return float((np.exp(lp) * (lp - lq)).sum(-1).mean())\n\n\ndef test_tiny_k_smoothing(tiny):\n    \"\"\"K's channels smoothed into the q_norm / k_norm gains (qk_gains). With the K outliers\n    planted, K's int8 scale (per token and head block) follows them and the other channels\n    round to a few levels: unsmoothed, the device is far from the fp32 reference. Smoothed\n    (sigma 64 on the outlier pairs: q . K unchanged, K's rounding balanced against q's) it is\n    as close as the plain tiny model's (KL ~3e-5 against 1.3e-3 unsmoothed), and follows the\n    emulation. sigma is a power of two, the same within each RoPE pair, and 1 on the plain tiny\n    model (its image unchanged); the fp32 reference stays the checkpoint's.\"\"\"\n    from dataclasses import replace\n\n    from opentpu.llm.qwen3 import qk_gains, qk_sigma\n    _, W0, spec = tiny\n    for i in range(spec.layers):\n        p = f\"model.layers.{i}.\"\n        g = qk_gains(spec, W0, p)\n        assert np.array_equal(g[0], W0[p + \"self_attn.q_norm.weight\"])\n        assert np.array_equal(g[1], W0[p + \"self_attn.k_norm.weight\"])\n    W = _planted(W0, spec)\n    a, h = \"model.layers.0.self_attn.\", spec.rope_dim // 2\n    s = qk_sigma(spec, *(W[a + n + \".weight\"] for n in (\"q_proj\", \"k_proj\", \"q_norm\", \"k_norm\")))\n    assert np.array_equal(np.exp2(np.round(np.log2(s))), s) and np.array_equal(s[:h], s[h:])\n    assert (s[OUTLIERS] == 64).all() and (np.delete(s, OUTLIERS) == 1).all()\n    toks = [int(t) for t in np.random.default_rng(0).integers(0, 1000, 24)]\n    ref = reference_logits(spec, W, toks)\n    assert np.array_equal(ref, reference_logits(replace(spec, qk_smooth=False), W, toks))\n    devs = {}\n    for on in (True, False):\n        eng = Engine(replace(spec, qk_smooth=on), W, cap=256)\n        devs[on] = np.array([eng.step(t) for t in toks])\n    assert _cos(devs[True], ref).min() > 0.999 and _kl(ref, devs[True]) < 1e-4\n    assert _cos(devs[False], ref).min() < 0.99 and _kl(ref, devs[False]) > 10 * _kl(ref, devs[True])\n    emu = emulated_logits(spec, W, toks[:12])\n    assert _cos(devs[True][:12], emu).min() > 0.9995\n\n\n@pytest.mark.parametrize(\"wformat\", [\"int4\", \"fp4\"])\ndef test_tiny_4bit_follows_emulation(tiny, wformat):\n    \"\"\"4-bit weights: the device follows the float64 emulation of the same 4-bit weights.\"\"\"\n    _, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(0).integers(0, 1000, 12)]\n    eng = Engine(spec, W, cap=256, wformat=wformat)\n    dev = np.array([eng.step(t) for t in toks])\n    emu = emulated_logits(spec, W, toks, wformat=wformat)\n    assert _cos(dev, emu).min() > 0.9995\n\n\n@pytest.mark.parametrize(\"wformat\", [\"int4\", \"fp4\"])\ndef test_tiny_4bit_column_reuse(tiny, wformat):\n    \"\"\"Column reuse (MCOLS=2, PAIR): every 4-bit decode MM runs PAIR on a QACT DUP operand;\n    the logits follow the emulation and differ from the half-rate MXU in fp32 rounding only.\"\"\"\n    from opentpu import isa as I\n    _, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(0).integers(0, 1000, 12)]\n    runs = {}\n    for pair in (False, True):\n        cfg = device_config(spec, 256, wformat=wformat, MCOLS=2, PAIR=pair)\n        eng = Engine(spec, W, cap=256, cfg=cfg, wformat=wformat)\n        runs[pair] = np.array([eng.step(t) for t in toks])\n        prog = eng.backend.machine.slices[0].prog\n        mm4 = [p for p in prog if p.op == I.MM and (p.flags >> I.WF_SHIFT) & 3]\n        assert mm4 and all(bool(p.flags & I.F_PAIR) == pair for p in mm4)\n        # the attention's query groups (two rows) fill both columns: no DUP\n        assert all(bool(p.flags & I.F_DUP) == (pair and p.w[1] & 0xFF == 1)\n                   for p in prog if p.op == I.QACT)\n    emu = emulated_logits(spec, W, toks, wformat=wformat)\n    assert _cos(runs[True], emu).min() > 0.9995\n    assert _cos(runs[True], runs[False]).min() > 0.99999\n\n\ndef test_tiny_resident_decode_is_bit_exact(tiny):\n    \"\"\"Resident decode (compile_decode: one program per attention bucket, the token and\n    position as run arguments) gives the per-position programs' logits bit for bit, from\n    position 0 and across the bucket boundary 256, after a chunked prefill.\"\"\"\n    _, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(1).integers(0, 1000, 262)]\n    a = Engine(spec, W, cap=512, resident=True)\n    b = Engine(spec, W, cap=512)\n    assert a.resident\n    for t in toks[:3]:\n        assert np.array_equal(a.step(t).view(np.uint32), b.step(t).view(np.uint32))\n    assert np.array_equal(a.prefill(toks[3:252]), b.prefill(toks[3:252]))\n    for t in toks[252:]:\n        pa = a.pos\n        assert np.array_equal(a.step(t).view(np.uint32), b.step(t).view(np.uint32)), pa\n    assert sorted(a._decodes) == [1, 2]\n\n\n@pytest.mark.parametrize(\"name, cap, P, end\", [(\"qwen3\", 640, 515, True),\n                                               (\"qwen3\", 384, 257, True),\n                                               (\"lfm2\", 384, 257, True),\n                                               (\"qwen35\", 384, 257, False)])\ndef test_resident_decode_at_a_partial_last_bucket(guarded, name, cap, P, end):\n    \"\"\"A KV capacity that is a multiple of D but not of the attention block (256): the last\n    bucket's masked block ends at the cache's end (cap - t0 tokens, attention.Bucket), so\n    resident decode reads nothing past the cache (every KV region is followed by -NaN words\n    here) and gives the per-position programs' logits bit for bit, after a prefill past the\n    last full block and (`end`) up to the cache's last position.\"\"\"\n    from test_autodecode import _tiny\n    W, spec = _tiny(name)\n    toks = [int(t) for t in np.random.default_rng(1).integers(0, 1000, cap)]\n    a, b = Engine(spec, W, cap=cap, resident=True), Engine(spec, W, cap=cap)\n    assert a.resident and guarded(a) and guarded(b)\n    same = lambda x, y: np.isfinite(y).all() and np.array_equal(x.view(np.uint32),  # noqa: E731\n                                                                y.view(np.uint32))\n    assert same(a.prefill(toks[:P]), b.prefill(toks[:P]))\n    for t in toks[P:P + 2]:\n        assert same(a.step(t), b.step(t)), a.pos\n    if end:\n        assert same(a.prefill(toks[P + 2:cap - 2]), b.prefill(toks[P + 2:cap - 2]))\n        for t in toks[cap - 2:]:\n            assert same(a.step(t), b.step(t)), a.pos\n        assert a.pos == cap\n    assert sorted(a._decodes) == [-(-cap // 256)]\n\n\ndef test_tiny_device_inputs(tiny, monkeypatch):\n    \"\"\"With the image's tables (resident decode's lookup tables), prefill runs and\n    per-position steps read their embedding and RoPE rows from the image too (the token ids\n    compiled into their programs): the host writes no inputs, only the run's arguments, and the\n    logits are the host-input engine's bit for bit. Without the resident program (a backend\n    without run arguments) every step is such a per-position program.\"\"\"\n    from opentpu.llm.qwen3 import IsaBackend\n    _, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(2).integers(0, 1000, 20)]\n    monkeypatch.setattr(IsaBackend, \"args\", False)      # no resident program: per-position\n    a = Engine(spec, W, cap=256, resident=True)\n    b = Engine(spec, W, cap=256)\n    assert a.device_inputs and not a.resident and not b.device_inputs\n    writes = []\n    wr = a.backend.write\n    a.backend.write = lambda s, addr, v: (writes.append(addr), wr(s, addr, v))\n    for t in toks[:2]:\n        assert np.array_equal(a.step(t).view(np.uint32), b.step(t).view(np.uint32))\n    assert np.array_equal(a.prefill(toks[2:17], chunk=6), b.prefill(toks[2:17], chunk=6))\n    for t in toks[17:]:\n        assert np.array_equal(a.step(t).view(np.uint32), b.step(t).view(np.uint32))\n    assert writes == []\n    assert [s.get(\"rows\", 1) for s in a.stats] == [1, 1, 6, 6, 3, 1, 1, 1]\n\n\ndef test_tiny_prefill_runs_take_whole_mxu_passes(tiny):\n    \"\"\"A default prefill run of more than MCOLS rows takes whole passes of MCOLS rows (each\n    pass streams every weight: 7 rows would cost what 8 do); an explicit chunk is kept.\"\"\"\n    from opentpu.isasim import board_config\n    _, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(3).integers(0, 1000, 15)]\n    cfg = board_config(DRAM_BYTES=1 << 24, MCOLS=4)\n    a, b = Engine(spec, W, cap=256, cfg=cfg), Engine(spec, W, cap=256, cfg=cfg)\n    assert np.array_equal(a.prefill(toks), b.prefill(toks, chunk=7))\n    assert [s.get(\"rows\", 1) for s in a.stats] == [8, 4, 3]\n    assert [s.get(\"rows\", 1) for s in b.stats] == [7, 7, 1]\n\n\ndef test_tiny_reset_reuses_cache(tiny):\n    _, W, spec = tiny\n    eng = Engine(spec, W, cap=128)\n    a = [eng.step(t) for t in (5, 6, 7)]\n    eng.reset()\n    b = [eng.step(t) for t in (5, 6, 7)]\n    assert all(np.array_equal(x, y) for x, y in zip(a, b))\n\n\n@pytest.mark.parametrize(\"wformat\", [\"int8\", \"fp4\"])\ndef test_waits_memo_is_exact_on_its_programs(tiny, wformat):\n    \"\"\"The waits pass's memoized entries (opentpu/waits.py _MemoPass) are the exact pass's on\n    every program a dense model runs, int8 and fp4: the chunked prefill's and the prompt runs'\n    (docs/prefill.md), the step and resident decode programs, the decode loop's (GEN, RLD).\n    Their MMs drain at their array's rate (compiler.slow_drains).\"\"\"\n    from conftest import assert_drains_keep_up, assert_waits_exact, waits_programs\n    _, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(3).integers(0, 1000, 40)]\n    n = 0\n    for kw in ({}, {\"prompt_runs\": True}):\n        e = Engine(spec, W, cap=512, resident=True, wformat=wformat, **kw)\n        progs = waits_programs(e)\n        e.prefill(toks[:30])\n        e.step(toks[30])\n        e.generate_card(toks[31], 6, stop_ids=[])\n        assert len(progs) >= 3\n        n += assert_waits_exact(progs, e.cfg)\n        assert assert_drains_keep_up(progs, e.cfg) > 0\n    assert n > 1000\n\n\ndef test_weights_refuse_non_finite_values(tmp_path):\n    \"\"\"A checkpoint tensor with a NaN or an infinity is refused where the weight classes convert\n    it (load_weights, LazyWeights, gemma4.Weights: whole tensors, one expert, PLE rows), naming\n    it: quantized, it would become a NaN or infinite block scale in the image. Finite tensors\n    and the finite parts of a bad one read as before.\"\"\"\n    from safetensors.torch import save_file\n\n    from opentpu.llm import gemma4 as G4\n    from opentpu.llm.qwen3 import LazyWeights\n    ok = torch.randn(4, 8)\n    nan, inf = ok.clone(), ok.clone().bfloat16()\n    nan[2, 5] = float(\"nan\")\n    inf[1, 0] = -float(\"inf\")\n    experts = torch.randn(3, 4, 8)\n    experts[1, 3, 7] = float(\"inf\")\n    ple = torch.randn(6, 8).bfloat16()\n    ple[4, 2] = float(\"nan\")\n    save_file({\"model.ok.weight\": ok, \"model.nan.weight\": nan, \"model.inf.weight\": inf,\n               \"model.experts\": experts, \"model.embed_tokens_per_layer.weight\": ple},\n              str(tmp_path / \"model.safetensors\"))\n    for W in (load_weights(tmp_path), LazyWeights(tmp_path), G4.Weights(tmp_path)):\n        assert np.array_equal(W[\"model.ok.weight\"], ok.numpy())\n        with pytest.raises(ValueError, match=r\"model\\.nan\\.weight: 1 of its 32 .*\\(2, 5\\)\"):\n            W[\"model.nan.weight\"]\n        with pytest.raises(ValueError, match=r\"model\\.inf\\.weight: 1 of its 32 .*\\(1, 0\\)\"):\n            W[\"model.inf.weight\"]\n        if hasattr(W, \"part\"):\n            assert np.array_equal(W.part(\"model.experts\", 2), experts[2].numpy())\n            with pytest.raises(ValueError, match=r\"model\\.experts\\[1\\]: .*\\(3, 7\\)\"):\n                W.part(\"model.experts\", 1)\n        else:\n            with pytest.raises(ValueError, match=r\"model\\.experts: \"):\n                W[\"model.experts\"]\n    rows = G4.Weights(tmp_path)[G4.Weights.PLE]\n    assert np.array_equal(rows[[0, 3]], ple[[0, 3]].float().numpy())\n    for key in (4, [0, 4], slice(3, 6)):\n        with pytest.raises(ValueError, match=r\"embed_tokens_per_layer\\.weight\\[.*\\(2,\\)|\"\n                                             r\"embed_tokens_per_layer\\.weight\\[3:6\\].*\\(1, 2\\)\"):\n            rows[key]\n\n\n@pytest.mark.skipif(not REAL.exists(), reason=\"models/Qwen3-0.6B not downloaded\")\ndef test_qwen3_0_6b_greedy_matches_hf():\n    tok = transformers.AutoTokenizer.from_pretrained(REAL)\n    msgs = [{\"role\": \"user\", \"content\": \"What is the capital of France? Answer in one sentence.\"}]\n    ids = tok.apply_chat_template(msgs, add_generation_prompt=True, enable_thinking=False,\n                                  tokenize=True)\n    ids = list(ids[\"input_ids\"] if hasattr(ids, \"keys\") else ids)\n    hf = transformers.AutoModelForCausalLM.from_pretrained(REAL, dtype=torch.float32).eval()\n    with torch.no_grad():\n        want = hf.generate(torch.tensor([ids]), max_new_tokens=8, do_sample=False)[0, len(ids):]\n    eng = Engine(Spec.from_hf(REAL), load_weights(REAL), cap=256)\n    got = eng.generate(ids, max_new=8)\n    assert got == want.tolist()[:len(got)] and len(got) >= 7\n    assert tok.decode(got).startswith(\"The capital of France is Paris.\")\n\n\n@pytest.mark.skipif(not REAL.exists(), reason=\"models/Qwen3-0.6B not downloaded\")\n@pytest.mark.parametrize(\"pair\", [False, True])\ndef test_qwen3_0_6b_fp4_greedy(pair):\n    \"\"\"Qwen3-0.6B with 4-bit (E2M1, two-level scales) layer weights and an int8 LM head on the\n    ISA simulator: the greedy answer is still right, and every generated token is the argmax of\n    the float64 emulation of the same 4-bit weights (the device follows the quantized math).\n    pair: the board's MCOLS=2 with column reuse (full-rate 4-bit MMs).\"\"\"\n    tok = transformers.AutoTokenizer.from_pretrained(REAL)\n    msgs = [{\"role\": \"user\", \"content\": \"What is the capital of France? Answer in one sentence.\"}]\n    ids = tok.apply_chat_template(msgs, add_generation_prompt=True, enable_thinking=False,\n                                  tokenize=True)\n    ids = list(ids[\"input_ids\"] if hasattr(ids, \"keys\") else ids)\n    spec, W = Spec.from_hf(REAL), load_weights(REAL)\n    cfg = device_config(spec, 256, wformat=\"fp4\", head_format=\"int8\", MCOLS=2, PAIR=True) \\\n        if pair else None\n    eng = Engine(spec, W, cap=256, cfg=cfg, wformat=\"fp4\", head_format=\"int8\")\n    got = eng.generate(ids, max_new=8)\n    assert tok.decode(got).startswith(\"The capital of France is Paris.\")\n    emu = emulated_logits(spec, W, ids + got[:-1], wformat=\"fp4\", head_format=\"int8\")\n    assert emu[len(ids) - 1:].argmax(-1).tolist() == got\n\n\n@pytest.mark.skipif(not REAL.exists(), reason=\"models/Qwen3-0.6B not downloaded\")\n@pytest.mark.parametrize(\"wformat,head_format,pair\", [(\"int8\", None, False),\n                                                      (\"fp4\", \"int8\", False),\n                                                      (\"fp4\", None, True)])\ndef test_qwen3_0_6b_token_on_rtl_is_bit_exact(wformat, head_format, pair):\n    \"\"\"Feed part of a prompt on the ISA simulator, then run the next token on the Verilator RTL\n    and on the ISA simulator from the same DRAM state: weights, KV cache and logits must agree\n    bit for bit (int8 weights; 4-bit layers with an int8 LM head; everything 4-bit on the\n    board's MCOLS=2 with column reuse).\"\"\"\n    from opentpu.llm.rtl_backend import RtlBackend\n    spec = Spec.from_hf(REAL)\n    cfg = device_config(spec, 256, wformat=wformat, head_format=head_format, MCOLS=2,\n                        PAIR=True) if pair else None\n    eng = Engine(spec, load_weights(REAL), cap=256, cfg=cfg, wformat=wformat,\n                 head_format=head_format)\n    prompt = [151644, 872, 198, 3838, 374, 279, 6722, 315, 9625, 30]\n    for t in prompt[:-1]:\n        eng.step(t)\n    n = eng.image.nbytes\n    rtl = RtlBackend(eng.cfg, [s.dram[:n] for s in eng.backend.machine.slices])\n    isa = eng.backend\n    want = eng.step(prompt[-1])\n    eng.backend, eng.pos = rtl, eng.pos - 1\n    got = eng.step(prompt[-1])\n    assert np.array_equal(want.view(np.uint32), got.view(np.uint32))\n    for s in range(eng.cfg.S):\n        assert np.array_equal(isa.machine.slices[s].dram[:n], rtl.drams[s][:n])\n\n\ndef test_tiny_chunked_prefill_is_bit_exact(tiny):\n    \"\"\"Prefill in chunks (P prompt rows per run, causal over the cache and the chunk) gives the\n    same logits and KV cache as token-by-token decode; decoding continues identically.\"\"\"\n    m, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(1).integers(0, 1000, 23)]\n    ref = Engine(spec, W, cap=256)\n    want = [ref.step(t) for t in toks]\n    eng = Engine(spec, W, cap=256, rows=4)\n    got = eng.prefill(toks[:21], chunk=4)\n    assert np.array_equal(got, want[20]) and eng.pos == 21\n    assert all(np.array_equal(eng.step(t), w) for t, w in zip(toks[21:], want[21:]))\n    with torch.no_grad():\n        hf = m(torch.tensor([toks[:21]])).logits[0, -1].numpy()\n    assert _cos(got, hf) > 0.998\n\n\ndef test_tiny_batched_decode_matches_separate_runs(tiny):\n    \"\"\"b sequences decoded together (each weight stream shared by b rows, one KV cache and\n    position per sequence) equal b separate runs bit for bit.\"\"\"\n    _, W, spec = tiny\n    rng = np.random.default_rng(2)\n    prompts = [[int(t) for t in rng.integers(0, 1000, n)] for n in (5, 12, 1)]\n    eng = Engine(spec, W, cap=128, batch=3)\n    got = eng.generate_batch(prompts, max_new=4, chunk=3)\n    for s, p in enumerate(prompts):\n        assert got[s] == Engine(spec, W, cap=128).generate(p, max_new=4)\n    lg = eng.step_batch([7, 8])                 # a subset; the last generated token was not fed\n    for s, t in enumerate((7, 8)):\n        ref = Engine(spec, W, cap=128)\n        ref.prefill(prompts[s] + got[s][:-1])\n        assert np.array_equal(lg[s], ref.step(t))\n\n\ndef test_tiny_batch_goes_on_when_a_sequence_fills_the_cache(tiny):\n    \"\"\"A sequence that reaches the cap ends (as Engine.generate) and leaves the batch: the\n    others decode on, each equal to its separate run; a finished sequence is fed no more (its\n    position stays after its last token fed). Before, the next step fed every row and the full\n    sequence's raised \"KV cache full\".\"\"\"\n    _, W, spec = tiny\n    rng = np.random.default_rng(5)\n    prompts = [[int(t) for t in rng.integers(0, 1000, n)] for n in (126, 3)]\n    eng = Engine(spec, W, cap=128, batch=2, rows=8)\n    got = eng.generate_batch(prompts, max_new=6, chunk=8)\n    for s, p in enumerate(prompts):\n        assert got[s] == Engine(spec, W, cap=128, rows=8).generate(p, max_new=6)\n    assert [len(g) for g in got] == [3, 6] and eng.poss == [128, 8]\n\n\n@pytest.mark.skipif(not REAL.exists(), reason=\"models/Qwen3-0.6B not downloaded\")\ndef test_qwen3_0_6b_chunked_prefill_and_batch_match_hf():\n    \"\"\"Real weights: chunked prefill then decode gives HF's greedy tokens, and two prompts\n    decoded as a batch give the same tokens as separate runs.\"\"\"\n    tok = transformers.AutoTokenizer.from_pretrained(REAL)\n    hf = transformers.AutoModelForCausalLM.from_pretrained(REAL, dtype=torch.float32).eval()\n    prompts = []\n    for q in (\"What is the capital of France? Answer in one sentence.\", \"Name a prime number.\"):\n        ids = tok.apply_chat_template([{\"role\": \"user\", \"content\": q}],\n                                      add_generation_prompt=True, enable_thinking=False,\n                                      tokenize=True)\n        prompts.append(list(ids[\"input_ids\"] if hasattr(ids, \"keys\") else ids))\n    W, spec = load_weights(REAL), Spec.from_hf(REAL)\n    eng = Engine(spec, W, cap=256, batch=2, rows=8)\n    got = eng.generate_batch(prompts, max_new=6, chunk=8)\n    for s, ids in enumerate(prompts):\n        with torch.no_grad():\n            want = hf.generate(torch.tensor([ids]), max_new_tokens=6,\n                               do_sample=False)[0, len(ids):].tolist()\n        assert got[s] == want[:len(got[s])] and len(got[s]) >= 5\n    assert got[1] == Engine(spec, W, cap=256).generate(prompts[1], max_new=6)\n\n\ndef test_tiny_vt_tiles_bit_exact(tiny, monkeypatch):\n    \"\"\"A 512-token cache holds V^T in tiles of 256 tokens (compiler.KVDesc): a prefill chunk\n    across the tile edge, then decode past it, give the same logits bit for bit as the plain\n    [d, cap] layout.\"\"\"\n    import opentpu.compiler as C\n    _, W, spec = tiny\n    toks = [int(t) for t in np.random.default_rng(3).integers(0, 1000, 264)]\n\n    def run():\n        eng = Engine(spec, W, cap=512, rows=8)\n        eng.step(toks[0])\n        out = [eng.prefill(toks[1:257], chunk=8)]          # rows 249..256 cross the edge\n        out += [eng.step(t) for t in toks[257:]]\n        return out\n    assert C.vt_tile(512) == 256\n    tiled = run()\n    monkeypatch.setattr(C, \"VT_TILE\", 1 << 30)\n    plain = run()\n    assert all(np.array_equal(a.view(np.uint32), b.view(np.uint32)) for a, b in zip(tiled, plain))\n\n\n@pytest.mark.parametrize(\"mcols,wformat\", [(2, \"int8\"), (4, \"int8\"), (2, \"fp4\")])\ndef test_tiny_prefill_chunk_with_mm_replay_on_rtl(tiny, have_verilator, mcols, wformat):\n    \"\"\"An 8-row prefill run at the board configuration with 8 ACT RAM rows (each projection is\n    one MM that replays every weight chunk for 8 / MCOLS groups) on the RTL's board memory\n    path: DRAM and TMEM equal the ISA simulator's, and the logits equal decode's. fp4: 4-bit\n    layers (two blocks a replayed chunk) with an int8 head, on a PAIR board (decode rows pair,\n    the 8-row MMs replay).\"\"\"\n    from opentpu import rtlsim\n    from opentpu.isasim import Machine, board_config\n    _, W, spec = tiny\n    wkw = dict(wformat=wformat, head_format=\"int8\") if wformat != \"int8\" else {}\n    toks = [int(t) for t in np.random.default_rng(4).integers(0, 1000, 11)]\n    ref = Engine(spec, W, cap=256, **wkw)\n    want = ref.prefill(toks, chunk=1)\n    cfg = board_config(MCOLS=mcols, ACT_ROWS=8, DRAM_BYTES=1 << 24, PAIR=wformat != \"int8\")\n    eng = Engine(spec, W, cap=256, cfg=cfg, **wkw)\n    eng.prefill(toks[:3])                         # a cache to attend over\n    rows = [(0, 3 + j) for j in range(8)]\n    progs = eng.image.compile_rows(rows, [7])\n    assert any(i.op == 0x20 and (i.w[5] >> 16) & 0xFF == 8 for i in progs[0])\n    x = eng.embed[toks[3:]]\n    io = eng.image.io\n    cs = [np.stack(a).astype(np.float32) for a in zip(*[rope_tables(spec, p) for _, p in rows])]\n    dram = eng.backend.machine.slices[0].dram.copy()\n    for k, v in ((\"x\", x), (\"cos\", cs[0]), (\"sin\", cs[1])):\n        b = np.ascontiguousarray(v, np.float32).view(np.uint8).reshape(-1)\n        dram[io[k]:io[k] + b.size] = b\n    m = Machine(cfg, progs, [dram.copy()]).run()\n    drams, tmems, _ = rtlsim.run(cfg, progs, [dram.copy()], uarch=rtlsim.BOARD_UARCH, axi=True,\n                                 boot=True)\n    assert np.array_equal(drams[0][:eng.image.nbytes], m.slices[0].dram[:eng.image.nbytes])\n    v = spec.vocab\n    lg = drams[0][io[\"logits\"] + 4 * 7 * v:io[\"logits\"] + 4 * 8 * v].view(np.float32)\n    assert np.array_equal(lg, want)\n"});
